INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b7c-38a7-7b0f-9fb8-080af5a69304'::uuid,'Air Elemental','TrueNeutral','5 (XP 1 800; PB +3)',1800,5,'Artillery','Large',15,NULL,90,'12d10+24','10 ft.',NULL,NULL,'90 ft.',14,20,14,6,10,6,'{}','Poison, Thunder; Exhaustion, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Darkvision 60 ft., Passive Perception 10','Primordial (Auran)',2,5,2,0,-2,-2,3,'[]','Habitat: Desert, Mountain, Planar (Elemental Plane of Air)','Elemental','','{"value":"Whirling cyclone dances gracefully, pulling in everything in its path."}','{"value": "Air elementals are powerful creatures formed from the very essence of the elemental plane of air. They are typically summoned by powerful spellcasters to do their bidding, or they can be found roaming the skies on their own accord. These creatures are often depicted as swirling masses of air and wind, with no distinct form or features.\n\nAir elementals are known for their incredible speed and agility, as well as their ability to manipulate the air around them to create powerful gusts of wind and even tornadoes. They are also able to fly effortlessly through the air, making them formidable opponents in combat.\n\nIn terms of behavior, air elementals are often considered to be aloof and unpredictable, as they are not bound by mortal desires or emotions. They are typically neutral in alignment, and may be prone to ignoring or even attacking creatures that they perceive as a threat to the natural balance of the world.\n\nOverall, air elementals are fascinating and enigmatic creatures that embody the raw power and unpredictability of the natural world. Crossing paths with one of these beings can be a thrilling and dangerous experience for any adventurer brave enough to face them."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Lightning, Piercing, Slashing',5.0,NULL),
	 ('01990b8b-09a6-7e92-a00e-524971f92a52'::uuid,'Giant Eagle','NeutralGood','1 (XP 200; PB +2)',200,3,'Skirmisher','Large',13,NULL,26,'4d10+4','10 ft.',NULL,NULL,'80 ft.',16,17,13,8,14,10,'{"Perception": 6}','None','Passive Perception 16','Celestial; understands Common and Primordial (Auran) but can''t speak them',1,3,3,2,0,-1,2,'[]',NULL,'Celestial','','{"value":"Wings beat with a thunderous roar as it dives from the sky."}','{"value": "Giant Eagles are majestic and noble creatures that resemble their smaller eagle counterparts but are much larger in size, with wingspans of up to 30 feet. They are known for their keen eyesight, incredible speed, and powerful beaks and talons, making them formidable predators in the skies.\n\nIn D&D 5e, Giant Eagles are often depicted as intelligent and noble creatures that are often seen as symbols of freedom and strength. They are known to be fiercely protective of their territory and will not hesitate to attack any intruders that threaten their nests or young.\n\nGiant Eagles are often used as mounts by powerful figures such as wizards, druids, and rangers who have formed a bond with the creatures. They are also known to be allies of good-aligned adventurers, assisting them in their quests and battles against evil creatures.\n\nOverall, Giant Eagles are revered and respected creatures in the world of D&D, known for their grace, power, and loyalty to those they choose to bond with."}',0,'Monster Manual 2024 (BR)','','Necrotic, Radiant',1.0,NULL),
	 ('01990b5e-323b-79d7-9c74-0e6cf54bf685'::uuid,'Adult Red Dragon','ChaoticEvil','17 (XP 18 000, or 20 000 in lair; PB +6)',18000,12,'Solo','Huge',19,NULL,256,'19d12+133','40 ft.','40 ft.',NULL,'80 ft.',27,10,25,16,13,23,'{"Stealth": 6, "Perception": 13}','Fire','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 23','Common, Draconic',7,6,8,7,6,3,6,'["None"]','Habitat: Hill, Mountain','Dragon','Chromatic','{"value":"Roaring with fiery breath, it curls its massive form protectively around its hoard."}','{"value": "The Adult Red Dragon is a fearsome and powerful creature that is considered one of the most iconic and dangerous monsters in the world of Dungeons and Dragons. These dragons are known for their fiery breath and their insatiable greed for treasure.\n\nAdult Red Dragons are among the most powerful of their kind, with immense strength, intelligence, and magical abilities. They are typically around 200 to 300 years old, and their scales are a deep red color, which helps them blend into their volcanic habitats.\n\nThese dragons are highly territorial and will fiercely defend their lairs and hoards of treasure from any intruders. They are known to be cunning and strategic in their attacks, using their fiery breath and powerful claws to devastate their enemies.\n\nIn D&D lore, Adult Red Dragons are often portrayed as ancient and wise creatures that have amassed great wealth and knowledge over their long lives. They are sometimes depicted as powerful rulers or tyrants in their respective domains, commanding fear and respect from lesser creatures.\n\nOverall, the Adult Red Dragon is a formidable adversary that adventurers must approach with caution and careful planning if they hope to defeat it and claim its treasure for themselves."}',0,'Monster Manual 2024 (BR)','Chromatic','None',17.0,20000.0),
	 ('01990b7f-3b42-75a8-adbb-a786a2106a4c'::uuid,'Archelon','Unaligned','4 (XP 1,100; PB +2)',1100,3,'Skirmisher','Huge',17,NULL,90,'12d12+12','20 ft.',NULL,'80 ft.',NULL,18,16,13,4,14,6,'{"Stealth": 5}','None','Passive Perception 12','None',1,3,4,2,-2,-3,2,'[]',NULL,'Beast','Dinosaur','{"value":"Ancient shell creaks as it lumbers towards you, eyes piercing the murky depths."}','{"value": "Archelon is a massive sea turtle-like creature that roams the depths of the ocean in the world of Dungeons and Dragons. They are known for their immense size, with some individuals reaching up to 100 feet in length and weighing thousands of pounds.\n\nArchelons are ancient creatures, believed to have been around since the beginning of time. They are often seen as symbols of wisdom and longevity, with many sailors and seafarers seeking their guidance and protection on long journeys across the seas.\n\nDespite their peaceful nature, Archelons are formidable creatures when provoked. They have incredibly strong jaws and sharp claws that they use to defend themselves against threats. They are also known for their ability to manipulate water and create powerful tidal waves to subdue their enemies.\n\nIn some cultures, Archelons are seen as guardians of the ocean and are revered as divine beings. They are said to have the ability to communicate with other sea creatures and possess vast knowledge of the seas and its secrets.\n\nEncountering an Archelon in the wild is a rare and awe-inspiring experience, as few have the privilege of seeing such a majestic creature up close. Those who do are often left in awe of its beauty and power, and are forever changed by the encounter."}',0,'Monster Manual 2024 (BR)','Dinosaur','None',4.0,NULL),
	 ('01990b8b-158b-74f5-b03c-a58e29cf540d'::uuid,'Giant Elk','NeutralGood','2 (XP 450; PB +2)',450,6,'Skirmisher','Huge',14,NULL,42,'5d12+10','60 ft.',NULL,NULL,NULL,19,18,14,7,14,10,'{"Perception": 4}','None','Darkvision 90 ft., Passive Perception 14','Celestial; understands Common, Elvish, and Sylvan but can''t speak them',2,6,6,2,0,-2,2,'[]',NULL,'Celestial','','{"value":"Antlers gleam as it stands tall, radiating a regal aura of ancient power."}','{"value": "In the world of Dungeons and Dragons, the Giant Elk is a majestic and powerful creature that roams the forests and mountains. These massive beasts are known for their imposing size, beautiful antlers, and swift speed. They are revered by druids and forest-dwelling creatures for their grace and strength.\n\nGiant Elks are often seen as symbols of the wilderness and are said to have a deep connection to the natural world. They are known to be peaceful creatures, but will fiercely defend their territory if threatened. Some believe that they possess magical abilities, such as the ability to cast spells or communicate with other creatures telepathically.\n\nLegends say that Giant Elks are the steeds of powerful nature spirits or forest deities, and that those who are pure of heart may be granted the honor of riding one. They are also said to be guardians of sacred groves and ancient forests, protecting them from harm and ensuring their survival for generations to come.\n\nEncountering a Giant Elk in the wild is a rare and awe-inspiring experience, and those who are lucky enough to witness one in its natural habitat are said to be blessed by the spirits of the forest."}',0,'Monster Manual 2024 (BR)','','Necrotic, Radiant',2.0,NULL),
	 ('01990b7d-f250-7dd7-b2a2-8ef61034f3e7'::uuid,'Ancient Gold Dragon','LawfulGood','24 (XP 62,000, or 75,000 in lair; PB +7)',62000,16,'Solo','Gargantuan',22,NULL,546,'28d20+252','40 ft.',NULL,'40 ft.','80 ft.',30,14,29,18,17,28,'{"Insight": 10, "Stealth": 9, "Perception": 17, "Persuasion": 16}','Fire','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 27','Common, Draconic',9,9,10,10,9,4,7,'[]','Habitat: Forest, Grassland','Dragon','Metallic','{"value":"Wings outstretched, it breathes fire with a regal presence."}','{"value": "Ancient Gold Dragons are one of the most powerful and majestic creatures in the world of Dungeons and Dragons. They are known for their wisdom, benevolence, and sense of justice. These dragons are often seen as protectors and leaders, using their immense power to defend the innocent and uphold the laws of the land.\n\nAncient Gold Dragons are known for their shimmering golden scales, which are said to be as strong as armor. They are also known for their powerful breath weapon, which is a cone of fire that can incinerate enemies in an instant. In addition to their physical prowess, Ancient Gold Dragons are also highly intelligent and possess a deep knowledge of magic and lore.\n\nThese dragons are often revered by other creatures as wise and powerful beings. They are seen as symbols of hope and protection, and many civilizations have stories and legends about the heroic deeds of Ancient Gold Dragons. However, these dragons are not to be trifled with, as they can be fierce and deadly foes to those who threaten the innocent or seek to do harm.\n\nOverall, Ancient Gold Dragons are creatures of great power and wisdom, and they play a crucial role in the balance of the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','Metallic','None',24.0,NULL),
	 ('01990b7e-89f0-78c5-8bd2-a8f0d3d42a85'::uuid,'Ancient Silver Dragon','LawfulGood','23 (XP 50 000, or 62 000 in lair; PB +7)',50000,14,'Solo','Gargantuan',22,NULL,468,'24d20+216','40 ft.',NULL,NULL,'80 ft.',30,10,29,18,15,26,'{"History": 11, "Stealth": 7, "Perception": 16}','Cold','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 26','Common, Draconic',9,7,10,9,8,4,7,'[]','Habitat: Mountain, Urban','Dragon','Metallic','{"value":"Wings spread wide, its majestic form gleams in the sunlight, eyes full of wisdom."}','{"value": "Ancient Silver Dragons are one of the most powerful and noble creatures in the world of Dungeons and Dragons. They are known for their wisdom, benevolence, and sense of justice. These dragons are considered ancient and are hundreds if not thousands of years old.\n\nAncient Silver Dragons are typically found in remote, icy regions where they can live in solitude and protect their hoard of treasure. They are known to be wise advisers and mentors to those who seek their guidance. These dragons are also fierce protectors of the innocent and will go to great lengths to defend those in need.\n\nIn combat, Ancient Silver Dragons are formidable opponents, possessing incredible strength, magical abilities, and a breath weapon that can freeze their enemies in their tracks. Despite their power, these dragons are usually peaceful and prefer to use their abilities to aid others rather than harm them.\n\nOverall, Ancient Silver Dragons are revered and respected by all who know of them, and encountering one is considered a rare and special event in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','Metallic','None',23.0,62000.0),
	 ('01990b7e-e2db-7f94-980d-c3d816ea0774'::uuid,'Animated Rug of Smothering','Unaligned','2 (XP 450; PB +2)',450,4,'Brute','Large',12,NULL,27,'5d10','10 ft.',NULL,NULL,NULL,17,14,10,1,3,1,'{}','Poison, Psychic; Charmed, Deafened, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned','Blindsight 60 ft., Passive Perception 6','—',0,2,3,-4,-5,-5,2,'[]','Habitat: Urban','Construct','','{"value":"Threads writhe and twist, hungrily reaching out with unseen hands."}','{"value": "The Animated Rug of Smothering is a unique and dangerous creature that appears as an ordinary rug until it springs to life and attacks unsuspecting victims. These creatures are created through dark magic or cursed artifacts and are typically found in abandoned homes or dungeons.\n\nThe Animated Rug of Smothering is known for its ability to wrap itself around a target and suffocate them, using its fabric to constrict and crush its prey. It is also capable of blending into its surroundings, making it difficult to detect until it is too late.\n\nThese creatures are often used as guardians by powerful wizards or necromancers, who use them to protect their lairs from intruders. They are relentless in their pursuit of prey and will not stop until their target is dead or incapacitated.\n\nAdventurers who encounter an Animated Rug of Smothering should exercise caution and be prepared for a tough fight. They are resistant to physical attacks and can quickly overwhelm a party if not dealt with swiftly. Fire and other forms of elemental damage are particularly effective against these creatures.\n\nOverall, the Animated Rug of Smothering is a terrifying and deadly monster that should not be underestimated in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01992ad6-4bdf-7ead-9340-6128c2d5bfa3'::uuid,'Skyborne Kobold Apex','TrueNeutral','1/4',50,2,'Solo','Small',16,NULL,38,'','30 ft.',NULL,NULL,'30 ft.',16,16,16,2,10,3,'{}','None','Darkvision 60 ft., Passive Perception 8','Common, Draconic',5,2,5,2,-4,-4,2,'[]','Habitat: Arctic, Coastal, Desert, Forest, Hill, Mountain, Swamp, Underdark, Urban','Dragon','','A nimble and cunning Winged Kobold, adept at outmaneuvering foes in solo combat.','{"originalLore": "In the depths of the ancient forests, there exists a rare and formidable creature known as the Winged Kobold Solo. Unlike its smaller, more common counterparts, the Winged Kobold Solo is a solitary and fearsome predator that roams the skies with unmatched agility and cunning.\n\nThis unique variation of the Winged Kobold possesses larger wings that allow it to soar effortlessly through the air, making it a master of aerial combat. Its sharp claws and teeth are honed to perfection, capable of tearing through even the toughest armor with ease. In addition, the Winged Kobold Solo has developed a keen sense of strategy and tactics, allowing it to outsmart and outmaneuver its opponents in battle.\n\nWhat truly sets the Winged Kobold Solo apart from its brethren is its ability to harness the power of the elements. With a flick of its wings, it can summon gusts of wind to knock its enemies off balance, or call down bolts of lightning to strike fear into their hearts. This elemental mastery, combined with its unmatched speed and agility, makes the Winged Kobold Solo a force to be reckoned with in any encounter.\n\nThose who dare to challenge the Winged Kobold Solo do so at their own peril, for this solitary creature is a true master of the skies and a formidable opponent in solo combat. Only the bravest and most skilled adventurers stand a chance against this fearsome predator, and even then, victory is far from guaranteed."}',0,'AI Generated','','None',0.25,NULL),
	 ('01990b7f-bafc-7ccc-95ae-e252304c63c8'::uuid,'Awakened Shrub','TrueNeutral','0 (XP 10; PB +2)',10,-1,'Ambusher','Small',9,NULL,10,'3d6','20 ft.',NULL,NULL,NULL,3,8,11,10,10,6,'{}','None','Passive Perception 10','Common plus one other language',0,-1,-4,0,-2,0,2,'[]','Habitat: Forest','Plant','','{"value":"Rustling leaves signal the awakened shrub\u0027s curious approach, vines reaching out tentatively."}','{"value": "In the world of Dungeons and Dragons, an Awakened Shrub is a magical creature that was once a simple shrub or plant that has been granted sentience and intelligence through the use of powerful magic. This transformation can occur through the casting of spells such as Awaken or through the intervention of a powerful druid or other magical being.\n\nAwakened Shrubs are typically peaceful creatures that live in harmony with nature, often serving as guardians of the forests or other natural areas. They have the ability to communicate with other creatures, although their methods of communication may be limited to gestures or simple sounds.\n\nDespite their small size and seemingly harmless appearance, Awakened Shrubs can be surprisingly resilient and resourceful in defending themselves and their homes. They may use their sharp thorns to protect themselves from predators or weave themselves into intricate patterns to confuse and trap their enemies.\n\nOverall, Awakened Shrubs are fascinating creatures that add an element of magic and mystery to the world of Dungeons and Dragons, serving as both allies and potential threats to adventurers who encounter them in their journeys."}',0,'Monster Manual 2024 (BR)','','Piercing',0.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b7f-fb4d-72ea-b12c-7ca4ef065e45'::uuid,'Baboon','Unaligned','0 (XP 10; PB +2)',10,2,'Minion','Small',12,NULL,3,'1d6','30 ft.','30 ft.',NULL,NULL,8,14,11,4,12,6,'{}','None','Passive Perception 11','None',0,2,-1,1,-2,-3,2,'[]',NULL,'Beast','','{"value":"Grunting loudly, it beats its chest and bares its sharp teeth."}','{"value": "In Dungeons and Dragons 5th Edition, the baboon is a creature that typically dwells in forests and jungles. They are known for their aggressive and territorial nature, often attacking intruders who encroach on their territory. Baboons are highly social animals, often forming large troops led by a dominant male.\n\nIn D&D lore, baboons are considered to be cunning and opportunistic creatures, using their numbers and agility to overwhelm their enemies. They are known for their sharp teeth and claws, which they use in both hunting and self-defense.\n\nBaboons are often depicted as chaotic neutral creatures, acting on their instincts and desires without much regard for morality. They are sometimes used as minions by more powerful creatures, such as hags or witches, who use the baboons'' natural strength and ferocity to their advantage.\n\nOverall, baboons are seen as dangerous and unpredictable creatures in the world of Dungeons and Dragons, making them a formidable foe for adventurers to face in the wilds."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b80-4e48-7e0a-b4f7-f36d9a12e863'::uuid,'Bandit Captain','TrueNeutral','2 (XP 450; PB +2)',450,3,'Leader','Medium',15,NULL,52,'8d8+16','30 ft.',NULL,NULL,NULL,15,16,14,14,11,14,'{"Athletics": 4, "Deception": 4}','None','Passive Perception 10','Common, Thieves'' Cant',2,5,4,2,2,2,2,'["Pistol", "Scimitar", "Studded Leather Armor"]','Habitat: Any','Humanoid','','{"value":"Leader sneers, fingers tapping sword hilt with a menacing glint in their eye."}','{"value": "The Bandit Captain is a cunning and ruthless leader of a bandit group, often found terrorizing villages and travelers in the countryside. They are typically skilled in combat and have a keen strategic mind, making them a formidable opponent for any adventurers who cross their path.\n\nBandit Captains are known for their ability to inspire and lead their followers, using intimidation and fear to maintain control over their bandit gang. They are also skilled in negotiation and diplomacy, often using their charisma to strike deals with other criminal organizations or corrupt officials.\n\nIn combat, Bandit Captains are typically armed with a variety of weapons, such as swords, bows, and crossbows, and are skilled in both melee and ranged combat. They are also known to be skilled in tactics, using ambushes and traps to gain the upper hand in battle.\n\nOverall, Bandit Captains are dangerous foes who should not be underestimated. Their cunning, combat skills, and leadership abilities make them a formidable challenge for any adventurers who dare to cross their path."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b80-b1f0-7b8b-ab88-b3b78569a562'::uuid,'Bat','Unaligned','0 (XP 10; PB +2)',10,2,'Ambusher','Tiny',12,NULL,1,'1d4-1','5 ft.',NULL,NULL,'30 ft.',2,15,8,2,12,4,'{}','None','Blindsight 60 ft., Passive Perception 11','None',1,2,4,1,-3,4,2,'[]',NULL,'Beast','','{"value":"Wings flutter wildly as it screeches, sending echoes bouncing through the cavern."}','{"value": "In Dungeons and Dragons 5th edition, bats are often depicted as small, flying creatures that are typically found in caves, forests, and other dark places. They are known for their ability to navigate in the dark using echolocation, allowing them to hunt for insects and other small prey.\n\nBats in D&D are often portrayed as harmless creatures that are more of a nuisance than a threat to adventurers. However, some larger species of bats, such as vampire bats or giant bats, can be more dangerous and aggressive.\n\nIn some D&D campaigns, bats are also associated with vampires and other undead creatures, as they are often depicted as being attracted to blood. They may serve as minions to vampires or other evil beings, or may be transformed into monstrous bat-like creatures themselves.\n\nOverall, bats in D&D are typically portrayed as curious, nocturnal creatures that are more likely to flee from danger than to engage in combat. However, they can still pose a threat to unwary adventurers, particularly if they are encountered in large numbers or in conjunction with more powerful foes."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b8b-2ced-79cb-ae4a-ef2b82e713db'::uuid,'Giant Fire Beetle','Unaligned','0 (XP 10; PB +2)',10,0,'Ambusher','Small',13,NULL,4,'1d6+1','30 ft.','30 ft.',NULL,NULL,8,10,12,1,7,3,'{}','None','Blindsight 30 ft., Passive Perception 8','None',1,0,-1,-2,-4,-5,2,'[]',NULL,'Beast','','{"value":"Antennae flicker and glow as it scuttles towards you, leaving a trail of embers."}','{"value": "In the world of Dungeons and Dragons, the Giant Fire Beetle is a creature that is typically found in dark, underground environments such as caves, tunnels, and dungeons. These creatures are known for their luminescent glands that emit a bright red light, which they use to navigate in the darkness and attract prey. \n\nGiant Fire Beetles are generally not aggressive towards creatures larger than themselves, but they will defend themselves if they feel threatened. They are commonly used by adventurers and miners as a source of light, as their glands can be harvested and used as torches or lanterns. \n\nIn some regions, Giant Fire Beetles are also seen as symbols of good luck or protection, and are often kept as pets or companions by those who live in dark environments. Despite their small size, Giant Fire Beetles are considered valuable creatures due to their unique abilities and usefulness in various situations."}',0,'Monster Manual 2024 (BR)','','Fire',0.0,NULL),
	 ('01990b80-f7ef-7df9-a111-03f3fcccb61e'::uuid,'Behir','NeutralEvil','11 (XP 7 200; PB +4)',7200,3,'Brute','Huge',17,NULL,168,'16d12+64','50 ft.','50 ft.',NULL,NULL,23,16,18,7,14,12,'{"Stealth": 7, "Perception": 6}','Lightning','Darkvision 90 ft., Passive Perception 16','Draconic',4,3,6,2,1,-2,4,'[]','Habitat: Underdark','Monstrosity','','{"value":"Serpentine coils writhe and snap, crackling with electricity."}','{"value": "The Behir is a massive, serpentine creature with a body covered in blue scales and a long, snakelike neck ending in a head filled with sharp teeth. They are known for their lightning-fast movements and powerful electrical breath attacks, making them formidable foes in battle.\n\nBehirs are typically solitary creatures that dwell in rocky terrain, such as mountain ranges or deep caves. They are known to be territorial and will fiercely defend their lairs from intruders. Despite their fierce nature, Behirs are not inherently evil and may be willing to negotiate with adventurers if they are approached diplomatically.\n\nIn terms of behavior, Behirs are known to be cunning hunters that use their lightning breath to stun and incapacitate their prey before devouring them whole. They are also known to be capable of forming alliances with other creatures, such as dragons or giants, in order to increase their power and influence in the region.\n\nOverall, Behirs are powerful and dangerous creatures that should not be underestimated by adventurers seeking to challenge them in combat. Their lightning breath and lightning-fast movements make them a formidable opponent that requires careful planning and strategy to defeat."}',0,'Monster Manual 2024 (BR)','','None',11.0,NULL),
	 ('01990b81-5e6c-787c-bf13-6a2af60608ec'::uuid,'Black Dragon Wyrmling','ChaoticEvil','2 (XP 450; PB +2)',450,4,'Solo','Medium',17,NULL,33,'6d8+6','30 ft.',NULL,'30 ft.','60 ft.',15,14,13,10,11,13,'{"Stealth": 4, "Perception": 4}','Acid','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Draconic',1,4,2,2,1,0,2,'[]','Habitat: Swamp','Dragon','Chromatic','{"value":"Smoke curls from its nostrils as it eyes you with malicious intent."}','{"value": "Black Dragon Wyrmlings are young, immature black dragons that are just beginning to establish their territory and power. They are typically around 5-10 years old and are already formidable creatures despite their young age. \n\nThese wyrmlings are known for their cunning and malicious personalities, often delighting in causing fear and destruction. They are capable of breathing a powerful stream of acid, which they use to dissolve their enemies and protect their lairs. \n\nBlack Dragon Wyrmlings are solitary creatures, preferring to live in swamps, marshes, or underground caves where they can easily ambush unsuspecting prey. They are fiercely territorial and will aggressively defend their territory from any intruders. \n\nAs they grow older and more powerful, black dragons become even more dangerous, developing a keen intelligence and a thirst for power and domination. Adventurers who encounter a Black Dragon Wyrmling should proceed with caution, as these creatures are not to be underestimated."}',0,'Monster Manual 2024 (BR)','Chromatic','None',2.0,NULL),
	 ('01990b81-e3f7-7278-9efc-6bde7f31552b'::uuid,'Blue Slaad','ChaoticNeutral','7 (XP 2 900; PB +3)',2900,2,'Solo','Large',15,NULL,133,'14d10+56','30 ft.',NULL,NULL,NULL,20,15,18,7,7,9,'{"Perception": 1}','None','Darkvision 60 ft., Passive Perception 11','Slaad; telepathy 60 ft.',4,2,5,-2,-1,-2,3,'[]','Habitat: Planar (Limbo)','Aberration','','{"value":"Eyes gleam with a chaotic hunger as it lunges forward, saliva dripping from its fangs."}','{"value": "The Blue Slaad is a chaotic evil creature from the Outer Planes, specifically the plane of Limbo. They are known for their aggressive and unpredictable behavior, often causing chaos and destruction wherever they go.\n\nBlue Slaads are amphibious humanoids with blue skin and sharp claws. They have a powerful bite attack that can infect their victims with a disease known as Slaad Fever, which slowly transforms the victim into a Slaad over time.\n\nThese creatures are often summoned by powerful spellcasters as guardians or enforcers, and can also be found leading groups of other Slaads in raids and attacks on settlements. Blue Slaads are highly intelligent and cunning, making them formidable foes in combat.\n\nIn terms of their lore, Blue Slaads are said to be the result of a curse placed on a powerful wizard who sought to control the chaotic energies of Limbo. The curse transformed the wizard into the first Blue Slaad, and from there, the species multiplied and spread throughout the planes.\n\nOverall, Blue Slaads are feared and respected for their strength and cunning, and are a formidable threat to any adventurers who cross their path."}',0,'Monster Manual 2024','','Acid, Cold, Fire, Lightning, Thunder',7.0,NULL),
	 ('01990b82-5265-7740-9f5d-9b24c2e84c2f'::uuid,'Brazen Gorgon','Unaligned','9 (XP 5 000; PB +4)',5000,2,'Brute','Large',19,NULL,161,'17d10+68','40 ft.',NULL,NULL,NULL,18,14,19,2,14,7,'{"Perception": 10}','Fire; Exhaustion, Petrified','Darkvision 60 ft., Passive Perception 20','—',4,2,4,2,-2,-4,4,'[]','Habitat: Forest, Grassland, Hill','Construct','','{"value":"Steely eyes glare as it stamps its hooves, ready to charge at any moment"}','{"value": "The Brazen Gorgon is a fearsome creature that resembles a large, metallic bull with burning eyes and sharp horns. It is said to have been created by powerful sorcerers in ancient times as a guardian for their most valuable treasures.\n\nThe Brazen Gorgon is known for its ability to turn creatures to stone with a single gaze, much like the mythical Medusa. Its metallic skin is nearly impenetrable, making it a formidable opponent in battle. It is also said to possess a powerful breath weapon that can unleash a blast of fire, causing great destruction to anything in its path.\n\nLegends say that the Brazen Gorgon can only be defeated by a hero who is able to outwit its powerful gaze and find a way to break through its impenetrable hide. Those who are able to defeat the Brazen Gorgon are said to be rewarded with its vast treasure hoard, making it a sought-after challenge for adventurers seeking fame and fortune."}',0,'Monster Manual 2024','','None',9.0,NULL),
	 ('01990b82-dddb-79c5-acc6-1d9d0ab13c9a'::uuid,'Bulette','Unaligned','5 (XP 1 800; PB +3)',1800,0,'Brute','Large',17,NULL,94,'9d10+45','40 ft.',NULL,NULL,NULL,19,11,21,2,10,5,'{"Perception": 6}','None','Darkvision 60 ft., Tremorsense 120 ft., Passive Perception 16','—',5,0,4,0,-3,-4,3,'[]','Habitat: Grassland, Hill, Mountain','Monstrosity','','{"value":"Earth shakes as it burrows beneath the surface, hungry for prey."}','{"value": "The Bulette, also known as the Land Shark, is a fearsome monster that resembles a cross between a snapping turtle and a bulldog. These massive creatures are known for their ferocious appetite and their ability to burrow through the earth with incredible speed, often surprising their prey from below.\n\nAccording to D&D lore, Bulettes are solitary predators that roam the wilderness in search of food. They are known for their insatiable hunger and are capable of devouring almost anything that crosses their path, including livestock, travelers, and even other monsters.\n\nBulettes are highly territorial creatures and will fiercely defend their territory from any intruders. They are also known for their tough armor-like hide, which makes them difficult to defeat in combat. Adventurers who encounter a Bulette are advised to exercise extreme caution and prepare for a tough battle.\n\nIn some D&D campaigns, Bulettes are sometimes used as mounts by powerful creatures or even intelligent races. However, taming a Bulette is a dangerous and difficult task, as these creatures are wild and unpredictable by nature.\n\nOverall, Bulettes are considered one of the most dangerous monsters in the D&D universe, and encountering one is often a harrowing and deadly experience for adventurers."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b83-42cf-7519-b33f-ea568b9da725'::uuid,'Carrion Crawler','Unaligned','2 (XP 450; PB +2)',450,1,'Ambusher','Large',13,NULL,51,'6d10+18','30 ft.','30 ft.',NULL,NULL,14,13,16,1,12,5,'{"Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','None',3,1,2,1,-3,-5,2,'[]','Habitat: Underdark, Urban','Monstrosity','','{"value":"It skitters silently, sniffing the air with twitching antennae"}','{"value": "In the world of Dungeons and Dragons, the Carrion Crawler is a monstrous, insect-like creature that feeds on dead bodies and decaying flesh. It is known for its long, tentacle-like appendages that it uses to grab and paralyze its prey before devouring it.\n\nCarrion Crawlers are often found in dark, damp environments such as caves, sewers, and graveyards. They are typically solitary creatures, but can sometimes be found in small groups or nests.\n\nIn D&D lore, Carrion Crawlers are considered to be a lower-level threat, but their paralyzing tentacles and ability to ambush unsuspecting adventurers make them dangerous opponents. They are often depicted as mindless predators driven solely by their insatiable hunger for flesh.\n\nMany adventurers fear encountering Carrion Crawlers, as their paralyzing attacks can leave victims vulnerable to being devoured alive. However, those who are able to defeat these creatures can often find valuable treasures hidden in their lairs, as Carrion Crawlers are known to collect and hoard shiny objects and trinkets."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b83-a488-7fca-a5dc-87c3fd0c8b43'::uuid,'Chain Devil','LawfulEvil','8 (XP 3 900; PB +3)',3900,5,'Controller','Medium',15,NULL,85,'10d8+40','30 ft.',NULL,NULL,NULL,18,15,18,11,12,14,'{}','Fire, Poison; Poisoned','Darkvision 120 ft. (unimpeded by magical Darkness), Passive Perception 11','Infernal; telepathy 120 ft.',7,2,4,4,2,0,3,'[]','Habitat: Planar (Nine Hells)','Fiend','Devil','{"value":"Chains rattle as it lashes out, eyes gleaming with sadistic glee."}','{"value": "In Dungeons and Dragons 5th Edition, the Chain Devil, also known as the Kyton, is a fiendish creature from the lower planes that delights in tormenting and binding souls. They are often found in the service of more powerful devils, acting as jailers and torturers in the infernal hierarchy.\n\nChain Devils appear as humanoid figures covered in chains and barbed wire, their elongated limbs and sharp features giving them a menacing and cruel appearance. They are skilled in combat, using their chains to entangle and restrain their enemies while inflicting painful wounds with their barbs.\n\nThese fiends are known for their ability to manipulate and control chains, using them to entrap and immobilize their victims. They are also adept at creating illusions and can cast spells to further confuse and disorient their foes.\n\nIn terms of lore, Chain Devils are typically depicted as sadistic and malevolent beings, reveling in the suffering of others and taking pleasure in the torment they inflict. They are often used as enforcers and taskmasters in the Nine Hells, carrying out the will of their infernal masters with ruthless efficiency.\n\nOverall, Chain Devils are a fearsome and dangerous adversary in the world of Dungeons and Dragons, embodying the dark and cruel nature of the lower planes. Players who encounter these fiends should be prepared for a brutal and unforgiving fight, as the Chain Devil will stop at nothing to break their will and claim their soul for the forces of evil."}',0,'Monster Manual 2024 (BR)','Devil','Bludgeoning, Cold, Piercing, Slashing',8.0,NULL),
	 ('01990b84-4e29-7bd4-a153-266dabb756b2'::uuid,'Cloaker','ChaoticNeutral','8 (XP 3 900; PB +3)',3900,5,'Ambusher','Large',14,NULL,91,'14d10+14','10 ft.',NULL,NULL,'40 ft.',17,15,12,13,14,7,'{"Stealth": 5}','Frightened','Darkvision 120 ft., Passive Perception 12','Deep Speech, Undercommon',1,2,3,2,-2,1,3,'[]','Habitat: Underdark','Aberration','','{"value":"Shadows coil and writhe, its eerie whispers filling the air."}','{"value": "The Cloaker is a mysterious and enigmatic creature that is believed to have originated from the Shadowfell, a dark and shadowy plane of existence. These creatures resemble large, dark cloaks that have the ability to come to life and move on their own. They are often found lurking in dark and desolate places, such as abandoned tombs, crypts, and dungeons.\n\nCloakers are known for their ability to manipulate shadows and create illusions, making them formidable opponents in battle. They have a keen sense of hearing and are able to detect the slightest sounds, allowing them to surprise their prey with ease. They also possess a powerful hypnotic ability that can cause their victims to become disoriented and confused.\n\nDespite their sinister appearance and abilities, Cloakers are not inherently evil creatures. They are solitary beings that prefer to keep to themselves, but they can become aggressive if they feel threatened or if their territory is encroached upon. Some believe that Cloakers are guardians of the Shadowfell, tasked with protecting its secrets and preventing outsiders from entering.\n\nOverall, the Cloaker is a mysterious and intriguing creature that adds an element of darkness and mystery to any Dungeons and Dragons campaign. Players must beware when encountering these creatures, as their illusions and hypnotic powers can easily lead to their downfall."}',0,'Monster Manual 2024 (BR)','','None',8.0,NULL),
	 ('01990b83-2033-7382-8aab-247d25978bb6'::uuid,'Cambion','NeutralEvil','5 (XP 1 800; PB +3)',1800,4,'Solo','Medium',19,NULL,105,'14d8+42','30 ft.',NULL,NULL,'60 ft.',18,18,16,14,12,16,'{"Stealth": 7, "Deception": 6, "Perception": 4}','Poisoned','Darkvision 120 ft., Passive Perception 14','Abyssal, Common, Infernal',6,4,7,1,6,5,3,'[]','Habitat: Any','Fiend','','{"value":"Eyes smoldering with malice, it grins as flames dance on its fingertips."}','{"value": "In Dungeons and Dragons, a Cambion is a fiendish creature that is the offspring of a demon and a humanoid. They are usually born from a devil seducing a mortal, resulting in a half-fiend with powers and abilities inherited from both of its parents.\n\nCambions are typically depicted as being cunning, charismatic, and manipulative, using their charm and dark powers to further their own goals. They have a natural affinity for magic, often specializing in spells that manipulate the minds of others or cause harm and destruction.\n\nIn terms of appearance, Cambions often exhibit a mix of features from both demon and humanoid ancestry. They may have horns, wings, or a tail, as well as a dark and sinister aura that marks them as creatures of evil.\n\nOverall, Cambions are dangerous foes to encounter in the world of Dungeons and Dragons, using their fiendish powers and cunning intellect to further their own dark agendas."}',0,'Monster Manual 2024','','Cold, Fire, Lightning, Poison',5.0,NULL),
	 ('01990b84-f750-704b-b607-e7db69ae8bfa'::uuid,'Crab','Unaligned','0 (XP 10; PB +2)',10,0,'Ambusher','Tiny',11,NULL,3,'1d4+1','20 ft.',NULL,'20 ft.',NULL,6,11,12,1,8,2,'{"Stealth": 2}','None','Blindsight 30 ft., Passive Perception 9','None',1,0,2,1,4,5,2,'[]',NULL,'Beast','','{"value":"Scuttling sideways, its pincers snap menacingly at the air."}','{"value": "In Dungeons and Dragons 5th Edition, the Crab is a creature that is commonly found in coastal regions and underwater environments. These creatures are known for their tough exoskeletons and powerful pincers, which they use to defend themselves and hunt for prey.\n\nCrabs are typically considered to be neutral creatures, not actively seeking out conflict with other beings unless provoked. They are opportunistic feeders, scavenging for food along the ocean floor and preying on smaller creatures that they can catch with their sharp claws.\n\nIn some D&D campaigns, crabs may be summoned or controlled by aquatic creatures such as merfolk or sahuagin to serve as guardians or soldiers. They are also sometimes featured in underwater encounters, where they can pose a threat to adventurers exploring sunken ruins or underwater caves.\n\nOverall, crabs in D&D are often portrayed as simple yet formidable creatures that add an element of danger and unpredictability to encounters in aquatic environments."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b85-4434-7b51-b818-6081ba89fb69'::uuid,'Cyclops Oracle','ChaoticNeutral','10 (XP 5 900; PB +4)',5900,8,'Leader','Huge',16,NULL,207,'18d12+90','40 ft.',NULL,NULL,NULL,22,11,20,16,18,10,'{"History": 11, "Perception": 12}','None','Truesight 30 ft., Passive Perception 22','Giant',9,0,6,8,0,3,4,'[]','Habitat: Coastal, Desert, Grassland, Hill, Mountain, Underdark','Giant','','{"value":"Its single eye glows with ancient wisdom, scanning the party with eerie precision."}','{"value": "In the world of Dungeons and Dragons, the Cyclops Oracle is a powerful and mystical giant known for its ability to see into the future and provide valuable insights and prophecies. These creatures are typically solitary and reclusive, living in remote mountain caves or ancient ruins where they meditate and commune with the spirits and gods.\n\nCyclops Oracles are revered by many as wise seers and advisers, sought out by kings, adventurers, and other powerful figures for their knowledge and foresight. They are said to possess a deep connection to the divine and are able to channel the powers of the gods to grant blessings or curses upon those who seek their counsel.\n\nIn combat, Cyclops Oracles are formidable opponents, using their immense strength and powerful spells to overwhelm their enemies. They are known for their ability to cast powerful divination magic, allowing them to predict their opponents'' movements and plan their attacks accordingly. They are also skilled healers, able to use their magic to mend wounds and cure ailments.\n\nOverall, the Cyclops Oracle is a mysterious and enigmatic creature, shrouded in legend and myth. Those who seek out these powerful beings do so at their own risk, as their prophecies and advice may come with unforeseen consequences."}',0,'Monster Manual 2024','','None',10.0,NULL),
	 ('01990b85-9ad3-7cf9-9f96-7a873a5297f8'::uuid,'Death Knight','ChaoticEvil','17 (XP 18 000; PB +6)',18000,12,'Brute','Medium',20,NULL,199,'21d8+105','30 ft.',NULL,NULL,NULL,20,11,20,12,16,18,'{}','Necrotic, Poison; Exhaustion, Frightened, Poisoned','Darkvision 120 ft., Passive Perception 13','Abyssal, Common',5,6,5,9,4,1,6,'[]','Habitat: Any','Undead','','{"value":"Shadows swirl around as Death Knight raises its sword, eyes blazing with malevolence."}','{"value": "In Dungeons and Dragons 5th edition, the Death Knight is a powerful undead warrior who was once a noble and valiant knight in life. However, after making a pact with dark forces or being corrupted by evil, they have been transformed into a fearsome and merciless servant of death.\n\nDeath Knights are often seen leading armies of undead or acting as powerful lieutenants for evil overlords. They are skilled in combat, wielding powerful weapons and dark magic to strike down their enemies. They are also resistant to many forms of damage and can only be truly destroyed by dealing with the source of their power or by using powerful magical weapons.\n\nDespite their monstrous appearance and evil nature, some Death Knights retain fragments of their former selves, struggling with the memories of their past lives and the guilt of their actions. Others fully embrace their new existence, reveling in the power and fear they inspire.\n\nOverall, Death Knights are formidable foes in the world of Dungeons and Dragons, serving as iconic villains that challenge even the most seasoned adventurers."}',0,'Monster Manual 2024','','None',17.0,NULL),
	 ('01990b85-d00a-72af-b30c-bff27584b0ad'::uuid,'Demilich','NeutralEvil','18 (XP 20 000, or 22 000 in lair; PB +6)',20000,17,'Solo','Tiny',20,NULL,180,'72d4','5 ft.',NULL,NULL,'30 ft.',1,20,10,20,17,20,'{}','Necrotic, Poison, Psychic; Charmed, Deafened, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned, Prone, Stunned','Truesight 120 ft., Passive Perception 13','None',6,5,-5,9,5,11,6,'[]','Habitat: Any','Undead','','{"value":"Eyes glow with malevolent intelligence as it floats silently, a spectral presence."}','{"value": "In Dungeons and Dragons 5th Edition, the Demilich is a powerful undead creature that was once a lich but has since transcended its mortal form. These creatures are incredibly powerful spellcasters, using their magical abilities to manipulate the world around them.\n\nThe Demilich is known for its insatiable hunger for souls and magical energy, which it consumes to sustain its own existence. They are also known for their mastery of necromancy, allowing them to raise the dead as minions to do their bidding.\n\nDemiliches are incredibly intelligent and crafty, often setting elaborate traps to lure unsuspecting adventurers into their lairs. They are also incredibly difficult to kill, as they can regenerate and reform themselves even if they are destroyed.\n\nOverall, the Demilich is a terrifying and formidable foe that should not be underestimated by any adventurers brave enough to face one."}',0,'Monster Manual 2024','','Bludgeoning, Piercing, Slashing',18.0,22000.0),
	 ('01990b86-24c4-7135-b0fb-44bba7d015fe'::uuid,'Displacer Beast','LawfulEvil','3 (XP 700; PB +2)',700,4,'Skirmisher','Large',13,NULL,76,'9d10+27','40 ft.',NULL,NULL,NULL,18,15,16,6,12,8,'{}','None','Darkvision 60 ft., Passive Perception 11','Understands Sylvan but can''t speak',3,2,4,1,-1,-2,2,'[]','Habitat: Forest','Monstrosity','','{"value":"Stalking silently, its shadow dances eerily out of sync with its true form."}','{"value": "Displacer Beasts are large, sleek, panther-like creatures with six legs and two tentacles sprouting from their shoulders. They are known for their ability to displace their image, making it appear as though they are a few feet away from their actual location. This ability makes them incredibly difficult to hit in combat, as attackers often find themselves striking at empty air while the Displacer Beast attacks from a different position.\n\nIn D&D lore, Displacer Beasts are considered to be highly intelligent and cunning predators. They are typically found in the wild, hunting in packs and preying on smaller creatures. Some Displacer Beasts have been known to be tamed and used as guardians by powerful wizards or other creatures.\n\nIn combat, Displacer Beasts are formidable opponents, using their speed, agility, and displacement ability to outmaneuver their enemies. They are known for their ferocity in battle and will not hesitate to attack anyone who crosses their path.\n\nOverall, Displacer Beasts are feared and respected creatures in the world of Dungeons & Dragons, known for their deadly combination of strength, speed, and deception."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01990b86-d580-7cac-ad52-cb96572ae4c7'::uuid,'Dragon Turtle','TrueNeutral','17 (XP 18 000; PB +6)',18000,6,'Brute','Gargantuan',20,NULL,356,'23d20+115','20 ft.',NULL,'50 ft.',NULL,25,10,20,10,12,12,'{}','None','Darkvision 120 ft., Passive Perception 11','Draconic, Primordial (Aquan)',11,0,7,7,1,0,6,'[]','Habitat: Coastal, Underwater','Dragon','','{"value":"Steam billows from its nostrils as it surveys the intruders with malevolent eyes"}','{"value": "The Dragon Turtle is a massive and ancient creature that resembles a giant turtle with dragon-like features. These powerful beings are known for their immense size, reaching up to 50 feet in length, and their thick, armored shells that are nearly impervious to most attacks.\n\nDragon Turtles are highly territorial and are often found in coastal waters or deep sea caves. They are known for their aggressive nature and their ability to breathe both fire and steam, making them formidable opponents in battle.\n\nLegends tell of Dragon Turtles amassing great treasures in their lairs at the bottom of the ocean, including gold, jewels, and magical artifacts. Many brave adventurers have sought out these treasures, only to meet a fiery end at the jaws of the Dragon Turtle.\n\nDespite their fearsome reputation, some sailors believe that Dragon Turtles can be appeased with offerings of treasure or sacrifices, allowing safe passage through their waters. However, these creatures are unpredictable and should not be underestimated.\n\nOverall, the Dragon Turtle is a legendary and iconic monster in the world of Dungeons and Dragons, feared by sailors and adventurers alike for its immense power and ferocious nature."}',0,'Monster Manual 2024 (BR)','','Fire',17.0,NULL),
	 ('01990b87-6f43-7185-be52-9e481edb9942'::uuid,'Eagle','Unaligned','0 (XP 10; PB +2)',10,2,'Skirmisher','Small',12,NULL,4,'1d6+1','10 ft.',NULL,NULL,'60 ft.',6,15,12,2,14,7,'{"Perception": 6}','None','Passive Perception 16','None',1,2,-2,2,-2,-4,2,'[]',NULL,'Beast','','{"value":"Wings spread wide, its piercing gaze locks onto you from high above."}','{"value": "In Dungeons and Dragons 5th edition, the eagle is a majestic and powerful creature that is known for its keen eyesight and incredible speed. Eagles are often used as symbols of freedom and courage in many cultures, and in the world of D&D, they are often associated with the god of the skies, Akadi.\n\nEagles are large birds of prey that are known for their ability to soar high in the sky and hunt with precision. They are often found in mountainous regions and are known for their impressive hunting skills. Eagles are solitary creatures, preferring to live and hunt alone or in small family groups.\n\nIn D&D, eagles are often used as mounts for adventurers, allowing them to travel quickly and scout out areas from above. They are also sometimes used as familiars for spellcasters, providing them with an extra set of eyes and the ability to deliver messages or spells from a distance.\n\nOverall, eagles are seen as noble and majestic creatures in the world of D&D, embodying the ideals of freedom, courage, and strength."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b88-5c57-7d6c-ab15-6ca99e6111fa'::uuid,'Empyrean Iota','TrueNeutral','1 (XP 200; PB+2)',200,2,'Support','Medium',13,NULL,22,'5d8','5 ft.',NULL,NULL,'30 ft.',1,14,10,15,16,16,'{"History": 4, "Insight": 5, "Perception": 5}','Prone','Truesight 30 ft., Passive Perception 15','All',0,2,-5,3,3,2,NULL,'[]','Habitat: Any','Celestial or Fiend','Titan','{"value":"Its radiant form pulses with divine energy, casting a warm, soothing light."}','{"value": "Empyrean Iota is a powerful celestial being in the world of Dungeons and Dragons. They are known to be the highest ranking of the Empyreans, a group of celestial entities tasked with maintaining balance and order in the universe. Empyrean Iota is said to possess immense strength, wisdom, and magical abilities, making them a formidable force to be reckoned with.\n\nIt is believed that Empyrean Iota resides in the highest planes of existence, where they oversee the affairs of gods and mortals alike. They are said to be benevolent beings, often intervening in conflicts to bring about peace and justice. However, they are also known to be fierce warriors when provoked, capable of unleashing devastating attacks with their divine powers.\n\nLegends speak of Empyrean Iota appearing in times of great need, to aid heroes in their quests and to vanquish evil forces threatening the world. Their presence is said to bring hope and inspiration to all who witness it, and their actions are always guided by a sense of righteousness and compassion.\n\nEncountering Empyrean Iota is a rare and awe-inspiring event, as their presence is a sign of divine intervention and a reminder of the higher powers that watch over the world. Those who are fortunate enough to receive their aid are forever changed, often becoming legendary figures themselves in the annals of history."}',0,'Monster Manual 2024','Titan','Bludgeoning, Piercing, Slashing',1.0,NULL),
	 ('01990b88-ce46-735f-9e5b-f2f222ce4299'::uuid,'Faerie Dragon Youth','ChaoticGood','1 (XP 200; PB +2)',200,3,'Ambusher','Tiny',13,NULL,21,'6d4+6','10 ft.',NULL,NULL,'60 ft.',3,16,12,12,12,14,'{"Arcana": 3, "Stealth": 5, "Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','Draconic, Sylvan; telepathy 60 ft. (faerie dragons only)',1,3,-4,1,2,1,2,'[]','Habitat: Forest','Dragon','','{"value":"Fluttering playfully, it releases shimmering sparks and colorful illusions."}','{"value": "Faerie dragons are mischievous and playful creatures that hail from the Feywild, a realm of magic and whimsy. They are known for their colorful scales, which can change color to match their surroundings, as well as their ability to cast spells and create illusions.\n\nFaerie dragon youth are the younger, less powerful version of adult faerie dragons. They are smaller in size and less experienced in using their magical abilities. Despite their youth, they are still capable of using their innate magical talents to create illusions and cast spells to confuse and confound their enemies.\n\nYoung faerie dragons are often found playing pranks on unsuspecting travelers or using their illusions to hide from predators. They are curious and energetic creatures, always eager to explore new places and meet new creatures.\n\nIn combat, faerie dragon youth rely on their agility and magical abilities to outmaneuver their opponents. They prefer to use their illusions and spells to confuse and distract their enemies, rather than engaging in direct combat. However, if threatened, they can use their sharp claws and teeth to defend themselves.\n\nOverall, faerie dragon youth are charming and whimsical creatures that add a touch of magic and wonder to the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','None',1.0,NULL),
	 ('01990b89-2302-704e-afed-c32fecdbfbd9'::uuid,'Fire Giant','LawfulEvil','9 (XP 5 000; PB +4)',5000,3,'Brute','Huge',18,NULL,162,'13d12+78','30 ft.',NULL,NULL,NULL,25,9,23,10,14,13,'{"Athletics": 11, "Perception": 6}','Fire','Passive Perception 16','Giant',10,3,7,2,5,0,4,'[]','Habitat: Mountain, Underdark','Giant','','{"value":"Roaring flames dance in its eyes, shaking the very ground beneath its colossal form."}','{"value": "Fire Giants are towering, fearsome creatures that hail from the Elemental Plane of Fire. They are known for their immense size, strength, and fiery temperament. Fire Giants are skilled blacksmiths and craftsmen, often forging powerful weapons and armor with which to wage war.\n\nThese giants are ruled by powerful kings and queens who command vast armies of loyal followers. They are often found living in great fortresses or citadels built near active volcanoes, where they can harness the power of fire to fuel their forges and furnaces.\n\nIn battle, Fire Giants are formidable opponents, wielding massive swords and axes that are imbued with the power of flames. They are also known to command fire magic, using spells to incinerate their enemies from a distance.\n\nDespite their fierce reputation, Fire Giants are not always inherently evil. Some may be willing to negotiate or form alliances with other races, especially if it benefits their own interests. However, crossing a Fire Giant is a dangerous endeavor, as they are quick to anger and have little tolerance for perceived weaknesses.\n\nOverall, Fire Giants are a force to be reckoned with in the world of Dungeons and Dragons, and encountering one is sure to be a memorable and potentially deadly experience for any adventuring party."}',0,'Monster Manual 2024 (BR)','','None',9.0,NULL),
	 ('01990b89-9ea8-7d3a-ac20-b5d3c7c2d75b'::uuid,'Fomorian','ChaoticEvil','8 (XP 3 900; PB +3)',3900,0,'Brute','Huge',14,NULL,172,'15d12+75','40 ft.',NULL,NULL,NULL,23,10,20,9,14,6,'{"Stealth": 3, "Perception": 8}','None','Darkvision 120 ft., Passive Perception 18','Giant, Undercommon',5,0,6,2,-2,-1,3,'[]','Habitat: Underdark','Giant','','{"value":"Hulking figure lumbers forward, its single eye glaring with malice."}','{"value": "Fomorians are a type of giant in the world of Dungeons and Dragons, known for their grotesque appearance and evil nature. They are typically described as being hunched and deformed, with one eye larger than the other and skin that is rough and scaly. Fomorians are also known for their immense strength and magical abilities, making them formidable foes in combat.\n\nIn D&D lore, Fomorians are said to be descendants of the giants who once ruled the world. However, they were cast out and banished to the Underdark for their wickedness and cruelty. In their exile, Fomorians have become even more twisted and malevolent, often forming alliances with other dark creatures such as drow and mind flayers.\n\nFomorians are known for their ability to manipulate and control others through their magical powers, as well as their skill in crafting powerful weapons and armor. They are often found ruling over lesser creatures in the Underdark, using fear and intimidation to maintain their power.\n\nOverall, Fomorians are considered to be dangerous and unpredictable adversaries in the world of D&D, and adventurers would do well to approach them with caution and prepare for a challenging battle."}',0,'Monster Manual 2024','','None',8.0,NULL),
	 ('01990b9b-1e93-7b5b-a424-19eba0ef381e'::uuid,'Seahorse','Unaligned','0 (XP 0; PB +2)',10,1,'Support','Tiny',12,NULL,1,'1d4-1','5 ft.',NULL,'20 ft.',NULL,1,12,8,1,10,2,'{"Stealth": 5, "Perception": 2}','None','Passive Perception 12','None',-1,1,-5,0,-4,-5,2,'[]',NULL,'Beast','','{"value":"Gentle seahorse gracefully dances through the shimmering coral, its tail flicking serenely."}','{"value": "In the world of D&D, seahorses are magical creatures that inhabit the depths of the ocean. These creatures are known for their graceful movements and vibrant colors, making them a popular choice for aquatic familiars among spellcasters.\n\nSeahorses are often associated with water deities and are believed to be protectors of the oceans. They are known to be intelligent and curious creatures, with a deep connection to the natural world around them.\n\nIn combat, seahorses are agile and swift, using their long tails to propel themselves through the water with ease. They are known for their sharp teeth and powerful jaws, making them formidable opponents in battle.\n\nSome seahorses are said to possess the ability to create powerful storms or control the tides, making them highly sought after by those who wish to harness their magical abilities.\n\nOverall, seahorses are revered in the world of D&D for their beauty, grace, and mystical powers, making them a fascinating and intriguing creature to encounter in the depths of the ocean."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b89-cc02-773b-8e7d-ec0fac681ce4'::uuid,'Frost Giant','NeutralEvil','8 (XP 3 900; PB +3)',3900,2,'Brute','Huge',15,NULL,149,'13d12+65','40 ft.',NULL,NULL,NULL,23,9,21,9,10,12,'{"Athletics": 9, "Perception": 3}','Cold','Passive Perception 13','Giant',8,-1,6,3,4,-1,3,'[]','Habitat: Arctic, Mountain','Giant','','{"value":"Frost Giant bellows, frosty breath crystallizing in the air around it."}','{"value": "Frost Giants are massive, brutal creatures that dwell in icy tundras and snow-covered mountains. They are known for their incredible strength and skill in combat, as well as their ability to wield massive weapons with ease. Frost Giants are often seen leading armies of other giants into battle, using their size and power to crush their enemies.\n\nIn terms of lore, Frost Giants are typically portrayed as ruthless and cruel beings who have little regard for the lives of others. They are known to raid settlements and villages, stealing food and resources to sustain themselves. They are also known to enslave smaller creatures, forcing them to do their bidding.\n\nFrost Giants are considered to be a constant threat to civilization, as they are always on the lookout for new territories to conquer and plunder. They are also known to be fiercely territorial, defending their homes and territories with extreme aggression.\n\nIn terms of abilities, Frost Giants have a natural resistance to cold damage, as well as the ability to cast spells such as Cone of Cold and Wall of Ice. They are also skilled in combat, using their massive strength and weapons to overwhelm their foes.\n\nOverall, Frost Giants are formidable adversaries that should not be taken lightly by any adventurers brave enough to challenge them."}',0,'Monster Manual 2024 (BR)','','None',8.0,NULL),
	 ('01990b8a-25f7-7f90-82ef-56c581b854da'::uuid,'Ghast','ChaoticEvil','2 (XP 450; PB +2)',450,3,'Ambusher','Medium',13,NULL,36,'8d8','30 ft.',NULL,NULL,NULL,16,17,10,11,10,8,'{}','Poison; Charmed, Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 10','Common',0,3,3,2,-1,0,2,'[]','Habitat: Swamp, Underdark, Urban','Undead','','{"value":"Its rotting form lurches forward, emitting a foul stench of death and decay."}','{"value": "Ghasts are undead creatures found in the world of Dungeons and Dragons. They are created when a humanoid dies and is transformed into a ghoul due to a curse or other dark magic. Over time, a ghoul may transform into a ghast, gaining increased strength, speed, and intelligence.\n\nGhasts are known for their insatiable hunger for flesh and their ability to paralyze their victims with their claws. They are often found in dark, underground lairs, hunting for prey to satisfy their never-ending hunger.\n\nIn D&D lore, ghasts are often depicted as servants of more powerful undead creatures, such as liches or vampires. They are feared by many adventurers for their deadly abilities and relentless pursuit of their victims.\n\nOverall, ghasts are terrifying monsters that embody the dark, twisted nature of undeath in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','','Necrotic',2.0,NULL),
	 ('01990b8a-731a-7d82-a6a2-244770136aeb'::uuid,'Ghoul','ChaoticEvil','1 (XP 200; PB +2)',200,2,'Ambusher','Medium',12,NULL,22,'5d8','30 ft.',NULL,NULL,NULL,13,15,10,7,10,6,'{}','Poison; Charmed, Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 10','Common',0,2,1,0,-2,-2,2,'[]','Habitat: Swamp, Underdark, Urban','Undead','','{"value":"Ravenous ghoul snarls, its milky eyes fixed hungrily on your trembling group."}','{"value": "In Dungeons and Dragons 5th edition, Ghouls are undead creatures that were once humanoids who have been transformed through dark magic and necromancy. Ghouls are depicted as emaciated and ravenous creatures with a never-ending hunger for flesh.\n\nGhouls are known to lurk in graveyards, crypts, and other desolate places, where they hunt for fresh corpses to devour. They are often found in the service of more powerful undead beings, such as vampires or necromancers, who use them as minions to carry out their bidding.\n\nGhouls have a paralyzing touch that can immobilize their victims, making them easy prey for the ghoul''s sharp teeth and claws. They are also known for their ability to regenerate wounds rapidly, making them difficult to kill.\n\nIn terms of lore, ghouls are often seen as cursed beings who have been twisted and corrupted by their insatiable hunger for flesh. Some believe that ghouls are created when a person dies in a particularly traumatic or violent manner, causing their soul to become trapped in their decaying body.\n\nOverall, ghouls are considered to be a terrifying and dangerous threat in the world of Dungeons and Dragons, posing a serious danger to adventurers who dare to venture into their lairs."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b8a-f967-7355-b0f1-3d3afd0d9d5d'::uuid,'Giant Crocodile','Unaligned','5 (XP 1 800; PB +3)',1800,-1,'Brute','Huge',14,NULL,85,'9d12+27','30 ft.',NULL,'50 ft.',NULL,21,9,17,2,10,7,'{"Stealth": 5}','None','Passive Perception 10','None',3,-1,5,0,-2,-4,3,'[]',NULL,'Beast','','{"value":"Jaws snap shut with a thunderous crash, sending water spraying in all directions."}','{"value": "In the world of Dungeons and Dragons, the Giant Crocodile is a fearsome predator that lurks in swamps, marshes, and rivers. These massive reptiles can grow up to 20 feet in length and are known for their powerful jaws and ability to ambush unsuspecting prey.\n\nLegends say that Giant Crocodiles are actually ancient creatures that have been blessed by dark powers, giving them enhanced strength and resilience. Some believe that they are guardians of hidden treasures or sacred sites, while others see them as harbingers of doom and destruction.\n\nIn combat, Giant Crocodiles are relentless hunters, using their stealth and surprise to strike quickly and drag their victims underwater to drown them. They are also known to be territorial creatures, fiercely defending their territory from any intruders.\n\nAdventurers who face off against a Giant Crocodile must be prepared for a tough and dangerous battle, as these creatures are formidable opponents that can easily overpower the unprepared. Only the bravest and most skilled warriors have a chance of surviving an encounter with a Giant Crocodile and emerging victorious."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b8b-68c4-75da-bdfd-0e91a3417e93'::uuid,'Giant Hyena','Unaligned','1 (XP 200; PB +2)',200,2,'Brute','Large',12,NULL,45,'6d10+12','50 ft.',NULL,NULL,NULL,16,14,14,2,12,7,'{"Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','None',2,2,3,1,-2,-4,2,'[]',NULL,'Beast','','{"value":"Looming over you, the Giant Hyena\u0027s laughter echoes with hunger and malice."}','{"value": "Giant hyenas are fearsome predators that roam the wilds in search of their next meal. These creatures are much larger and more aggressive than their smaller counterparts, often hunting in packs to take down larger prey. Known for their powerful jaws and sharp teeth, giant hyenas can easily overpower their victims and tear them apart with ease.\n\nIn some cultures, giant hyenas are seen as symbols of death and destruction, with stories of them roaming the land at night, hunting and feasting on the souls of the living. Others believe that giant hyenas are guardians of the underworld, protecting the gates that separate the living from the dead.\n\nAdventurers who encounter giant hyenas in the wild are advised to proceed with caution, as these creatures are known to be relentless and cunning hunters. With their keen senses and ferocious nature, giant hyenas are not to be underestimated in combat."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b8b-901f-7c6c-b9c1-81c82f45aeaa'::uuid,'Giant Octopus','Unaligned','1 (XP 200; PB +2)',200,1,'Ambusher','Large',11,NULL,45,'7d10+7','10 ft.',NULL,'60 ft.',NULL,17,13,13,5,10,4,'{"Stealth": 5, "Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','None',1,1,3,0,-3,-3,2,'[]',NULL,'Beast','','{"value":"Tentacles undulate gracefully, creating a mesmerizing dance of death."}','{"value": "In Dungeons and Dragons 5th edition, the Giant Octopus is a monstrous creature that dwells in the depths of the ocean. These massive cephalopods are known for their immense size and powerful tentacles, which they use to capture and subdue prey.\n\nGiant Octopuses are highly intelligent creatures, capable of complex problem-solving and strategic thinking. They are also known for their ability to change color and texture to blend in with their surroundings, making them expert hunters and ambush predators.\n\nLegends speak of Giant Octopuses attacking ships and dragging sailors down to a watery grave. Their lairs are often filled with the bones of their victims, serving as a grim reminder of their deadly nature.\n\nAdventurers who dare to venture into the depths where Giant Octopuses dwell must be cautious and prepared for a fierce battle. These creatures are not to be underestimated, as they are formidable opponents with powerful attacks and deadly tactics."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b8c-5715-76de-b2d5-89d34398f6ba'::uuid,'Giant Squid','Unaligned','6 (XP 2 300; PB +3)',2300,2,'Ambusher','Huge',12,NULL,120,'16d12+16','5 ft.',NULL,'80 ft.',NULL,23,14,12,5,11,4,'{"Perception": 6}','None','Darkvision 120 ft., Passive Perception 16','None',1,5,9,0,-3,-3,3,'[]',NULL,'Beast','','{"value":"Tentacles writhe in a hypnotic dance, eyes fixed on its prey."}','{"value": "The Giant Squid is a massive and terrifying creature that lurks in the depths of the ocean. It is said to be the size of a small ship, with long tentacles that can reach out and snatch prey from great distances. The Giant Squid is a solitary predator, hunting alone in the dark depths of the ocean.\n\nLegends say that the Giant Squid is a creature of great intelligence and cunning, able to outsmart even the most seasoned sailors. It is said to be able to change its color and texture to blend in with its surroundings, making it nearly invisible to its prey.\n\nMany sailors fear the Giant Squid, believing it to be a harbinger of doom and death. Some believe that the Giant Squid is a servant of an ancient sea god, sent to wreak havoc on ships that venture too far into its domain.\n\nEncounters with the Giant Squid are rare, but those who have faced it and lived to tell the tale speak of its immense strength and ferocity. It is a formidable opponent, capable of dragging even the largest ships down into the depths of the ocean.\n\nOverall, the Giant Squid is a mysterious and terrifying creature, a true monster of the deep that strikes fear into the hearts of sailors and adventurers alike."}',0,'Monster Manual 2024','','None',6.0,NULL),
	 ('01990b8c-e2d2-7580-8641-ad42503c5094'::uuid,'Githyanki Dracomancer','LawfulEvil','16 (XP 15 000; PB +5)',15000,8,'Artillery','Medium',18,NULL,255,'30d8+120','30 ft.',NULL,NULL,'30 ft.',10,16,18,20,16,18,'{"Arcana": 10, "Perception": 8}','None','Blindsight 30 ft., Passive Perception 18','Common, Draconic, Gith',9,8,0,8,4,10,5,'[]','Habitat: Planar (Astral Plane)','Aberration','Gith','{"value":"Wicked laughter echoes as the Dracomancer commands a shadowy dragon spirit."}','{"value": "The Githyanki Dracomancer is a powerful and rare subclass of the Githyanki race, known for their ability to command and control dragons. They are highly skilled in the arts of magic, particularly when it comes to summoning and binding dragons to their will.\n\nThese Dracomancers are often found leading armies of Githyanki warriors into battle, using their dragon allies to devastating effect. They are feared and respected by their own kind, as well as by other races, for their mastery over these powerful creatures.\n\nThe origins of the Githyanki Dracomancer are shrouded in mystery, with some believing that they have a special connection to the ancient dragon gods worshipped by the Githyanki. Others speculate that they have made pacts with powerful dragons in exchange for their loyalty and service.\n\nRegardless of their origins, the Githyanki Dracomancer is a formidable foe on the battlefield, capable of unleashing devastating magical attacks and commanding dragons with unparalleled skill. They are a force to be reckoned with, and those who cross their path would do well to tread lightly."}',0,'Monster Manual 2024','Gith','None',16.0,NULL),
	 ('01990b5d-969e-73bd-b89a-14660ec2fc19'::uuid,'Adult Copper Dragon','ChaoticGood','14 (XP 11 500, or 13 000 in lair; PB +5)',11500,11,'Solo','Huge',18,NULL,184,'16d12+80','40 ft.','40 ft.',NULL,'80 ft.',23,12,21,18,15,18,'{"Stealth": 6, "Deception": 9, "Perception": 12}','Acid','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 22','Common, Draconic',5,6,6,7,4,4,5,'["None"]','Habitat: Hill','Dragon','Metallic','{"value":"Scales shimmer in the sun as it playfully twirls in the air, eyes gleaming."}','{"value": "Adult Copper Dragons are mischievous and playful creatures known for their love of pranks and riddles. They are skilled shape-shifters and can often be found in the guise of humanoids, animals, or even objects to mess with unsuspecting travelers.\n\nDespite their playful nature, Adult Copper Dragons are also fiercely protective of their territory and will not hesitate to defend it against any threats. They are highly intelligent and cunning creatures, known for their strategic thinking and ability to outwit their enemies.\n\nIn combat, Adult Copper Dragons prefer to use their breath weapon, a powerful cone of acid that can melt through armor and flesh with ease. They are also skilled in physical combat, using their razor-sharp claws and teeth to tear through opponents.\n\nOverall, Adult Copper Dragons are complex creatures with a mix of playful and fierce traits, making them both entertaining and dangerous adversaries for adventurers in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','Metallic','None',14.0,13000.0),
	 ('01990b8d-3ed8-7704-878e-c795835489f4'::uuid,'Gnoll Demoniac','ChaoticEvil','8 (XP 3 900; PB +3)',3900,4,'Leader','Medium',16,NULL,135,'18d8+54','30 ft.',NULL,NULL,NULL,16,12,17,14,15,17,'{"Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','Abyssal, Common, Gnoll',6,1,6,5,6,2,3,'[]','Habitat: Desert, Forest, Grassland, Hill','Fiend','','{"value":"Eyes burn with a manic fervor as it chants in a guttural, unholy tongue"}','{"value": "Gnoll Demoniacs are a rare and terrifying breed of gnolls that have been corrupted by dark forces, usually demonic in nature. These gnolls have made dark pacts with demons, exchanging their souls for increased power and abilities.\n\nGnoll Demoniacs are often distinguishable by their dark, twisted horns, red eyes, and foul-smelling aura of brimstone. They are known to be incredibly cunning and malicious, often using their demonic powers to manipulate and control others.\n\nIn combat, Gnoll Demoniacs are incredibly dangerous foes, possessing powerful demonic abilities such as summoning hellish creatures, casting curses, and even wielding dark magic. They are also skilled in combat, wielding weapons with deadly precision and ferocity.\n\nGnoll Demoniacs are feared and avoided by other gnolls, who view them as harbingers of destruction and chaos. They are usually found leading packs of gnolls on raids and pillaging, spreading terror and chaos wherever they go.\n\nOverall, Gnoll Demoniacs are powerful and malevolent creatures that should be approached with extreme caution by any adventurers brave enough to face them."}',0,'Monster Manual 2024','','None',8.0,NULL),
	 ('01990b8d-9788-7b6a-ab95-b1d2811b9f08'::uuid,'Goblin Hexer','ChaoticNeutral','3 (XP 700; PB +2)',700,3,'Controller','Small',13,NULL,45,'10d6+10','30 ft.',NULL,NULL,NULL,8,16,12,16,10,10,'{"Stealth": 7, "Sleight of Hand": 5}','None','Darkvision 60 ft., Passive Perception 10','Common, Goblin',1,3,-1,0,0,3,2,'[]','Habitat: Forest, Grassland, Hill, Planar (Acheron), Planar (Feywild), Underdark','Fey','Goblinoid','{"value":"Chanting dark incantations, its eyes glow with malevolent magic."}','{"value": "Goblin Hexers are a rare and dangerous type of goblin spellcaster that possess a deep connection to dark magic. They are often shunned and feared by other goblins for their mysterious powers and sinister nature. \n\nGoblin Hexers are known to use their magical abilities to curse their enemies, causing them to suffer from various afflictions and misfortunes. They are also skilled in summoning dark spirits and creatures to aid them in battle.\n\nIt is said that Goblin Hexers gain their powers from making pacts with malevolent entities or dark gods, granting them the ability to wield powerful magic in exchange for their loyalty and service.\n\nThese creatures are often found leading groups of goblins or other monsters, using their magic to bolster their forces and strike fear into their enemies. They are cunning and deceitful, using their powers to manipulate and control those around them.\n\nEncountering a Goblin Hexer in the wild is a dangerous proposition, as they are known to be ruthless and merciless in their pursuit of power and control. Only the bravest and most skilled adventurers dare to challenge these malevolent spellcasters and their dark magic."}',0,'Monster Manual 2024','Goblinoid','None',3.0,NULL),
	 ('01990b8e-06e6-76cf-8783-5dcb254f41d6'::uuid,'Graveyard Revenant','TrueNeutral','7 (XP 2 900; PB +3)',2900,2,'Brute','Huge',14,NULL,161,'14d12+70','40 ft.',NULL,NULL,NULL,20,14,20,13,16,18,'{}','Poison; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned, Stunned, Unconscious','Darkvision 120 ft., Passive Perception 13','Common plus two other languages',8,2,8,6,7,1,3,'[]','Habitat: Forest, Swamp, Urban','Undead','','{"value":"Eyes glow with vengeful fury as it rises from the earth, bones cracking."}','{"value": "The Graveyard Revenant is a terrifying undead creature that is said to be created when a powerful necromancer raises the dead from a graveyard. These creatures are driven by a deep hatred for the living and seek to bring death and destruction wherever they go.\n\nGraveyard Revenants are typically humanoid in appearance, with rotting flesh, glowing red eyes, and a chilling aura of death surrounding them. They are incredibly strong and resilient, able to shrug off most physical attacks with ease.\n\nOne of the most terrifying aspects of the Graveyard Revenant is its ability to drain the life force from its victims, sapping their strength and vitality with a mere touch. This draining effect can leave even the bravest adventurers weak and vulnerable in its presence.\n\nMany believe that the only way to truly defeat a Graveyard Revenant is to destroy the necromancer who created it, as the creature''s ties to the living world are said to be severed upon the necromancer''s death. Until then, these undead horrors will continue to roam the land, spreading fear and suffering wherever they go."}',0,'Monster Manual 2024','','Necrotic, Psychic',7.0,NULL),
	 ('01990b95-a6d5-74fd-8c6a-a63625a64b8f'::uuid,'Noble','TrueNeutral','1/8 (XP 25; PB +2)',25,1,'Leader','Medium',15,NULL,9,'2d8','30 ft.',NULL,NULL,NULL,11,12,11,12,14,16,'{"Insight": 4, "Deception": 5, "Persuasion": 5}','None','Passive Perception 12','Common plus two other languages',0,1,0,2,3,1,2,'["Breastplate", "Rapier"]','Habitat: Any','Humanoid','','{"value":"Regal creature surveys its domain with a cold, calculating gaze"}','{"value": "Nobles in D&D 5e are typically wealthy, influential individuals who come from noble families and hold positions of power in society. They are often depicted as arrogant, entitled, and self-important, and may have a sense of superiority over others.\n\nIn terms of gameplay, nobles may serve as quest-givers, allies, or enemies for the players to interact with. They may have access to resources such as guards, servants, and wealth, making them formidable opponents or valuable allies depending on how the players choose to approach them.\n\nNobles may have ties to political factions, guilds, or other organizations, and may use their influence to further their own agendas or manipulate others. They may also have secrets or hidden motives that the players can uncover through investigation or social interaction.\n\nOverall, nobles in D&D 5e add depth and intrigue to the world, providing opportunities for roleplaying, social encounters, and political intrigue in the game."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b8e-6062-754e-8f6f-2b950b002174'::uuid,'Green Slaad','ChaoticNeutral','8 (XP 3 900; PB +3)',3900,5,'Leader','Large',16,NULL,144,'17d10+51','30 ft.',NULL,NULL,NULL,16,15,16,11,8,18,'{"Arcana": 3, "Perception": 2}','None','Blindsight 30 ft., Darkvision 60 ft., Passive Perception 12','Common, Slaad; telepathy 60 ft.',3,2,3,-1,4,0,3,'[]','Habitat: Planar (Limbo)','Aberration','','{"value":"Glistening with slime, it croaks a disturbing melody, its eyes glowing with malice."}','{"value": "Green Slaadi are chaotic evil creatures that resemble large, bipedal frogs with sharp claws and fangs. They are known for their ability to infect other creatures with a disease that slowly transforms them into Slaadi as well. Green Slaadi are often found in the chaotic plane of Limbo, where they serve as foot soldiers in the eternal war between the forces of chaos and order.\n\nThese creatures are highly intelligent and have a deep understanding of magic, often using their abilities to manipulate and deceive others. They are known for their cunning and devious nature, as well as their insatiable hunger for power and control.\n\nGreen Slaadi are typically encountered in groups, working together to achieve their goals and further their own agendas. They are highly adaptable and can quickly adjust their tactics in order to outmaneuver their enemies.\n\nOverall, Green Slaadi are dangerous and formidable foes, capable of wreaking havoc and chaos wherever they go. Players should approach these creatures with caution and be prepared for a challenging and unpredictable encounter."}',0,'Monster Manual 2024','','Acid, Cold, Fire, Lightning, Thunder',8.0,NULL),
	 ('01990b8e-89b2-7f4c-8e01-09c6a2d8838f'::uuid,'Griffon','Unaligned','2 (XP 450; PB +2)',450,2,'Skirmisher','Large',12,NULL,59,'7d10+21','30 ft.',NULL,NULL,'80 ft.',18,15,16,2,13,8,'{"Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','—',3,2,4,1,-1,-4,2,'[]','Habitat: Arctic, Coastal, Grassland, Hill, Mountain','Monstrosity','','{"value":"Wings outstretched, it lets loose a mighty roar that echoes through the valley."}','{"value": "In the world of Dungeons and Dragons, the griffon is a majestic and powerful creature that combines the body of a lion with the wings and head of an eagle. Griffons are known for their fierce loyalty and bravery, often serving as mounts for noble knights and warriors.\n\nIn D&D lore, griffons are typically portrayed as noble and regal creatures, known for their strength and hunting prowess. They are often depicted as guardians of the skies, fiercely defending their territory from any intruders.\n\nGriffons are intelligent creatures and are capable of forming bonds with humans and other intelligent beings. They are often trained for combat and used as mounts by skilled warriors. Griffons are known for their keen senses and powerful attacks, making them formidable adversaries in battle.\n\nOverall, griffons are seen as noble and majestic creatures in the world of D&D, embodying qualities such as courage, loyalty, and strength. They are often revered and respected by those who encounter them, and are a popular choice for players looking for a powerful and iconic mount in their adventures."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b8e-f1c3-7b76-bbaf-2b314565e51c'::uuid,'Half-Dragon','TrueNeutral','5 (XP 1,800; PB +3)',1800,5,'Brute','Medium',18,NULL,105,'14d8+42','40 ft.',NULL,NULL,NULL,19,14,16,10,15,14,'{"Stealth": 5, "Athletics": 7, "Perception": 5}','None','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 15','Common, Draconic',3,5,4,5,2,0,3,'[]','Habitat: Any','Dragon','','{"value":"Wings spread wide, it roars with fiery breath and bares its sharp teeth."}','{"value": "In Dungeons and Dragons 5th edition, a Half-Dragon is a creature that is the result of a dragon mating with another creature, most commonly a humanoid. This union results in a being that possesses traits of both a dragon and its humanoid parent.\n\nHalf-Dragons are typically larger and stronger than their humanoid parent, with scales, claws, and sometimes wings reminiscent of a dragon. They also inherit some of the elemental powers of their dragon parent, such as the ability to breathe fire or ice. \n\nHalf-Dragons are often feared and misunderstood by society due to their draconic heritage, and may struggle with their identity as they navigate the world. Some Half-Dragons embrace their dragon side and seek to dominate others, while others try to prove themselves as noble and honorable beings despite their lineage.\n\nIn combat, Half-Dragons are formidable opponents, using their physical strength and elemental powers to overpower their enemies. They are often found serving dragons as loyal minions or acting as mercenaries for those who can afford their services."}',0,'Monster Manual 2024 (BR)','','Damage type chosen for the Draconic Origin trait below',5.0,NULL),
	 ('01990b8f-6a39-7a50-8ab0-cd3c09212d4c'::uuid,'Hell Hound','LawfulEvil','3 (XP 700; PB +2)',700,1,'Ambusher','Medium',15,NULL,58,'9d8+18','50 ft.',NULL,NULL,NULL,17,12,14,6,13,6,'{"Perception": 5}','Fire','Darkvision 60 ft., Passive Perception 15','Understands Infernal but can''t speak',2,1,3,1,-2,-2,2,'[]','Habitat: Mountain, Planar (Lower Planes), Underdark','Fiend','','{"value":"Smoke curls from its nostrils as it snarls, flames dancing in its eyes."}','{"value": "Hell Hounds are demonic creatures that are often used by more powerful evil beings to guard their lairs or hunt down their enemies. These creatures resemble large, black dogs with fiery red eyes and fur that seems to be constantly smoldering. They are known for their speed and ferocity in combat, as well as their ability to breathe fire.\n\nHell Hounds are believed to originate from the lower planes of existence, such as the Nine Hells, where they serve various demon lords and devils. They are often summoned to the Material Plane by dark wizards or warlocks to do their bidding, and are fiercely loyal to their masters.\n\nIn combat, Hell Hounds are known for their pack mentality, often working together to take down their enemies. They are also highly resistant to fire, making them even more dangerous opponents. Despite their demonic nature, Hell Hounds are still animals at heart, and can be tamed or trained by those with the skill and patience to do so.\n\nOverall, Hell Hounds are feared and respected creatures in the world of Dungeons and Dragons, known for their infernal origins and deadly abilities."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b8f-c2f1-73b2-90bb-6298d74f7131'::uuid,'Hippogriff','Unaligned','1 (XP 200; PB +2)',200,1,'Skirmisher','Large',11,NULL,26,'4d10+4','40 ft.',NULL,NULL,'60 ft.',17,13,13,2,12,8,'{"Perception": 5}','None','Passive Perception 15','None',1,1,3,1,-1,-4,2,'[]','Habitat: Grassland, Hill, Mountain','Monstrosity','','{"value":"Wings beat rhythmically as it fixes you with a piercing gaze"}','{"value": "The Hippogriff is a majestic and powerful creature that is a cross between a horse and a giant eagle. In Dungeons and Dragons lore, Hippogriffs are often depicted as noble and proud beings that are fiercely loyal to their riders.\n\nHippogriffs are known for their incredible speed and agility, making them excellent mounts for skilled riders. They are also highly intelligent creatures, capable of understanding complex commands and forming strong bonds with their riders.\n\nIn D&D, Hippogriffs are often found in mountainous regions or other remote wilderness areas where they can roam freely. They are typically solitary creatures, but can be tamed and trained by those who earn their trust.\n\nIn combat, Hippogriffs are formidable opponents, using their sharp talons and beak to strike at enemies with deadly precision. They are also able to fly at great speeds, making them difficult to catch or escape from.\n\nOverall, the Hippogriff is a creature of great beauty and power, embodying the harmony of nature and the untamed wilderness."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b90-2183-73d4-bf32-cf424be4cc15'::uuid,'Homunculus','TrueNeutral','0 (XP 10; PB +2)',10,2,'Support','Tiny',13,NULL,4,'1d4+2','20 ft.',NULL,NULL,'40 ft.',4,15,14,10,10,7,'{}','Poison; Charmed, Poisoned','Darkvision 60 ft., Passive Perception 10','Understands Common plus one other language but can''t speak',2,2,-3,2,0,0,2,'[]','Habitat: Any','Construct','','{"value":"Whispers in a high-pitched voice, darting around with unnerving speed."}','{"value": "In Dungeons and Dragons 5th Edition, a homunculus is a small, humanoid creature created through alchemical means. They are typically created by spellcasters or alchemists to serve as assistants or minions. Homunculi are often created using a mixture of rare ingredients, including blood, clay, and magical energy.\n\nHomunculi are usually loyal to their creators and will follow their orders without question. They are capable of understanding and carrying out complex tasks, making them useful for a variety of purposes such as serving as spies, messengers, or guardians.\n\nIn terms of combat, homunculi are not particularly powerful on their own, but they can be a nuisance in large numbers or when working together with other creatures. They have the ability to deliver touch-based spells on behalf of their creator, making them potentially dangerous in the right circumstances.\n\nOverall, homunculi are versatile and useful creatures in the world of Dungeons and Dragons, often serving as valuable allies or minions for characters with the knowledge and resources to create them."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b90-6e36-777a-941e-d07bae44b83a'::uuid,'Hydra','Unaligned','8 (XP 3 900; PB +3)',3900,4,'Brute','Huge',15,NULL,184,'16d12+80','40 ft.',NULL,'40 ft.',NULL,20,12,20,2,10,7,'{"Perception": 6}','Blinded, Charmed, Deafened, Frightened, Stunned, Unconscious','Darkvision 60 ft., Passive Perception 16','—',5,1,5,0,-2,-4,3,'[]','Habitat: Coastal, Swamp','Monstrosity','','{"value":"Jaws snapping hungrily, each head scans independently for prey."}','{"value": "The Hydra is a fearsome and legendary creature in Dungeons and Dragons lore. It is a massive serpent-like monster with multiple heads, each capable of acting independently and regenerating if severed. The most common depiction of a Hydra in D&D is a creature with anywhere from three to nine heads, each capable of spitting acid or venom at its enemies.\n\nAccording to mythology, the Hydra was a formidable monster that terrorized the land, until it was slain by the hero Hercules as one of his Twelve Labors. In D&D, the Hydra is often portrayed as a powerful and aggressive predator that lurks in swamps, marshes, and other watery environments.\n\nHydras are known for their regenerative abilities, making them incredibly difficult to kill. Even if a hero manages to sever one of the Hydra''s heads, two more will grow in its place, making the creature even more dangerous. In combat, a Hydra will use its multiple heads to attack multiple targets at once, making it a deadly opponent for even the most skilled adventurers.\n\nOverall, the Hydra is a fearsome and iconic monster in D&D lore, known for its regenerative abilities and its ability to strike fear into the hearts of those who dare to face it in battle."}',0,'Monster Manual 2024 (BR)','','None',8.0,NULL),
	 ('01990b90-fcd2-7f82-95b8-cdb8e91b2d91'::uuid,'Incubus','NeutralEvil','4 (XP 1,100; PB +2)',1100,3,'Ambusher','Medium',15,NULL,66,'12d8+12','30 ft.',NULL,NULL,'60 ft.',8,17,13,15,12,20,'{"Insight": 5, "Stealth": 7, "Deception": 9, "Perception": 5, "Persuasion": 9}','None','Darkvision 60 ft., Passive Perception 15','Abyssal, Common, Infernal; telepathy 60 ft.',1,3,-1,1,5,2,2,'[]','Habitat: Planar (Lower Planes), Urban','Fiend','','{"value":"Whispers sweet promises as its eyes gleam with sinister desire."}','{"value": "In Dungeons & Dragons 5th Edition, an Incubus is a fiendish creature that is the male counterpart to the succubus. They are shape-shifting demons that are known for their seductive nature and ability to manipulate and corrupt mortals. Incubi are often depicted as handsome, charming individuals who use their charisma and supernatural abilities to lure victims into their grasp.\n\nIncubi are commonly found in the lower planes of existence, such as the Abyss or the Nine Hells, where they serve powerful demon lords or devils. They are skilled in deception and manipulation, and often use their powers to sow chaos and discord among mortals. Incubi are also known for their ability to drain the life force from their victims through their touch, leaving them weakened and vulnerable.\n\nIn combat, Incubi are formidable foes, using their shape-shifting abilities to confuse and confound their enemies. They are skilled in both melee and ranged combat, and often use their charm and seductive powers to distract and incapacitate their foes. Incubi are also resistant to many forms of damage and have a number of magical abilities at their disposal, making them a dangerous adversary for any group of adventurers.\n\nOverall, the Incubus is a cunning and dangerous creature that preys on the weaknesses of mortals, using their charm and seductive powers to manipulate and corrupt those who fall under their influence. Adventurers would be wise to approach an Incubus with caution, as they are skilled manipulators and deadly foes in combat."}',0,'Monster Manual 2024 (BR)','','Cold, Fire, Poison, Psychic',4.0,NULL),
	 ('01990b91-9150-7fd3-b0f1-3f43fc0ab89a'::uuid,'Knight','Any','3 (XP 700; PB +2)',700,0,'Soldier','Medium',18,NULL,52,'8d8+16','30 ft.',NULL,NULL,NULL,16,11,14,11,11,15,'{}','None','Passive Perception 10','Common plus one other language',4,0,3,2,2,0,2,'["Greatsword", "Heavy Crossbow", "Plate Armor"]','Habitat: Any','Humanoid','','{"value":"Armor gleams as it readies its sword, eyes fixed with unwavering determination."}','{"value": "Knights in Dungeons and Dragons 5th Edition are typically depicted as skilled warriors who are dedicated to serving a lord or lady, or upholding a code of honor and chivalry. They are often clad in heavy armor and wield powerful weapons, making them formidable opponents in battle.\n\nIn terms of lore, knights are often seen as figures of nobility and valor, known for their bravery and loyalty. They may be part of an order or organization that has a long history of protecting the realm or serving a particular deity. Knights are often seen as symbols of justice and righteousness, and are respected by the common folk for their dedication to serving and protecting others.\n\nIn some campaigns, knights may be portrayed as more complex characters, struggling with issues of morality or facing challenges to their code of honor. They may be torn between their duty to their lord and their own personal beliefs, or may be forced to make difficult choices that test their commitment to their ideals.\n\nOverall, knights in Dungeons and Dragons 5th Edition are powerful and iconic figures that can add depth and drama to any campaign setting. Whether they are noble heroes fighting against evil forces, or complex characters grappling with their own inner demons, knights are a classic element of fantasy storytelling that can bring a sense of honor and adventure to any game."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b92-2455-7513-9341-53b9aa0893bd'::uuid,'Kuo-toa Monitor','NeutralEvil','3 (XP 700; PB +2)',700,0,'Soldier','Medium',13,NULL,65,'10d8+20','30 ft.',NULL,'30 ft.',NULL,16,10,14,12,14,11,'{"Religion": 3, "Perception": 6}','None','Darkvision 120 ft., Truesight 30 ft., Passive Perception 16','Undercommon',2,0,3,2,0,1,2,'[]','Habitat: Coastal, Underdark','Aberration','','{"value":"Eyes dart around frantically, trident at the ready, ready to strike at any moment"}','{"value": "Kuo-toa Monitors are a type of Kuo-toa, a fish-like humanoid creature that worships bizarre and twisted deities. Monitors are typically larger and more powerful than regular Kuo-toa, serving as enforcers and protectors of their communities.\n\nIn Kuo-toa society, Monitors hold a position of authority and are responsible for maintaining order and protecting the tribe. They are skilled warriors, known for their fierce combat abilities and their mastery of the spear and trident.\n\nKuo-toa Monitors are also known for their strange and unpredictable behavior, often driven by their devotion to their gods. They may engage in bizarre rituals and sacrifices to appease their deities, and are willing to go to extreme lengths to ensure their favor.\n\nOverall, Kuo-toa Monitors are formidable foes in combat, with a combination of physical strength, martial prowess, and religious fervor that makes them a dangerous adversary for any would-be heroes."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01990b92-59a1-789c-ad74-c45d936d6354'::uuid,'Larva','NeutralEvil','0 (XP 10; PB +2)',10,-1,'Minion','Medium',9,NULL,9,'2d8','20 ft.',NULL,NULL,NULL,9,9,10,6,10,2,'{}','None','Darkvision 60 ft., Passive Perception 10','Understands Common plus one other language but can''t speak',0,-1,-1,0,-4,-2,2,'[]','Habitat: Planar (Lower Planes)','Fiend','','{"value":"Squirming hungrily, larvae writhe and burrow through the decaying flesh."}','{"value": "In Dungeons and Dragons 5th edition, a larva is a type of demon that is typically found in the Abyss, the chaotic and evil plane of existence. Larvae are the lowest rank of demons, often created from the souls of evil mortals who were damned to the Abyss after death.\n\nLarvae are depicted as grotesque, worm-like creatures with twisted, humanoid faces and a never-ending hunger for souls. They are often used as foot soldiers by more powerful demons, sent out to hunt for souls to devour and add to their own power.\n\nLarvae are considered to be mindless and cruel, driven solely by their insatiable hunger and the desire to serve their demon masters. They are often used as guards or sentries in demonic strongholds, as their ability to sense the presence of souls makes them effective at detecting intruders.\n\nOverall, larvae are considered to be a low-level threat in the hierarchy of demons, but their sheer numbers and relentless hunger make them a dangerous foe for adventurers to face in the Abyss."}',0,'Monster Manual 2024','','None',0.0,NULL),
	 ('01990b9a-b6e9-7f05-8f2d-a5e77f2e286c'::uuid,'Satyr Revelmaster','ChaoticNeutral','6 (XP 2 300; PB +3)',2300,7,'Skirmisher','Medium',17,NULL,82,'15d8+15','40 ft.',NULL,NULL,NULL,12,18,12,12,14,17,'{"Acrobatics": 7, "Perception": 5, "Performance": 9}','None','Passive Perception 15','Common, Elvish, Sylvan',1,7,1,5,3,1,3,'[]','Habitat: Forest, Planar (Feywild)','Fey','','{"value":"Hooves stamp in rhythm as it twirls, a mischievous glint in its eyes."}','{"value": "Satyr Revelmasters are powerful and charismatic leaders among satyr communities. They are known for their exceptional musical and dancing abilities, as well as their knack for organizing and hosting wild and extravagant celebrations. Satyr Revelmasters are often found leading revelry in the forests and meadows where their kind resides, enchanting all who hear their music and drawing them into joyous festivities.\n\nIn addition to their musical talents, Satyr Revelmasters are skilled in combat, using their agility and cunning to outmaneuver their foes. They are known to wield magical abilities related to enchantment and illusion, charming and beguiling their enemies to gain the upper hand in battle.\n\nSatyr Revelmasters are fiercely loyal to their community and will do whatever it takes to protect their fellow satyrs and their way of life. They are also known to have a mischievous streak, delighting in playing pranks on unsuspecting travelers who wander into their territory.\n\nOverall, Satyr Revelmasters are complex and enigmatic creatures, embodying the joy and freedom of the natural world while also possessing a fierce and protective nature when their home or loved ones are threatened."}',0,'Monster Manual 2024','','None',6.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b92-d3c0-7ea3-a849-f93829448400'::uuid,'Lizardfolk Sovereign','TrueNeutral','4 (XP 1 100; PB +2)',1100,1,'Leader','Medium',15,NULL,78,'12d8+24','30 ft.',NULL,'30 ft.',NULL,17,12,15,11,11,15,'{"Stealth": 5, "Perception": 4}','Frightened','Darkvision 60 ft., Passive Perception 14','Draconic, Primordial (Terran)',4,1,3,2,2,0,2,'[]','Habitat: Forest, Swamp','Elemental','','{"value":"Sovereign\u0027s gaze pierces the air, commanding loyalty from its scaly subjects."}','{"value": "Lizardfolk Sovereigns are powerful leaders within lizardfolk society, often revered for their strength, wisdom, and cunning. These creatures are known for their fierce loyalty to their tribe and their ability to command respect and obedience from their followers.\n\nLizardfolk Sovereigns are typically larger and more imposing than other lizardfolk, with scales that glisten in the sunlight and sharp, menacing teeth. They are skilled warriors and hunters, able to take down even the most formidable of foes with ease.\n\nIn addition to their combat prowess, Lizardfolk Sovereigns are also adept at diplomacy and strategy, using their keen intellect to outmaneuver their enemies and secure alliances with other tribes. They are known to be ruthless when provoked, but also fair and just rulers who prioritize the well-being of their people above all else.\n\nOverall, Lizardfolk Sovereigns are formidable adversaries and powerful allies, respected and feared by all who come into contact with them."}',0,'Monster Manual 2024','','None',4.0,NULL),
	 ('01990b93-6e5f-7c25-a6ec-33e85cf4d37d'::uuid,'Manticore','LawfulEvil','3 (XP 700; PB +2)',700,3,'Skirmisher','Large',14,NULL,68,'8d10+24','30 ft.',NULL,NULL,'50 ft.',17,16,17,7,12,8,'{}','None','Darkvision 60 ft., Passive Perception 11','Common',3,3,3,1,-1,-2,2,'[]','Habitat: Arctic, Coastal, Grassland, Hill, Mountain','Monstrosity','','{"value":"Jaws snap open, revealing rows of razor-sharp teeth as it eyes its prey."}','{"value": "In Dungeons and Dragons, the Manticore is a fearsome and ferocious monster that is often depicted as a lion-like creature with the head of a human, bat-like wings, and a tail ending in a cluster of deadly spikes. Manticores are known for their vicious nature and their insatiable appetite for human flesh.\n\nAccording to lore, Manticores are intelligent creatures that possess a cruel and sadistic nature. They are often found in desolate and remote areas, preying on unsuspecting travelers and adventurers. Manticores are known for their keen sense of smell and their ability to track their prey over great distances.\n\nIn some interpretations, Manticores are creatures of chaos and destruction, serving as harbingers of doom and terror. They are often aligned with evil forces and may be used as guardians by dark wizards or demons.\n\nOverall, the Manticore is a formidable and dangerous monster in the world of Dungeons and Dragons, capable of striking fear into the hearts of even the bravest adventurers."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b93-d68d-75b6-9126-24e55a0d2ce4'::uuid,'Medusa','LawfulEvil','6 (XP 2 300; PB +3)',2300,6,'Controller','Medium',15,NULL,127,'17d8+51','30 ft.',NULL,NULL,NULL,10,17,16,12,13,15,'{"Stealth": 6, "Deception": 5, "Perception": 4}','None','Darkvision 150 ft., Passive Perception 14','Common plus one other language',3,3,0,4,2,1,3,'[]','Habitat: Desert','Monstrosity','','{"value":"Hair of serpents writhe, her gaze freezes you in place."}','{"value": "In Dungeons and Dragons 5th edition, the Medusa is a monstrous creature with the upper body of a woman and the lower body of a snake. They are infamous for their ability to turn creatures to stone with a single gaze, a power granted to them by the gods as punishment for their vanity and pride.\n\nAccording to lore, Medusas were once beautiful mortal women who drew the attention of the gods. However, their vanity and arrogance led them to defy the gods, resulting in their transformation into monstrous creatures. Medusas now dwell in remote locations, such as ruins or caves, where they lure unsuspecting victims with their beauty before turning them to stone.\n\nMedusas are often depicted as cunning and intelligent creatures, using their petrifying gaze to defend their territory and treasure. They are feared by many adventurers and are known for their ability to outsmart and outmaneuver their opponents.\n\nOverall, the Medusa is a classic monster in Dungeons and Dragons lore, embodying themes of vanity, punishment, and the dangers of beauty. Players must exercise caution when facing a Medusa, as their petrifying gaze can quickly turn a challenging encounter into a deadly one."}',0,'Monster Manual 2024 (BR)','','None',6.0,NULL),
	 ('01990b7e-ce38-7b82-810f-edb3be1a5caf'::uuid,'Animated Broom','Unaligned','1/4 (XP 50; PB +2)',50,5,'Support','Small',15,NULL,14,'4d6','5 ft.',NULL,NULL,'50 ft.',10,17,10,1,5,1,'{}','Poison, Psychic; Charmed, Deafened, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned','Blindsight 60 ft., Passive Perception 7','—',0,3,0,-3,-5,-5,2,'[]','Habitat: Urban','Construct','','{"value":"Swiftly sweeping, the animated broom twirls and dances with unsettling grace."}','{"value": "In the world of Dungeons and Dragons, the Animated Broom is a seemingly harmless household object that has been magically imbued with life. These enchanted brooms are typically created by powerful wizards or sorcerers to perform menial tasks such as sweeping, cleaning, or fetching items.\n\nHowever, if left unchecked or mistreated, an Animated Broom can become mischievous or even dangerous. They have been known to attack intruders, defend their territory, or wreak havoc in a home or establishment.\n\nDespite their small size and seemingly harmless appearance, Animated Brooms are surprisingly agile and quick, using their bristles to deliver sharp strikes or their handle to trip up unsuspecting foes. They are immune to most forms of damage, except for magical attacks or those specifically designed to destroy constructs.\n\nAdventurers who encounter an Animated Broom should approach with caution and be prepared for a surprisingly tough fight. It''s always best to try and reason with the broom''s creator or find a way to dispel the enchantment before resorting to violence."}',0,'Monster Manual 2024','','None',0.25,NULL),
	 ('01990b94-8d90-77a3-835d-59cce5963e26'::uuid,'Minotaur Skeleton','LawfulEvil','2 (XP 450; PB +2)',450,0,'Brute','Large',12,NULL,45,'6d10+12','40 ft.',NULL,NULL,NULL,18,11,15,6,8,5,'{}','Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 9','Understands Abyssal but can''t speak',2,0,4,-1,-3,-2,2,'[]','Habitat: Planar (Shadowfell), Underdark, Urban','Undead','','{"value":"Rage echoes in its hollow chest as it charges, bones rattling with fury."}','{"value": "Minotaur Skeletons are undead creatures created from the remains of minotaurs, powerful humanoid beasts with the head of a bull and the body of a human. These creatures are often found in ancient ruins, dungeons, or other places where minotaurs once roamed. \n\nMinotaur Skeletons are animated through dark magic or necromancy and are bound to serve their creator. They retain the strength and ferocity of their living counterparts, making them formidable opponents in combat. Their skeletal form makes them resistant to many forms of damage, but they are vulnerable to bludgeoning weapons.\n\nMinotaur Skeletons are often used as guardians or soldiers by necromancers or other dark forces. They are relentless in their pursuit of their enemies and will stop at nothing to destroy them. Despite their lack of intelligence, they are cunning in battle and will use their horns and brute strength to overwhelm their foes. \n\nAdventurers must be cautious when facing a Minotaur Skeleton, as they are powerful and deadly opponents. It is said that destroying the remains of the minotaur that the skeleton was created from can release its spirit and put it to rest, finally freeing it from its undead form."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b95-146c-7381-a4b5-e556699105e8'::uuid,'Myconid Spore Servant','Unaligned','1 (XP 200; PB +2)',200,1,'Support','Medium',13,NULL,37,'5d8+15','20 ft.',NULL,NULL,NULL,16,12,16,2,6,1,'{}','Poison; Blinded, Charmed, Frightened, Paralyzed, Poisoned','Blindsight 30 ft., Passive Perception 8','Telepathy 30 ft.',3,1,3,-2,-5,-4,2,'[]','Habitat: Underdark','Plant','','{"value":"Pulsating with spores, it sways rhythmically, emitting a faint, sweet scent of decay."}','{"value": "Myconid Spore Servants are humanoid creatures created by Myconids, a race of sentient fungi, through a process known as \"sporification.\" These creatures are typically used as servants and guards in Myconid colonies, carrying out tasks and defending their fungal masters.\n\nMyconid Spore Servants are created from the bodies of deceased creatures that are infused with Myconid spores. The spores animate the body and transform it into a loyal servant of the Myconids. These creatures are typically mindless and obedient, following the commands of their Myconid masters without question.\n\nDespite their mindless nature, Myconid Spore Servants are formidable fighters, capable of wielding weapons and using their fungal abilities to attack enemies. They are also immune to mind-affecting abilities and have resistance to poison and psychic damage.\n\nIn some cases, Myconid Spore Servants may break free from their Myconid masters'' control, becoming independent creatures with their own goals and desires. These renegade Spore Servants can be unpredictable and dangerous, posing a threat to both Myconids and other creatures alike.\n\nOverall, Myconid Spore Servants are a fascinating and unique addition to the world of Dungeons and Dragons, adding an element of fungal horror and intrigue to any campaign."}',0,'Monster Manual 2024','','None',1.0,NULL),
	 ('01990b95-9841-7349-990c-db209e9d786e'::uuid,'Nightmare','NeutralEvil','3 (XP 700; PB +2)',700,2,'Solo','Large',13,NULL,68,'8d10+24','60 ft.',NULL,NULL,'90 ft.',18,15,16,10,13,15,'{}','Fire','Passive Perception 11','Understands Abyssal, Common, and Infernal but can''t speak',3,2,4,1,2,0,2,'[]','Habitat: Planar (Lower Planes)','Fiend','','{"value":"Shadows swirl, coalescing into a creature with eyes that pierce the soul."}','{"value": "Nightmares are powerful fiends that are created from the tormented souls of evil beings. They are often used as mounts by powerful evil creatures such as liches, demons, and powerful wizards. Nightmares have a fearsome appearance, with flaming manes and eyes that burn with an otherworldly fire.\n\nNightmares are known for their ability to create terrifying visions in the minds of their enemies, causing them to experience their worst fears and nightmares. They can also create illusions to confuse and disorient their foes, making them powerful and dangerous adversaries in combat.\n\nDespite their terrifying appearance and abilities, nightmares are not mindless creatures. They are intelligent and cunning, using their powers to manipulate and deceive others to further their own dark purposes.\n\nIn the world of Dungeons and Dragons, nightmares are often associated with the plane of the Abyss, where they are said to dwell in the fiery pits of hell. They are considered to be harbingers of doom and destruction, spreading fear and chaos wherever they go. Only the bravest and most skilled adventurers dare to face these fearsome creatures in battle."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b9b-a79e-70ca-95fe-ea7cd246cd45'::uuid,'Silver Dragon Wyrmling','LawfulGood','2 (XP 450; PB +2)',450,2,'Brute','Medium',17,NULL,45,'6d8+18','30 ft.',NULL,NULL,'60 ft.',19,10,17,12,11,15,'{"Stealth": 2, "Perception": 4}','Cold','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Draconic',3,2,4,2,2,1,2,'[]','Habitat: Mountain, Urban','Dragon','Metallic','{"value":"Glides gracefully, shimmering scales reflecting light like dancing stars"}','{"value": "Silver Dragons are noble and wise creatures that are known for their love of justice and righteousness. They are considered one of the most powerful and benevolent types of dragons. \n\nSilver Dragon Wyrmlings are young silver dragons that are typically around 4-5 years old and are about the size of a small horse. Despite their young age, they are already highly intelligent and possess a strong sense of morality. \n\nThese wyrmlings are known for their silver-white scales that shimmer in the light, giving them a majestic appearance. They are also capable of using their breath weapon, which is a powerful cone of cold that can freeze their enemies in their tracks. \n\nSilver Dragon Wyrmlings are often curious and adventurous, seeking out knowledge and wisdom from the world around them. They are also fiercely protective of their territory and will go to great lengths to defend it from any threats. \n\nOverall, Silver Dragon Wyrmlings are noble and virtuous creatures that embody the ideals of justice and good. They are highly respected by other creatures in the world of Dungeons and Dragons and are often sought out for their wisdom and guidance."}',0,'Monster Manual 2024 (BR)','Metallic','None',2.0,NULL),
	 ('01990b95-e4af-73f2-b801-4adb75f30777'::uuid,'Ochre Jelly','Unaligned','2 (XP 450; PB +2)',450,-2,'Solo','Large',8,NULL,52,'7d10+14','20 ft.','20 ft.',NULL,NULL,15,6,14,2,6,1,'{}','Lightning, Slashing; Charmed, Deafened, Exhaustion, Frightened, Grappled, Prone, Restrained','Blindsight 60 ft., Passive Perception 8','None',2,-2,2,-2,-5,-4,2,'[]','Habitat: Underdark','Ooze','','{"value":"It oozes and pulsates, leaving a trail of acidic slime in its wake."}','{"value": "Ochre jellies are a type of ooze creature that are typically found in dark, damp environments such as caves, dungeons, or sewers. They are mindless, gelatinous blobs that move slowly but relentlessly towards their prey.\n\nOchre jellies are known for their ability to split into smaller jellies when struck with a slashing or piercing weapon, making them a formidable opponent for adventurers. They are also able to engulf their prey, slowly digesting them with their acidic secretions.\n\nThese creatures are often used as guardians by more powerful beings or as traps in dungeons, as their ability to split and regenerate makes them difficult to fully defeat without the use of fire or other sources of extreme heat.\n\nOverall, ochre jellies are considered a low-level threat for experienced adventurers, but their ability to divide and conquer makes them a dangerous foe in the right circumstances."}',0,'Monster Manual 2024 (BR)','','Acid',2.0,NULL),
	 ('01990b96-415e-7eec-8dc5-dfab538a0392'::uuid,'Ogrillon Ogre','ChaoticEvil','1 (XP 200; PB +2)',200,0,'Brute','Large',12,NULL,52,'7d10+14','30 ft.',NULL,NULL,NULL,17,10,14,7,9,10,'{}','None','Darkvision 60 ft., Passive Perception 9','Common, Giant',2,0,3,-1,0,-2,2,'["Battleaxe", "three Javelins"]','Habitat: Arctic, Desert, Forest, Grassland, Hill, Mountain, Swamp, Underdark','Giant','','{"value":"Rage boils in its eyes as it grunts and swings its massive club."}','{"value": "The Ogrillon is a hybrid creature created through the union of an ogre and an orc. These creatures are typically larger and stronger than orcs, inheriting the brute strength and size of their ogre parent. They are known for their ferocity in battle and their intimidating appearance.\n\nOgrillons are often used as enforcers or bodyguards by powerful orc or ogre leaders, as they possess the best qualities of both parent races. They are fiercely loyal to their masters and will stop at nothing to protect them.\n\nDespite their fearsome reputation, Ogrillons are not particularly intelligent and can be easily manipulated or controlled by those who are clever enough to do so. They are often used as shock troops in battles, charging into the fray with reckless abandon and causing chaos among enemy ranks.\n\nOverall, the Ogrillon is a formidable and dangerous creature that should not be underestimated on the battlefield. Their combination of brute strength and ferocity make them a force to be reckoned with in any conflict."}',0,'Monster Manual 2024','','None',1.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b96-b9bc-7d03-bf0d-cf239c826eb2'::uuid,'Owlbear','Unaligned','3 (XP 700; PB +2)',700,1,'Brute','Large',13,NULL,59,'7d10+21','40 ft.','40 ft.',NULL,NULL,20,12,17,3,12,7,'{"Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','None',3,1,5,1,-2,-4,2,'[]','Habitat: Forest','Monstrosity','','{"value":"Feathers ruffle as it screeches, claws outstretched in a primal display"}','{"value": "The Owlbear is a fearsome and iconic monster in Dungeons and Dragons. It is a large, hulking creature with the body of a bear and the head of an owl, combining the strength and ferocity of a bear with the keen senses and predatory instincts of an owl.\n\nAccording to lore, Owlbears are believed to be the result of magical experimentation gone wrong, with wizards or druids attempting to create a powerful hybrid creature for their own purposes. However, Owlbears are now known to reproduce on their own in the wild, typically found in dense forests or deep caves.\n\nOwlbears are solitary creatures, fiercely territorial and aggressive towards any intruders in their territory. They are known for their powerful claws and beak, capable of tearing through armor and flesh with ease. Their owl-like eyes give them exceptional night vision, making them formidable hunters even in the dark.\n\nAdventurers who encounter an Owlbear must tread carefully, as they are known to be relentless in their pursuit of prey and will not hesitate to attack anything that comes too close. Many tales have been told of brave warriors who have fallen to the deadly claws and beak of an Owlbear, making them a creature to be feared and respected in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b97-2583-7b20-a7dc-0ef5472878c6'::uuid,'Phase Spider','Unaligned','3 (XP 700; PB +2)',700,3,'Skirmisher','Large',14,NULL,45,'7d10+7','30 ft.','30 ft.',NULL,NULL,15,16,12,6,10,6,'{"Stealth": 7}','None','Darkvision 60 ft., Passive Perception 10','—',1,3,2,0,-2,-2,2,'[]','Habitat: Desert, Forest, Grassland, Hill, Planar (Ethereal Plane), Underdark, Urban','Monstrosity','','{"value":"Phantom-like, it flickers in and out of existence, ready to strike from shadows."}','{"value": "Phase spiders are magical creatures that inhabit the Ethereal Plane and use their ability to phase in and out of reality to hunt their prey. These spiders are known for their ability to appear suddenly and without warning, making them formidable opponents in combat.\n\nPhase spiders are solitary creatures that prefer to live and hunt alone, using their ability to move between planes to surprise their victims. They are highly intelligent and cunning, often setting traps for their prey before striking.\n\nIn some cultures, phase spiders are worshipped as symbols of trickery and cunning, while in others they are feared as deadly predators. Adventurers who encounter a phase spider must be on their guard, as these creatures are known to be relentless in their pursuit of prey.\n\nIn combat, phase spiders use their phasing ability to move in and out of reality, making them difficult to hit. They can also create webs of magical energy to trap their enemies, allowing them to strike with their venomous bite.\n\nOverall, phase spiders are dangerous and elusive creatures that should be approached with caution by any adventurer looking to face them in battle."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b9a-b726-706e-8d74-4945fb8ea5bf'::uuid,'Scarecrow','ChaoticEvil','1 (XP 200; PB +2)',200,3,'Ambusher','Medium',11,NULL,27,'6d8','30 ft.',NULL,NULL,NULL,11,13,11,10,10,13,'{}','Poison; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned, Unconscious','Darkvision 60 ft., Passive Perception 10','Common plus one other language',0,1,0,0,1,0,2,'[]','Habitat: Grassland','Construct','','{"value":"Watches stoically, straw rustling in the wind, eyes fixed on intruders"}','{"value": "In the world of Dungeons and Dragons, scarecrows are not just simple agricultural tools used to scare away birds. They are actually animated constructs, often created by powerful spellcasters or evil entities, to serve as guardians or enforcers. \n\nScarecrows are typically made of straw, cloth, and wood, giving them a humanoid shape with a tattered and ragged appearance. They are often imbued with dark magic, giving them the ability to move and act independently. Scarecrows are known for their eerie and unsettling presence, often instilling fear in those who come across them.\n\nIn combat, scarecrows use their sharp claws and teeth to attack their enemies, often employing tactics that play on their ability to invoke fear. They are also known to have a resistance to many types of damage, making them formidable adversaries. \n\nScarecrows are often found guarding haunted houses, cursed farmlands, or other areas of dark magic. They are usually created with a specific purpose in mind, whether it be to protect a certain area, carry out a dark ritual, or simply to sow chaos and fear.\n\nOverall, scarecrows are a creepy and mysterious monster in the world of Dungeons and Dragons, adding a touch of horror and unease to any campaign they appear in."}',0,'Monster Manual 2024','','None',1.0,NULL),
	 ('01990b7e-f212-77ac-9ca0-e7b03f007090'::uuid,'Ankheg','Unaligned','2 (XP 450; PB +2)',450,0,'Ambusher','Large',14,NULL,45,'6d10+12','30 ft.',NULL,NULL,NULL,17,11,14,1,13,6,'{}','None','Darkvision 60 ft., Tremorsense 60 ft., Passive Perception 11','—',2,0,3,1,-2,-5,2,'[]','Habitat: Forest, Grassland','Monstrosity','','{"value":"Mandibles snap shut with a deafening crunch, spraying acid in all directions"}','{"value": "Ankhegs are large insect-like creatures that dwell underground, primarily in sandy or rocky areas. They are known for their burrowing abilities and their ability to spit acid at their enemies. \n\nAnkhegs are carnivorous creatures that primarily feed on small animals, but will not hesitate to attack larger prey if given the opportunity. They are solitary creatures and are usually encountered alone or with their young. \n\nAnkhegs are highly territorial and will fiercely defend their burrows from intruders. They are also known to attack travelers passing through their territory, making them a dangerous threat to adventurers exploring the wilderness. \n\nIn some cultures, ankhegs are revered as symbols of strength and resilience, while in others they are feared and avoided at all costs. Their tough exoskeletons make them difficult to kill, and their acid spit can cause serious harm to their enemies. \n\nOverall, ankhegs are formidable opponents that should not be underestimated by any adventurer brave enough to face them in combat."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b98-0b97-70e5-9e05-f54fe129ccb2'::uuid,'Plesiosaurus','Unaligned','2 (XP 450; PB +2)',450,2,'Ambusher','Large',13,NULL,68,'8d10+24','20 ft.',NULL,'40 ft.',NULL,18,15,16,2,12,5,'{"Stealth": 4, "Perception": 3}','None','Passive Perception 13','None',3,2,4,1,-3,-4,2,'[]',NULL,'Beast','Dinosaur','{"value":"Sleek form emerges from the water, long neck craning to survey its surroundings."}','{"value": "In Dungeons and Dragons 5th edition, the Plesiosaurus is a large aquatic dinosaur with a long neck and four flippers. They are known for their graceful swimming abilities and predatory nature. Plesiosaurs are often found in deep ocean waters, where they hunt for fish and other sea creatures.\n\nLegends tell of Plesiosaurs being tamed by powerful sea witches or wizards to serve as guardians of underwater realms. They are sometimes summoned by these magic users to aid in battles or protect their underwater lairs.\n\nPlesiosaurs are typically neutral in alignment, but can be aggressive if provoked. They are considered dangerous predators by sailors and fishermen who venture into their territory. Some sea-faring cultures worship Plesiosaurs as sea gods or spirits of the deep.\n\nOverall, Plesiosaurs are fascinating and mysterious creatures that add an element of danger and excitement to underwater adventures in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','Dinosaur','None',2.0,NULL),
	 ('01990b98-6e57-7f4c-b654-68dd6e5b08fe'::uuid,'Primeval Owlbear','Unaligned','7 (XP 2 900; PB +3)',2900,5,'Brute','Huge',16,NULL,126,'12d12+48','40 ft.','40 ft.',NULL,'5 ft.',22,14,19,8,15,7,'{"Perception": 8}','None','Darkvision 120 ft., Passive Perception 18','—',7,2,6,5,-2,-1,3,'[]','Habitat: Forest','Monstrosity','','{"value":"Feathers rustle as it hoots menacingly, eyes gleaming with primal hunger."}','{"value": "The Primeval Owlbear is a fearsome creature that hails from the ancient forests of the world. It is said to be a distant ancestor of the common Owlbear, possessing a larger size, more powerful abilities, and a primal, savage demeanor. \n\nLegends say that the Primeval Owlbear was created by a powerful druid who sought to protect the forests from encroaching civilizations. Infusing the spirit of an owl with the ferocity of a bear, the druid unleashed this monstrous hybrid upon any who dared harm the natural world.\n\nThe Primeval Owlbear is known for its sharp talons, powerful beak, and keen senses, making it a formidable predator in the wild. It is said to be highly territorial and fiercely protective of its offspring, making it a dangerous foe for any adventurers who stumble into its territory.\n\nSome believe that encountering a Primeval Owlbear is a sign of the forest''s displeasure, warning interlopers to respect the balance of nature or face the wrath of this ancient guardian. Only the bravest and most skilled adventurers dare to challenge the Primeval Owlbear, knowing that they face a creature that has survived for centuries in the untamed wilderness."}',0,'Monster Manual 2024','','None',7.0,NULL),
	 ('01990b98-ce32-7b63-a49b-7d7c1d00641a'::uuid,'Quaggoth','ChaoticNeutral','2 (XP 450; PB +2)',450,1,'Brute','Medium',13,NULL,45,'6d8+18','30 ft.','30 ft.',NULL,NULL,17,12,16,6,12,7,'{"Athletics": 5}','Poison; Poisoned','Darkvision 120 ft., Passive Perception 11','Undercommon',3,1,3,1,-2,-2,2,'[]','Habitat: Underdark','Monstrosity','','{"value":"Muscles ripple as it snarls, saliva dripping from its gnashing teeth"}','{"value": "Quaggoths are large, furry, bear-like humanoids that inhabit the Underdark in the world of Dungeons & Dragons. They are known for their fierce and aggressive nature, often attacking anything that enters their territory.\n\nQuaggoths are believed to have originated from a curse placed on a group of dwarves by the drow, transforming them into the savage creatures they are today. They are skilled in combat and often work together in packs to overpower their enemies.\n\nDespite their ferocity, quaggoths are not mindless beasts and are capable of forming alliances with other creatures, such as drow or other Underdark denizens. They are known to be loyal to those they consider allies, but will turn on them if betrayed.\n\nQuaggoths are a formidable enemy for any adventurers exploring the depths of the Underdark, and their presence often signals danger and potential conflict."}',0,'Monster Manual 2024','','None',2.0,NULL),
	 ('01990b9a-bf98-79ad-ae27-379d3f9b57ed'::uuid,'Scorpion','Unaligned','0 (XP 10; PB +2)',10,0,'Ambusher','Tiny',11,NULL,1,'1d4-1','10 ft.',NULL,NULL,NULL,2,11,8,1,8,2,'{}','None','Blindsight 10 ft., Passive Perception 9','None',1,0,4,1,4,5,2,'[]',NULL,'Beast','','{"value":"Stinger poised, it skitters in a menacing dance, claws clicking on the ground."}','{"value": "In Dungeons and Dragons 5th edition, the scorpion is a creature typically found in arid desert regions. These large arachnids are known for their venomous stinger and powerful pincers, making them formidable opponents for adventurers.\n\nScorpions are often depicted as solitary hunters, using their keen sense of smell and vibration detection to track prey. They are also known for their ability to burrow into the sand, making them difficult to spot until it''s too late.\n\nIn D&D lore, scorpions are sometimes associated with evil deities or dark magic, and are occasionally used as guardians by powerful wizards or sorcerers. Some scorpions may even be enchanted or mutated, giving them supernatural abilities or enhanced strength.\n\nOverall, scorpions are a classic monster in D&D, known for their deadly sting and intimidating presence in desert environments. Adventurers should approach them with caution, as their venom can be quite potent and their tactics cunning."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b8b-dc3c-7980-bc5c-85a936c537b6'::uuid,'Giant Scorpion','Unaligned','3 (XP 700; PB +2)',700,1,'Ambusher','Large',15,NULL,52,'7d10+14','40 ft.',NULL,NULL,NULL,16,13,15,1,9,3,'{}','None','Blindsight 60 ft., Passive Perception 9','None',2,1,3,-1,-4,-5,2,'[]',NULL,'Beast','','{"value":"Stinger poised, it skitters menacingly towards you, chelicerae clicking with anticipation."}','{"value": "In the world of Dungeons and Dragons, the Giant Scorpion is a fearsome and deadly creature that is often found lurking in desolate deserts, rocky caves, and other arid environments. These monstrous arachnids are known for their massive size, powerful claws, and venomous stinger.\n\nGiant Scorpions are solitary hunters, preying on anything that crosses their path, from small animals to unwary travelers. They are highly aggressive and will not hesitate to attack anything that threatens them or their territory.\n\nLegends say that Giant Scorpions were created by an ancient god of chaos and destruction, who imbued them with incredible strength and a relentless thirst for blood. Some believe that these creatures are the embodiment of vengeance and retribution, sent to punish those who have strayed from the path of righteousness.\n\nAdventurers who encounter a Giant Scorpion must be cautious and prepared for a fierce battle, as these creatures are formidable opponents with deadly attacks. Those who manage to defeat a Giant Scorpion are often rewarded with valuable treasures hidden in their lairs, as well as the knowledge that they have rid the world of one of its most dangerous predators."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b99-5f47-794c-ba88-d1e9d2971fcc'::uuid,'Red Slaad','ChaoticNeutral','5 (XP 1 800; PB +3)',1800,1,'Solo','Large',14,NULL,93,'11d10+33','30 ft.',NULL,NULL,NULL,16,12,16,6,6,7,'{"Perception": 1}','None','Darkvision 60 ft., Passive Perception 11','Slaad; telepathy 60 ft.',3,1,3,-2,-2,-2,3,'[]','Habitat: Planar (Limbo)','Aberration','','{"value":"Jaws snap hungrily as its eyes lock onto your party\u0027s vulnerable members."}','{"value": "The Red Slaad is a chaotic and malevolent creature that originates from the plane of Limbo. These monstrous amphibians are known for their voracious appetite and their ability to infect other creatures with a disease that transforms them into Slaad spawn.\n\nRed Slaads are powerful fighters, using their sharp claws and teeth to tear through their enemies. They are also capable of casting spells and have a resistance to magic, making them formidable opponents in battle. In addition, Red Slaads can reproduce by implanting Slaad eggs into the bodies of living creatures, which eventually hatch into Slaad spawn.\n\nThese creatures are often found leading groups of Slaad spawn in raids on the Material Plane, spreading chaos and destruction wherever they go. They are worshipped by some cults as symbols of chaos and destruction, and are feared by many for their unpredictability and insatiable hunger."}',0,'Monster Manual 2024','','Acid, Cold, Fire, Lightning, Thunder',5.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b99-eb5a-7bff-a763-04c86a9ca761'::uuid,'Roper','NeutralEvil','5 (XP 1 800; PB +3)',1800,5,'Ambusher','Large',20,NULL,93,'11d10+33','10 ft.','20 ft.',NULL,NULL,18,8,17,7,16,6,'{"Stealth": 5, "Perception": 6}','None','Darkvision 60 ft., Passive Perception 16','—',3,-1,4,3,-2,-2,3,'[]','Habitat: Underdark','Aberration','','{"value":"Slithering tendrils writhe, beckoning with hypnotic grace."}','{"value": "In Dungeons and Dragons 5th edition, a Roper is a large, bizarre creature that resembles a stalactite or stalagmite. They are known for their long, slimy tentacles that they use to catch unsuspecting prey. \n\nThe lore of the Roper suggests that they are solitary creatures that dwell in dark, cavernous areas such as underground caves or deep dungeons. They are incredibly patient hunters, waiting for their prey to come close enough for them to strike with their tentacles. \n\nRopers are also known for their ability to camouflage themselves, blending in seamlessly with their surroundings to surprise their victims. They are highly territorial and will fiercely defend their lairs from any intruders. \n\nSome believe that Ropers have a symbiotic relationship with other creatures, such as Darkmantles or Cloakers, using them as minions to help defend their lairs. Overall, Ropers are considered dangerous and cunning predators that should be approached with caution by any adventurers venturing into their territory."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b9a-8758-7f95-a445-be36736917cf'::uuid,'Salamander','NeutralEvil','5 (XP 1 800; PB +3)',1800,2,'Brute','Large',15,NULL,90,'12d10+24','30 ft.','30 ft.',NULL,NULL,18,14,15,11,10,12,'{}','Fire','Darkvision 60 ft., Passive Perception 10','Primordial (Ignan)',2,2,4,0,1,0,3,'[]','Habitat: Planar (Elemental Plane of Fire), Underdark','Elemental','','{"value":"Tongue flicks out, eyes burning with fiery hunger."}','{"value": "Salamanders in Dungeons and Dragons are fiery, reptilian creatures that dwell in the Elemental Plane of Fire. They are known for their affinity for flames and their ability to manipulate and control fire.\n\nIn D&D lore, salamanders are typically depicted as aggressive and territorial beings, often serving as guardians of volcanic regions or as soldiers in the armies of fire-based creatures such as red dragons or efreeti. They are fearsome opponents in combat, wielding weapons made of molten metal and using their fiery breath to incinerate their enemies.\n\nSalamanders are known for their ability to withstand extreme heat, making them well-suited to their fiery environments. They are immune to fire damage and can even heal themselves by immersing in lava. They are also capable of summoning fire elementals to aid them in battle.\n\nIn some D&D campaigns, salamanders are portrayed as intelligent beings with a complex society and culture. They may be encountered as traders or diplomats, offering their services in exchange for valuable treasures or magical artifacts.\n\nOverall, salamanders are a fascinating and dangerous addition to the world of Dungeons and Dragons, providing a fiery challenge for adventurers brave enough to face them."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b9b-1034-7f2b-8d19-80002f454224'::uuid,'Sea Hag','ChaoticEvil','2 (XP 450; PB +2)',450,1,'Controller','Medium',14,NULL,52,'7d8+21','30 ft.',NULL,'40 ft.',NULL,16,13,16,12,12,13,'{}','None','Darkvision 60 ft., Passive Perception 11','Common, Giant, Primordial (Aquan)',3,1,3,1,1,1,2,'[]','Habitat: Coastal, Underwater','Fey','','{"value":"Swaying on her seaweed-covered rock, the Sea Hag cackles with twisted delight."}','{"value": "In Dungeons and Dragons 5th edition, Sea Hags are grotesque and malevolent creatures that dwell along coastlines and in underwater caves. These hags are known for their hideous appearance, with slimy green skin, stringy hair, and sharp claws. They are also known for their ability to cast powerful spells and curses, using their magic to manipulate and harm those who cross their path.\n\nSea Hags are often portrayed as solitary creatures, living in isolated areas where they can prey on unwary sailors and travelers. They are known to use their magic to lure victims to their lairs, where they then subject them to torture and torment. Sea Hags are also said to have a taste for the flesh of humans and other sentient beings, further adding to their reputation as cruel and malevolent creatures.\n\nIn D&D lore, Sea Hags are often associated with the sea and are said to have a deep connection to the ocean and its creatures. They are known to have the ability to control sea creatures and use them to do their bidding, further enhancing their reputation as powerful and dangerous foes.\n\nOverall, Sea Hags are terrifying and dangerous creatures in the world of Dungeons and Dragons, using their magic and cunning to prey on the unsuspecting and spread fear and chaos wherever they go."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b9b-6338-7573-8ffc-68f87abc8781'::uuid,'Shambling Mound','Unaligned','5 (XP 1 800; PB +3)',1800,-1,'Brute','Large',15,NULL,110,'13d10+39','30 ft.',NULL,'20 ft.',NULL,18,8,16,5,10,5,'{"Stealth": 3}','Lightning; Deafened, Exhaustion','Blindsight 60 ft., Passive Perception 10','—',3,-1,4,0,-3,-3,3,'[]','Habitat: Forest, Swamp','Plant','','{"value":"Vines writhe and grope, pulling the earth with each lumbering step"}','{"value": "The Shambling Mound is a large, sentient plant creature that roams the swamps and marshes of the world. It is believed to have been created by powerful druidic magic, combining various plant materials and infusing them with a malevolent spirit. The Shambling Mound is a fearsome predator, using its vines and tendrils to trap and crush its prey before absorbing their nutrients.\n\nDespite its slow and lumbering appearance, the Shambling Mound is surprisingly agile and can move quickly through the dense undergrowth of its swampy habitat. It is also highly resistant to physical attacks, as its thick, fibrous body can absorb and deflect blows with ease. Fire is one of the few weaknesses of the Shambling Mound, as its plant-based nature makes it highly susceptible to flames.\n\nLegends say that the Shambling Mound is fiercely protective of its territory, attacking any intruders that venture too close to its domain. Some believe that it serves as a guardian of the natural world, punishing those who seek to exploit or harm the delicate balance of the swamp ecosystem.\n\nEncountering a Shambling Mound in the wild is a daunting prospect for even the most experienced adventurers, as its formidable strength and resilience make it a formidable opponent. Only those with a deep understanding of nature and its mysteries may be able to find a way to defeat this fearsome monster and emerge victorious."}',0,'Monster Manual 2024 (BR)','','Cold, Fire',5.0,NULL),
	 ('01990b9c-022f-777c-9956-97d6c8783d6d'::uuid,'Spectator','LawfulNeutral','3 (XP 700; PB +2)',700,2,'Controller','Medium',14,NULL,45,'7d8+14','5 ft.',NULL,NULL,'30 ft.',8,14,14,13,14,11,'{"Perception": 6}','Exhaustion, Prone','Darkvision 120 ft., Passive Perception 16','Deep Speech, Undercommon; telepathy 120 ft.',2,2,-1,2,0,1,2,'[]','Habitat: Underdark','Aberration','Beholder','{"value":"Four eyes dart around the room, each one glowing with a different color."}','{"value": "The Spectator is a lesser beholder, a magical creature that resembles a large orb with a central eye and several smaller eye stalks. Unlike their more powerful beholder counterparts, Spectators are created through magical rituals and are typically bound to serve as guardians or protectors.\n\nSpectators are known for their ability to shoot various magical beams from their eye stalks, each with a different effect such as petrification, sleep, or fear. They are also capable of creating magical barriers to protect themselves and their charges.\n\nSpectators are typically summoned and bound to guard a specific location or object, such as a treasure trove or a magical artifact. They are fiercely loyal to their masters and will defend their charges with all of their magical abilities.\n\nDespite their fearsome appearance, Spectators are generally not malevolent creatures and will only attack if they feel threatened or if their charges are in danger. They are known to be quite intelligent and can be reasoned with, making them valuable allies if approached diplomatically.\n\nIn summary, Spectators are powerful magical guardians that are bound to protect specific locations or objects. They are capable of unleashing a variety of magical attacks and defenses, but are generally not aggressive unless provoked."}',0,'Monster Manual 2024','Beholder','None',3.0,NULL),
	 ('01990b9c-448b-766b-b406-884f0c13df26'::uuid,'Sphinx of Lore','LawfulNeutral','11 (XP 7 200, or 8 400 in lair; PB +4)',7200,10,'Solo','Large',17,NULL,170,'20d10+60','40 ft.',NULL,NULL,'60 ft.',18,15,16,18,18,18,'{"Arcana": 12, "History": 12, "Religion": 12, "Perception": 8}','Psychic; Charmed, Frightened','Truesight 120 ft., Passive Perception 18','Celestial, Common',3,2,4,4,4,4,4,'[]','Habitat: Desert, Planar (Upper Planes)','Celestial','','{"value":"Eyes gleam with ancient wisdom, a riddle poised on its tongue."}','{"value": "The Sphinx of Lore is a powerful and enigmatic creature that is known for its vast knowledge and wisdom. These creatures are often found in ancient ruins, libraries, or other places of knowledge and are said to possess incredible intelligence and insight.\n\nSphinxes of Lore are typically depicted as having the body of a lion and the head of a human, with wings and a tail. They are known for their riddles and puzzles, which they use to test the intelligence and worthiness of those who seek their knowledge.\n\nThese creatures are said to be guardians of ancient wisdom and are rumored to have access to secret knowledge and prophecies. Many adventurers seek out Sphinxes of Lore in hopes of gaining insight into the mysteries of the world or finding answers to difficult questions.\n\nHowever, approaching a Sphinx of Lore is not without risk, as they are known to be fierce and unpredictable creatures. Those who fail to answer their riddles or challenges may face grave consequences.\n\nOverall, the Sphinx of Lore is a fascinating and mysterious creature in the world of Dungeons and Dragons, embodying the ideals of knowledge, wisdom, and mystery."}',0,'Monster Manual 2024 (BR)','','Necrotic, Radiant',11.0,8400.0),
	 ('01990b9c-a5b6-7f0b-8041-2f75b72eeb76'::uuid,'Sphinx of Wonder','LawfulGood','1 (XP 200; PB +2)',200,3,'Support','Tiny',13,NULL,24,'7d4+7','20 ft.',NULL,NULL,'40 ft.',6,17,13,15,12,11,'{"Arcana": 4, "Stealth": 5, "Religion": 4}','None','Darkvision 60 ft., Passive Perception 11','Celestial, Common',1,3,-2,1,0,2,2,'[]','Habitat: Desert, Planar (Upper Planes)','Celestial','','{"value":"Its eyes glow with ancient knowledge, its voice a melodic hum of secrets."}','{"value": "The Sphinx of Wonder is a powerful and enigmatic creature that is said to possess great knowledge and wisdom. It is known for its ability to ask riddles and puzzles to those who seek its counsel, testing their intelligence and problem-solving skills.\n\nLegends say that the Sphinx of Wonder was created by ancient gods as a guardian of hidden knowledge and secrets. It is said to reside in a hidden temple or labyrinth, where only the most worthy and determined adventurers can reach it.\n\nThose who successfully answer the Sphinx''s riddles are said to be granted a boon or a piece of valuable information. However, those who fail are often met with a terrible fate, such as being turned to stone or cursed in some way.\n\nThe Sphinx of Wonder is a creature of neutrality, neither inherently good nor evil. It values intelligence, curiosity, and a thirst for knowledge above all else. It is a being of great mystery and power, and those who seek it out must be prepared to face its challenges and prove themselves worthy of its wisdom."}',0,'Monster Manual 2024 (BR)','','Necrotic, Psychic, Radiant',1.0,NULL),
	 ('01990b9d-1b49-74b8-9cc5-ac0fa4bc67b6'::uuid,'Spy','TrueNeutral','1 (XP 200; PB +2)',200,4,'Ambusher','Medium',12,NULL,27,'6d8','30 ft.','30 ft.',NULL,NULL,10,15,10,12,14,16,'{"Insight": 4, "Stealth": 6, "Deception": 5, "Perception": 6, "Investigation": 5, "Sleight of Hand": 4}','None','Passive Perception 16','Common plus one other language',0,2,0,2,3,1,2,'["Hand Crossbow", "Shortsword", "Thieves'' Tools"]','Habitat: Any','Humanoid','','{"value":"Eyes darting, it whispers secrets to unseen allies, always watching."}','{"value": "Spies in D&D 5e are humanoid creatures that are skilled in espionage and stealth. They are often used by governments, organizations, or individuals to gather information, carry out covert operations, or sabotage enemies. \n\nSpies are highly trained in various forms of combat, as well as in deception, disguise, and infiltration. They are masters of disguise, able to blend in seamlessly with their surroundings and adopt different personas to accomplish their missions. \n\nThese creatures are often equipped with tools such as lockpicks, poisons, and other gadgets to aid them in their work. They are also skilled in both ranged and melee combat, making them formidable opponents in battle. \n\nOverall, spies in D&D 5e are dangerous and cunning adversaries, capable of outsmarting and outmaneuvering their enemies with their stealth and cunning tactics."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b9d-f6bb-733d-a315-5547bf7fad88'::uuid,'Storm Giant','ChaoticGood','13 (XP 10 000; PB +5)',10000,7,'Artillery','Huge',16,NULL,230,'20d12+100','50 ft.',NULL,'50 ft.','25 ft.',29,14,20,16,20,18,'{"Arcana": 8, "History": 8, "Athletics": 14, "Perception": 10}','Lightning, Thunder','Darkvision 120 ft., Truesight 30 ft., Passive Perception 20','Common, Giant',10,2,14,10,9,3,5,'[]','Habitat: Coastal, Underwater','Giant','','{"value":"Thunderous steps shake the ground as lightning crackles around its massive form"}','{"value": "Storm giants are powerful and majestic beings that stand at over 20 feet tall. They are known for their control over the weather, able to summon storms and lightning at will. These giants are often seen as protectors of the sea and sky, using their powers to maintain balance in nature.\n\nIn D&D 5e, storm giants are described as wise and benevolent beings, often living in secluded and remote locations such as mountaintops or islands. They are known for their intelligence and are sometimes sought out by other races for their wisdom and guidance.\n\nIn combat, storm giants are formidable opponents, using their immense strength and lightning abilities to overpower their foes. They are also skilled in the use of weapons and can hurl massive boulders with deadly accuracy.\n\nDespite their power and strength, storm giants are typically peaceful and prefer to avoid conflict whenever possible. They are known to be kind and compassionate towards other creatures, especially those in need of help.\n\nOverall, storm giants are seen as noble and majestic creatures in the world of D&D, embodying the power and beauty of nature itself."}',0,'Monster Manual 2024 (BR)','','Cold',13.0,NULL),
	 ('01990b8c-1a79-70d9-8b44-9ccb1bb8fd2c'::uuid,'Giant Shark','Unaligned','5 (XP 1 800; PB +3)',1800,3,'Brute','Huge',13,NULL,92,'8d12+40','5 ft.',NULL,'60 ft.',NULL,23,11,21,1,10,5,'{"Perception": 3}','None','Blindsight 60 ft., Passive Perception 13','—',5,0,6,0,-3,-5,3,'[]',NULL,'Beast','','{"value":"Jaws snap open, revealing rows of razor-sharp teeth, eyes fixated on prey."}','{"value": "Giant Sharks are massive, predatory creatures that inhabit the oceans and seas of the world. They are known for their immense size, powerful jaws filled with rows of razor-sharp teeth, and their insatiable hunger for prey. Giant Sharks are feared by sailors and coastal communities alike, as they are known to attack ships and even coastal villages in search of food.\n\nIn D&D 5e, Giant Sharks are classified as Huge beasts with a CR of 5. They have a high swim speed and are capable of leaping out of the water to attack their prey. Giant Sharks are solitary hunters, typically patrolling their territory in search of smaller creatures to devour. They are known to be highly aggressive and territorial, making them a dangerous threat to anyone who ventures into their domain.\n\nIn some D&D campaigns, Giant Sharks may be worshiped as deities by underwater civilizations or used as mounts by powerful sea creatures. They are often encountered as random encounters while traveling by sea or during underwater adventures. Defeating a Giant Shark can be a challenging and rewarding experience for a party of adventurers, as they are formidable opponents with powerful abilities and a ferocious fighting style."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b9e-6684-75de-9f16-eee02ae3a0eb'::uuid,'Swarm of Lemures','LawfulEvil','3 (XP 700; PB +2)',700,-2,'Minion','Large',12,NULL,45,'6d10+12','40 ft.',NULL,NULL,NULL,14,7,14,1,12,3,'{}','Fire, Poison; Charmed, Frightened, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Stunned','Darkvision 120 ft. (unimpeded by magical Darkness), Passive Perception 11','Understands Infernal but can''t speak',2,-2,2,1,-4,-5,2,'[]','Habitat: Planar (Nine Hells)','swarm of Medium Fiends','Devil','{"value":"Whispers in unison, writhing and squirming in a putrid mass."}','{"value": "In Dungeons and Dragons 5th edition, a Swarm of Lemures is a horde of lesser devils known as lemures that have been bound together in a mass of writhing, mindless flesh. Lemures are the lowest-ranking devils in the hierarchy of the Nine Hells, and they are considered to be little more than mindless drones used for manual labor and menial tasks.\n\nWhen a group of lemures is magically bound together, they form a Swarm of Lemures, a terrifying mass of twisted, writhing bodies that moves as one and attacks as a single entity. The swarm can engulf its enemies, overwhelming them with sheer numbers and tearing them apart with its claws and teeth.\n\nSwarm of Lemures are often summoned by more powerful devils to serve as shock troops or to guard important locations. They are mindless and relentless in their pursuit of their orders, attacking anything that comes within their grasp without hesitation or fear. Dealing with a Swarm of Lemures requires quick thinking and powerful attacks, as they can quickly overwhelm even the most seasoned adventurers with their sheer numbers and ferocity."}',0,'Monster Manual 2024','Devil','Bludgeoning, Cold, Piercing, Slashing',3.0,NULL),
	 ('01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Tarrasque','Unaligned','30 (XP 155 000; PB +9)',155000,18,'Solo','Gargantuan',25,NULL,697,'34d20+340','60 ft.','60 ft.',NULL,NULL,30,11,30,3,11,11,'{"Perception": 9}','Fire, Poison; Charmed, Deafened, Frightened, Paralyzed, Poisoned','Blindsight 120 ft., Passive Perception 19','None',10,9,10,9,9,5,9,'[]','Habitat: Urban','Monstrosity','Titan','{"value":"Rumbling steps shake the earth as the Tarrasque\u0027s massive form emerges from the shadows."}','{"value": "The Tarrasque is a legendary creature in the world of Dungeons & Dragons, known for its immense size, strength, and destructive power. It is often described as a colossal, reptilian monster with thick, armored scales covering its body. The creature is said to be nearly indestructible, with the ability to regenerate from almost any injury.\n\nLegends say that the Tarrasque is a primal force of destruction, awakening from its slumber every few centuries to wreak havoc upon the land. It is said to be a mindless beast, driven only by its insatiable hunger and desire to destroy everything in its path.\n\nMany civilizations throughout history have tried to defeat the Tarrasque, but few have succeeded. The creature is often depicted as a force of nature, too powerful and too dangerous to be controlled or tamed.\n\nAdventurers who dare to face the Tarrasque are often seen as heroes or fools, risking their lives to protect their homes and loved ones from the creature''s wrath. Some believe that defeating the Tarrasque is impossible, while others see it as a challenge worthy of their skills and bravery.\n\nIn the world of Dungeons & Dragons, the Tarrasque is considered one of the most powerful and iconic monsters, a true force of nature that strikes fear into the hearts of even the most seasoned adventurers."}',0,'Monster Manual 2024 (BR)','Titan','Bludgeoning, Piercing, Slashing',30.0,NULL),
	 ('01990b9f-1a86-73ff-8e8e-db9b3e0dd5df'::uuid,'Tiger','Unaligned','1 (XP 200; PB +2)',200,3,'Skirmisher','Large',13,NULL,30,'4d10+8','40 ft.',NULL,NULL,NULL,17,16,14,3,12,8,'{"Stealth": 7, "Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','None',2,3,3,1,1,4,2,'[]',NULL,'Beast','','{"value":"Roaring, it prowls with predatory grace, eyes fixed hungrily on its prey."}','{"value": "In Dungeons and Dragons 5th edition, the tiger is a large, powerful, and ferocious feline creature that is often found in forests and jungles. Tigers are apex predators known for their strength, agility, and deadly hunting skills.\n\nIn D&D lore, tigers are often portrayed as solitary hunters that roam their territory in search of prey. They are known to be territorial creatures, fiercely defending their territory from other predators and intruders.\n\nTigers are typically depicted as having a sleek, striped fur coat, sharp claws, and powerful jaws. They are known for their stealth and ambush tactics, using their camouflage and agility to surprise their prey.\n\nIn D&D, tigers are sometimes used as mounts by certain humanoid races, such as orcs or hobgoblins. These creatures use tigers as powerful and intimidating mounts in battle.\n\nOverall, tigers are fearsome and iconic creatures in D&D lore, known for their strength, ferocity, and predatory instincts. They are a popular choice for encounters in wilderness settings, adding a dangerous and thrilling element to any adventure."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b8c-2f60-70e1-b4ff-998cc2f10495'::uuid,'Giant Spider','Unaligned','1 (XP 200; PB +2)',200,3,'Ambusher','Large',14,NULL,26,'4d10+4','30 ft.','30 ft.',NULL,NULL,14,16,12,2,11,4,'{"Stealth": 7, "Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','None',1,3,2,0,3,4,2,'[]',NULL,'Beast','','{"value":"Eight legs skitter, fangs dripping with venom, as it descends from the shadows."}','{"value": "In the world of Dungeons and Dragons, Giant Spiders are fearsome creatures that dwell in dark, damp places such as forests, caves, and dungeons. These monstrous arachnids are known for their large size, ranging from the size of a dog to that of a horse, and their ability to spin webs to trap their prey.\n\nGiant Spiders are highly intelligent predators that use their webs to catch unsuspecting victims. They are able to sense vibrations in their webs, allowing them to quickly pounce on any creature that becomes ensnared. Their venomous bite can paralyze or kill their prey, making them a formidable opponent for adventurers.\n\nIn D&D lore, Giant Spiders are often depicted as solitary creatures, but some can be found living in colonies with a queen spider at the helm. These colonies can be quite dangerous, as the spiders work together to defend their territory and capture food.\n\nOverall, Giant Spiders are iconic monsters in Dungeons and Dragons, known for their creepy appearance and deadly abilities. Players must be cautious when encountering these creatures, as they are skilled hunters that can easily overpower the unprepared."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990ba0-06f1-7c9c-93d2-d4295bd1b34d'::uuid,'Umber Hulk','ChaoticEvil','5 (XP 1 800; PB +3)',1800,4,'Brute','Large',18,NULL,93,'11d10+33','30 ft.',NULL,NULL,NULL,20,13,16,9,10,10,'{}','None','Darkvision 120 ft., Tremorsense 60 ft., Passive Perception 10','Umber Hulk',3,1,5,0,0,-1,3,'[]','Habitat: Underdark','Monstrosity','','{"value":"Eyes gleam with predatory hunger as it burrows towards you, claws clicking."}','{"value": "Umber Hulks are large, insectoid creatures that dwell underground in dark, labyrinthine tunnels. They are known for their powerful claws and massive mandibles, as well as their ability to confuse and disorient their enemies with their hypnotic gaze.\n\nAccording to lore, Umber Hulks are solitary creatures that prefer to live and hunt alone. They are highly territorial and will fiercely defend their underground lairs from intruders. Despite their fearsome appearance, Umber Hulks are not inherently aggressive and will only attack if provoked or if they feel their territory is threatened.\n\nUmber Hulks are often employed by evil creatures such as drow and mind flayers as guards or enforcers, due to their natural strength and ferocity in battle. They are also known to be skilled diggers, able to tunnel through solid rock with ease to create new passageways or escape routes.\n\nIn some cultures, Umber Hulks are believed to be harbingers of bad luck or omens of impending disaster. Others see them as symbols of strength and resilience, revered for their ability to survive and thrive in the harsh conditions of the Underdark.\n\nOverall, Umber Hulks are formidable foes that should not be underestimated by adventurers brave enough to venture into the depths of the earth."}',0,'Monster Manual 2024','','None',5.0,NULL),
	 ('01990ba0-d6c7-7dca-bc53-4a43adf6b054'::uuid,'Vampire Nightbringer','NeutralEvil','8 (XP 3 900; PB +3)',3900,4,'Brute','Medium',16,NULL,142,'19d8+57','30 ft.',NULL,NULL,'30 ft.',16,18,16,13,14,15,'{"Stealth": 7, "Perception": 5}','Cold, Necrotic; Charmed, Exhaustion, Frightened','Darkvision 120 ft., Passive Perception 15','Common plus one other language',3,7,3,5,2,1,3,'[]','Habitat: Underdark, Urban','Undead','','{"value":"Sulking in the shadows, its eyes gleam with hunger as it stalks its prey."}','{"value": "The Vampire Nightbringer is a powerful and ancient undead creature that is said to be a master of the shadows and darkness. It is believed to have been created by a powerful necromancer who sought to achieve immortality through dark magic. The Vampire Nightbringer is said to be able to control and manipulate shadows to its will, using them to strike fear into the hearts of its enemies.\n\nThis monster is said to be incredibly fast and agile, able to move swiftly and silently through the darkness. It is also said to have a hypnotic gaze that can mesmerize its victims, making them easy prey for its deadly attacks. The Vampire Nightbringer is known to be incredibly strong and resilient, able to shrug off most physical attacks with ease.\n\nLegends say that the only way to truly destroy a Vampire Nightbringer is to expose it to direct sunlight, which will cause it to burst into flames and be consumed by the light. Otherwise, it is said to be nearly impossible to defeat this fearsome creature in combat. Many adventurers have sought to challenge the Vampire Nightbringer, but few have returned to tell the tale."}',0,'Monster Manual 2024','','None',8.0,NULL),
	 ('01990ba1-42e6-7a3d-a034-77b0db3aefe7'::uuid,'Violet Fungus Necrohulk','NeutralEvil','7 (XP 2,900; PB +3)',2900,4,'Brute','Large',17,NULL,123,'13d10+52',NULL,NULL,NULL,NULL,19,12,18,7,14,10,'{}','Necrotic, Poison; Blinded, Charmed, Deafened, Frightened, Poisoned','Blindsight 60 ft., Passive Perception 12','None',4,1,4,2,0,-2,3,'[]','Habitat: Underdark','Plant','','{"value":"Spores burst forth as it looms, tendrils writhing with necrotic energy."}','{"value": "The Violet Fungus Necrohulk is a monstrous creature that combines the deadly abilities of a Violet Fungus with the immense strength and resilience of a hulking undead creature. This abomination is created through dark necromantic rituals that infuse a Violet Fungus with the power of undeath, turning it into a towering and terrifying monster.\n\nThe Violet Fungus Necrohulk is covered in pulsating violet spores that release a toxic gas, causing paralysis in its victims. Its massive size and strength make it a formidable opponent in combat, capable of crushing its enemies with its powerful tentacles and releasing waves of necrotic energy.\n\nLegends say that the Violet Fungus Necrohulk was originally created by a powerful necromancer seeking to create the ultimate guardian for their lair. However, the creature proved to be uncontrollable and broke free, wreaking havoc on the surrounding lands. Now, it roams the wilderness, seeking out new victims to feed on and spreading fear wherever it goes. Its very presence is a reminder of the dark and twisted powers that can be unleashed through forbidden magic."}',0,'Monster Manual 2024','','None',7.0,NULL),
	 ('01990ba2-0c06-7e3c-9734-4195cb02aafa'::uuid,'Weasel','Unaligned','0 (XP 10; PB +2)',10,3,'Ambusher','Tiny',13,NULL,1,'1d4-1','30 ft.','30 ft.',NULL,NULL,3,16,8,2,12,3,'{"Stealth": 5, "Acrobatics": 5, "Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','None',1,3,4,1,4,4,2,'[]',NULL,'Beast','','{"value":"Sleek body twitches with anticipation, eyes fixed and darting."}','{"value": "Weasels are small, carnivorous creatures known for their agility and speed. They are commonly found in forests and grasslands, where they use their keen sense of smell and sharp claws to hunt for small prey such as mice, rabbits, and birds.\n\nIn D&D 5e, weasels are depicted as cunning and opportunistic creatures that are often used as familiars by spellcasters. They are known for their ability to squeeze into tight spaces and move quickly to avoid danger. Weasels are typically neutral in alignment, but can be trained to be loyal companions to those who earn their trust.\n\nIn some cultures, weasels are seen as symbols of stealth and trickery, and are sometimes associated with thieves and spies. They are also sometimes used in alchemical experiments or as ingredients in potions due to their unique properties.\n\nOverall, weasels are versatile creatures that can be used in a variety of ways in a D&D campaign, whether as a familiar, a companion, or a foe to be reckoned with."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990ba2-81d0-730e-b70b-bb07b1769bdb'::uuid,'Wererat','LawfulEvil','2 (XP 450; PB +2)',450,3,'Skirmisher','Medium',13,NULL,60,'11d8+11','30 ft.','30 ft.',NULL,NULL,10,16,12,11,10,8,'{"Stealth": 5, "Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','Common (can''t speak in rat form)',1,3,0,0,-1,0,2,'["Hand Crossbow"]','Habitat: Forest, Urban','Monstrosity','Lycanthrope','{"value":"Sneaky whiskers twitch, eyes gleaming with hunger as it circles its prey."}','{"value": "Wererats are cursed humanoids who can transform into rat-like creatures. They are often found in urban areas, living in sewers or abandoned buildings. Wererats are known for their stealth and cunning, making them skilled thieves and assassins.\n\nIn their humanoid form, wererats appear as normal humans, but with sharp features and rat-like qualities. When they transform into their rat form, they become larger versions of regular rats with sharp teeth and claws.\n\nWererats are immune to non-magical weapons and have heightened senses of smell and hearing. They are also resistant to poison and disease. In combat, they rely on their agility and speed to outmaneuver their opponents.\n\nWererats are known to spread their curse by biting humans and infecting them with lycanthropy. Those who are bitten by a wererat may eventually transform into one themselves.\n\nOverall, wererats are dangerous and cunning creatures that should be approached with caution. Their presence in a city can lead to increased crime and chaos, making them a threat to both adventurers and civilians alike."}',0,'Monster Manual 2024 (BR)','Lycanthrope','None',2.0,NULL),
	 ('01990ba3-5aed-79e1-ae68-bd05dcb45c94'::uuid,'Wight','NeutralEvil','3 (XP 700; PB +2)',700,4,'Brute','Medium',14,NULL,82,'11d8+33','30 ft.',NULL,NULL,NULL,15,14,16,10,13,15,'{"Stealth": 4, "Perception": 3}','Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 13','Common plus one other language',3,2,2,1,2,0,2,'["Studded Leather Armor"]','Habitat: Desert, Planar (Shadowfell), Swamp, Underdark, Urban','Undead','','{"value":"Grasping at souls, its eyes burn with an insatiable hunger."}','{"value": "In Dungeons and Dragons 5th Edition, a wight is an undead creature that was once a humanoid but has been transformed into a fearsome undead being through a curse or dark ritual. Wights are usually created when a powerful evil spirit possesses the body of a deceased humanoid, animating it and imbuing it with dark powers.\n\nWights are often found in dark, desolate places such as graveyards, crypts, or abandoned ruins. They are known for their insatiable hunger for life force, which they drain from the living to sustain themselves. Wights are also capable of draining the life force of their victims with a touch, turning them into mindless undead thralls under their control.\n\nIn combat, wights are formidable foes, using their supernatural strength and agility to overpower their enemies. They are resistant to many forms of damage and can regenerate quickly, making them difficult to defeat. Wights are also immune to many types of magical effects, making them even more dangerous opponents.\n\nIn D&D lore, wights are often depicted as tragic figures, cursed to roam the world in eternal torment. Some wights may have retained fragments of their former selves, leading them to seek revenge on those who wronged them in life. Others may simply be mindless predators, driven by their insatiable thirst for life force.\n\nOverall, wights are a terrifying and dangerous foe in the world of Dungeons and Dragons, and adventurers would be wise to approach them with caution and prepare themselves for a difficult battle."}',0,'Monster Manual 2024 (BR)','','Necrotic',3.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990ba3-a9eb-7e67-bd83-7158f0741ba0'::uuid,'Wraith','NeutralEvil','5 (XP 1,800; PB +3)',1800,3,'Ambusher','Medium',13,NULL,67,'9d8+27','5 ft.',NULL,NULL,'60 ft.',6,16,16,12,14,15,'{}','Necrotic, Poison; Charmed, Exhaustion, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Darkvision 60 ft., Passive Perception 12','Common plus two other languages',3,3,-2,2,2,1,3,'[]','Habitat: Planar (Shadowfell), Underdark','Undead','','{"value":"It hovers silently, its ghostly form flickering with malevolent energy"}','{"value": "In the world of Dungeons and Dragons, a wraith is a type of undead creature that was once a powerful and malevolent entity in life. Wraiths are created when a person dies with a deep hatred or desire for revenge, causing their soul to linger on in the material plane as a twisted and vengeful spirit.\n\nWraiths are typically found haunting places where they met their demise or where they harbored intense negative emotions in life. They are known for their ability to drain the life force from living creatures with a touch, leaving their victims weakened and vulnerable.\n\nIn combat, wraiths are formidable foes, able to pass through walls and other obstacles with ease and strike at their enemies with their chilling touch. They are immune to many forms of damage and are resistant to most spells and magical effects.\n\nWraiths are often encountered as guardians of ancient tombs or cursed locations, where they serve to protect the treasures or secrets hidden within. They are relentless in their pursuit of vengeance and will stop at nothing to destroy those who trespass in their domain.\n\nOverall, wraiths are terrifying and malevolent creatures that embody the darker aspects of death and undeath in the world of Dungeons and Dragons. They are a constant reminder of the dangers of anger, hatred, and unfulfilled desires in life, and serve as a cautionary tale for those who would seek to defy the natural order of life and death."}',0,'Monster Manual 2024 (BR)','','Acid, Bludgeoning, Cold, Fire, Piercing, Slashing',5.0,NULL),
	 ('01990b8c-7a44-7a0e-97ba-f9010e75710c'::uuid,'Giant Toad','Unaligned','1 (XP 200; PB +2)',200,1,'Brute','Large',11,NULL,39,'6d10+6','30 ft.',NULL,'30 ft.',NULL,15,13,13,2,10,3,'{}','None','Darkvision 60 ft., Passive Perception 10','None',1,1,2,0,-4,-4,2,'[]',NULL,'Beast','','{"value":"Giant Toad croaks loudly, tongue flicking out to snatch unsuspecting prey."}','{"value": "Giant toads are massive amphibious creatures that can be found in swamps, marshes, and other damp environments. They are known for their powerful jumps and sticky tongues, which they use to catch prey such as insects, small animals, and even unwary adventurers. \n\nIn some regions, giant toads are revered as sacred creatures and are seen as symbols of fertility and abundance. They are often associated with water deities and are sometimes kept as pets or guardians by druids and other nature-oriented spellcasters.\n\nGiant toads are typically solitary creatures, but during mating season they will gather in large groups to mate and lay their eggs. Their tadpoles are voracious predators and will eat anything they can catch, including their own siblings. Once they reach adulthood, giant toads are fierce hunters and will not hesitate to attack anything that comes too close to their territory.\n\nDespite their fearsome reputation, giant toads can be tamed and trained by skilled handlers. Some adventurers have even been known to ride them into battle, using their strength and agility to gain an advantage over their enemies. However, those who underestimate the power of a giant toad are likely to end up as a meal for these formidable creatures."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990ba4-4917-72cb-a75d-ef4a5660583d'::uuid,'Young Blue Dragon','LawfulEvil','9 (XP 5 000; PB +4)',5000,4,'Brute','Large',18,NULL,152,'16d10+64','40 ft.',NULL,NULL,'80 ft.',21,10,19,14,13,17,'{"Stealth": 4, "Perception": 9}','Lightning','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 19','Common, Draconic',4,4,5,5,3,2,4,'[]','Habitat: Coastal, Desert','Dragon','Chromatic','{"value":"Electricity crackles along its scales as it snarls, eyes fixed hungrily on you."}','{"value": "Young Blue Dragons are chromatic dragons known for their cunning and vicious nature. They are often found in deserts or arid regions where they can easily blend in with their surroundings. These dragons are known for their lightning breath weapon, which they use to devastating effect in combat.\n\nYoung Blue Dragons are highly intelligent and prideful creatures, often viewing themselves as superior to other beings. They are known for their love of treasure and will go to great lengths to hoard as much wealth as possible. Despite their arrogance, they are also known for their loyalty to their allies, particularly those who can help them acquire more treasure.\n\nIn combat, Young Blue Dragons are known for their tactical prowess and ability to outmaneuver their opponents. They are also skilled in aerial combat, using their wings to quickly move around the battlefield. They are formidable opponents and should not be underestimated by any would-be adventurers."}',0,'Monster Manual 2024 (BR)','Chromatic','None',9.0,NULL),
	 ('01990ba4-a075-79b8-b502-dca089f0791a'::uuid,'Young Copper Dragon','ChaoticGood','7 (XP 2 900; PB +3)',2900,4,'Solo','Large',17,NULL,119,'14d10+42','40 ft.','40 ft.',NULL,'80 ft.',19,12,17,16,13,15,'{"Stealth": 4, "Deception": 5, "Perception": 7}','Acid','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 17','Common, Draconic',3,4,4,4,2,3,3,'[]','Habitat: Hill','Dragon','Metallic','{"value":"Scales shimmering, it playfully dances in the air, exhaling a warm breath of curiosity."}','{"value": "Young Copper Dragons are mischievous and playful creatures that enjoy tricking and outsmarting those they encounter. They are known for their love of riddles and puzzles, often using them to test the intelligence of potential foes. Despite their playful nature, they are fiercely protective of their hoards and will defend them with vigor.\n\nThese dragons are known for their copper-colored scales, which provide them with excellent camouflage in rocky or forested terrain. They are skilled in both aerial and ground combat, using their breath weapon of acid to dissolve their enemies. Young Copper Dragons are also adept at burrowing underground to surprise their foes.\n\nWhile they may be playful and mischievous, Young Copper Dragons are also intelligent and cunning creatures. They are known for their ability to manipulate situations to their advantage and are not to be underestimated in battle. Their hoards often contain a mix of valuable treasures and practical items that they have collected over time."}',0,'Monster Manual 2024 (BR)','Metallic','None',7.0,NULL),
	 ('01990b8c-e83d-7438-8c48-752227fa572f'::uuid,'Githyanki Warrior','LawfulEvil','3 (XP 700; PB +2)',700,4,'Soldier','Medium',17,NULL,49,'9d8+9','30 ft.',NULL,NULL,NULL,15,14,12,13,13,10,'{}','None','Passive Perception 11','Common, Gith',3,2,2,3,0,3,2,'["Half Plate Armor"]','Habitat: Planar (Astral Plane)','Aberration','Gith','{"value":"Brandishing its silver sword, the warrior\u0027s eyes glow with a thirst for battle."}','{"value": "The Githyanki are a race of astral-traveling warriors who were once enslaved by mind flayers. The Githyanki Warrior is a fierce and disciplined warrior who is trained from birth in the art of combat. They are known for their mastery of the silver sword, a weapon that is infused with psychic energy and is deadly to their enemies.\n\nGithyanki Warriors are fiercely loyal to their leaders, the Lich-Queen and the Supreme Commander, and will stop at nothing to further the goals of their people. They are often encountered riding red dragons, which they use as mounts in battle.\n\nThese warriors are highly skilled in both melee and ranged combat, and are capable of using psionic abilities to enhance their fighting prowess. They are also skilled in the use of magic, particularly spells that manipulate time and space.\n\nIn battle, Githyanki Warriors are known for their aggressive and relentless tactics, never giving an inch to their enemies. They are feared throughout the multiverse for their skill in combat and their unyielding determination to achieve victory at any cost."}',0,'Monster Manual 2024','Gith','None',3.0,NULL),
	 ('01990ba5-1b1f-7bbb-a169-e7e21f7b7cff'::uuid,'Young Silver Dragon','LawfulGood','9 (XP 5 000; PB +4)',5000,4,'Solo','Large',18,NULL,168,'16d10+80','40 ft.',NULL,NULL,'80 ft.',23,10,21,14,11,19,'{"History": 6, "Stealth": 4, "Perception": 8}','Cold','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 18','Common, Draconic',5,4,6,4,4,2,4,'[]','Habitat: Mountain, Urban','Dragon','Metallic','{"value":"Its silver scales shimmer in the sunlight as it playfully circles overhead, watching you."}','{"value": "Young Silver Dragons are noble and benevolent creatures that are known for their love of justice and protection of the innocent. They often take on the role of guardians and champions, using their strength, intelligence, and magical abilities to defend those in need.\n\nThese dragons are typically found in remote, mountainous regions where they make their lairs in caves or hidden valleys. They have shimmering silver scales that reflect the light like polished metal, and their wings are graceful and powerful, allowing them to soar through the skies with ease.\n\nYoung Silver Dragons are highly intelligent and wise, and they possess a natural charisma that allows them to easily communicate with other creatures. They are known for their sense of honor and duty, and they will go to great lengths to uphold justice and protect the innocent.\n\nIn combat, Young Silver Dragons are formidable opponents, using their breath weapon of icy cold to freeze their enemies in their tracks. They are also skilled in melee combat, using their sharp claws and powerful bite to take down foes.\n\nOverall, Young Silver Dragons are revered as symbols of hope and protection in the world of Dungeons and Dragons, and encountering one is considered a rare and wondrous event."}',0,'Monster Manual 2024 (BR)','Metallic','None',9.0,NULL),
	 ('01990bc2-cfa8-70df-b173-7a8f45c7a69a'::uuid,'Yuan-ti Malison (Type 2)','NeutralEvil','3 (XP 700; PB +2)',700,2,'Soldier','Medium',12,NULL,66,'12d8+12','30 ft.','30 ft.',NULL,NULL,16,14,13,14,16,12,'{"Stealth": {"bonus": 4, "condition": "while in snake form", "conditionalBonus": 6}}','Poison; Poisoned','Darkvision 60 ft., Passive Perception 13','Abyssal, Common, Draconic',1,2,3,3,1,2,2,'[]','Habitat: Desert, Forest, Swamp, Urban','Monstrosity','','{"value":"Serpentine body coils, eyes fixated on prey, tongue flicking the air with anticipation"}','{"value": "The Yuan-ti Malison (Type 2) is a powerful serpent-like creature in Dungeons and Dragons 5th edition. They are a higher ranking member of the Yuan-ti race, a race of snake-like humanoids who worship and serve the evil snake deity, Merrshaulk.\n\nYuan-ti Malisons are known for their cunning and devious nature, often using their shape-shifting abilities to infiltrate and manipulate others for their own gain. They are skilled in both magic and combat, making them formidable opponents in battle.\n\nThese creatures are often found leading groups of lesser Yuan-ti or other creatures in service to their dark god. They are known for their cruelty and ruthlessness, showing no mercy to those who stand in their way.\n\nYuan-ti Malisons are typically encountered in underground lairs, ancient ruins, or other remote locations where they can conduct their dark rituals and schemes without interference. They are a dangerous foe for any adventurer to face, as they are not only powerful in combat but also skilled in manipulation and deception."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01990b81-b7b7-75d3-992f-3d3e3db3b941'::uuid,'Blood Hawk','Unaligned','1/8 (XP 25; PB +2)',25,2,'Skirmisher','Small',12,NULL,7,'2d6','10 ft.',NULL,NULL,'60 ft.',6,14,10,3,14,5,'{"Perception": 6}','None','Passive Perception 16','None',0,2,-2,2,-3,-4,2,'[]',NULL,'Beast','','{"value":"Feathers rustle as it eyes you hungrily, wings poised to strike."}','{"value": "Blood Hawks are large predatory birds known for their aggressive and territorial nature. They are often found in mountainous regions or forests, where they hunt for small animals and other birds. Blood Hawks are named for their distinctive crimson feathers, which are said to be stained with the blood of their prey.\n\nIn some cultures, Blood Hawks are considered symbols of death and destruction, and are feared and respected by those who live in their territory. They are known to attack lone travelers or small groups, swooping down from the sky with their sharp talons and beaks.\n\nDespite their fearsome reputation, Blood Hawks have been known to form close bonds with certain individuals, particularly those who prove themselves to be strong and skilled hunters. In some cases, these birds have even been tamed and trained to serve as companions or mounts.\n\nOverall, Blood Hawks are dangerous creatures that should be approached with caution, but they also possess a certain majesty and beauty that has captivated many adventurers and scholars alike."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b5d-2220-7fcb-8a9e-62ac929409b1'::uuid,'Adult Brass Dragon','ChaoticGood','13 (XP 10 000, or 11 500 in lair; PB +5)',10000,10,'Solo','Huge',18,NULL,172,'15d12+75','40 ft.',NULL,NULL,'80 ft.',23,10,21,14,13,17,'{"History": 7, "Stealth": 5, "Perception": 11, "Persuasion": 8}','Fire','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 21','Common, Draconic',5,5,6,6,3,2,5,'["None"]','Habitat: Desert','Dragon','Metallic','{"value":"Scales shimmer in the desert sun as it lets out a booming roar."}','{"value": "Adult Brass Dragons are powerful and cunning creatures that are known for their love of conversation and riddles. They are typically found in arid desert regions, where they use their fire breath and other abilities to protect their territory and treasure hoards.\n\nBrass Dragons are known for their playful and mischievous nature, often using their shape-shifting abilities to take on different forms and trick unsuspecting travelers. Despite their playful demeanor, they are fiercely intelligent and will not hesitate to defend themselves or their hoard if threatened.\n\nThese dragons are also known for their love of riddles and puzzles, often challenging those who seek their wisdom with difficult questions and tests of intelligence. They are considered to be some of the most talkative and sociable of all dragon species, and are known to form alliances with other creatures if it suits their purposes.\n\nIn combat, Adult Brass Dragons are formidable opponents, using their fire breath, claw attacks, and magical abilities to overwhelm their enemies. They are also skilled in aerial combat, using their wings to maneuver and outmaneuver their foes.\n\nOverall, Adult Brass Dragons are complex and enigmatic creatures, known for their intelligence, cunning, and love of conversation. They are a force to be reckoned with in the world of Dungeons and Dragons, and encountering one is sure to be a memorable and challenging experience for any adventuring party."}',0,'Monster Manual 2024 (BR)','Metallic','None',13.0,11500.0),
	 ('01990b8b-584a-74df-9c8b-b395eb1df1d9'::uuid,'Giant Goat','Unaligned','1/2 (XP 100; PB +2)',100,1,'Skirmisher','Large',11,NULL,19,'3d10+3','40 ft.','30 ft.',NULL,NULL,17,13,12,3,12,6,'{"Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','None',1,1,5,1,-2,-4,2,'[]',NULL,'Beast','','{"value":"Majestic horns clash as it stamps its hooves, eyes fixed with determined gaze."}','{"value": "In the world of Dungeons and Dragons, the Giant Goat is a creature that inhabits rugged and mountainous terrain. These creatures are much larger and more powerful than their ordinary goat counterparts, standing several feet tall at the shoulder and possessing great strength and agility.\n\nGiant Goats are known for their aggressive nature and will fiercely defend their territory against any perceived threats. They are often found in small herds, led by a dominant male known as a \"billy goat.\" These creatures are herbivores, feeding on a diet of grasses, shrubs, and other vegetation found in their mountainous habitats.\n\nIn some regions, Giant Goats are revered by local tribes or communities as symbols of strength and resilience. They are sometimes used as mounts by skilled riders who have earned the creature''s trust and respect.\n\nAdventurers who encounter Giant Goats must be cautious, as these creatures are known to charge and ram intruders with their powerful horns. However, they can also be valuable allies if approached with caution and respect. Their fur is often prized for its warmth and durability, making them targets for hunters and poachers in some regions.\n\nOverall, the Giant Goat is a fascinating and formidable creature that adds a unique flavor to the diverse ecosystems of the D&D world."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b83-25f0-7700-b4bf-d8cb9d82a9f4'::uuid,'Camel','Unaligned','1/8 (XP 25; PB +2)',25,-1,'Soldier','Large',10,NULL,17,'2d10+6','50 ft.',NULL,NULL,NULL,15,8,17,2,11,5,'{}','None','Darkvision 60 ft., Passive Perception 10','None',5,1,2,0,3,4,2,'[]',NULL,'Beast','','{"value":"Humps sway rhythmically as it spits and stamps its hooves in agitation"}','{"value": "Camels in Dungeons and Dragons are typically portrayed as large, docile creatures that are commonly used as pack animals in desert environments. They are known for their ability to survive long periods of time without water and for their ability to carry heavy loads over long distances.\n\nIn D&D lore, camels are often associated with nomadic desert-dwelling tribes and are frequently used as mounts by these groups. They are known for their stubbornness and resilience, making them valuable companions in harsh desert environments.\n\nIn terms of combat abilities, camels are not typically seen as aggressive creatures and are more likely to flee from danger rather than engage in combat. However, they are known for their powerful kicks, which can be quite dangerous if provoked.\n\nOverall, camels in D&D are seen as useful and reliable creatures that are well-suited for surviving and thriving in arid environments. They are often a common sight in desert campaigns and can serve as valuable allies or mounts for adventurers exploring the harsh wilderness."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b91-577e-757a-8349-3521752d9267'::uuid,'Jackalwere','ChaoticEvil','1/2 (XP 100; PB +2)',100,2,'Ambusher','Small',12,NULL,18,'4d6+4','40 ft.',NULL,NULL,NULL,11,15,12,13,11,10,'{"Stealth": 4, "Deception": 4, "Perception": 4}','None','Darkvision 90 ft., Passive Perception 14','Common',1,2,0,0,0,1,2,'[]','Habitat: Desert, Grassland','Fiend','','{"value":"Eyes gleam with cunning as it grins, revealing sharp fangs."}','{"value": "Jackalweres are fiendish creatures that resemble jackals but possess the ability to shape-shift into humanoid form, usually that of a human or elf. They are known for their cunning and deceptive nature, often luring travelers into traps with their humanoid guise before revealing their true form and attacking.\n\nIn their jackal form, they are skilled hunters and scavengers, often preying on small animals and the occasional humanoid. They are known to be fiercely territorial and will defend their territory with aggression if threatened.\n\nJackalweres are said to be cursed beings, transformed by a powerful curse or dark magic that binds them to their dual nature. They are often associated with evil deities or dark forces, and are sometimes used as minions by more powerful creatures such as liches or vampires.\n\nTheir shape-shifting ability makes them difficult to detect and track, allowing them to move unseen and strike unexpectedly. They are also known for their keen senses, particularly their sense of smell, which they use to track prey and detect intruders.\n\nOverall, jackalweres are dangerous and unpredictable creatures that should be approached with caution and dealt with swiftly if encountered in the wild. Their deceptive nature and shape-shifting abilities make them formidable foes for any adventurer."}',0,'Monster Manual 2024','','None',0.5,NULL),
	 ('01990b93-3d83-7a41-847a-f62e5c0b1e9a'::uuid,'Magmin','ChaoticNeutral','1/2 (XP 100; PB +2)',100,2,'Ambusher','Small',14,NULL,13,'3d6+3','30 ft.',NULL,NULL,NULL,7,15,12,8,11,10,'{}','Fire','Darkvision 60 ft., Passive Perception 10','Primordial (Ignan)',1,2,-2,0,0,-1,2,'[]','Habitat: Planar (Elemental Plane of Fire)','Elemental','','{"value":"Dancing flames whirl in chaotic patterns, flickering with a fiery malevolence."}','{"value": "Magmin are small elemental creatures with fiery bodies that constantly burn and smolder. They are chaotic creatures, driven by a desire to spread destruction and chaos wherever they go. Magmin are typically found in areas of intense heat, such as volcanic regions or the Elemental Plane of Fire.\n\nThese creatures are often summoned by more powerful beings, such as fire giants or powerful mages, to serve as minions or guardians. Magmin are known for their explosive nature, as they can self-destruct in a fiery explosion when they are killed or when they feel threatened.\n\nMagmin are immune to fire damage and resistant to physical damage. They can also heat up nearby objects and creatures with their fiery touch. Despite their chaotic nature, magmin are not particularly intelligent and can be easily manipulated or controlled by stronger beings.\n\nOverall, magmin are dangerous creatures that should be approached with caution, as their fiery nature and explosive tendencies make them unpredictable and volatile."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b98-2a79-70a8-beab-59463abefbed'::uuid,'Pony','Unaligned','1/8 (XP 25; PB +2)',25,0,'Brute','Medium',10,NULL,11,'2d8+2','40 ft.',NULL,NULL,NULL,15,10,13,2,11,7,'{}','None','Passive Perception 10','None',1,0,4,0,2,4,2,'[]',NULL,'Beast','','{"value":"It snorts and stomps, eyes wild with an untamed spirit."}','{"value": "Ponies in Dungeons and Dragons 5th edition are typically depicted as small, gentle creatures that are often used as mounts or pack animals by adventurers. They are known for their agility and speed, making them ideal for traveling through rough terrain or quickly escaping danger.\n\nIn D&D lore, ponies are usually domesticated animals that are commonly found in rural areas or owned by farmers and traders. They are often used for pulling carts or plows, but can also be trained for riding or combat. Some ponies may even have magical abilities or be enchanted creatures in certain settings.\n\nOverall, ponies in D&D are seen as loyal and reliable companions, valued for their versatility and adaptability. They are not typically considered dangerous creatures, but can still be formidable opponents if provoked or threatened."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b9b-3785-7e2b-af68-7fe6fce62bb8'::uuid,'Shadow','ChaoticEvil','1/2 (XP 100; PB +2)',100,2,'Ambusher','Medium',12,NULL,27,'5d8+5','40 ft.',NULL,NULL,NULL,6,14,13,6,10,8,'{"Stealth": 6}','Necrotic, Poison; Exhaustion, Frightened, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Darkvision 60 ft., Passive Perception 10','None',1,2,-2,0,-1,-2,2,'[]','Habitat: Planar (Shadowfell), Underdark, Urban','Undead','','{"value":"Whispers of darkness swirl, coalescing into a shapeless mass of malevolent intent."}','{"value": "Shadows are sinister undead creatures that are created from the souls of living beings who have died under particularly tragic circumstances. These creatures are often found lurking in dark and desolate places, where they feed off the life force of living creatures. Shadows are able to drain the strength and vitality of their victims with a mere touch, leaving them weakened and vulnerable.\n\nShadows are typically created when a sentient being dies a violent or tragic death, and their soul is unable to find peace. The soul becomes trapped in the Shadowfell, a dark and shadowy plane of existence that exists parallel to the material plane. Over time, the soul''s bitterness and despair manifest into a shadowy form, creating a shadow creature.\n\nShadows are often used by necromancers and other dark spellcasters as minions, due to their ability to drain the life force of their enemies. They are also known to be particularly difficult to destroy, as they are immune to many forms of damage and can move swiftly and silently through the darkness.\n\nIn combat, shadows are known to be stealthy and elusive, using their dark powers to blend into the shadows and surprise their enemies. They are particularly dangerous to those who are already weakened or injured, as their touch can drain the remaining vitality from their victims.\n\nOverall, shadows are considered to be malevolent and dangerous creatures that should be avoided at all costs. Their presence is often a sign of impending doom and death, and those who encounter them should be wary and prepared for a difficult and deadly battle."}',0,'Monster Manual 2024 (BR)','','Acid, Cold, Fire, Lightning, Thunder',0.5,NULL),
	 ('01990b9f-2d29-79c5-9dfe-686f0a8a1fa4'::uuid,'Tough','TrueNeutral','1/2 (XP 100; PB +2)',100,1,'Soldier','Medium',12,NULL,32,'5d8+10','30 ft.',NULL,NULL,NULL,15,12,14,10,10,11,'{}','None','Passive Perception 10','Common',2,1,2,0,0,0,2,'["Heavy Crossbow", "Leather Armor", "Mace"]','Habitat: Any','Humanoid','','{"value":"Muscles ripple as it flexes, a low growl emanating from its throat."}','{"value": "Tough is a unique and powerful monster in the world of Dungeons and Dragons 5th edition. It is said to have been created by a powerful wizard who sought to create the ultimate guardian and protector. Tough is a massive, humanoid creature with thick, resilient skin that is almost impenetrable to most weapons.\n\nTough is known for its incredible strength and durability, able to withstand even the most powerful attacks without flinching. It is also highly intelligent, able to outsmart and outmaneuver its opponents in battle. Tough is often used as a powerful ally by those who are able to tame and control it, but it is also a fearsome enemy to those who dare to challenge it.\n\nLegends say that Tough was created to guard a powerful artifact or treasure, and it will stop at nothing to protect its charge. It is said that only the bravest and most skilled adventurers are able to defeat Tough and claim the prize it guards.\n\nOverall, Tough is a formidable and enigmatic creature in the world of D&D, feared and respected by all who encounter it."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990ba1-cf18-7896-b425-2cf5a117af2c'::uuid,'Warrior Infantry','TrueNeutral','1/8 (XP 25; PB +2)',25,0,'Soldier','Medium',13,NULL,9,'2d8','30 ft.',NULL,NULL,NULL,13,11,11,8,11,8,'{}','None','Passive Perception 10','Common',0,0,1,0,-1,-1,2,'["Chain Shirt", "Spear"]','Habitat: Any','Humanoid','','{"value":"Squad marches in perfect unison, shields raised and swords gleaming in the sunlight"}','{"value": "The Warrior Infantry is a formidable creature that is often found in the ranks of armies and military forces. These creatures are highly trained in various forms of combat and are skilled in both melee and ranged attacks. They are typically clad in heavy armor and wield powerful weapons such as swords, axes, and crossbows.\n\nThe Warrior Infantry is known for its unwavering loyalty to its commanding officers and will follow orders without question. They are often used as front-line soldiers in battle, leading the charge against enemy forces with their superior strength and combat skills.\n\nDespite their fearsome reputation on the battlefield, Warrior Infantry are not mindless killing machines. They are capable of independent thought and decision-making, and some may even possess a sense of honor and loyalty towards their comrades.\n\nOverall, the Warrior Infantry is a versatile and deadly foe that should not be underestimated in combat. Their disciplined training, combat skills, and unwavering loyalty make them a force to be reckoned with on the battlefield."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b7c-e690-7f25-a189-e4cc604c9c00'::uuid,'Ancient Black Dragon','ChaoticEvil','21 (XP 33 000, or 41 000 in lair; PB +7)',33000,16,'Solo','Gargantuan',22,NULL,367,'21d20+147','40 ft.',NULL,'40 ft.','80 ft.',27,14,25,16,15,22,'{"Stealth": 9, "Perception": 16}','Acid','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 26','Common, Draconic',7,9,8,9,6,3,7,'[]','Habitat: Swamp','Dragon','Chromatic','{"value":"Wings unfurl, casting a shadow as its eyes gleam with malice."}','{"value": "Ancient Black Dragons are massive and powerful creatures that are known for their cunning and cruelty. They are among the oldest and most feared of all dragonkind, with centuries of experience and a deep knowledge of the world. \n\nThese dragons are masters of deception and manipulation, often using their intelligence and charisma to manipulate others to do their bidding. They are also known for their incredible strength and ferocity in battle, able to crush enemies with their powerful claws and teeth.\n\nAncient Black Dragons are typically found in swamps, marshes, and other dark and murky places. They are solitary creatures, preferring to live alone and only coming together with others of their kind during mating season.\n\nIn terms of abilities, Ancient Black Dragons are known for their acid breath, which can melt through armor and flesh with ease. They are also highly resistant to magic and have keen senses that allow them to detect enemies from great distances.\n\nOverall, Ancient Black Dragons are feared and respected by all who know of them, and facing one in battle is a daunting and dangerous task. Only the bravest and most skilled adventurers would dare to challenge one of these mighty creatures."}',0,'Monster Manual 2024 (BR)','Chromatic','None',21.0,41000.0),
	 ('01990b7e-d5e7-7d99-91cc-b53b774a8dc1'::uuid,'Animated Flying Sword','Unaligned','1/4 (XP 50; PB +2)',50,4,'Ambusher','Small',17,NULL,14,'4d6','5 ft.',NULL,NULL,'50 ft.',12,15,11,1,5,1,'{}','Poison, Psychic; Charmed, Deafened, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned','Blindsight 60 ft., Passive Perception 7','—',0,4,1,-3,-5,-5,2,'[]','Habitat: Urban','Construct','','{"value":"Sword slices through the air with a menacing hum"}','{"value": "The Animated Flying Sword is a magical construct created by powerful wizards or skilled artificers. It is typically crafted from a combination of metal and enchanted materials, imbuing it with a semblance of life and the ability to fly and attack on its own.\n\nThese constructs are often used as guardians of ancient tombs, treasure hoards, or important locations. They are programmed to detect and attack any intruders that enter their territory, using their razor-sharp blades to strike down their foes with deadly precision.\n\nWhile Animated Flying Swords do not possess any true intelligence or emotions, they are relentless in their pursuit of their designated targets. They can be difficult to defeat due to their agility and ability to fly out of reach of most melee attacks.\n\nAdventurers who encounter Animated Flying Swords must be wary and prepared for a challenging battle, as these constructs are formidable opponents that will stop at nothing to protect their masters'' treasures."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b8c-9651-77ef-b152-5df758ff38b7'::uuid,'Giant Vulture','NeutralEvil','1 (XP 200; PB +2)',200,0,'Skirmisher','Large',10,NULL,25,'3d10+9','10 ft.',NULL,NULL,'60 ft.',15,10,16,6,12,7,'{"Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','Understands Common but can''t speak',3,0,2,1,-2,-2,2,'[]',NULL,'Monstrosity','','{"value":"Wings outstretched, it screeches a deafening cry before swooping down with razor-sharp talons."}','{"value": "Giant Vultures are massive, bird-like creatures that are often found in desolate and barren landscapes. These creatures are known for their keen eyesight and their ability to spot prey from great distances. They are scavengers by nature, feeding on the remains of dead animals and other creatures.\n\nGiant Vultures are considered to be solitary creatures, rarely forming bonds with others of their kind. They are highly territorial and will fiercely defend their hunting grounds from intruders. Despite their intimidating size and appearance, Giant Vultures are not typically aggressive towards living creatures unless provoked or if they are desperate for food.\n\nIn some cultures, Giant Vultures are seen as omens of death or harbingers of doom. It is said that when a Giant Vulture circles overhead, it is a sign that death is near. However, others see these creatures as symbols of rebirth and renewal, as they play a vital role in the cycle of life by cleaning up carrion and recycling nutrients back into the earth.\n\nAdventurers who encounter Giant Vultures in the wild should approach with caution, as these creatures are not easily intimidated and will defend themselves fiercely if threatened. However, those who are able to earn the respect of a Giant Vulture may find a valuable ally in their travels, as these creatures are known for their keen intelligence and their ability to navigate even the most treacherous terrain."}',0,'Monster Manual 2024 (BR)','','Necrotic',1.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b8c-e585-7e40-ab47-8703d2df6dfb'::uuid,'Githyanki Knight','LawfulEvil','8 (XP 3 900; PB +3)',3900,5,'Soldier','Medium',18,NULL,117,'18d8+36','30 ft.',NULL,NULL,NULL,16,14,15,14,14,15,'{}','None','Passive Perception 12','Common, Gith',5,2,3,5,2,5,3,'["Plate Armor"]','Habitat: Planar (Astral Plane)','Aberration','Gith','{"value":"Armor gleaming, the Githyanki Knight charges forward, sword raised high."}','{"value": "The Githyanki Knight is a powerful and fearsome warrior that belongs to the Githyanki race, a race of humanoid creatures that were once enslaved by mind flayers and have since broken free to form their own society. The Githyanki are known for their mastery of psionics and their hatred of their former masters.\n\nGithyanki Knights are elite warriors within the Githyanki society, often serving as commanders of their armies or personal bodyguards to their leaders. They are highly skilled in combat, wielding weapons and armor made from a mysterious silver-like material known as Githyanki silver.\n\nIn battle, Githyanki Knights are known for their ruthless efficiency and tactical prowess. They are capable of using their psionic abilities to enhance their combat skills, allowing them to strike with deadly precision and speed. They are also skilled in the use of magic, often casting spells to augment their own abilities or to weaken their enemies.\n\nGithyanki Knights are fiercely loyal to their leaders and their cause, willing to lay down their lives in service to the Githyanki race. They are often seen as symbols of strength and honor within Githyanki society, revered for their combat prowess and unwavering dedication to their people.\n\nEncountering a Githyanki Knight in battle is a daunting prospect, as they are formidable opponents that will stop at nothing to achieve victory. Only the most skilled and brave adventurers dare to face off against these fearsome warriors and live to tell the tale."}',0,'Monster Manual 2024','Gith','None',8.0,NULL),
	 ('01990b5e-004c-7330-a191-82e9923041e8'::uuid,'Adult Green Dragon','LawfulEvil','15 (XP 13 000, or 15 000 in lair; PB +5)',13000,11,'Solo','Huge',19,NULL,207,'18d12+90','40 ft.',NULL,'40 ft.','80 ft.',23,12,21,18,15,18,'{"Stealth": 6, "Deception": 9, "Perception": 12, "Persuasion": 9}','Poison; Poisoned','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 22','Common, Draconic',5,6,6,7,4,4,5,'["None"]','Habitat: Forest','Dragon','Chromatic','{"value":"Wings unfurl with a deafening roar, poison dripping from sharp fangs."}','{"value": "Adult Green Dragons are powerful and cunning creatures that are known for their love of trickery and manipulation. They are masters of deception and enjoy playing mind games with their enemies before ultimately destroying them. \n\nThese dragons are typically found in ancient forests or other lush, green environments where they can easily blend in with their surroundings. They are highly territorial and will fiercely defend their lairs from any intruders.\n\nAdult Green Dragons have a breath weapon that consists of a deadly cloud of poisonous gas. They are also skilled in both physical combat and magic, making them formidable opponents in battle.\n\nIn terms of their behavior, Adult Green Dragons are known to be extremely arrogant and prideful. They see themselves as superior beings and will often demand tribute or servitude from weaker creatures in exchange for their protection. They are also known to form alliances with other powerful creatures, using them as pawns in their elaborate schemes.\n\nOverall, Adult Green Dragons are intelligent and dangerous creatures that should not be underestimated. Those who encounter one would do well to approach with caution and be prepared for a battle of wits as well as strength."}',0,'Monster Manual 2024 (BR)','Chromatic','None',15.0,15000.0),
	 ('01990b5e-aa60-769c-8899-ff4825a947be'::uuid,'Adult White Dragon','ChaoticEvil','13 (XP 10 000, or 11 500 in lair; PB +5)',10000,10,'Solo','Huge',18,NULL,200,'16d12+96','40 ft.',NULL,'40 ft.','80 ft.',22,10,22,8,12,12,'{"Stealth": 5, "Perception": 11}','Cold','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 21','Common, Draconic',6,5,6,6,1,-1,5,'["None"]','Habitat: Arctic','Dragon','Chromatic','{"value":"Frosty breath billows out as it looms over you, eyes gleaming with malice."}','{"value": "Adult White Dragons are formidable creatures that are known for their cunning nature and icy breath. They are solitary and territorial, often claiming large expanses of frozen tundra or icy mountains as their own. These dragons are highly intelligent and possess a keen understanding of their environment, using their natural camouflage abilities to blend in with their surroundings and ambush unsuspecting prey.\n\nIn combat, Adult White Dragons are fearsome opponents, using their breath weapon to freeze their enemies in place before swooping in for the kill. They are also skilled hunters, using their keen senses and powerful claws to track and take down prey with deadly precision.\n\nAdult White Dragons are highly protective of their hoards, which typically consist of valuable gems, precious metals, and magical artifacts. They are known to be ruthless in defending their treasures, often laying elaborate traps and ambushes for would-be thieves.\n\nOverall, Adult White Dragons are formidable foes that should not be underestimated. Their combination of intelligence, cunning, and raw power make them a force to be reckoned with in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','Chromatic','None',13.0,11500.0),
	 ('01990b5b-4a26-76c9-8998-2e1b63c2e257'::uuid,'Aarakocra Aeromancer','TrueNeutral','4 (XP 1 100; PB +2)',1100,3,'Support','Medium',16,NULL,66,'12d8+12','20 ft.',NULL,NULL,'50 ft.',10,16,12,13,17,12,'{"Arcana": 3, "Nature": 5, "Perception": 7}','None','Passive Perception 17','Aarakocra, Primordial (Auran)',1,5,0,5,1,1,2,'["None"]','Habitat: Mountain, Planar (Elemental Plane of Air)','Elemental','','{"value":"Wings outstretched, it weaves intricate patterns in the swirling winds above."}','{"value": "The Aarakocra Aeromancer is a powerful and rare subrace of the Aarakocra, a humanoid bird-like race known for their connection to the element of air. Aeromancers are gifted with innate magical abilities that allow them to manipulate the winds and control the weather.\n\nLegend has it that the first Aeromancers were chosen by the elemental deity of air, who granted them their powers in exchange for their service as protectors of the skies. These winged spellcasters are revered among the Aarakocra for their ability to summon powerful storms, create gusts of wind to aid their allies, and even call down lightning from the heavens.\n\nAeromancers are known to live high in the mountains or atop towering cliffs, where they can harness the full power of the winds and clouds. They are often called upon by their fellow Aarakocra to help with important rituals, ceremonies, or battles, using their magic to turn the tide in their favor.\n\nDespite their formidable powers, Aeromancers are also seen as wise and peaceful beings, preferring to use their abilities to bring balance to the natural world rather than cause destruction. They are respected for their deep connection to the elements and their role as guardians of the skies."}',0,'Monster Manual 2024','','None',4.0,NULL),
	 ('01990b5b-e2ef-7ee0-b3ff-11cb2e2113a8'::uuid,'Aarakocra Skirmisher','TrueNeutral','1/4 (XP 50; PB +2)',50,2,'Skirmisher','Medium',12,NULL,11,'2d8+2','20 ft.',NULL,NULL,'50 ft.',10,14,12,11,12,11,'{"Perception": 5}','None','Passive Perception 15','Aarakocra, Primordial (Auran)',1,2,0,1,0,0,2,'["None"]','Habitat: Mountain, Planar (Elemental Plane of Air)','Elemental','','{"value":"Wings beat rhythmically as it circles overhead, eyes locked on its prey."}','{"value": "Aarakocra Skirmishers are skilled warriors and hunters among the Aarakocra race, which are bird-like humanoids with wings and talons. They are known for their agility and speed in combat, using their aerial advantage to swoop down on their foes and strike with precision.\n\nThese Skirmishers are often tasked with scouting missions and protecting the borders of their territories. They are expert trackers and are able to navigate through difficult terrain with ease. In battle, they use hit-and-run tactics, quickly diving in to attack and then soaring back out of reach before their enemies can react.\n\nAarakocra Skirmishers are fiercely loyal to their tribes and will stop at nothing to defend their homes and loved ones. They are highly intelligent creatures and have a deep connection to the natural world, often forming bonds with other creatures such as giant eagles or owls.\n\nOverall, Aarakocra Skirmishers are formidable opponents on the battlefield, combining their aerial prowess with their keen senses and strategic thinking to outmaneuver and outwit their enemies."}',0,'Monster Manual 2024','','None',0.25,NULL),
	 ('01990b5c-240a-71d6-85b2-0a669445d32d'::uuid,'Aberrant Cultist','NeutralEvil','8 (XP 3 900; PB +3)',3900,7,'Controller','Medium',14,NULL,137,'25d8+25','30 ft.',NULL,NULL,NULL,10,19,12,16,18,15,'{"Arcana": 6, "Religion": 6, "Perception": 7}','None','Darkvision 90 ft., Passive Perception 17','Common, Deep Speech; telepathy 30 ft.',1,4,0,7,2,6,3,'["None"]','Habitat: Any','Humanoid','','{"value":"Whispers madly, eyes glowing with fanatic devotion, etching sigils into flesh."}','{"value": "The Aberrant Cultist is a sinister and twisted figure, often found in the depths of dark and forbidden places. They are followers of powerful aberrations, such as mind flayers or beholders, and seek to bring about the destruction and chaos that their masters desire.\n\nThese cultists are known for their dark rituals and sacrifices, using their powers to summon otherworldly creatures and bend reality to their will. They are skilled in the dark arts of magic and often have a deep understanding of the arcane and eldritch.\n\nAberrant cultists are often marked by physical deformities or mutations, a result of their close connection to the aberrant beings they worship. They are often clad in dark robes and carry twisted, otherworldly weapons to carry out their dark deeds.\n\nEncountering an Aberrant Cultist is a harrowing experience, as they are unpredictable and dangerous foes. They will stop at nothing to further their dark goals and will not hesitate to use their powers to manipulate and control those around them.\n\nIn battle, Aberrant Cultists are formidable opponents, using their dark magic to weaken and confuse their enemies. They are skilled in the use of illusions and mind-altering spells, making them a dangerous threat to any who dare to oppose them.\n\nOverall, the Aberrant Cultist is a malevolent and twisted figure, driven by dark desires and a thirst for power. They are a reminder of the dangers of dabbling in dark magic and consorting with otherworldly beings."}',0,'Monster Manual 2024','','None',8.0,NULL),
	 ('01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'Aboleth','LawfulEvil','10 (XP 5 900, or 7 200 in lair; PB +4)',5900,7,'Controller','Large',17,NULL,150,'20d10+40','10 ft.',NULL,'40 ft.',NULL,21,9,15,18,15,18,'{"History": 12, "Perception": 10}','None','Darkvision 120 ft., Passive Perception 20','Deep Speech; telepathy 120 ft.',6,3,5,6,4,8,4,'["None"]','Habitat: Underdark, Underwater','Aberration','','{"value":"Slick tendrils undulate hypnotically, beckoning with ancient whispers."}','{"value": "Aboleths are ancient, powerful, and intelligent aquatic monsters that are said to predate the gods themselves. These creatures are known for their ability to manipulate and control the minds of other creatures, as well as their vast knowledge of history and magic.\n\nAboleths are typically found in the deepest parts of the ocean, where they build vast underwater cities and enslave other aquatic creatures to serve them. They possess a unique ability called \"mucus cloud,\" which allows them to emit a cloud of mucus that can suffocate and paralyze their enemies.\n\nAboleths are also known for their long memories and ability to live for thousands of years, which allows them to hold grudges and plots for revenge over centuries. They are often portrayed as sinister and manipulative beings, using their powers to further their own inscrutable goals.\n\nIn Dungeons & Dragons lore, aboleths are considered to be one of the most powerful and dangerous monsters in the game, and encountering one is often a harrowing experience for adventurers. Their ancient and mysterious nature, as well as their potent mind-control abilities, make them a formidable foe that should not be underestimated."}',0,'Monster Manual 2024 (BR)','','None',10.0,7200.0),
	 ('01990b82-8e61-76f6-a20e-a4ad60db2c5b'::uuid,'Brown Bear','Unaligned','1 (XP 200; PB +2)',200,1,'Brute','Large',11,NULL,22,'3d10+6','40 ft.','30 ft.',NULL,NULL,17,12,15,2,13,7,'{"Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','None',2,1,3,1,-2,4,2,'[]',NULL,'Beast','','{"value":"The bear rises on its hind legs, roaring with primal fury."}','{"value": "In the world of Dungeons and Dragons, the Brown Bear is a large and powerful creature that is known for its strength and ferocity. Brown Bears are typically found in forests and mountainous regions, where they hunt for food and protect their territory.\n\nBrown Bears are solitary creatures, except during mating season when they may form temporary bonds with a mate. They are omnivorous and will eat a variety of foods including fish, berries, and small mammals. However, they are also known to be aggressive hunters and will attack anything that threatens them or their territory.\n\nIn combat, Brown Bears are formidable opponents, using their powerful claws and teeth to maul their enemies. They are also known for their ability to stand on their hind legs and swipe at their foes with their massive paws.\n\nOverall, Brown Bears are respected and feared by adventurers and travelers alike, as they are powerful predators that should not be underestimated."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b5c-77d9-7078-957f-8951783b2188'::uuid,'Abominable Yeti','ChaoticEvil','9 (XP 5 000; PB +4)',5000,4,'Brute','Huge',15,NULL,137,'11d12+66','40 ft.','40 ft.',NULL,NULL,24,10,22,9,13,9,'{"Stealth": 8, "Perception": 9}','Cold','Darkvision 60 ft., Passive Perception 19','Yeti',6,0,7,1,-1,-1,4,'["None"]','Habitat: Arctic','Monstrosity','','{"value":"Snow crunches under its massive feet as it lets out a bone-chilling roar."}','{"value": "The Abominable Yeti is a fearsome and powerful creature that roams the icy and mountainous regions of the world. Standing at over 10 feet tall and covered in thick white fur, the Abominable Yeti is a formidable predator known for its strength and ferocity.\n\nAccording to legend, the Abominable Yeti is said to be a cursed creature, created when a normal Yeti is exposed to dark and corrupting magic. This curse transforms the Yeti into a larger, more aggressive, and more dangerous version of itself, known as the Abominable Yeti.\n\nAbominable Yetis are solitary creatures, preferring to live in isolated areas away from civilization. They are known to be incredibly territorial and will fiercely defend their territory from any intruders, often attacking without warning.\n\nIn combat, Abominable Yetis rely on their brute strength and sharp claws to overpower their opponents. They are also known to possess a powerful chilling breath attack, capable of freezing their enemies solid.\n\nEncountering an Abominable Yeti is a dangerous prospect, as they are relentless hunters and will stop at nothing to satisfy their insatiable hunger for flesh and blood. Adventurers who dare to face off against an Abominable Yeti must be prepared for a brutal and unforgiving battle."}',0,'Monster Manual 2024','','None',9.0,NULL),
	 ('01990b5c-aee7-7898-a2f6-48c3874a04d2'::uuid,'Adult Black Dragon','ChaoticEvil','14 (XP 11 500, or 13 000 in lair; PB +5)',11500,12,'Solo','Huge',19,NULL,195,'17d12+85','40 ft.',NULL,'40 ft.','80 ft.',23,14,21,14,13,19,'{"Stealth": 7, "Perception": 11}','Acid','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 21','Common, Draconic',5,7,6,6,4,2,5,'["None"]','Habitat: Swamp','Dragon','Chromatic','{"value":"Wings unfurl with a deafening roar, eyes gleaming with malice."}','{"value": "The Adult Black Dragon is a powerful and cunning creature that is feared by many in the world of Dungeons and Dragons. These dragons are known for their cruelty, greed, and desire for power. They are often found in swamps, marshes, and other dark and foreboding places.\n\nAdult Black Dragons are typically around 60 feet in length and have a wingspan of about 80 feet. They have thick, leathery black scales that are resistant to most forms of damage. Their eyes are a piercing yellow color, and their breath weapon is a powerful acid that can dissolve almost anything it touches.\n\nThese dragons are highly intelligent and often use their cunning to manipulate and deceive others. They are also skilled in combat, using their sharp claws and teeth to tear apart their enemies. Adult Black Dragons are solitary creatures and do not often interact with others of their kind, except during mating season.\n\nIn terms of their lore, Adult Black Dragons are often seen as symbols of death and destruction. They are considered to be agents of chaos and are feared by many for their destructive tendencies. However, some stories also portray them as wise and ancient beings, with a deep knowledge of the world and its secrets.\n\nOverall, the Adult Black Dragon is a formidable foe that should not be underestimated in the world of Dungeons and Dragons. Their cunning, power, and cruelty make them a force to be reckoned with, and encountering one is sure to be a dangerous and thrilling experience for any adventurer."}',0,'Monster Manual 2024 (BR)','Chromatic','None',14.0,13000.0);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b5c-e19f-7df2-84c2-95757a34cecc'::uuid,'Adult Blue Dragon','LawfulEvil','16 (XP 15 000, or 18 000 in lair; PB +5)',15000,0,'Solo','Huge',19,NULL,212,'17d12+102','40 ft.',NULL,NULL,'80 ft.',25,10,23,16,15,20,'{"Stealth": 5, "Perception": 12}','Lightning','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 22','Common, Draconic',6,5,7,7,5,3,5,'["None"]','Habitat: Coastal, Desert','Dragon','Chromatic','{"value":"Wings crackle with electricity as it coils its serpentine body, eyes gleaming with malice."}','{"value": "Adult Blue Dragons are powerful and cunning creatures that are known for their fierce territorial nature and their mastery of lightning-based magic. These dragons typically make their lairs in desolate desert regions, where they can easily ambush unsuspecting prey and defend their territory from rival creatures.\n\nAdult Blue Dragons are known for their keen intelligence and strategic minds, making them formidable opponents in battle. They are also highly skilled in the use of lightning-based magic, which they can harness to devastating effect in combat. Their lightning breath can strike multiple targets at once, making them a deadly threat to any would-be adventurers who dare to challenge them.\n\nIn addition to their magical abilities, Adult Blue Dragons are also physically strong and possess tough scales that provide them with excellent protection in battle. They are known to be fiercely territorial creatures, and will go to great lengths to defend their lairs from any intruders.\n\nOverall, Adult Blue Dragons are fearsome creatures that are not to be underestimated. Adventurers who encounter one of these powerful dragons would be wise to proceed with caution and be prepared for a tough and challenging battle."}',0,'Monster Manual 2024 (BR)','Chromatic','None',16.0,18000.0),
	 ('01990b5d-5e2d-7693-a477-4073b9a46907'::uuid,'Adult Bronze Dragon','LawfulGood','15 (XP 13 000, or 15 000 in lair; PB +5)',13000,10,'Solo','Huge',18,NULL,212,'17d12+102','40 ft.',NULL,'40 ft.','80 ft.',25,10,23,16,15,20,'{"Insight": 7, "Stealth": 5, "Perception": 12}','Lightning','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 22','Common, Draconic',6,5,7,7,5,3,5,'["None"]','Habitat: Coastal','Dragon','Metallic','{"value":"Wings spread wide, it breathes lightning, eyes crackling with ancient wisdom."}','{"value": "Adult Bronze Dragons are a majestic and powerful species of dragon known for their noble and virtuous nature. They are typically found near bodies of water, such as lakes, rivers, and oceans, where they serve as protectors of the land and its inhabitants.\n\nThese dragons are known for their metallic bronze scales which shimmer and gleam in the sunlight, giving them a regal and imposing appearance. They are skilled in combat and possess a variety of powerful abilities, including their iconic breath weapon which allows them to unleash a deadly bolt of lightning upon their enemies.\n\nAdult Bronze Dragons are highly intelligent creatures and are known for their wisdom and cunning. They are often sought out by adventurers and rulers alike for their knowledge and guidance, and are respected and revered by many for their sense of justice and honor.\n\nIn D&D lore, Adult Bronze Dragons are typically depicted as wise and benevolent creatures who use their power to protect and defend the world from evil forces. They are known to form alliances with other good-aligned creatures and are fierce defenders of their territories.\n\nOverall, Adult Bronze Dragons are seen as symbols of strength, wisdom, and protection in the world of Dungeons and Dragons, and are revered by many for their noble and virtuous nature."}',0,'Monster Manual 2024 (BR)','Metallic','None',15.0,15000.0),
	 ('01990b5d-cba0-74d7-8a0a-f76f33defb99'::uuid,'Adult Gold Dragon','LawfulGood','17 (XP 18 000, or 20 000 in lair; PB +6)',18000,14,'Solo','Huge',19,NULL,243,'18d12+126','40 ft.',NULL,'40 ft.','80 ft.',27,14,25,16,15,24,'{"Insight": 8, "Stealth": 8, "Perception": 14, "Persuasion": 13}','Fire','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 24','Common, Draconic',7,8,8,8,7,3,6,'["None"]','Habitat: Forest, Grassland','Dragon','Metallic','{"value":"Beams with radiant light, exuding an aura of wisdom and nobility"}','{"value": "Adult Gold Dragons are powerful and majestic creatures known for their wisdom, nobility, and sense of justice. They are one of the most powerful and respected types of dragons in the D&D universe. \n\nThese dragons are typically found in remote mountain ranges or ancient ruins, where they serve as protectors of the land and its inhabitants. They are known to be wise and benevolent, using their immense strength and magical abilities to defend those in need and uphold the values of honor and righteousness.\n\nAdult Gold Dragons are known for their shimmering golden scales, which reflect light in a dazzling display. They are also known for their keen intellect and ability to shape-shift into human form, allowing them to walk among mortals unnoticed.\n\nIn combat, Adult Gold Dragons are formidable foes, using their breath weapon of searing golden fire to incinerate their enemies. They are also skilled in both melee and ranged combat, making them versatile opponents.\n\nOverall, Adult Gold Dragons are seen as symbols of power, protection, and justice in the D&D universe, and encountering one is considered a rare and awe-inspiring experience."}',0,'Monster Manual 2024 (BR)','Metallic','None',17.0,20000.0),
	 ('01990b5e-760a-770e-a2cd-a46915852e35'::uuid,'Adult Silver Dragon','LawfulGood','16 (XP 15 000, or 18 000 in lair; PB +5)',15000,10,'Solo','Huge',19,NULL,216,'16d12+112','40 ft.',NULL,NULL,'80 ft.',27,10,25,16,13,22,'{"History": 8, "Stealth": 5, "Perception": 11}','Cold','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 21','Common, Draconic',7,5,8,6,6,3,5,'["None"]','Habitat: Mountain, Urban','Dragon','Metallic','{"value":"Wings outstretched, it gazes down with wise eyes, shimmering in the moonlight."}','{"value": "The Adult Silver Dragon is a majestic and wise creature known for its intelligence, grace, and sense of justice. These dragons are typically found living in remote mountainous regions or icy tundras, where they use their shapeshifting abilities to interact with other races and protect the natural world.\n\nAdult Silver Dragons are known for their strong sense of morality and desire to help those in need. They often take on the role of guardians or protectors, using their powerful breath weapon of cold energy to defend against threats. They are also skilled in combat, using their sharp claws and teeth to subdue enemies.\n\nThese dragons are highly intelligent and have a deep understanding of magic and the world around them. They are known for their ability to speak multiple languages and their knowledge of ancient lore and history. Many seek out the counsel of Adult Silver Dragons for their wisdom and insight.\n\nOverall, Adult Silver Dragons are seen as noble and benevolent creatures, respected and revered by those who encounter them. They are seen as symbols of hope and protection, embodying the ideals of honor, courage, and compassion."}',0,'Monster Manual 2024 (BR)','Metallic','None',16.0,18000.0),
	 ('01990b7c-a32b-7fd5-9b62-0b34faa4ada3'::uuid,'Allosaurus','Unaligned','2 (XP 450; PB +2)',450,1,'Brute','Large',13,NULL,51,'6d10+18','60 ft.',NULL,NULL,NULL,19,13,17,2,12,5,'{"Perception": 5}','None','Passive Perception 15','None',3,1,4,1,-3,-4,2,'[]',NULL,'Beast','Dinosaur','{"value":"Jaws snap open, revealing rows of razor-sharp teeth as it lets out a deafening roar."}','{"value": "The Allosaurus is a large, carnivorous dinosaur that roams the primeval jungles and wildlands of the world. They are known for their powerful jaws filled with sharp teeth, and their ability to take down large prey with swift and deadly attacks. \n\nIn the world of Dungeons and Dragons, Allosauruses are often depicted as fierce predators that hunt in packs, using their keen senses and agility to outmaneuver their prey. They are typically solitary creatures, but will work together when hunting in order to take down larger prey.\n\nAllosauruses are known for their territorial nature, fiercely defending their hunting grounds and will attack anything that threatens their territory. They are also highly intelligent creatures, capable of strategic planning and coordination when hunting. \n\nIn D&D, Allosauruses are often encountered in primal wilderness settings, where they serve as challenging opponents for adventurers looking to test their skills against one of nature''s most fearsome predators. Their ferocity and strength make them a formidable foe, and those who underestimate them do so at their own peril."}',0,'Monster Manual 2024 (BR)','Dinosaur','None',2.0,NULL),
	 ('01990b7d-16f0-7f61-86cb-3601aec1df33'::uuid,'Ancient Blue Dragon','LawfulEvil','23 (XP 50 000, or 62 000 in lair; PB +7)',50000,14,'Solo','Gargantuan',22,NULL,481,'26d20+208','40 ft.',NULL,NULL,'80 ft.',29,10,27,18,17,25,'{"Stealth": 7, "Perception": 17}','Lightning','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 27','Common, Draconic',8,7,9,10,7,4,7,'[]','Habitat: Coastal, Desert','Dragon','Chromatic','{"value":"Electricity crackles around its scales as it coils its massive body, ready to strike."}','{"value": "Ancient Blue Dragons are among the most feared and powerful creatures in the world of Dungeons & Dragons. These massive, serpentine beasts are known for their lightning breath and their cunning intellect. Ancient Blue Dragons are ancient beings, having lived for centuries and accumulated immense knowledge and power. They are highly territorial creatures, often claiming vast stretches of land as their own and fiercely defending it from intruders.\n\nAncient Blue Dragons are known for their love of treasure, and will go to great lengths to acquire more wealth and power. They are masterful manipulators and are skilled at using their charisma and intelligence to get what they want. They are also highly skilled in combat, using their lightning breath to devastating effect and their immense strength and durability to overpower their enemies.\n\nDespite their fearsome reputation, Ancient Blue Dragons are not mindless beasts. They are capable of forming alliances and working with other creatures if it suits their goals. However, they are also known for their capricious nature, and it is often difficult to predict their actions.\n\nOverall, Ancient Blue Dragons are formidable foes that should not be underestimated. Those who dare to challenge them must be prepared for a battle of epic proportions."}',0,'Monster Manual 2024 (BR)','Chromatic','None',23.0,62000.0),
	 ('01990b7d-5462-7707-a772-8564c9ba625b'::uuid,'Ancient Brass Dragon','ChaoticGood','20 (XP 25 000, or 33 000 in lair; PB +6)',25000,12,'Solo','Gargantuan',20,NULL,332,'19d20+133','40 ft.',NULL,NULL,'80 ft.',27,10,25,16,15,22,'{"History": 9, "Stealth": 6, "Perception": 14, "Persuasion": 12}','Fire','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 24','Common, Draconic',7,6,8,8,6,3,6,'[]','Habitat: Desert','Dragon','Metallic','{"value":"Wings spread wide, it bellows with the crackling power of ancient flames."}','{"value": "Ancient Brass Dragons are powerful and wise creatures known for their love of conversation and riddles. They are one of the oldest and most respected types of dragons, possessing immense knowledge and insight. These dragons are typically found in deserts, where they lair in hidden caves or ancient ruins.\n\nAncient Brass Dragons are known for their cunning and strategic thinking, often using their intelligence and charm to outwit their enemies. They are also skilled spellcasters, able to wield powerful magic to protect themselves and their hoards.\n\nDespite their immense power, Ancient Brass Dragons are typically benevolent beings who prefer to use their abilities to help and protect others. They are often seen as guardians or protectors by the creatures that live in their territory, and many seek out their wisdom and guidance.\n\nHowever, Ancient Brass Dragons can also be fierce and formidable foes to those who threaten them or their hoards. They are known for their fiery breath weapon, which can cause devastating damage to anyone who crosses them.\n\nOverall, Ancient Brass Dragons are complex and multifaceted creatures, embodying both wisdom and power. They are respected and revered by many, and their presence is often seen as a sign of good fortune and protection."}',0,'Monster Manual 2024 (BR)','Metallic','None',20.0,33000.0),
	 ('01990b7d-8464-7423-bf35-301eb7b90e44'::uuid,'Ancient Bronze Dragon','LawfulGood','22 (XP 41 000, or 50 000 in lair; PB +7)',41000,14,'Solo','Gargantuan',22,NULL,444,'24d20+192','40 ft.',NULL,'40 ft.','80 ft.',29,10,27,18,17,25,'{"Insight": 10, "Stealth": 7, "Perception": 17}','Lightning','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 27','Common, Draconic',8,7,9,10,7,4,7,'[]','Habitat: Coastal','Dragon','Metallic','{"value":"Wings outstretched, it roars, lightning crackling along its scales."}','{"value": "Ancient Bronze Dragons are wise and noble creatures that are known for their love of knowledge, history, and art. They are typically seen as protectors and guardians of the land, using their immense power and wisdom to defend their territories and the creatures that live within them.\n\nThese dragons are known for their metallic bronze scales, which shimmer in the sunlight like polished metal. They are also known for their lightning breath, which they use to defend themselves and their territory from threats.\n\nAncient Bronze Dragons are often seen as mentors and guides to younger dragons and adventurers, offering wisdom and advice to those who seek it. They are also known for their love of riddles and puzzles, often challenging those who seek their help to solve a difficult riddle before granting their assistance.\n\nOverall, Ancient Bronze Dragons are respected and revered by those who know of them, seen as powerful and benevolent beings who use their power for the greater good."}',0,'Monster Manual 2024 (BR)','Metallic','None',22.0,50000.0),
	 ('01990b7d-bfd6-785e-b2b8-76b766a93a79'::uuid,'Ancient Copper Dragon','ChaoticGood','21 (XP 33 000, or 41 000 in lair; PB +7)',33000,15,'Solo','Gargantuan',21,NULL,367,'21d20+147','40 ft.','40 ft.',NULL,'80 ft.',27,12,25,20,17,22,'{"Stealth": 8, "Deception": 13, "Perception": 17}','Acid','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 27','Common, Draconic',7,8,8,10,6,5,7,'[]','Habitat: Hill','Dragon','Metallic','{"value":"Wings outstretched, it exhales a glistening cloud of electrified breath."}','{"value": "Ancient Copper Dragons are wise and cunning creatures known for their love of trickery and pranks. They are masterful shape-shifters and enjoy taking on various forms to play tricks on unsuspecting mortals. Despite their playful nature, Ancient Copper Dragons are also fiercely protective of their territory and will fiercely defend it against any threats.\n\nThese dragons are known for their love of riddles and puzzles, often challenging adventurers to solve them in exchange for information or treasure. They are also skilled spellcasters, able to cast powerful spells to aid them in battle or deceive their enemies.\n\nAncient Copper Dragons are highly intelligent and have a vast knowledge of history and magic. They are often sought out by adventurers and scholars alike for their wisdom and guidance. However, gaining the favor of an Ancient Copper Dragon is no easy task, as they are known to be capricious and unpredictable in their dealings with mortals."}',0,'Monster Manual 2024 (BR)','Metallic','None',21.0,41000.0),
	 ('01990b7e-283e-7045-b316-dedb8906b26e'::uuid,'Ancient Green Dragon','LawfulEvil','22 (XP 41 000, or 50 000 in lair; PB +7)',41000,15,'Solo','Gargantuan',21,NULL,402,'23d20+161','40 ft.',NULL,'40 ft.','80 ft.',27,12,25,20,17,22,'{"Stealth": 8, "Deception": 13, "Perception": 17, "Persuasion": 13}','Poison; Poisoned','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 27','Common, Draconic',7,8,8,10,6,5,7,'[]','Habitat: Forest','Dragon','Chromatic','{"value":"Wings spread wide, it exhales a noxious cloud of poisonous gas."}','{"value": "Ancient Green Dragons are among the oldest and most powerful of all dragonkind. These immense creatures are known for their cunning intellect, mastery of magic, and unparalleled skill in combat. Ancient Green Dragons are typically found deep within ancient forests or hidden swamps, where they rule over vast territories with an iron claw.\n\nThese dragons are known for their deep connection to nature, often using their powers to manipulate the natural world to suit their needs. They are skilled shape-shifters, able to take on the form of a humanoid or beast at will. Ancient Green Dragons are also masters of illusion magic, using their powers to deceive and confuse their enemies.\n\nIn combat, Ancient Green Dragons are fearsome opponents, using their immense strength and razor-sharp claws and teeth to tear through their foes. They also have a breath weapon that can unleash a devastating cloud of poisonous gas, capable of taking down even the hardiest of adventurers.\n\nDespite their immense power, Ancient Green Dragons are not invincible. They are fiercely territorial and will defend their domain with all their might. However, they are also known to be cunning and manipulative, often using deception and trickery to achieve their goals.\n\nEncountering an Ancient Green Dragon is a rare and dangerous experience, as these creatures are not only powerful but also highly intelligent. Adventurers who cross paths with an Ancient Green Dragon must be prepared for a battle of wits as well as strength, as these creatures are as cunning as they are deadly."}',0,'Monster Manual 2024 (BR)','Chromatic','None',22.0,50000.0);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b7e-50f7-7068-abe2-1dfc6ed5de4d'::uuid,'Ancient Red Dragon','ChaoticEvil','24 (XP 62 000, or 75 000 in lair; PB +7)',62000,14,'Solo','Gargantuan',22,NULL,507,'26d20+234','40 ft.','40 ft.',NULL,'80 ft.',30,10,29,18,15,27,'{"Stealth": 7, "Perception": 16}','Fire','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 26','Common, Draconic',9,7,10,9,8,4,7,'[]','Habitat: Hill, Mountain','Dragon','Chromatic','{"value":"Roaring with fury, flames licking from its jaws and smoke billowing in the air"}','{"value": "Ancient Red Dragons are the most powerful and fearsome of all dragonkind. They are legendary for their immense size, incredible strength, and fiery breath that can incinerate anything in its path. These dragons are known for their insatiable greed and desire for power, often hoarding vast amounts of treasure and ruling over vast territories with an iron claw.\n\nAncient Red Dragons are incredibly intelligent and cunning, using their intellect to manipulate and control those around them. They are also extremely vain creatures, always seeking to prove their superiority over others. Despite their fearsome reputation, some ancient red dragons are known to form alliances with other powerful beings in order to achieve their goals.\n\nIn combat, Ancient Red Dragons are nearly unbeatable foes. Their thick scales provide them with incredible protection, and their fiery breath can devastate entire armies in a single blast. They are also skilled in physical combat, using their massive claws and teeth to tear apart their enemies.\n\nOverall, Ancient Red Dragons are beings of immense power and malevolence, and anyone who crosses paths with one should be prepared for a battle of epic proportions. Only the most skilled and courageous adventurers have any hope of defeating these ancient and terrifying creatures."}',0,'Monster Manual 2024 (BR)','Chromatic','None',24.0,75000.0),
	 ('01990b7e-bb55-77a3-ac50-0a07204dade8'::uuid,'Ancient White Dragon','ChaoticEvil','20 (XP 25 000, or 33 000 in lair; PB +6)',25000,12,'Solo','Gargantuan',20,NULL,333,'18d20+144','40 ft.',NULL,'40 ft.','80 ft.',26,10,26,10,13,18,'{"Stealth": 6, "Perception": 13}','Cold','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 23','Common, Draconic',8,6,8,7,4,0,6,'[]','Habitat: Arctic','Dragon','Chromatic','{"value":"Frost swirls around its massive form, its icy gaze piercing the adventurers\u0027 souls."}','{"value": "Ancient White Dragons are fearsome and powerful creatures that are among the oldest and most cunning of their kind. They are known for their icy breath and their ability to freeze their enemies with just a touch. These dragons are often found in cold, snowy regions, where they make their lairs in vast, frozen caverns.\n\nAncient White Dragons are solitary creatures that prefer to live alone, only coming together with others of their kind during mating season. They are fiercely territorial and will defend their lairs with deadly force. These dragons are highly intelligent and are known for their strategic thinking and cunning tactics.\n\nIn terms of physical appearance, Ancient White Dragons are massive creatures with sleek, white scales that blend in perfectly with their snowy surroundings. They have sharp claws and teeth, and their icy breath can freeze even the hardiest of adventurers in an instant.\n\nLegends say that Ancient White Dragons are ancient beings that have been around since the beginning of time, and that they possess vast knowledge of the world and its secrets. They are said to be incredibly wise and are often sought out by those who seek knowledge or power.\n\nEncountering an Ancient White Dragon is a daunting prospect for any adventurer, as these creatures are incredibly powerful and can easily overpower even the most skilled warriors. Those who dare to face an Ancient White Dragon must be prepared for a battle of epic proportions, as these creatures will stop at nothing to protect their territory and their hoard of treasure."}',0,'Monster Manual 2024 (BR)','Chromatic','None',20.0,33000.0),
	 ('01990b7e-c175-798b-ab04-36e6afd07f42'::uuid,'Animal Lord','TrueNeutral','20 (XP 25 000; PB +6)',25000,19,'Support','Medium',19,NULL,323,'34d8+170','60 ft.',NULL,'60 ft.','60 ft.',24,25,20,19,23,22,'{"Stealth": 13, "Athletics": 13, "Acrobatics": 13, "Perception": 18}','Charmed, Frightened, Stunned','Truesight 120 ft., Passive Perception 28','All',11,7,7,12,6,4,6,'[]','Habitat: Planar (Beastlands)','Celestial','','{"value":"Roaring, the Animal Lord commands its pack with primal authority."}','{"value": "The Animal Lord is a powerful and enigmatic creature in the world of Dungeons and Dragons. It is said to be an ancient being that holds dominion over all animals in the natural world. The Animal Lord is often depicted as a towering figure with the head of a majestic beast, such as a lion or eagle, and the body of a humanoid.\n\nLegends say that the Animal Lord is a guardian of the balance of nature, ensuring that all creatures coexist harmoniously. It is said to possess incredible powers over the animal kingdom, able to command and communicate with any creature it chooses. Some believe that the Animal Lord has the ability to shape-shift into any animal it desires, allowing it to move undetected through the wilds.\n\nEncountering an Animal Lord is a rare and awe-inspiring event, as they are said to only reveal themselves to those who have proven themselves worthy of their attention. Those who are deemed unworthy may face the wrath of the Animal Lord, as it is said to be a fierce and formidable adversary in battle.\n\nIn the realm of Dungeons and Dragons, the Animal Lord is a symbol of the untamed power of nature and the importance of respecting and protecting the natural world. Those who seek to harm or disrupt the balance of nature may find themselves facing the wrath of the Animal Lord and its formidable animal allies."}',0,'Monster Manual 2024','','Cold, Fire, Necrotic, Psychic, Radiant',20.0,NULL),
	 ('01990b7e-cbca-7418-a115-023588b9f0a7'::uuid,'Animated Armor','Unaligned','1 (XP 200; PB +2)',200,2,'Soldier','Medium',18,NULL,33,'6d8+6','25 ft.',NULL,NULL,NULL,14,11,13,1,3,1,'{}','Poison, Psychic; Charmed, Deafened, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned','Blindsight 60 ft., Passive Perception 6','—',1,0,2,-4,-5,-5,2,'[]','Habitat: Urban','Construct','','{"value":"Armor clanks ominously as it advances, shield raised in a defensive stance."}','{"value": "Animated Armor is a construct creature in D&D 5e that is brought to life through magical means. It is typically made of metal and can be found guarding treasure, ancient ruins, or serving as a protector for a powerful wizard or sorcerer. \n\nThe lore behind Animated Armor varies depending on the campaign setting, but in general, these creatures are created by powerful spellcasters or artificers who imbue them with magic to give them life. They are often programmed with a specific set of instructions or commands to follow, making them obedient servants or guardians.\n\nSome Animated Armors are created from the souls of fallen warriors, bound to their armor even in death. These spirits may be restless and seek vengeance on those who disturb their resting place or desecrate their armor.\n\nIn combat, Animated Armors are formidable opponents, using their strength and durability to overpower their foes. They are resistant to many types of damage and immune to conditions like poison and exhaustion. Their attacks can be devastating, as they are able to wield weapons with great proficiency.\n\nOverall, Animated Armor is a mysterious and enigmatic creature in the world of D&D, often serving as a challenging obstacle for adventurers to overcome in their quests for glory and treasure."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b7e-fd2e-777f-a941-0958504f3336'::uuid,'Ankylosaurus','Unaligned','3 (XP 700; PB +2)',700,0,'Brute','Huge',15,NULL,68,'8d12+16','30 ft.',NULL,NULL,NULL,19,11,15,2,12,5,'{}','None','Passive Perception 11','None',2,0,6,1,-3,-4,2,'[]',NULL,'Beast','Dinosaur','{"value":"Armor rattles as it swings its massive tail, ready to defend its territory."}','{"value": "An Ankylosaurus is a massive dinosaur with a heavily armored body covered in thick, bony plates and spikes. They are known for their distinctive tail club, which they use as a formidable weapon against predators. Ankylosauruses are herbivores and are typically peaceful creatures, but will fiercely defend themselves if threatened.\n\nIn D&D 5e, Ankylosauruses are often found in tropical or subtropical regions, where they roam in small herds in search of food. They are territorial creatures and will aggressively defend their territory from any intruders. Despite their slow movement speed, Ankylosauruses are surprisingly agile and can deliver devastating blows with their tail clubs.\n\nIn combat, Ankylosauruses are formidable opponents, using their tail clubs to deal heavy damage to enemies. Their thick armor plating provides them with excellent protection against physical attacks, making them difficult to take down. However, they are vulnerable to attacks from above, as their armored back is less protected.\n\nOverall, Ankylosauruses are powerful and dangerous creatures that should not be underestimated in the world of D&D."}',0,'Monster Manual 2024 (BR)','Dinosaur','None',3.0,NULL),
	 ('01990b7f-0b8b-7b87-8acf-8fe035d32f9b'::uuid,'Ape','Unaligned','1/2 (XP 100; PB +2)',50,2,'Brute','Medium',12,NULL,19,'3d8+6','30 ft.','30 ft.',NULL,NULL,16,14,14,6,12,7,'{"Athletics": 5, "Perception": 3}','None','Passive Perception 13','None',2,2,3,1,-2,2,2,'[]',NULL,'Beast','','{"value":"Hulking ape beats its chest, bellowing a challenge to all who approach."}','{"value": "In the world of Dungeons and Dragons, apes are powerful and aggressive primates that are known for their strength and agility. They are commonly found in jungles and forests, where they live in social groups called troops. Apes are primarily herbivorous, feeding on fruits, leaves, and other vegetation, but they are also known to hunt small animals for food.\n\nIn combat, apes are formidable foes, using their powerful arms to deliver devastating blows to their enemies. They are also known to use rocks and branches as improvised weapons, further increasing their lethality. Despite their brutish appearance, apes are surprisingly intelligent creatures, capable of using basic tactics and strategies in battle.\n\nIn some D&D campaigns, apes are also known to be magical creatures, with some possessing the ability to cast spells or harness elemental powers. These mystical apes are often revered by druids and other nature-oriented spellcasters, who see them as powerful allies in the fight against unnatural forces.\n\nOverall, apes are creatures to be reckoned with in the world of Dungeons and Dragons, with their combination of strength, agility, and intelligence making them formidable opponents for any adventurer brave enough to face them."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b7f-1735-7fd8-b23d-b3b3c164281d'::uuid,'Arcanaloth','NeutralEvil','12 (XP 8 400; PB +4)',8400,5,'Controller','Medium',18,NULL,175,'27d8+54','30 ft.',NULL,NULL,'30 ft.',17,12,14,20,16,17,'{"Arcana": 9, "Insight": 7, "Deception": 7, "Perception": 7}','Acid, Poison; Charmed, Poisoned','Truesight 120 ft., Passive Perception 17','All; telepathy 120 ft.',6,5,3,7,3,9,4,'[]','Habitat: Planar (Lower Planes)','Fiend','Yugoloth','{"value":"It cackles with glee, weaving spells with wicked precision."}','{"value": "The Arcanaloth is a fiendish creature that is often found serving powerful spellcasters and other evil beings as advisors and enforcers. They are known for their vast knowledge of magic and their ability to manipulate and deceive others to further their own goals.\n\nArcanaloths are highly intelligent and cunning, using their magical abilities to influence events and manipulate others to achieve their own ends. They are masters of illusion and enchantment magic, able to create powerful illusions and charm spells to control those around them.\n\nDespite their cunning and intellect, Arcanaloths are also known for their greed and desire for power. They are often willing to make deals and alliances with other creatures in exchange for favors or services, but they are always looking for ways to betray their allies and further their own agenda.\n\nIn combat, Arcanaloths are formidable opponents, using their magical abilities to control and weaken their enemies. They are also able to summon other fiendish creatures to aid them in battle, making them even more dangerous foes.\n\nOverall, Arcanaloths are dangerous and manipulative creatures that should not be underestimated. They are masters of magic and deception, using their powers to further their own goals and sow chaos and destruction wherever they go."}',0,'Monster Manual 2024','Yugoloth','Cold, Fire, Lightning',12.0,NULL),
	 ('01990b7f-22c0-7fea-8f48-014437294300'::uuid,'Arch-hag','NeutralEvil','21 (XP 33 000, or 41 000 in lair; PB +7)',33000,16,'Solo','Large',20,NULL,333,'29d10+174','40 ft.',NULL,NULL,NULL,24,15,23,19,19,25,'{"Deception": 14, "Perception": 11, "Persuasion": 21}','Charmed, Exhaustion, Frightened','Truesight 60 ft., Passive Perception 21','All',6,9,7,11,7,4,7,'[]','Habitat: Any','Fey','','{"value":"Her eyes gleam with malice as she cackles, stirring a foul concoction in her cauldron."}','{"value": "The Arch-hag is a powerful and ancient being in the world of Dungeons and Dragons, known for their immense magical abilities and cunning intellect. These hags are often the leaders of coven of lesser hags, ruling over their followers with an iron fist.\n\nArch-hags are said to have made pacts with dark powers or ancient beings, granting them incredible powers and longevity. They are often depicted as monstrous and grotesque creatures, with twisted features and a malevolent aura.\n\nThese creatures are known for their ability to cast powerful spells, manipulate minds, and shape reality to their will. They are often feared and respected by other creatures in the world, as they are capable of great destruction and chaos.\n\nArch-hags are often encountered in dark and foreboding places, such as ancient ruins, cursed forests, or shadowy swamps. They are said to be extremely cunning and deceptive, able to manipulate others to do their bidding.\n\nOverall, the Arch-hag is a formidable and dangerous foe in the world of Dungeons and Dragons, capable of great power and destruction. Adventurers who come across these creatures should proceed with caution, as they are not to be underestimated."}',0,'Monster Manual 2024','','Cold, Fire, Psychic',21.0,41000.0),
	 ('01990b7f-6041-7fe4-bcce-41ed203b0eb5'::uuid,'Archmage','TrueNeutral','12 (XP 8 400; PB +4)',8400,6,'Artillery','Medium',17,NULL,170,'31d8+31','30 ft.',NULL,NULL,NULL,10,14,12,20,15,16,'{"Arcana": 13, "History": 9, "Perception": 6}','Psychic; Charmed (with','Passive Perception 16','Common plus five other languages',1,2,0,6,3,9,4,'["Wand"]','Habitat: Any','Humanoid','Wizard','{"value":"Eyes gleam with arcane power, hands crackling with lightning."}','{"value": "In Dungeons and Dragons 5th Edition, an Archmage is a powerful spellcaster who has mastered the highest levels of magic. They are typically depicted as wise and knowledgeable individuals who have spent a lifetime studying and practicing the arcane arts. Archmages are often the leaders of wizarding orders or magical organizations, and they are highly respected and feared by those who know of their existence.\n\nArchmages are able to cast spells of incredible power and complexity, and they have access to a wide range of magical abilities. They are known for their ability to manipulate reality, control the elements, and summon powerful creatures to do their bidding. Archmages are also skilled in the use of magical items and artifacts, and they are often in possession of powerful relics that grant them even greater powers.\n\nIn combat, Archmages are formidable opponents, able to unleash devastating spells and summon powerful allies to aid them in battle. They are also adept at using illusions and enchantments to confuse and disorient their enemies. Archmages are typically found in hidden towers, secret libraries, or other secluded locations where they can study and practice their magic in peace.\n\nOverall, Archmages are some of the most powerful and enigmatic beings in the world of Dungeons and Dragons, and encountering one is sure to be a memorable and challenging experience for any adventuring party."}',0,'Monster Manual 2024 (BR)','Wizard','None',12.0,NULL),
	 ('01990b7f-8f4f-7a28-a8c0-f48e5aec8e59'::uuid,'Archpriest','TrueNeutral','12 (XP 8 400; PB +4)',8400,5,'Leader','Medium',16,NULL,240,'32d8+96','30 ft.',NULL,NULL,NULL,16,12,17,14,21,14,'{"Insight": 9, "Medicine": 9, "Religion": 10, "Perception": 9}','None','Passive Perception 19','Common plus two other languages',7,1,7,9,2,6,4,'["Chain Mail", "Holy Symbol"]','Habitat: Any','Humanoid','Cleric','{"value":"Eyes glow with dark power as it raises trembling hands in a sinister blessing."}','{"value": "The Archpriest is a powerful and malevolent creature that serves as a high-ranking leader in a cult or religious organization. These beings are often devoted to dark gods or evil entities, using their powers to further their own twisted agendas.\n\nArchpriests are highly skilled in both magic and combat, making them formidable foes for any adventurers who cross their path. They are able to cast powerful spells, summon undead minions, and even manipulate the minds of their enemies.\n\nThese creatures are often surrounded by loyal followers who will do anything to protect their leader and carry out their will. The Archpriest''s influence over their followers is strong, often leading them to commit heinous acts in the name of their dark deity.\n\nIn battle, Archpriests are cunning and strategic, using their spells and minions to weaken and defeat their enemies. They are not easily defeated, and adventurers must use all of their skills and resources to overcome these formidable foes.\n\nOverall, the Archpriest is a dangerous and formidable adversary, spreading darkness and chaos wherever they go. Only the bravest and most skilled adventurers dare to face these powerful creatures in battle."}',0,'Monster Manual 2024','Cleric','None',12.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b7f-b32a-72f3-8697-6b09e2c1253f'::uuid,'Assassin','TrueNeutral','8 (XP 3 900; PB +3)',3900,10,'Ambusher','Medium',16,NULL,97,'15d8+30','30 ft.',NULL,NULL,NULL,11,18,14,16,11,10,'{"Stealth": 10, "Acrobatics": 7, "Perception": 6}','None','Passive Perception 16','Common, Thieves'' Cant',2,7,0,0,0,6,3,'["Light Crossbow", "Shortsword", "Studded Leather Armor"]','Habitat: Any','Humanoid','','{"value":"Silent shadows flicker as its blade dances with deadly precision"}','{"value": "The Assassin is a deadly and stealthy humanoid creature that is trained in the art of killing. They are often hired by powerful individuals or organizations to eliminate specific targets with precision and efficiency. Assassins are highly skilled in combat, particularly in using poisons and striking from the shadows.\n\nAssassins are typically portrayed as cold and calculating individuals who have no qualms about taking a life if it serves their purpose. They are often depicted as being ruthless and relentless in their pursuit of their target, willing to do whatever it takes to complete their mission.\n\nIn Dungeons and Dragons lore, Assassins are often members of secretive organizations such as the Zhentarim or the Thieves'' Guild, and are known for their ability to blend in with their surroundings and strike without warning. They are feared and respected by many, as their skills make them formidable opponents in combat.\n\nOverall, Assassins are dangerous foes to encounter in the world of D&D, and players must be cautious and vigilant when facing off against them. Their stealth and deadly abilities make them a formidable challenge for even the most experienced adventurers."}',0,'Monster Manual 2024 (BR)','','Poison',8.0,NULL),
	 ('01990b7f-c12d-7fa0-8e39-a3d38029c9e4'::uuid,'Awakened Tree','TrueNeutral','2 (XP 450; PB +2)',450,-2,'Brute','Huge',13,NULL,59,'7d12+14','20 ft.',NULL,NULL,NULL,19,6,15,10,10,7,'{}','None','Passive Perception 10','Common plus one other language',2,-2,4,0,-2,0,2,'[]','Habitat: Forest','Plant','','{"value":"Roots writhe beneath the soil as branches sway menacingly in the moonlight"}','{"value": "Awakened Trees are ancient, sentient trees that have been magically brought to life through powerful druidic or arcane rituals. These creatures are typically peaceful and reclusive, preferring to live in deep forests far away from civilization. \n\nAwakened Trees are fiercely protective of their forest homes and will go to great lengths to defend them from any intruders. They have a deep connection to nature and can communicate with other plant life, animals, and even some fey creatures. \n\nDespite their peaceful nature, Awakened Trees are formidable opponents in battle. They have immense strength and can uproot themselves to attack enemies with their massive branches. They are also resistant to many forms of damage, making them difficult to defeat in combat. \n\nSome druids and rangers seek out Awakened Trees as allies and guardians of the forest, forming strong bonds with these ancient beings. However, others view them as dangerous and unpredictable creatures that should be avoided at all costs. Regardless of how they are perceived, Awakened Trees remain mysterious and enigmatic creatures that command respect and awe from those who encounter them."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing',2.0,NULL),
	 ('01990b7f-c956-76e7-9b40-98b4b5c2f15d'::uuid,'Axe Beak','Unaligned','1/4 (XP 50; PB +2)',50,1,'Skirmisher','Large',11,NULL,19,'3d10+3','50 ft.',NULL,NULL,NULL,14,12,12,2,10,5,'{}','None','Passive Perception 10','—',1,1,2,0,-3,-4,2,'[]','Habitat: Arctic, Grassland, Hill','Monstrosity','','{"value":"Feathers bristle as it lets out a piercing screech, charging forward with deadly intent"}','{"value": "Axe beaks are large, flightless birds known for their aggressive nature and sharp beaks that resemble axes. These creatures are native to dense forests and jungles, where they use their powerful legs to run at high speeds and hunt down prey. They are often used as mounts by goblinoid tribes and other humanoid races, who train them for battle and use them as fierce steeds.\n\nAxe beaks are solitary creatures and fiercely territorial, often attacking anything that enters their territory. They are carnivorous and will eat almost anything they can catch, including small animals and even humanoids. Their sharp beaks can easily tear through flesh and armor, making them formidable opponents in combat.\n\nIn some cultures, axe beaks are considered sacred animals and are revered as symbols of strength and power. Shamans and druids often form bonds with these creatures, using their abilities to aid in hunting and protection. However, taming an axe beak is no easy task, as they are stubborn and independent creatures that do not easily submit to control.\n\nOverall, axe beaks are dangerous creatures that should be approached with caution, as their aggression and strength make them formidable foes in the wild."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b7f-d452-70af-bddc-63cfdb18fc2b'::uuid,'Azer Pyromancer','LawfulNeutral','6 (XP 2 300; PB +3)',2300,2,'Brute','Medium',18,NULL,97,'13d8+39','30 ft.',NULL,NULL,NULL,15,14,16,12,18,13,'{"Arcana": 4, "Perception": 7}','Fire, Poison; Poisoned','Passive Perception 17','Primordial (Ignan)',6,2,2,7,1,1,3,'[]','Habitat: Mountain, Planar (Elemental Plane of Fire)','Elemental','','{"value":"Flames dance and flicker in the eyes of the Azer Pyromancer, ready to unleash fiery wrath."}','{"value": "Azer Pyromancers are powerful fire genies that hail from the elemental plane of fire. These beings are skilled in the manipulation of flames and have a deep connection to the element of fire. They are often called upon by powerful beings to serve as guardians or advisors due to their immense power and knowledge of fire magic.\n\nAzer Pyromancers are known for their fiery temper and fierce loyalty to those they serve. They are highly intelligent and cunning, using their mastery of fire magic to outsmart and defeat their enemies. In battle, Azer Pyromancers unleash devastating fire spells and attacks, engulfing their foes in flames and leaving a trail of destruction in their wake.\n\nDespite their fierce nature, Azer Pyromancers are not inherently evil. They are simply beings of fire and are driven by their fiery nature to protect and serve those they deem worthy. However, they can be dangerous foes to those who cross them or threaten their allies.\n\nOverall, Azer Pyromancers are formidable creatures with a strong connection to the element of fire. They are revered for their mastery of fire magic and feared for their fiery tempers and destructive power."}',0,'Monster Manual 2024','','None',6.0,NULL),
	 ('01990b7f-e95e-7fa0-92fa-a15e2e7c13f4'::uuid,'Azer Sentinel','LawfulNeutral','2 (XP 450; PB +2)',450,1,'Soldier','Medium',17,NULL,39,'6d8+12','30 ft.',NULL,NULL,NULL,17,12,15,12,13,10,'{}','Fire, Poison; Poisoned','Passive Perception 11','Primordial (Ignan)',4,1,3,1,0,1,2,'[]','Habitat: Mountain, Planar (Elemental Plane of Fire)','Elemental','','{"value":"Flames dance and crackle within its armored form, eyes burning with vigilant determination."}','{"value": "The Azer Sentinel is a type of elemental creature that originates from the Plane of Fire. They are known for their fierce loyalty and dedication to guarding their homes and the treasures within them. Azer Sentinels are humanoid in appearance, with bodies made of fiery bronze and eyes that glow like hot coals.\n\nThese creatures are skilled warriors and are typically armed with weapons such as swords, spears, and shields that are also made of fire. They are highly disciplined and work together as a team to defend their territory from intruders.\n\nAzer Sentinels are also known for their craftsmanship, particularly in metalworking. They are skilled blacksmiths and are able to create intricate and powerful weapons and armor from the metals found in the Plane of Fire.\n\nIn combat, Azer Sentinels are formidable opponents, using their fiery weapons and elemental powers to strike down their enemies. They are also resistant to fire and heat-based attacks, making them even more difficult to defeat.\n\nOverall, Azer Sentinels are proud and honorable creatures that value duty and loyalty above all else. They are often found serving as guardians in the strongholds and fortresses of powerful elemental beings or powerful individuals seeking protection."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b80-0210-7fb1-971a-f8a807a7435a'::uuid,'Badger','Unaligned','0 (XP 10; PB +2)',10,0,'Ambusher','Tiny',11,NULL,5,'1d4+3','20 ft.',NULL,NULL,NULL,10,11,16,2,12,5,'{"Perception": 3}','None','Darkvision 30 ft., Passive Perception 13','None',3,0,0,1,-3,4,2,'[]',NULL,'Beast','','{"value":"Ravenous badger snarls fiercely, digging up earth with lightning speed."}','{"value": "In Dungeons & Dragons 5th edition, the badger is a small, ferocious creature known for its tenacity and bravery in battle. Badgers are solitary animals that typically make their homes in underground burrows, where they live and raise their young. They are known for their sharp claws and teeth, which they use to hunt for food and defend themselves against predators.\n\nIn D&D lore, badgers are often depicted as fierce and fearless creatures that will not hesitate to attack anything that threatens them or their territory. They are known for their stubbornness and determination, and will often fight to the death rather than retreat. Despite their small size, badgers are formidable opponents in combat, using their sharp claws and teeth to inflict serious damage on their enemies.\n\nIn some D&D campaigns, badgers are also known for their loyalty and strong sense of family. They are often depicted as fiercely protective of their offspring, and will go to great lengths to ensure their safety and well-being. In certain stories, badgers are even depicted as wise and mystical creatures with a deep connection to nature and the earth.\n\nOverall, in D&D lore, the badger is a symbol of courage, determination, and loyalty, making it a popular choice for players looking to embody these traits in their characters."}',0,'Monster Manual 2024 (BR)','','Poison',0.0,NULL),
	 ('01990b80-2cfa-7ed3-a8d5-c6aad63c171e'::uuid,'Balor','ChaoticEvil','19 (XP 22 000; PB +6)',22000,14,'Solo','Huge',19,NULL,287,'23d12+138','40 ft.',NULL,NULL,'80 ft.',26,15,22,20,16,22,'{"Perception": 9}','Fire, Poison; Charmed, Frightened, Poisoned','Truesight 120 ft., Passive Perception 19','Abyssal; telepathy 120 ft.',12,2,8,9,6,5,6,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Fiery wings beat as it roars, casting a shadow of dread and destruction."}','{"value": "The Balor is a powerful demon in the world of Dungeons and Dragons, known for its immense strength and fiery abilities. This monstrous creature is one of the most feared demons in the Abyss, ruling over lesser demons with an iron fist. Balors are tall, muscular beings with bat-like wings and a long, whip-like tail. They have sharp horns on their heads and fiery eyes that can strike fear into the hearts of their enemies.\n\nBalors are known for their mastery of fire magic, able to summon flames to incinerate their foes. They wield a massive sword called a \"Flame Whip,\" which is imbued with elemental fire and can cause devastating damage to anyone who stands in their way. In addition to their physical prowess, Balors also possess powerful spellcasting abilities, allowing them to cast spells of destruction and chaos.\n\nIn D&D lore, Balors are often depicted as leaders of demonic armies, commanding legions of lesser demons in the eternal war against the forces of good. They are considered to be some of the most dangerous adversaries that adventurers can face, requiring careful planning and powerful abilities to defeat. Only the most skilled and brave heroes dare to challenge a Balor in combat, knowing that the consequences of failure could be catastrophic."}',0,'Monster Manual 2024 (BR)','Demon','Cold, Lightning',19.0,NULL),
	 ('01990b80-55a5-7750-8c94-616e99cc4266'::uuid,'Bandit Crime Lord','TrueNeutral','11 (XP 7 200; PB +4)',7200,9,'Leader','Medium',17,NULL,169,'26d8+52','30 ft.',NULL,NULL,NULL,10,20,14,18,14,15,'{"Stealth": 13, "Acrobatics": 9, "Perception": 10}','None','Passive Perception 20','Common, Thieves'' Cant',6,9,0,2,2,4,4,'["two Pistols", "Scimitar", "Studded Leather Armor"]','Habitat: Any','Humanoid','','{"value":"Swaggering through the room, the Bandit Crime Lord eyes you with a greedy grin."}','{"value": "Bandit Crime Lords are powerful and cunning leaders of criminal organizations that operate outside the law in the world of Dungeons and Dragons. These individuals are usually highly skilled in combat, tactics, and manipulation, using their influence and resources to control their underlings and expand their criminal empire.\n\nBandit Crime Lords are often former thieves, mercenaries, or assassins who have risen through the ranks to become the top dog in their criminal organization. They are known for their ruthless and cutthroat nature, willing to do whatever it takes to maintain their power and wealth.\n\nIn combat, Bandit Crime Lords are formidable opponents, employing a mix of martial prowess and dirty tricks to gain the upper hand. They are often surrounded by loyal minions who will fight to the death to protect their leader, making them a challenging adversary for any adventuring party.\n\nOverall, Bandit Crime Lords are complex and intriguing characters in the world of D&D, offering a unique and dangerous challenge for players to overcome in their adventures."}',0,'Monster Manual 2024','','None',11.0,NULL),
	 ('01990b80-55fd-74b6-8fe4-6bfeeb6c5011'::uuid,'Bandit Deceiver','TrueNeutral','7 (XP 2 900; PB +3)',2900,6,'Skirmisher','Medium',16,NULL,130,'20d8+40','30 ft.',NULL,NULL,NULL,8,16,14,17,12,16,'{"Stealth": 9, "Acrobatics": 6, "Perception": 4}','None','Passive Perception 14','Common, Thieves'' Cant',2,6,-1,1,3,6,3,'["six Daggers", "Wand"]','Habitat: Any','Humanoid','','{"value":"Mischief glints in its eyes as it twirls a stolen dagger."}','{"value": "The Bandit Deceiver is a cunning and deceptive creature that roams the wilderness, preying on unsuspecting travelers and adventurers. These creatures are known for their ability to disguise themselves as harmless animals or even humanoid beings in order to blend in with their surroundings and lure their victims into a false sense of security.\n\nThe origins of the Bandit Deceiver are shrouded in mystery, with some scholars speculating that they are the result of a curse or magical experiment gone wrong. Others believe that they are simply opportunistic predators who have evolved to take advantage of their surroundings.\n\nRegardless of their origins, Bandit Deceivers are feared for their ability to outsmart even the most experienced adventurers. They are known to set elaborate traps, ambush their prey from the shadows, and use their shape-shifting abilities to confuse and disorient their victims.\n\nThose who have encountered a Bandit Deceiver and lived to tell the tale often speak of their unnerving intelligence and malevolent cunning. They are elusive creatures, rarely seen by mortal eyes, and those who do manage to catch a glimpse of one are advised to proceed with caution, for the Bandit Deceiver is a formidable foe indeed."}',0,'Monster Manual 2024','','None',7.0,NULL),
	 ('01990b80-600e-7e9a-82ff-20404d25cb3e'::uuid,'Banshee','ChaoticEvil','4 (XP 1 100; PB +2)',1100,2,'Ambusher','Medium',12,NULL,54,'12d8','5 ft.',NULL,NULL,'40 ft.',1,14,10,12,11,17,'{}','Cold, Necrotic, Poison; Charmed, Exhaustion, Frightened, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained','Darkvision 60 ft., Passive Perception 10','Common, Elvish',0,2,-5,2,3,1,2,'[]','Habitat: Any','Undead','','{"value":"Wails mournfully, her ghostly form flickering in and out of existence"}','{"value": "In Dungeons and Dragons 5th edition, a Banshee is an undead creature that was once a female elf consumed by a great tragedy or heartbreak. The Banshee''s spirit is bound to the material plane, unable to move on to the afterlife, and is filled with eternal sorrow and anger.\n\nBanshees are known for their chilling wails that can freeze the blood of those who hear it. They are often found haunting desolate places such as abandoned ruins, graveyards, or haunted forests. The mere presence of a Banshee can bring a feeling of unease and dread to those around them.\n\nBanshees have a deep hatred for the living and will attack anyone who dares to trespass on their domain. They possess the ability to drain the life force from their victims with a touch, leaving them weakened and vulnerable. Their wails can also cause fear in those who hear it, making them easy prey for the Banshee''s attacks.\n\nDespite their malevolent nature, some Banshees retain memories of their past lives and may be driven by a desire for revenge or justice. They may seek out those responsible for their tragic fate and exact their own form of twisted justice upon them.\n\nOverall, Banshees are formidable foes that should not be taken lightly by adventurers. Their supernatural abilities and haunting presence make them a deadly threat to anyone who crosses their path."}',0,'Monster Manual 2024','','Acid, Bludgeoning, Fire, Lightning, Piercing, Slashing, Thunder',4.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b80-8bc7-7fe9-9808-3b9fc06815b0'::uuid,'Barbed Devil','LawfulEvil','5 (XP 1 800; PB +3)',1800,3,'Brute','Medium',15,NULL,110,'13d8+52','30 ft.','30 ft.',NULL,NULL,16,17,18,12,14,14,'{"Insight": 5, "Deception": 5, "Perception": 8}','Fire, Poison; Poisoned','Darkvision 120 ft. (unimpeded by magical Darkness), Passive Perception 18','Infernal; telepathy 120 ft.',7,3,6,5,5,1,3,'[]','Habitat: Planar (Nine Hells)','Fiend','Devil','{"value":"Spikes jut from its body, sizzling with infernal heat."}','{"value": "Barbed Devils, also known as Hamatulas, are fiendish creatures that serve as enforcers and torturers in the infernal hierarchy of the Nine Hells. They are tall, muscular humanoids with red skin, large horns, and long, sharp barbs covering their bodies. These barbs can inflict painful wounds on their enemies, making them formidable opponents in battle.\n\nBarbed Devils are known for their cruelty and sadism, taking pleasure in causing pain and suffering to their victims. They are often summoned by evil spellcasters to carry out acts of violence and torture, or to guard infernal strongholds and treasure hoards. In combat, Barbed Devils use their sharp claws and barbed tails to slash and stab at their foes, inflicting grievous wounds that are slow to heal.\n\nDespite their vicious nature, Barbed Devils are not mindless brutes. They are cunning and manipulative, using their intelligence to outwit their enemies and achieve their infernal goals. They are loyal servants of the archdevils and demon lords of the Nine Hells, carrying out their orders with ruthless efficiency.\n\nOverall, Barbed Devils are fearsome adversaries that embody the cruelty and malice of the Lower Planes. Those who face them in battle would do well to be wary of their sharp barbs and wicked intentions."}',0,'Monster Manual 2024 (BR)','Devil','Cold',5.0,NULL),
	 ('01990b80-9860-771a-ad80-1bb7012ef2e0'::uuid,'Barlgura','ChaoticEvil','5 (XP 1 800; PB +3)',1800,2,'Brute','Large',15,NULL,85,'10d10+30','40 ft.','40 ft.',NULL,NULL,18,15,16,7,14,9,'{"Stealth": 5, "Perception": 5}','Poison; Poisoned','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 15','Abyssal; telepathy 120 ft.',6,5,4,2,-1,-2,3,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Muscles ripple as it beats its chest, bellowing a primal challenge to all."}','{"value": "Barlguras are large, powerful demons that resemble massive, savage gorillas with demonic features such as sharp fangs, red eyes, and thick fur that crackles with energy. They are known for their incredible strength and ferocity in battle, often serving as shock troops or enforcers for more powerful demon lords.\n\nBarlguras are typically found in the Abyss, the chaotic and dangerous plane of existence that is home to many demons. They are often summoned to the Material Plane by powerful spellcasters seeking to wreak havoc and destruction, or by cultists seeking to summon demons to do their bidding.\n\nIn combat, Barlguras are known for their brutal attacks and their ability to manipulate and control the elements. They can hurl balls of fire, create gusts of wind to knock their enemies off balance, and even call down lightning to strike their foes. Their immense strength allows them to easily overpower most opponents, and their demonic nature makes them nearly immune to many types of damage.\n\nBarlguras are considered to be among the most dangerous and feared demons in the Abyss, and encountering one is usually a sign of impending doom. Only the most skilled and powerful adventurers stand a chance against these savage beasts, and even then, victory is far from guaranteed."}',0,'Monster Manual 2024','Demon','Cold, Fire, Lightning',5.0,NULL),
	 ('01990b80-aa28-7272-9d4e-d8191165d6d9'::uuid,'Basilisk','Unaligned','3 (XP 700; PB +2)',700,-1,'Brute','Medium',15,NULL,52,'8d8+16','20 ft.',NULL,NULL,NULL,16,8,15,2,8,7,'{}','None','Darkvision 60 ft., Passive Perception 9','None',2,-1,3,-1,-2,-4,2,'[]','Habitat: Mountain, Underdark','Monstrosity','','{"value":"A shadow slithers across the ground as its gaze freezes you in place."}','{"value": "According to D&D lore, the Basilisk is a fearsome creature that resembles a large, reptilian lizard with the ability to turn its victims to stone with a single glance. It is said to be born from the blood of a cockerel that has been incubated by a toad or serpent.\n\nBasilisks are often found lurking in dark caves or underground lairs, where they hunt for prey by petrifying them with their gaze and then devouring them. They are highly territorial creatures and will fiercely defend their territory against any intruders.\n\nIn combat, Basilisks are known for their deadly gaze attack, which can turn a creature to stone if they fail a saving throw. They are also formidable in melee combat, with sharp claws and a powerful bite.\n\nBasilisks are considered to be a dangerous and deadly threat to adventurers, and many tales tell of brave heroes who have fallen victim to their petrifying gaze. They are often sought after for their valuable parts, such as their venomous blood and petrified victims, which can be used in potions and magical rituals."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b80-d2ba-74f7-ad01-dc60d8a4be6f'::uuid,'Bearded Devil','LawfulEvil','3 (XP 700; PB +2)',700,2,'Brute','Medium',13,NULL,58,'9d8+18','30 ft.',NULL,NULL,NULL,16,15,15,9,11,14,'{}','Fire, Poison; Frightened, Poisoned','Darkvision 120 ft. (unimpeded by magical Darkness), Passive Perception 10','Infernal; telepathy 120 ft.',4,2,5,0,4,-1,2,'[]','Habitat: Planar (Nine Hells)','Fiend','Devil','{"value":"Grinning devil twirls its fiery beard, eyes fixed on its prey."}','{"value": "Bearded Devils, also known as Barbazu, are fiendish creatures from the Nine Hells in the world of Dungeons and Dragons. These devilish beings are often found serving powerful devils or demon lords as soldiers and enforcers. \n\nBearded Devils are easily recognizable by their sharp, black beards that they use as weapons in battle. These beards are actually made of iron spikes that can cause serious injury to their enemies. They are also known for their strong and muscular bodies, as well as their ability to resist fire and poison.\n\nIn battle, Bearded Devils are fierce and relentless fighters, using their spiked beards and sharp glaives to strike down their foes. They are known for their loyalty to their masters and will carry out any orders given to them without question.\n\nBearded Devils are often tasked with guarding important locations or individuals in the Nine Hells, as well as leading armies of lesser devils into battle. They are feared for their strength and ferocity, making them formidable adversaries for any adventurers who dare to challenge them."}',0,'Monster Manual 2024 (BR)','Devil','Cold',3.0,NULL),
	 ('01990b81-07e2-7cf9-b69c-34da88e827a3'::uuid,'Beholder','LawfulEvil','13 (XP 10 000, or 11 500 in lair; PB +5)',10000,12,'Solo','Large',18,NULL,190,'20d10+80','5 ft.',NULL,NULL,'40 ft.',16,14,18,17,15,17,'{"Perception": 12}','Prone','Darkvision 120 ft., Passive Perception 22','Deep Speech, Undercommon',9,2,3,7,3,3,5,'[]','Habitat: Underdark','Aberration','','{"value":"Its central eye glows malevolently, each stalk twitching independently with malicious curiosity."}','{"value": "Beholders are large, floating, spherical creatures with ten eyestalks and a large central eye, each capable of firing different magical rays. They are highly intelligent and extremely paranoid, believing themselves to be the most superior beings in existence.\n\nBeholders are known for their intense hatred of all other creatures, particularly other beholders. They are solitary and territorial, often dwelling in deep underground lairs filled with traps and magical defenses. They see themselves as the ultimate rulers of their domains and will go to great lengths to protect their territory from intruders.\n\nDespite their fearsome appearance and aggressive nature, beholders are not inherently evil. They are simply driven by their intense paranoia and desire for control. Some beholders may form alliances with other creatures, but these alliances are usually short-lived and based on mutual benefit.\n\nIn combat, beholders are formidable opponents, using their multiple eye rays to attack from a distance and their central eye to cast powerful spells. They are highly resistant to magic and can quickly adapt to changing tactics.\n\nOverall, beholders are one of the most iconic and feared creatures in the world of Dungeons & Dragons, known for their unique appearance, powerful abilities, and complex psychology."}',0,'Monster Manual 2024','','None',13.0,11500.0),
	 ('01990b81-0a1c-7cfc-bbb8-05d380e49a2b'::uuid,'Beholder Zombie','NeutralEvil','5 (XP 1 800; PB +3)',1800,-1,'Ambusher','Large',15,NULL,93,'11d10+33','5 ft.',NULL,NULL,'20 ft.',14,8,16,3,8,5,'{}','Poison; Exhaustion, Poisoned, Prone','Darkvision 60 ft., Passive Perception 9','Understands Deep Speech and Undercommon but can''t speak',3,-1,2,2,-3,-4,3,'[]','Habitat: Planar (Shadowfell), Underdark, Urban','Undead','','{"value":"Eyes rotting, it floats ominously, each gaze filled with hunger and decay."}','{"value": "Beholder Zombies are a terrifying undead creature created when a Beholder, a powerful and magical aberration with multiple eye stalks and a central eye that can shoot deadly rays, is reanimated after death. These creatures are created through dark necromantic rituals and are often used by powerful necromancers or evil wizards to guard their lairs or carry out their bidding.\n\nBeholder Zombies retain some of the abilities of the Beholder they once were, including their ability to shoot deadly eye rays from their central eye. However, they are slower and less intelligent than their living counterparts, often just mindlessly following orders or attacking anything that comes near them.\n\nThese creatures are incredibly dangerous and are not to be underestimated. They can pose a serious threat to even the most experienced adventurers due to their powerful eye rays and undead resilience. It is said that Beholder Zombies can only truly be destroyed by completely destroying their central eye, making them a formidable foe to face in battle."}',0,'Monster Manual 2024','','None',5.0,NULL),
	 ('01990b81-1afd-7699-82ba-9e57cb3d6bc2'::uuid,'Berserker','Any','2 (XP 450; PB +2)',450,1,'Brute','Medium',13,NULL,67,'9d8+27','30 ft.',NULL,NULL,NULL,16,12,17,9,11,9,'{}','None','Passive Perception 10','Common',3,1,3,0,-1,-1,2,'["Greataxe", "Hide Armor"]','Habitat: Any','Humanoid','','{"value":"Rage boils within as it howls, swinging its massive weapon wildly."}','{"value": "In Dungeons and Dragons 5th Edition, the Berserker is a fierce warrior known for their reckless abandon in battle. They are often depicted as belonging to barbarian tribes or warrior clans, wielding massive weapons and wearing little armor. Berserkers are known for their ability to fly into a frenzy during combat, gaining increased strength and endurance but losing control of their actions.\n\nThe lore behind Berserkers usually involves tales of their ferocity in battle, their wild and unpredictable nature, and their reputation for being nearly unstoppable once they enter their berserker rage. Some stories suggest that Berserkers have a connection to primal forces or ancient spirits that grant them their exceptional combat abilities.\n\nIn D&D, Berserkers are typically encountered as enemies in encounters, serving as powerful and dangerous adversaries for player characters to face off against. They may be encountered as lone warriors or as part of a larger group of barbaric fighters, adding a challenging element to combat encounters.\n\nOverall, Berserkers are fearsome and iconic warriors in D&D lore, known for their fierce combat abilities and their wild, unpredictable nature in battle."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b83-54c1-7ab2-b12a-e573bf143a17'::uuid,'Cat','Unaligned','0 (XP 10; PB +2)',10,2,'Skirmisher','Tiny',12,NULL,2,'1d4','40 ft.','40 ft.',NULL,NULL,3,15,10,3,12,7,'{"Stealth": 4, "Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','None',0,4,-4,1,-2,-4,2,'[]',NULL,'Beast','','{"value":"Whiskers twitch as it stalks, eyes gleaming with predatory intent"}','{"value": "Cats in Dungeons and Dragons are typically portrayed as small, agile creatures that possess keen senses and a mischievous nature. They are often found in cities or towns, prowling the streets and alleys in search of food or entertainment.\n\nIn some D&D settings, cats are believed to be familiars to witches or other spellcasters, serving as their magical companions and assistants. They are said to have a strong connection to the Feywild, and are sometimes able to see into other realms or sense magical energies.\n\nWhile cats are generally harmless to humans, they can become aggressive if threatened or cornered. They are known for their ability to move quickly and quietly, making them adept hunters and ambush predators.\n\nOverall, cats in D&D are often depicted as mysterious and enigmatic creatures, with a hint of the supernatural about them. They are both beloved and feared by many, and are often considered to be creatures of great cunning and intelligence."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b81-3834-7351-a4b2-d0d4594d4ddd'::uuid,'Berserker Commander','TrueNeutral','8 (XP 3 900; PB +3)',3900,5,'Brute','Medium',16,NULL,136,'16d8+64','40 ft.',NULL,NULL,NULL,19,14,19,10,14,9,'{"Athletics": 7, "Perception": 5}','Charmed, Frightened','Passive Perception 15','Common',7,2,7,2,-1,0,3,'["Greataxe", "six Javelins"]','Habitat: Any','Humanoid','','{"value":"Rage boils within as it barks orders, eyes wild with bloodlust."}','{"value": "The Berserker Commander is a fearsome and powerful enemy in the world of Dungeons and Dragons. These creatures are known for their incredible strength and skill in combat, as well as their insatiable bloodlust and rage on the battlefield.\n\nBerserker Commanders are often found leading groups of berserkers into battle, using their commanding presence and strategic mind to direct their forces and crush their enemies. They are known for their ability to inspire their allies with their ferocity and fearlessness, often pushing them to fight harder and with more determination.\n\nThese monsters are typically found in savage and warlike societies, where strength and aggression are valued above all else. They are often seen as symbols of power and authority, and are respected and feared by those under their command.\n\nIn combat, Berserker Commanders are relentless and relentless, charging into battle with reckless abandon and cutting down their enemies with brutal efficiency. They are known for their formidable combat skills, as well as their ability to shrug off injuries and keep fighting no matter what.\n\nOverall, the Berserker Commander is a formidable foe that should not be underestimated. Their strength, skill, and ferocity make them a deadly opponent on the battlefield, and those who face them in combat would be wise to approach with caution and prepare for a fierce and brutal fight."}',0,'Monster Manual 2024','','None',8.0,NULL),
	 ('01990b81-7e06-74b1-b275-591731ca6231'::uuid,'Black Pudding','Unaligned','4 (XP 1 100; PB +2)',1100,-3,'Ambusher','Large',7,NULL,68,'8d10+24','20 ft.','20 ft.',NULL,NULL,16,5,16,1,6,1,'{}','Acid, Cold, Lightning, Slashing; Charmed, Deafened, Exhaustion, Frightened, Grappled, Prone, Restrained','Blindsight 60 ft., Passive Perception 8','None',3,-3,3,-2,-5,-5,2,'[]','Habitat: Underdark','Ooze','','{"value":"Glistening mass of ooze slithers and oozes towards you, hunger in its depths."}','{"value": "Black puddings are amorphous, mindless oozes that lurk in dark, damp places such as caves, dungeons, and sewers. They are created from the remains of dead creatures and magical experiments gone wrong. Black puddings are able to dissolve organic material upon contact, making them extremely dangerous to adventurers who come across them.\n\nThese oozes are typically black in color with a thick, viscous consistency. They have the ability to split into smaller puddings when struck with a slashing or piercing weapon, making them difficult to defeat in combat. Black puddings are also known for their ability to sense vibrations in the ground, allowing them to detect the presence of nearby creatures.\n\nDespite their lack of intelligence, black puddings are cunning predators that will lie in wait for unsuspecting prey to come within reach. They are immune to most types of damage, with the exception of cold and lightning attacks. Adventurers who encounter a black pudding must exercise caution and use tactics to defeat these deadly oozes."}',0,'Monster Manual 2024 (BR)','','None',4.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b81-496c-79b3-ad05-7dac646a28cc'::uuid,'Black Bear','Unaligned','1/2 (XP 100; PB +2)',100,1,'Brute','Medium',11,NULL,19,'3d8+6','30 ft.','30 ft.','30 ft.',NULL,15,12,14,2,12,7,'{"Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','None',2,1,2,1,-2,4,2,'[]',NULL,'Beast','','{"value":"Sleek fur ripples as it sniffs the air, eyes fixed on its prey."}','{"value": "Black bears are a common sight in the forests and mountains of the world, known for their strength, agility, and fierce demeanor. These creatures are typically solitary, only coming together during mating season or when a mother is caring for her cubs. \n\nIn D&D 5e, black bears are depicted as medium-sized creatures with dark fur and a distinctive white patch on their chest. They are omnivorous, feeding on a variety of plants, insects, and small animals. While they are generally not aggressive towards humans, they will defend themselves if threatened or if their territory is encroached upon.\n\nBlack bears are known for their powerful claws and teeth, which they use to tear apart their prey. They are also skilled climbers, able to scale trees with ease to escape danger or reach food sources. Despite their reputation for being ferocious, black bears are actually quite shy and will typically avoid confrontations whenever possible.\n\nIn D&D lore, black bears are often seen as symbols of strength and resilience, embodying the qualities of endurance and survival in the face of adversity. They are also associated with the natural world and are often revered by druids and other nature-oriented classes. Overall, black bears are a staple of the D&D ecosystem, providing both a formidable opponent and a source of inspiration for adventurers seeking to explore the wilds."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b81-a683-75cb-bc25-1d25173e86a4'::uuid,'Blob of Annihilation','NeutralEvil','23 (XP 50 000; PB +7)',50000,16,'Solo','Gargantuan',18,NULL,448,'23d20+207','30 ft.',NULL,NULL,NULL,27,14,28,10,16,10,'{}','Acid, Necrotic, Poison; Charmed, Exhaustion, Frightened, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Stunned, Unconscious','Blindsight 120 ft., Passive Perception 13','—',16,9,8,3,0,0,7,'[]','Habitat: Any','Ooze','Titan','{"value":"Gelatinous mass undulates, dissolving all in its path with acidic hunger."}','{"value": "The Blob of Annihilation is a terrifying and mysterious creature that exists in the darkest corners of the multiverse. It is said to be a manifestation of pure chaos and destruction, appearing as a shifting mass of black, viscous goo that devours everything in its path.\n\nLegends tell of powerful wizards and mad scientists who have attempted to create the Blob of Annihilation through dark rituals and forbidden experiments, only to be consumed by their own creation. Some believe that the Blob is a cosmic entity sent to cleanse the universe of impurities, while others see it as a malevolent force seeking to bring about the end of all things.\n\nEncountering a Blob of Annihilation is a rare and terrifying experience, as it is nearly impossible to predict its movements or intentions. It is immune to most forms of damage, and can only be harmed by powerful magical weapons or spells. Those who are unfortunate enough to cross paths with a Blob of Annihilation are advised to run for their lives, as there is little hope of surviving an encounter with this destructive force."}',0,'Monster Manual 2024','Titan','Bludgeoning, Piercing, Slashing',23.0,NULL),
	 ('01990b81-d989-7917-ad31-ace6e98e01c7'::uuid,'Blue Dragon Wyrmling','LawfulEvil','3 (XP 700; PB +2)',700,2,'Solo','Medium',17,NULL,65,'10d8+20','30 ft.',NULL,NULL,'60 ft.',17,10,15,12,11,15,'{"Stealth": 2, "Perception": 4}','Lightning','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Draconic',2,2,3,2,2,1,2,'[]','Habitat: Coastal, Desert','Dragon','Chromatic','{"value":"Scales shimmer with electric energy as it crackles with pent-up fury."}','{"value": "Blue Dragon Wyrmlings are young dragons that are born from the powerful and ancient blue dragons. They are known for their vibrant blue scales, sharp claws, and electric breath weapon. Blue Dragon Wyrmlings are cunning and intelligent creatures, often using their superior intellect to outsmart their enemies in battle.\n\nThese young dragons are fiercely territorial and will fiercely defend their lairs from any intruders. They are known to be ruthless and cruel, often taking pleasure in causing fear and suffering to those who dare to challenge them.\n\nBlue Dragon Wyrmlings are also known for their love of treasure and will hoard vast amounts of wealth and magical items in their lairs. They are highly skilled at manipulating and controlling lesser creatures to serve them, using them as minions and guards to protect their treasures.\n\nDespite their young age, Blue Dragon Wyrmlings are formidable opponents and should not be underestimated by any adventurers who encounter them in the wild. Only the bravest and most skilled warriors stand a chance against these fearsome creatures."}',0,'Monster Manual 2024 (BR)','Chromatic','None',3.0,NULL),
	 ('01990b82-1b34-7f2d-921a-c00875c4f558'::uuid,'Bone Devil','LawfulEvil','9 (XP 5 000; PB +4)',5000,7,'Brute','Large',16,NULL,161,'17d10+68','40 ft.',NULL,NULL,'40 ft.',18,16,18,13,14,16,'{"Insight": 6, "Deception": 7}','Fire, Poison; Poisoned','Darkvision 120 ft. (unimpeded by magical Darkness), Passive Perception 12','Infernal; telepathy 120 ft.',4,3,8,6,7,5,4,'[]','Habitat: Planar (Nine Hells)','Fiend','Devil','{"value":"Sinister figure cackles as spikes protrude from its skeletal form."}','{"value": "Bone Devils, also known as osyluths, are powerful fiends that serve as enforcers and torturers in the hierarchy of the Nine Hells. They are often summoned by more powerful devils to carry out their bidding, using their strength and cunning to extract information from prisoners or punish disobedient souls.\n\nBone Devils resemble large, skeletal creatures with sharp claws and a barbed tail that drips with poison. They are highly intelligent and skilled in combat, using their abilities to manipulate and deceive their enemies. They are also known for their ability to teleport short distances and their resistance to magical attacks.\n\nIn the lore of Dungeons and Dragons, Bone Devils are feared for their sadistic nature and their willingness to carry out the most gruesome tasks without hesitation. They are often found in the service of powerful devils such as archdevils or pit fiends, acting as their loyal servants and executing their will with ruthless efficiency.\n\nOverall, Bone Devils are dangerous and formidable foes in the world of D&D, representing the cruelty and malice of the Nine Hells in their terrifying form."}',0,'Monster Manual 2024 (BR)','Devil','Cold',9.0,NULL),
	 ('01990b82-1bcc-712c-a4af-783f3b3f20f2'::uuid,'Bone Naga','NeutralEvil','4 (XP 1 100; PB +2)',1100,3,'Ambusher','Large',15,NULL,65,'10d10+10','40 ft.',NULL,NULL,NULL,15,16,12,16,15,15,'{}','Poison; Charmed, Exhaustion, Paralyzed, Poisoned','Darkvision 60 ft., Passive Perception 12','Common plus one other language',1,3,2,2,2,3,2,'[]','Habitat: Underdark','Undead','','{"value":"Skeletal coils writhe menacingly, eyeless skull fixed on prey."}','{"value": "The Bone Naga is a powerful undead creature that was once a powerful spellcaster in life. Through dark rituals and necromantic magic, the spellcaster transformed into a Bone Naga upon death, gaining immense power and a thirst for vengeance against the living.\n\nThe Bone Naga resembles a serpent-like creature made entirely of bone, with glowing red eyes and a sinister intelligence. It possesses a variety of powerful spells and abilities, making it a formidable opponent for any adventurers who dare to challenge it.\n\nLegends say that the Bone Naga can only be defeated by destroying its phylactery, an object that contains its soul and grants it immortality. Without destroying the phylactery, the Bone Naga will continue to rise again and again, seeking revenge on those who have wronged it.\n\nThose who have encountered the Bone Naga and lived to tell the tale speak of its cunning and ruthlessness, as well as its insatiable hunger for power and control. It is said that those who cross paths with a Bone Naga should tread carefully, for few can escape its wrath unscathed."}',0,'Monster Manual 2024','','None',4.0,NULL),
	 ('01990b82-49b7-7a41-9342-7c290648592e'::uuid,'Brass Dragon Wyrmling','ChaoticGood','1 (XP 200; PB +2)',200,2,'Ambusher','Medium',15,NULL,22,'4d8+4','30 ft.',NULL,NULL,'60 ft.',15,10,13,10,11,13,'{"Stealth": 2, "Perception": 4}','Fire','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Draconic',1,2,2,2,1,0,2,'[]','Habitat: Desert','Dragon','Metallic','{"value":"Roaring proudly, it playfully dances in the shimmering desert heat."}','{"value": "Brass Dragon Wyrmlings are young, playful, and mischievous creatures that are born from the eggs of adult brass dragons. They are typically found in arid desert regions, where they enjoy basking in the hot sun and exploring their surroundings.\n\nBrass Dragon Wyrmlings possess the typical traits of brass dragons, including their affinity for fire and their love of conversation and storytelling. They are known for their cleverness and quick wit, as well as their ability to charm others with their charismatic personalities.\n\nDespite their youthful exuberance, Brass Dragon Wyrmlings are also fiercely protective of their territory and will not hesitate to defend themselves if they feel threatened. They have a keen sense of justice and will often intervene in conflicts to ensure that the right side prevails.\n\nAs they grow older and more powerful, Brass Dragon Wyrmlings will eventually mature into adult brass dragons, gaining the ability to breathe fire and manipulate flames to their advantage. They will also develop a deeper understanding of the world around them and may take on more serious responsibilities, such as guarding important treasures or protecting their allies from harm."}',0,'Monster Manual 2024 (BR)','Metallic','None',1.0,NULL),
	 ('01990b82-78a4-78a2-bbf7-923daeb741c7'::uuid,'Bronze Dragon Wyrmling','LawfulGood','2 (XP 450; PB +2)',450,2,'Solo','Medium',15,NULL,39,'6d8+12','30 ft.',NULL,'30 ft.','60 ft.',17,10,15,12,11,15,'{"Stealth": 2, "Perception": 4}','Lightning','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Draconic',2,2,3,2,2,1,2,'[]','Habitat: Coastal','Dragon','Metallic','{"value":"Glittering scales shimmer as it playfully splashes in the crystal-clear stream."}','{"value": "Bronze Dragon Wyrmlings are young dragons that are just beginning to explore the world and learn about their place in it. They are usually around 5-10 years old and are already quite formidable creatures despite their young age. \n\nBronze dragons are known for their love of water and their affinity for storms. They are often found near bodies of water, such as rivers, lakes, or oceans, where they enjoy swimming and playing in the water. They are also known for their ability to control storms and weather, using their breath weapon to create lightning bolts that can strike their enemies from a distance.\n\nBronze Dragon Wyrmlings are typically curious and adventurous, always eager to explore new places and meet new creatures. They are also fiercely protective of their territory and will not hesitate to defend it against any intruders. Despite their young age, they are intelligent and cunning creatures, using their wits and their natural abilities to outsmart and outmaneuver their foes.\n\nOverall, Bronze Dragon Wyrmlings are noble and majestic creatures that are respected and revered by those who know of their existence. They are creatures of great power and potential, destined to grow into even more formidable beings as they age and mature."}',0,'Monster Manual 2024 (BR)','Metallic','None',2.0,NULL),
	 ('01990b82-b1fe-7d5a-bf6c-402ce07b35c1'::uuid,'Bugbear Stalker','ChaoticEvil','3 (XP 700; PB +2)',700,2,'Skirmisher','Medium',15,NULL,65,'10d8+20','30 ft.',NULL,NULL,NULL,17,14,14,11,12,11,'{"Stealth": 6, "Survival": 3}','None','Darkvision 60 ft., Passive Perception 11','Common, Goblin',4,2,3,3,0,0,2,'["Chain Shirt", "Javelins (6)", "Morningstar"]','Habitat: Forest, Grassland, Planar (Feywild), Underdark','Fey','Goblinoid','{"value":"Stealthily, it lurks in the shadows, eyes gleaming with malice."}','{"value": "The Bugbear Stalker is a fearsome creature that lurks in the shadows, using its stealth and cunning to stalk and ambush its prey. Known for their brutal strength and savage nature, Bugbear Stalkers are often employed as assassins or enforcers by powerful individuals or organizations.\n\nThese creatures are a subrace of bugbears that have honed their skills in stealth and assassination, making them even deadlier than their already formidable kin. They are known for their ability to move silently and strike quickly, often catching their victims off guard and delivering a fatal blow before they even realize they are under attack.\n\nBugbear Stalkers are highly intelligent and resourceful, using their keen senses and knowledge of tactics to outmaneuver their enemies. They are also skilled in tracking and hunting, making them formidable opponents in the wild.\n\nOverall, Bugbear Stalkers are ruthless and efficient killers, feared by many for their deadly prowess and relentless pursuit of their targets. They are a force to be reckoned with in the world of Dungeons and Dragons, and adventurers would do well to be cautious when facing one of these deadly creatures."}',0,'Monster Manual 2024 (BR)','Goblinoid','None',3.0,NULL),
	 ('01990b82-c7d6-7162-a5b7-480ec0195fa1'::uuid,'Bugbear Warrior','ChaoticEvil','1 (XP 200; PB +2)',200,2,'Brute','Medium',14,NULL,33,'6d8+6','30 ft.',NULL,NULL,NULL,15,14,13,8,11,9,'{"Stealth": 6, "Survival": 2}','None','Darkvision 60 ft., Passive Perception 10','Common, Goblin',1,2,2,0,-1,-1,2,'["Hide Armor", "Light Hammers (3)"]','Habitat: Forest, Grassland, Planar (Feywild), Underdark','Fey','Goblinoid','{"value":"Grinning, it sharpens its rusty blade against a jagged rock, eyes fixed on you."}','{"value": "Bugbears are large, brutish creatures that are known for their strength and ferocity in battle. They are often found in tribes in the wilderness, where they live in crude settlements and raid nearby villages for food and supplies.\n\nBugbear warriors are the elite fighters of bugbear society, skilled in combat and highly respected by their fellow tribe members. They are typically larger and stronger than other bugbears, and are known for their prowess with weapons such as swords, axes, and bows.\n\nBugbear warriors are often used as front-line fighters in battle, charging into combat with reckless abandon and using their brute strength to overpower their enemies. They are also skilled hunters and trackers, making them valuable assets for their tribe when it comes to scouting and hunting for food.\n\nIn addition to their physical abilities, bugbear warriors are also known for their cunning and tactical intelligence. They are skilled at setting ambushes and traps for their enemies, and are able to adapt to changing situations on the battlefield with ease.\n\nOverall, bugbear warriors are dangerous foes to face in battle, and should not be underestimated by even the most seasoned adventurers."}',0,'Monster Manual 2024 (BR)','Goblinoid','None',1.0,NULL),
	 ('01990b82-e2a9-789e-80d6-c7529cd52e33'::uuid,'Bulette Pup','Unaligned','2 (XP 450; PB +2)',450,-1,'Solo','Medium',16,NULL,45,'6d8+18','30 ft.',NULL,NULL,NULL,16,8,17,2,10,4,'{"Perception": 4}','None','Darkvision 30 ft., Tremorsense 60 ft., Passive Perception 14','—',3,-1,3,0,-3,-4,2,'[]','Habitat: Grassland, Hill, Mountain','Monstrosity','','{"value":"Tiny jaws snap eagerly, eyes bright with ferocious playfulness."}','{"value": "Bulette Pups are the young offspring of the fearsome Bulette, also known as the Land Shark. These creatures are born underground and spend their early days feasting on insects and small creatures in their burrows. As they grow, they become more aggressive and start hunting larger prey.\n\nBulette Pups have a thick, armored hide that provides them with excellent protection from attacks. Their powerful jaws are capable of crushing bones and their sharp claws can easily tear through flesh. Despite their small size, Bulette Pups are incredibly fast and can quickly chase down their prey.\n\nAs they mature, Bulette Pups will eventually grow into full-sized Bulettes, becoming one of the most feared predators in the land. They are solitary creatures that roam the wilderness in search of food, striking fear into the hearts of travelers and adventurers alike.\n\nEncountering a Bulette Pup in the wild is a dangerous situation, as they are fiercely territorial and will defend their territory with deadly force. Many adventurers have underestimated these creatures, only to meet a swift and brutal end at the jaws of a Bulette Pup."}',0,'Monster Manual 2024','','None',2.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b83-0353-7b20-9d38-01e134faa474'::uuid,'Bullywug Bog Sage','TrueNeutral','4 (XP 1,100; PB +2)',1100,3,'Controller','Medium',16,NULL,52,'8d8+16','30 ft.',NULL,'30 ft.',NULL,8,16,14,10,16,12,'{"Nature": 4, "Stealth": 5}','None','Passive Perception 13','Bullywug, Common, Sylvan',4,3,-1,5,1,0,2,'["Component Pouch"]','Habitat: Swamp','Fey','','{"value":"Moss-covered sage croaks ancient curses, stirring foul waters with a twisted staff."}','{"value": "The Bullywug Bog Sage is a rare and powerful variant of the standard Bullywug creature found in swamps and marshes. Unlike their more common counterparts, Bog Sages are revered and feared by other Bullywugs for their incredible intelligence and magical abilities.\n\nBog Sages are typically the rulers or spiritual leaders of Bullywug communities, using their knowledge of ancient rituals and powerful spells to maintain control and protect their people. They are often seen as wise and enigmatic figures, consulted for their advice and guidance in times of need.\n\nIn combat, Bullywug Bog Sages are formidable opponents, using a combination of powerful spells and natural abilities to overpower their enemies. They are skilled in the use of dark magic and can summon minions to aid them in battle. They are also capable of manipulating the environment to their advantage, creating illusions and traps to confuse and disorient their foes.\n\nOverall, the Bullywug Bog Sage is a mysterious and powerful creature that commands respect and fear in equal measure. Their presence in a swamp or marsh is a sign of great danger, as they are not to be underestimated in their knowledge and power."}',0,'Monster Manual 2024 (BR)','','None',4.0,NULL),
	 ('01990b83-7712-7dc9-a91b-76b02e3db3b7'::uuid,'Centaur Trooper','NeutralGood','2 (XP 450; PB +2)',450,2,'Soldier','Large',16,NULL,45,'6d10+12','50 ft.',NULL,NULL,NULL,18,14,14,9,13,11,'{"Athletics": 6, "Perception": 3}','None','Passive Perception 13','Elvish, Sylvan',2,2,4,1,0,-1,2,'["Breastplate", "Longbow", "Pike"]','Habitat: Forest, Grassland, Planar (Feywild)','Fey','','{"value":"Hooves thunder as it charges, bow at the ready, eyes fixed on its target."}','{"value": "Centaur Troopers are a unique breed of centaur that have been trained and bred for combat. They are known for their exceptional speed, strength, and skill in battle. Centaur Troopers are often used as elite cavalry units in military forces or as mercenary soldiers.\n\nThese creatures are highly disciplined and follow a strict code of honor. They are fiercely loyal to their leaders and comrades, and will fight to the death to protect them. Centaur Troopers are usually equipped with heavy armor, spears, and shields, making them formidable opponents on the battlefield.\n\nIn addition to their combat prowess, Centaur Troopers are also skilled trackers and scouts. Their keen senses and knowledge of the land make them valuable assets for gathering intelligence and conducting reconnaissance missions.\n\nOverall, Centaur Troopers are respected and feared for their skill in battle and unwavering loyalty. They are often seen as symbols of strength and honor in the world of D&D."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b83-7bac-7441-9d87-6eb3bae7bfbf'::uuid,'Centaur Warden','NeutralGood','7 (XP 2 900; PB +3)',2900,2,'Skirmisher','Large',16,NULL,105,'14d10+28','50 ft.',NULL,NULL,NULL,18,14,14,9,18,11,'{"Nature": 5, "Athletics": 7, "Perception": 7}','None','Passive Perception 17','Druidic, Elvish, Sylvan',5,2,4,7,0,-1,3,'[]','Habitat: Forest, Grassland, Planar (Feywild)','Fey','','{"value":"Hooves pound the earth as it stands tall, bow in hand, eyes watchful."}','{"value": "Centaur Wardens are powerful guardians of nature, often found patrolling the borders of ancient forests and sacred groves. They are known for their fierce loyalty to their homeland and their unwavering commitment to protecting the natural world from any threats.\n\nThese creatures are the embodiment of the wild, blending the strength and speed of a horse with the keen senses and sharp instincts of a human. They are skilled archers and trackers, able to navigate the densest of forests with ease and precision.\n\nCentaur Wardens are highly respected among other woodland creatures and are often called upon to lead hunting parties or defend their territory from encroaching enemies. They are known for their stoic demeanor and deep connection to the land, often communicating with animals and plants in a way that few others can understand.\n\nDespite their strong sense of duty and honor, Centaur Wardens are not without their flaws. They can be quick to anger when their homeland is threatened, and have been known to unleash their full fury upon those who would harm the natural world.\n\nOverall, Centaur Wardens are noble and powerful protectors of the wild, standing as a beacon of strength and resilience in a world that is constantly under threat from forces that seek to exploit and destroy the beauty of nature."}',0,'Monster Manual 2024','','None',7.0,NULL),
	 ('01990b83-ae1f-7762-b7c8-487b38846493'::uuid,'Chasme','ChaoticEvil','6 (XP 2 300; PB +3)',2300,5,'Skirmisher','Large',15,NULL,78,'12d10+12','20 ft.',NULL,NULL,'60 ft.',15,15,12,11,14,10,'{"Perception": 5}','Poison; Poisoned','Blindsight 10 ft., Darkvision 120 ft., Passive Perception 15','Abyssal; telepathy 120 ft.',1,5,2,5,0,0,3,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Wings hum loudly as it hovers menacingly, eyes fixed on its prey"}','{"value": "Chasmes are grotesque, insect-like demons that dwell in the Abyss. They are known for their insatiable hunger and their ability to spread disease and corruption wherever they go. Chasmes are often used as scouts and spies by more powerful demons, using their ability to fly silently and invisibly to gather information or sow chaos in the mortal realm.\n\nChasmes are said to have been created by the demon lord Graz''zt, who imbued them with a portion of his own power. As a result, they are particularly resilient and difficult to kill. Chasmes are also capable of draining the life force of their victims, using their proboscis-like mouths to suck the vitality from their prey.\n\nIn combat, Chasmes are known for their agility and their ability to strike quickly and unexpectedly. They are also skilled spellcasters, able to cast a variety of spells to confuse and disorient their foes. Chasmes are often found leading groups of lesser demons into battle, using their cunning and guile to outmaneuver their enemies.\n\nOverall, Chasmes are feared and reviled by mortals and demons alike, as their presence often heralds death and destruction. They are considered to be one of the most dangerous and unpredictable demons in the Abyss, and those who encounter them would do well to tread carefully."}',0,'Monster Manual 2024','Demon','Cold, Fire, Lightning',6.0,NULL),
	 ('01990b83-d0dc-7a41-86a8-fc87ac2de215'::uuid,'Chimera','ChaoticEvil','6 (XP 2 300; PB +3)',2300,0,'Brute','Large',14,NULL,114,'12d10+48','30 ft.',NULL,NULL,'60 ft.',19,11,19,3,14,10,'{"Perception": 8}','None','Darkvision 60 ft., Passive Perception 18','Understands Draconic but can''t speak',4,0,4,2,0,-4,3,'[]','Habitat: Grassland, Hill, Mountain','Monstrosity','','{"value":"Roaring loudly, it breathes fire and lashes out with multiple heads."}','{"value": "In the world of Dungeons and Dragons, the Chimera is a fearsome and legendary creature that is said to have the body of a lion, the head of a goat, and the tail of a serpent. It is a ferocious and unpredictable beast that is known for its incredible strength and ability to breathe fire.\n\nAccording to lore, Chimeras are often found in remote and desolate areas, where they hunt and terrorize any creatures that come across their path. They are considered to be a symbol of chaos and destruction, and many believe that encountering a Chimera is a bad omen.\n\nLegends say that Chimeras were created by powerful sorcerers or dark gods as a twisted experiment, combining different animals to create a creature that embodies pure savagery and power. They are often used as guardians by evil creatures or as weapons of war by dark sorcerers.\n\nChimeras are highly intelligent creatures and are capable of understanding and speaking multiple languages. They are known for their cunning and ability to outsmart their enemies in battle.\n\nOverall, Chimeras are feared and respected in the world of Dungeons and Dragons, and encountering one is a dangerous and potentially deadly experience. Only the bravest and most skilled adventurers dare to face these monstrous beasts in combat."}',0,'Monster Manual 2024 (BR)','','None',6.0,NULL),
	 ('01990b83-e93c-7189-964e-49e522ccbc94'::uuid,'Chuul','ChaoticEvil','4 (XP 1 100; PB +2)',1100,0,'Brute','Large',16,NULL,76,'9d10+27','30 ft.',NULL,'30 ft.',NULL,19,10,16,5,11,5,'{"Perception": 4}','Poison; Poisoned','Darkvision 60 ft., Passive Perception 14','Understands Deep Speech but can''t speak',3,0,4,0,-3,-3,2,'[]','Habitat: Coastal, Swamp, Underdark','Aberration','','{"value":"Silent, the chuul lurks in the murky waters, its pincers twitching with anticipation."}','{"value": "Chuuls are large, crab-like monstrosities that dwell in coastal regions and underground caves. They are highly intelligent and possess a cruel and cunning nature. Chuuls are known for their ability to camouflage themselves in their surroundings, making them excellent ambush predators.\n\nChuuls are often found in service to more powerful beings, such as aboleths or mind flayers, acting as guards or enforcers. They are attracted to sources of magic and treasure, making them dangerous foes for adventurers seeking to plunder ancient ruins or treasure hoards.\n\nIn combat, chuuls use their powerful claws to grapple and crush their enemies, while their paralyzing tentacles can incapacitate foes. They are also capable of emitting a noxious gas that can weaken and disorient their opponents.\n\nChuuls are feared by sailors and coastal communities, as they are known to drag unsuspecting victims into the depths of the ocean to feed on them. Their presence is often a sign of darker forces at work, and encountering a chuul is a sure sign that danger is close at hand."}',0,'Monster Manual 2024 (BR)','','None',4.0,NULL),
	 ('01990b84-11da-783f-8008-0d2a54a2f35f'::uuid,'Clay Golem','Unaligned','9 (XP 5 000; PB +4)',5000,3,'Brute','Large',14,NULL,123,'13d10+52','20 ft.',NULL,NULL,NULL,20,9,18,3,8,1,'{}','Acid, Poison, Psychic; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned','Darkvision 60 ft., Passive Perception 9','Common plus one other language',4,-1,5,-1,-5,-4,4,'[]','Habitat: Urban','Construct','','{"value":"Stomping heavily, it leaves deep footprints in the damp earth."}','{"value": "Clay Golems are creatures made from enchanted clay that have been brought to life through powerful magic. They are typically created by powerful spellcasters or wizards to serve as guardians or protectors of their lairs or treasures. \n\nClay Golems are massive, hulking creatures with immense strength and durability. They are immune to most forms of physical damage, and can only be harmed by magical weapons or spells. They are also resistant to most forms of magic, making them formidable opponents in combat.\n\nDespite their immense physical strength, Clay Golems are not particularly intelligent creatures and typically follow simple commands given to them by their creators. They are known for their relentless pursuit of their targets, never tiring or giving up until they have completed their task.\n\nIn some legends, it is said that Clay Golems possess a fragment of the soul of their creator, giving them a sense of purpose and loyalty to their master. However, if their creator dies or abandons them, Clay Golems may become uncontrollable and wreak havoc on their surroundings.\n\nOverall, Clay Golems are formidable and dangerous creatures that should not be underestimated in combat. Their sheer strength and resilience make them a force to be reckoned with, and only the most skilled adventurers should attempt to face them in battle."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',9.0,NULL),
	 ('01990b84-7797-7678-b9a6-b04709e7ab40'::uuid,'Cloud Giant','TrueNeutral','9 (XP 5 000; PB +4)',5000,4,'Artillery','Huge',14,NULL,200,'16d12+96','40 ft.',NULL,NULL,'20 ft.',27,10,22,12,16,16,'{"Insight": 7, "Perception": 11}','None','Passive Perception 21','Common, Giant',10,0,8,7,3,1,4,'[]','Habitat: Mountain','Giant','','{"value":"Thunderous footsteps shake the ground as it commands the storm to its will."}','{"value": "Cloud giants are a race of giants known for their affinity with the sky and their connection to the element of air. They are known for their immense size and strength, as well as their ability to control and manipulate the weather.\n\nCloud giants are typically peaceful and live in isolated communities high in the mountains or in the clouds themselves. They are skilled artisans and craftsmen, known for creating beautiful works of art and architecture. They are also known for their intelligence and wisdom, often serving as advisors to other giants or even powerful rulers.\n\nIn combat, cloud giants are formidable foes, using their immense strength and size to overpower their enemies. They are also known for their ability to control the weather, summoning storms or gusts of wind to aid them in battle.\n\nOverall, cloud giants are a powerful and enigmatic race, revered for their connection to the sky and their mastery of the elements. They are a rare sight in the world of Dungeons and Dragons, but those who encounter them are sure to remember the encounter for years to come."}',0,'Monster Manual 2024 (BR)','','None',9.0,NULL),
	 ('01990b85-a65a-749c-af96-125e78f4ccee'::uuid,'Death Slaad','ChaoticEvil','10 (XP 5 900; PB +4)',5900,10,'Brute','Medium',18,NULL,178,'21d8+84','40 ft.',NULL,NULL,NULL,20,15,19,15,10,19,'{"Arcana": 6, "Perception": 8}','None','Blindsight 60 ft., Darkvision 60 ft., Passive Perception 18','Common, Slaad; telepathy 60 ft.',4,2,5,0,4,2,4,'[]','Habitat: Planar (Limbo)','Aberration','','{"value":"Infectious laughter echoes as it twirls a wicked blade in its clawed hand"}','{"value": "Death Slaads are powerful and terrifying creatures that are created when a Red Slaad reaches the end of its lifespan. These creatures are much larger and more powerful than their lesser counterparts, with the ability to cast powerful spells and drain the life force from their enemies.\n\nDeath Slaads are often seen as harbingers of doom and destruction, appearing in the Material Plane to sow chaos and death. They are known for their brutal and savage nature, delighting in the suffering and pain of their victims.\n\nSome believe that Death Slaads serve as agents of the demon lord Ygorl, spreading chaos and destruction in his name. Others believe that they are simply manifestations of pure evil, drawn to places of great suffering and despair.\n\nDespite their terrifying power, Death Slaads are not invincible. They can be banished or destroyed by powerful magic or brave adventurers willing to take on the challenge. However, facing a Death Slaad is always a dangerous proposition, as their strength and cunning make them formidable foes."}',0,'Monster Manual 2024','','Acid, Cold, Fire, Lightning, Thunder',10.0,NULL),
	 ('01990b84-8af1-7627-b127-99b9fc6112fc'::uuid,'Cockatrice Regent','Unaligned','8 (XP 3 900; PB +3)',3900,2,'Solo','Large',15,NULL,136,'16d10+48','30 ft.',NULL,NULL,'60 ft.',19,14,16,3,16,5,'{}','Petrified','Darkvision 120 ft., Passive Perception 13','—',3,2,4,6,-3,-4,3,'[]','Habitat: Grassland','Monstrosity','','{"value":"Feathers bristle as it surveys its domain, freezing all who dare approach."}','{"value": "The Cockatrice Regent is a powerful and fearsome creature that rules over a colony of cockatrices. It is said to be a massive and ancient beast, with scales as hard as stone and a gaze that can turn its enemies to stone with a single glance.\n\nThe Cockatrice Regent is believed to have been created by a powerful wizard who sought to harness the power of the cockatrice for his own purposes. However, the creature proved to be too wild and uncontrollable, and it eventually broke free from its creator''s control and established itself as the ruler of its own kind.\n\nThe Cockatrice Regent is a cunning and ruthless leader, using its powers of petrification to keep its subjects in line and maintain its dominance over the surrounding territory. It is said to be fiercely territorial and will not hesitate to attack any intruders who dare to enter its domain.\n\nDespite its fearsome reputation, the Cockatrice Regent is not invincible, and many brave adventurers have attempted to slay the creature and claim its treasure for themselves. However, few have succeeded, as the Cockatrice Regent is a formidable foe with deadly powers and a cunning mind.\n\nOverall, the Cockatrice Regent is a creature of legend and myth, feared by all who dwell in the lands where it reigns supreme. It is a reminder of the dangers that lurk in the wild places of the world, and a testament to the power and majesty of the creatures that inhabit them."}',0,'Monster Manual 2024','','None',8.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b84-97b2-79c3-a633-b9d100100239'::uuid,'Colossus','Unaligned','25 (XP 75 000; PB +8)',75000,16,'Brute','Gargantuan',23,NULL,553,'27d20+270','60 ft.',NULL,NULL,NULL,30,11,30,3,11,8,'{}','Poison, Psychic; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned, Stunned, Unconscious','Truesight 300 ft., Passive Perception 10','Understands Celestial and Common but can''t speak',10,8,10,8,-1,-4,8,'[]','Habitat: Any','Construct','Titan','{"value":"Towering over you, its footsteps shake the ground with thunderous might."}','{"value": "Colossus is a giant humanoid creature that is said to be created by powerful magic or divine intervention. They are massive in size, towering over normal-sized beings, and are often depicted as guardians of ancient ruins or holy sites.\n\nColossi are known for their immense strength and durability, able to withstand attacks that would easily kill a lesser creature. Their skin is said to be as tough as stone, making them nearly impervious to harm.\n\nIt is said that colossi are incredibly rare, with only a handful of them existing in the world at any given time. Some believe that they are the remnants of a long-forgotten civilization, while others think that they are beings of pure elemental energy given physical form.\n\nDespite their intimidating appearance, colossi are not inherently evil creatures. They are often neutral in alignment and only attack those who threaten their domain or the beings they are sworn to protect.\n\nEncountering a colossus is a rare and awe-inspiring experience, as their presence alone can shake the very earth beneath your feet. Many adventurers seek out these creatures in the hopes of gaining their favor or unlocking the secrets of their creation. But approaching a colossus is not without risk, as their power is unmatched and they will not hesitate to defend themselves if provoked."}',0,'Monster Manual 2024','Titan','Necrotic, Radiant',25.0,NULL),
	 ('01990b84-a6be-7413-a6de-e6cd8a77693a'::uuid,'Commoner','TrueNeutral','0 (XP 10; PB +2)',10,0,'Minion','Medium',10,NULL,4,'1d8','30 ft.',NULL,NULL,NULL,10,10,10,10,10,10,'{}','None','Passive Perception 10','Common',0,0,0,0,0,0,2,'["Club"]','Habitat: Any','Humanoid','','{"value":"Shuffling nervously, the commoner clutches a small dagger, eyes wide with fear."}','{"value": "Commoners are ordinary, everyday people found in the world of Dungeons and Dragons. They are non-adventurers who live and work in villages, towns, and cities, performing various tasks such as farming, blacksmithing, or trading. Commoners have no special abilities or powers and are generally considered to be weak and vulnerable compared to adventurers and monsters.\n\nIn the world of D&D, commoners make up the majority of the population and are essential for the functioning of society. They can be found in all walks of life, from peasants working the fields to shopkeepers selling goods in the marketplace. Commoners are often the first to suffer in times of war or trouble, as they lack the skills and resources to defend themselves against threats.\n\nWhile commoners may not be powerful or heroic, they play an important role in the world of Dungeons and Dragons, providing a sense of realism and grounding for the fantastical adventures of the player characters. They serve as a reminder of the everyday struggles and challenges faced by ordinary people in a world filled with magic and monsters."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b84-c470-7507-962a-acef2dc8301e'::uuid,'Copper Dragon Wyrmling','ChaoticGood','1 (XP 200; PB +2)',200,3,'Ambusher','Medium',16,NULL,22,'4d8+4','30 ft.','30 ft.',NULL,'60 ft.',15,12,13,14,11,13,'{"Stealth": 3, "Perception": 4}','Acid','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Draconic',1,3,2,2,1,2,2,'[]','Habitat: Hill','Dragon','Metallic','{"value":"Wings shimmer in the sunlight, playfully darting in and out of shadows"}','{"value": "Copper Dragons are known for their playful and mischievous nature, often enjoying practical jokes and riddles. They are also fiercely independent and value their freedom above all else. \n\nCopper Dragon Wyrmlings are young dragons that have recently hatched from their eggs. They are small in size compared to adult dragons, but still possess the same copper scales and sharp claws and teeth. Despite their youth, Copper Dragon Wyrmlings are still quite intelligent and cunning, often using their wit and charm to outsmart their foes.\n\nThese young dragons are known for their love of treasure and will often hoard shiny objects in their lairs. They are also skilled at shape-shifting and can take on the form of a human or elf to interact with other creatures. \n\nCopper Dragon Wyrmlings are typically neutral in alignment, but can lean towards chaotic tendencies due to their playful nature. They are also known to be protective of their territory and will fiercely defend it against any intruders.\n\nOverall, Copper Dragon Wyrmlings are lively and curious creatures that bring a sense of whimsy to the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','Metallic','None',1.0,NULL),
	 ('01990b84-e8d3-7a19-905f-f794fd139b8d'::uuid,'Couatl','LawfulGood','4 (XP 1 100; PB +2)',1100,5,'Support','Medium',19,NULL,60,'8d8+24','30 ft.',NULL,NULL,'90 ft.',16,20,17,18,20,18,'{}','Psychic, Radiant','Truesight 120 ft., Passive Perception 15','All; telepathy 120 ft.',5,5,3,7,4,4,2,'[]','Habitat: Desert, Forest, Grassland, Urban','Celestial','','{"value":"Wings unfurl majestically, casting a radiant glow upon the sacred chamber"}','{"value": "The Couatl is a serpent-like celestial being in Dungeons and Dragons 5th edition, often serving as a symbol of wisdom and protector of good. They are known for their vibrant colors and graceful flying abilities.\n\nIn D&D lore, Couatls are ancient and powerful creatures that hail from the Upper Planes, specifically the plane of Elysium. They are often associated with benevolent deities and are considered to be wise and just beings. Couatls are known for their ability to shape-shift into a more humanoid form, allowing them to interact with mortals more easily.\n\nCouatls are typically depicted as protectors of ancient ruins, temples, and other sacred sites. They are known to offer guidance and aid to those who seek to do good, but can also be fierce adversaries to those who seek to do harm or desecrate sacred places.\n\nIn combat, Couatls are formidable opponents, using their powerful magic and innate abilities to strike down their enemies. They are known for their ability to cast spells, such as charm person and suggestion, as well as their powerful bite and stunning gaze attack.\n\nOverall, Couatls are revered and respected beings in the world of Dungeons and Dragons, embodying the ideals of wisdom, justice, and protection."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',4.0,NULL),
	 ('01990b85-0977-7b28-b494-93290ebc9fa1'::uuid,'Crawling Claw','NeutralEvil','0 (XP 10; PB +2)',10,2,'Minion','Tiny',12,NULL,2,'1d4','20 ft.','20 ft.',NULL,NULL,13,14,11,5,10,4,'{}','Necrotic, Poison; Charmed, Exhaustion, Frightened, Incapacitated, Poisoned','Blindsight 30 ft., Passive Perception 10','Understands Common but can''t speak',0,2,1,0,-3,-3,2,'[]','Habitat: Any','Undead','','{"value":"Fingers scuttle along the ground, searching with eerie purpose."}','{"value": "The Crawling Claw is a horrifying undead creature that is essentially a severed hand animated by dark magic. It scuttles along on its fingers, searching for its next victim to attack and kill.\n\nAccording to lore, Crawling Claws are created when a powerful necromancer or dark wizard animates the severed hand of a humanoid creature, typically a criminal or someone who has committed great evil in their life. The hand retains a twisted version of its former owner''s personality, making it even more dangerous and unpredictable.\n\nCrawling Claws are often used as minions by necromancers or other dark spellcasters, sent out to do their bidding and carry out acts of violence and terror. They are relentless in their pursuit of their targets, using their sharp nails to slash and tear at their victims.\n\nDespite their small size, Crawling Claws are surprisingly resilient and difficult to kill, as they possess a regenerative ability that allows them to quickly heal from injuries. They are also known for their ability to climb walls and ceilings, making them even more difficult to evade or escape from.\n\nOverall, the Crawling Claw is a fearsome and unsettling creature that strikes fear into the hearts of those who encounter it, serving as a reminder of the dark and twisted powers of necromancy in the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','None',0.0,NULL),
	 ('01990b85-40b8-7145-84ca-901c2c250ca5'::uuid,'Cultist Fanatic','Any','2 (XP 450; PB +2)',450,2,'Support','Medium',13,NULL,44,'8d8+8','30 ft.',NULL,NULL,NULL,11,14,12,10,14,13,'{"Religion": 2, "Deception": 3, "Persuasion": 3}','None','Passive Perception 12','Common',1,2,0,4,1,0,2,'["Holy Symbol", "Leather Armor"]','Habitat: Any','Humanoid','','{"value":"Eyes wide with devotion, the cultist fanatic chants fervently, a manic gleam in their gaze."}','{"value": "The Cultist Fanatic is a humanoid creature that has become completely devoted to serving a dark and powerful deity or being. They are often members of cults or secret societies that worship this entity and will stop at nothing to further its goals and spread its influence.\n\nCultist Fanatics are typically armed with weapons and wear dark robes or armor adorned with symbols of their deity. They are fanatical in their beliefs, willing to sacrifice themselves or others in the name of their cause. They may also possess magical abilities granted to them by their deity, such as the ability to cast spells or summon otherworldly creatures.\n\nCultist Fanatics are often encountered in groups, working together to carry out rituals or perform dark deeds in the name of their deity. They are feared and reviled by many, as their actions can bring chaos and destruction to the world around them.\n\nAdventurers who encounter Cultist Fanatics must be cautious, as they are often skilled in combat and are willing to fight to the death for their cause. It is important to uncover their plans and stop them before they can unleash their dark powers upon the world."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b85-416d-7b2d-9220-09403fd85620'::uuid,'Cultist Hierophant','TrueNeutral','10 (XP 5 900; PB +4)',5900,8,'Leader','Medium',16,NULL,144,'17d8+68','30 ft.',NULL,NULL,NULL,14,18,18,13,16,20,'{"Religion": 5, "Perception": 7, "Persuasion": 9}','None','Passive Perception 17','Celestial, Common',4,4,2,7,9,1,4,'["Breastplate", "Holy Symbol"]','Habitat: Any','Humanoid','','{"value":"Eyes glow with fanatical zeal as it chants ancient incantations."}','{"value": "The Cultist Hierophant is a powerful and sinister figure in the world of Dungeons and Dragons. They are high-ranking members of dark cults who have gained immense power through their devotion to dark gods or forbidden practices. \n\nThese vile spellcasters are known for their ability to manipulate and control the minds of others, as well as their mastery of dark magic and rituals. They often serve as leaders within their cults, guiding their followers in their dark pursuits and enacting the will of their malevolent deities.\n\nCultist Hierophants are often found in hidden temples or secret gatherings, where they perform dark rituals and sacrifices to appease their twisted gods. They are feared and respected by their cult followers, who believe that their Hierophant possesses a direct connection to their dark deity.\n\nIn combat, Cultist Hierophants are formidable foes, using their powerful spells and dark magic to devastate their enemies. They are adept at summoning demons and other dark creatures to aid them in battle, and are known for their ability to twist the minds of their foes with curses and mind-controlling spells.\n\nOverall, the Cultist Hierophant is a dark and malevolent figure in the world of D&D, a powerful enemy that must be faced with caution and skill."}',0,'Monster Manual 2024','','None',10.0,NULL),
	 ('01990b85-4770-7f75-8885-dfebc8df056e'::uuid,'Cyclops Sentry','ChaoticNeutral','6 (XP 2 300; PB +3)',2300,0,'Soldier','Huge',14,NULL,138,'12d12+60','40 ft.',NULL,NULL,NULL,22,11,20,8,6,10,'{}','None','Passive Perception 8','Giant',5,0,6,-2,0,-1,3,'[]','Habitat: Coastal, Desert, Grassland, Hill, Mountain, Underdark','Giant','','{"value":"Thunderous footsteps shake the ground as it scans the horizon with one piercing eye"}','{"value": "Cyclops Sentries are formidable creatures that were created by powerful wizards and sorcerers to guard important locations or treasures. These towering giants stand over 15 feet tall, with rippling muscles and a single, large eye in the center of their forehead. \n\nCyclops Sentries are highly intelligent and fiercely loyal to their creators, following orders with unwavering dedication. They are equipped with powerful weapons, such as massive clubs or enchanted bows, and are skilled in combat tactics and strategy. \n\nIn battle, Cyclops Sentries use their immense strength and keen senses to detect and eliminate threats to their charges. They are able to see in the dark and have a keen sense of smell, making it difficult for intruders to evade their watchful gaze. \n\nDespite their fearsome appearance, Cyclops Sentries are not mindless brutes. They can be reasoned with and even persuaded to change sides if the offer is tempting enough. However, betraying a Cyclops Sentry is a dangerous proposition, as they will stop at nothing to exact revenge on those who have wronged them or their masters."}',0,'Monster Manual 2024','','None',6.0,NULL),
	 ('01990b85-4cbc-73a1-890d-635e85323d75'::uuid,'Dao','TrueNeutral','11 (XP 7 200; PB +4)',7200,1,'Brute','Large',18,NULL,200,'16d10+112','30 ft.',NULL,NULL,'30 ft.',23,12,24,12,13,18,'{}','Petrified','Darkvision 120 ft., Passive Perception 11','Primordial (Terran)',7,5,6,5,4,1,4,'[]','Habitat: Planar (Elemental Plane of Earth), Underdark','Elemental','Genie','{"value":"Stony giant gestures grandly, its eyes gleaming with greed."}','{"value": "In Dungeons and Dragons 5th Edition, a Dao is a type of genie that originates from the Elemental Plane of Earth. They are powerful beings with a deep connection to the earth and are known for their greed and love of material wealth.\n\nDaos are typically depicted as large, muscular beings with dark skin, glowing eyes, and long, flowing hair. They are often seen wearing lavish clothing and adorned with precious gems and metals.\n\nIn terms of their abilities, Daos are incredibly strong and durable, able to withstand immense amounts of damage. They also have the ability to manipulate earth and stone, allowing them to create earthquakes, shape stone structures, and even burrow through the ground.\n\nDespite their formidable powers, Daos are not inherently evil and can be bargained with. They are often summoned by those seeking wealth or power, as they are known to grant wishes in exchange for valuable treasures.\n\nOverall, Daos are fascinating and powerful creatures in the world of Dungeons and Dragons, embodying the essence of the earth itself and serving as both a formidable foe and a potential ally for adventurers brave enough to seek them out."}',0,'Monster Manual 2024','Genie','None',11.0,NULL),
	 ('01990b85-824e-79d6-b460-221330517ae2'::uuid,'Death Cultist','NeutralEvil','8 (XP 3 900; PB +3)',3900,4,'Controller','Medium',17,NULL,127,'15d8+60','30 ft.',NULL,NULL,NULL,19,12,18,12,16,14,'{"Insight": 6, "Religion": 4, "Perception": 6}','None','Passive Perception 16','Common',7,1,4,6,2,1,3,'["Splint Armor"]','Habitat: Any','Humanoid','','{"value":"Its eyes glow with dark intent as it whispers eldritch incantations."}','{"value": "Death Cultists are sinister individuals who have dedicated themselves to worshiping dark and malevolent deities associated with death and decay. They are often found in hidden temples or secret societies, carrying out dark rituals and sacrifices in the name of their twisted beliefs.\n\nDeath Cultists are known for their proficiency in necromancy, using dark magic to raise the dead and manipulate the forces of death to their advantage. They are skilled in combat, often wielding weapons imbued with dark magic and wearing dark robes adorned with macabre symbols.\n\nThese cultists are fanatical in their devotion to their dark gods, willing to go to extreme lengths to please them and further their malevolent agendas. They are often feared and reviled by the general populace, as their actions often bring suffering and death to those around them.\n\nEncountering a Death Cultist in a campaign can be a harrowing experience, as they are willing to do whatever it takes to achieve their goals, even if it means sacrificing innocent lives or unleashing powerful undead creatures upon the world. Defeating a Death Cultist requires courage, skill, and a strong sense of morality to stand against their dark influence."}',0,'Monster Manual 2024','','None',8.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b85-8f8f-7eae-b5fa-bcd5245bdef2'::uuid,'Death Dog','NeutralEvil','1 (XP 200; PB +2)',200,2,'Brute','Medium',12,NULL,39,'6d8+12','40 ft.',NULL,NULL,NULL,15,14,14,3,13,6,'{"Stealth": 4, "Perception": 5}','Blinded, Charmed, Deafened, Frightened, Stunned, Unconscious','Darkvision 120 ft., Passive Perception 15','—',2,2,2,1,-2,-4,2,'[]','Habitat: Desert','Monstrosity','','{"value":"Baring its rotting fangs, the Death Dog growls low and menacingly."}','{"value": "In the world of Dungeons and Dragons, Death Dogs are fearsome and grotesque creatures that are often associated with death and decay. They are large, dog-like creatures with two heads, each head possessing razor-sharp teeth and glowing red eyes. Death Dogs are known for their ferocity and their insatiable hunger for flesh, particularly the flesh of living creatures.\n\nDeath Dogs are often found in dark and desolate places, such as graveyards, battlefields, and abandoned ruins. They are believed to be harbingers of death and are said to be able to sense when a creature is near death. Some believe that Death Dogs are actually undead creatures, risen from the grave to serve as guardians of the dead.\n\nIn combat, Death Dogs are ruthless and relentless, using their sharp teeth and powerful jaws to tear apart their enemies. They are also known for their ability to sense fear in their opponents, using this to their advantage in battle.\n\nOverall, Death Dogs are feared and avoided by most creatures, as they are seen as omens of death and destruction. Encountering a Death Dog is often a sign of impending danger and should be approached with caution and extreme care."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b85-a23a-742b-93b1-a508bcaebc22'::uuid,'Death Knight Aspirant','ChaoticEvil','11 (XP 7 200; PB +4)',7200,4,'Brute','Medium',20,NULL,178,'21d8+84','30 ft.',NULL,NULL,NULL,20,10,18,10,12,16,'{}','Necrotic, Poison; Exhaustion, Frightened, Poisoned','Darkvision 120 ft., Passive Perception 11','Abyssal, Common',4,4,5,5,3,0,4,'[]','Habitat: Any','Undead','','{"value":"Driven by ambition, it kneels in solemn reverence before its dark master."}','{"value": "The Death Knight Aspirant is a powerful undead creature that was once a mortal warrior seeking to become a Death Knight. In order to achieve this dark transformation, the warrior made a pact with a powerful evil entity, usually a demon or a lich, in exchange for their eternal servitude.\n\nThe Death Knight Aspirant retains much of their former combat prowess and skills, but they are now consumed by a thirst for power and vengeance. They are clad in dark, intimidating armor and wield a wicked sword imbued with necrotic energy.\n\nThese creatures are often found leading armies of undead or serving as enforcers for dark lords and necromancers. They are driven by a desire to prove themselves worthy of becoming a full-fledged Death Knight, and will stop at nothing to achieve their goal.\n\nEncountering a Death Knight Aspirant is a dangerous proposition, as they are ruthless and relentless in combat. They are immune to most forms of damage and possess powerful necrotic abilities that can drain the life force of their enemies.\n\nIn order to defeat a Death Knight Aspirant, one must be prepared for a brutal and intense battle. They are cunning strategists and skilled warriors, making them formidable opponents for even the most experienced adventurers. Only the bravest and most skilled heroes have a chance of emerging victorious against these fearsome undead warriors."}',0,'Monster Manual 2024','','None',11.0,NULL),
	 ('01990b85-b46f-7994-9f67-63c2e9d965ce'::uuid,'Death Tyrant','LawfulEvil','14 (XP 11 500, or 13 000 in lair; PB +5)',11500,12,'Solo','Large',19,NULL,195,'26d10+52','5 ft.',NULL,NULL,'40 ft.',18,14,14,19,15,19,'{"Perception": 12}','Poison; Charmed, Exhaustion, Paralyzed, Petrified, Poisoned, Prone','Darkvision 120 ft., Passive Perception 22','Deep Speech, Undercommon',7,2,4,7,4,4,5,'[]','Habitat: Underdark','Undead','Beholder','{"value":"Glowing eyes fixate with malevolent intent, casting an eerie shadow on the walls."}','{"value": "In Dungeons and Dragons 5th Edition, the Death Tyrant is a powerful undead creature that is a more powerful version of a Beholder. The Death Tyrant is created when a Beholder reaches the end of its life and its body decays, leaving behind its powerful magical essence which forms into a new, more powerful form. \n\nThe Death Tyrant is a large floating beholder-like creature with a skeletal appearance and glowing red eyes. It has all of the same abilities and powers as a regular Beholder, including its eye rays which can cause various debilitating effects on its enemies. However, the Death Tyrant is even more powerful and dangerous, able to control and command other undead creatures and unleash devastating magical attacks.\n\nThe lore surrounding the Death Tyrant often portrays it as a feared and malevolent creature, ruling over a domain of undead minions and using its powers to terrorize and manipulate those that come near it. Its origins are shrouded in mystery, with some believing that it is a cursed form of punishment for particularly evil Beholders, while others speculate that it is a creation of powerful necromancers seeking to harness the immense magical energies of a Beholder''s essence.\n\nEncountering a Death Tyrant is a daunting and dangerous prospect for adventurers, as they must navigate its deadly eye rays and powerful spells while also contending with its undead minions. Only the bravest and most skilled heroes stand a chance against such a formidable foe."}',0,'Monster Manual 2024','Beholder','None',14.0,13000.0),
	 ('01990b85-c435-7d99-9eae-82cbfc6fc221'::uuid,'Deer','Unaligned','0 (XP 10; PB +2)',10,3,'Skirmisher','Medium',13,NULL,4,'1d8','50 ft.',NULL,NULL,NULL,11,16,11,2,14,5,'{"Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','None',0,3,0,2,-3,-4,2,'[]',NULL,'Beast','','{"value":"Graceful creature bounds effortlessly through the forest, its eyes alert and cautious."}','{"value": "Deer in D&D 5e are typically portrayed as the normal deer found in the real world, but occasionally with magical or supernatural abilities. They are often depicted as peaceful creatures, but can become aggressive if provoked or threatened. In some settings, deer are seen as symbols of grace, beauty, and agility, and are sometimes associated with nature deities or forest spirits.\n\nIn some campaigns, deer may be guardians of sacred forests or gateways to other realms. They may possess the ability to blend into their surroundings with natural camouflage, move swiftly and silently through the forest, or even possess the power of nature magic.\n\nDeer are usually neutral creatures, but can be aligned with good or evil depending on the setting. They are typically not considered dangerous foes on their own, but can be formidable opponents when defending their territory or young.\n\nOverall, deer in D&D 5e are often used to add a touch of realism and natural beauty to the game world, while also providing opportunities for unique encounters and interactions with nature."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b85-f49c-72ad-b0ae-1763b0203178'::uuid,'Deva','LawfulGood','10 (XP 5 900; PB +4)',5900,4,'Leader','Medium',17,NULL,229,'27d8+108','30 ft.',NULL,NULL,'90 ft.',18,18,18,17,20,20,'{"Insight": 9, "Perception": 9}','Charmed, Exhaustion, Frightened','Darkvision 120 ft., Passive Perception 19','All; telepathy 120 ft.',4,4,4,9,9,3,4,'[]','Habitat: Planar (Upper Planes)','Celestial','Angel','{"value":"Radiant wings beat gently as the Deva\u0027s eyes shine with divine purpose."}','{"value": "In Dungeons and Dragons 5th Edition, a Deva is a celestial being that serves as a divine messenger or agent of a god. Devas are typically depicted as tall, beautiful humanoids with radiant skin, glowing eyes, and wings that allow them to fly. They are known for their incredible wisdom, compassion, and purity of spirit.\n\nDevas are often tasked with delivering messages or guidance to mortals on behalf of their deity, and they may also intervene in mortal affairs to protect the innocent or punish the wicked. They are powerful beings with a range of magical abilities, including the ability to heal, cast spells, and smite evil creatures with holy energy.\n\nDespite their benevolent nature, devas are not to be underestimated in combat, as they are formidable opponents with the strength and skill to rival even the most powerful mortal warriors. They are immune to disease and poison, and they have resistance to many types of damage.\n\nIn D&D lore, devas are often associated with the gods of good, such as Bahamut, Pelor, or Moradin, but they may also serve other deities depending on the campaign setting. They are considered to be among the highest-ranking celestial beings in the hierarchy of the divine realms, and they are revered as paragons of virtue and righteousness."}',0,'Monster Manual 2024 (BR)','Angel','Radiant',10.0,NULL),
	 ('01990b86-05c3-7455-ac1c-9c646a8d4bec'::uuid,'Dire Wolf','Unaligned','1 (XP 200; PB +2)',200,2,'Ambusher','Large',14,NULL,22,'3d10+6','50 ft.',NULL,NULL,NULL,17,15,15,3,12,7,'{"Stealth": 4, "Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','None',2,2,3,1,2,4,2,'[]',NULL,'Beast','','{"value":"Jaws snap shut with a thunderous growl, eyes fixed on prey."}','{"value": "Dire wolves are large, aggressive predators that roam the wilderness in search of prey. They are known for their incredible strength and speed, as well as their keen hunting instincts. Dire wolves are often found in packs, working together to bring down larger prey such as elk, moose, or even bears.\n\nIn some regions, dire wolves are seen as symbols of strength and power, and are revered by local tribes as sacred animals. They are often depicted in myths and legends as noble and majestic creatures, embodying the spirit of the wild.\n\nHowever, dire wolves can also be incredibly dangerous to unsuspecting travelers and hunters who wander into their territory. They are known for their ferocity in battle, and will not hesitate to attack anything they perceive as a threat.\n\nIn the world of Dungeons and Dragons, dire wolves are a common sight in the untamed wilderness, and are often encountered by adventurers exploring remote areas. They are formidable opponents in combat, with their powerful bite and razor-sharp claws making them a force to be reckoned with. Only the most skilled and brave adventurers dare to face off against these fearsome predators."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b89-afcc-7f8b-bffd-68c0b2bbd4fd'::uuid,'Frog','Unaligned','0 (XP 10; PB +2)',10,1,'Ambusher','Tiny',11,NULL,1,'1d4-1','20 ft.',NULL,'20 ft.',NULL,1,13,8,1,8,3,'{"Stealth": 3, "Perception": 1}','None','Darkvision 30 ft., Passive Perception 11','None',-1,1,-5,-1,-4,-5,2,'[]',NULL,'Beast','','{"value":"Croaks in a deafening chorus, leaping with surprising speed towards its prey"}','{"value": "Frogs in D&D are typically depicted as small amphibians that can be found in various environments such as forests, swamps, and caves. They are usually non-aggressive creatures, but some species may be poisonous or have other dangerous abilities.\n\nIn some D&D campaigns, frogs may be used as familiars for spellcasters or as companions for druids. They are often associated with water and nature, and may be used as symbols of transformation or rebirth.\n\nIn combat, frogs are generally weak creatures with low hit points and minimal offensive capabilities. They may use their tongues to grab or attack enemies, or they may have abilities related to jumping or camouflage.\n\nOverall, frogs are commonly used as minor creatures in D&D campaigns, but they can add a touch of realism and atmosphere to the game world."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b86-0ce4-75c5-824d-5b13f90680d1'::uuid,'Dire Worg','NeutralEvil','10 (XP 5 900; PB +4)',5900,2,'Skirmisher','Huge',16,NULL,147,'14d12+56','50 ft.',NULL,NULL,NULL,22,14,18,7,16,8,'{"Perception": 11}','None','Darkvision 120 ft., Passive Perception 21','Goblin, Sylvan, Worg',4,6,6,7,-1,-2,4,'[]','Habitat: Forest, Grassland, Hill, Planar (Feywild)','Fey','','{"value":"Jaws snapping, the Dire Worg prowls with predatory eyes gleaming in the darkness."}','{"value": "The Dire Worg is a larger and more ferocious version of the standard worg, a wolf-like creature that is known for its intelligence and pack hunting abilities. The Dire Worg is often found in the wilds, hunting in packs and preying on unsuspecting travelers.\n\nThese creatures are known for their keen senses, sharp teeth, and powerful jaws, making them deadly predators. They are also incredibly fast and agile, able to outrun most prey and easily navigate through rough terrain.\n\nIn terms of lore, the Dire Worg is often seen as a symbol of the untamed wilderness and the dangers that lurk within. They are feared by those who venture into the wilds, knowing that a pack of Dire Worgs could easily overpower them and tear them apart.\n\nSome believe that the Dire Worgs are creatures of darkness, sent by malevolent forces to terrorize the land. Others see them as simply part of the natural order, predators that play a vital role in maintaining the balance of the ecosystem.\n\nOverall, the Dire Worg is a formidable and dangerous creature in the world of Dungeons and Dragons, one that should be approached with caution and respect by any adventurers who encounter them in their travels."}',0,'Monster Manual 2024','','None',10.0,NULL),
	 ('01990b86-4a7a-785c-b525-bc7cb0a0ffab'::uuid,'Djinni','ChaoticGood','11 (XP 7 200; PB +4)',7200,2,'Artillery','Large',17,NULL,218,'19d10+114','30 ft.',NULL,NULL,'90 ft.',21,15,22,15,16,20,'{}','Lightning, Thunder','Darkvision 120 ft., Passive Perception 13','Primordial (Auran)',6,6,5,7,5,2,4,'[]','Habitat: Coastal, Planar (Elemental Plane of Air)','Elemental','Genie','{"value":"Whirls effortlessly through the air, trailing glimmers of sparkling magic"}','{"value": "In the world of Dungeons and Dragons, Djinn are powerful elemental beings that reside in the elemental plane of air. They are known for their immense strength and magical abilities, as well as their ability to grant wishes to those who summon them. Djinn are often depicted as towering figures with blue skin and swirling air around them, resembling a powerful storm.\n\nDjinn are typically neutral beings who are not inherently good or evil, but can be unpredictable and capricious in their actions. They are often bound to serve those who summon them, either through magical means or by striking a bargain. Djinn are known for their love of freedom and independence, and may become resentful or rebellious if forced to serve against their will.\n\nIn combat, Djinn are formidable foes, using their control over air and weather to manipulate the battlefield to their advantage. They can create powerful gusts of wind, summon lightning strikes, and even create tornadoes to devastate their enemies. Djinn are also skilled in the use of magical weapons and can unleash devastating melee attacks with their massive strength.\n\nOverall, Djinn are powerful and enigmatic beings that can be both allies and adversaries to adventurers in the world of Dungeons and Dragons. Their ability to grant wishes and manipulate the forces of nature make them a force to be reckoned with, and encountering a Djinn is sure to lead to an unforgettable and potentially life-changing encounter."}',0,'Monster Manual 2024 (BR)','Genie','None',11.0,NULL),
	 ('01990b86-6ce9-7538-8b44-4c52bf74942d'::uuid,'Doppelganger','TrueNeutral','3 (XP 700; PB +2)',700,4,'Ambusher','Medium',14,NULL,52,'8d8+16','30 ft.',NULL,NULL,NULL,11,18,14,11,12,14,'{"Insight": 3, "Deception": 6}','Charmed','Darkvision 60 ft., Passive Perception 11','Common plus three other languages',2,4,0,1,2,0,2,'[]','Habitat: Underdark, Urban','Monstrosity','','{"value":"Whispers mimic the party\u0027s voices, sending shivers down their spines"}','{"value": "In the world of Dungeons & Dragons, Doppelgangers are shape-shifting humanoid creatures that are often associated with deceit and deception. These creatures have the ability to change their appearance to mimic any humanoid they have seen, allowing them to infiltrate communities and organizations with ease.\n\nDoppelgangers are mysterious beings with unknown origins, leading many to speculate on where they come from and what their true purpose is. Some believe that they were created by powerful wizards or dark gods, while others think they may be extraplanar beings from another realm.\n\nDespite their ability to blend in seamlessly with society, Doppelgangers are often feared and mistrusted due to their reputation for manipulation and betrayal. They are known to take on the identities of important figures in order to sow discord and chaos, or to further their own sinister agendas.\n\nIn combat, Doppelgangers are cunning and resourceful opponents, using their shape-shifting abilities to outmaneuver their enemies and gain the upper hand. They are known for their intelligence and adaptability, making them formidable adversaries for even the most skilled adventurers.\n\nOverall, Doppelgangers are enigmatic and dangerous creatures that embody the idea of the \"double agent\" or \"traitor within.\" Their lore serves as a cautionary tale about the dangers of trusting appearances and the importance of remaining vigilant in a world filled with deception and intrigue."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Dracolich','LawfulEvil','17 (XP 18 000, or 20 000 in lair; PB +6)',18000,12,'Solo','Medium',20,NULL,225,'18d12+108','40 ft.',NULL,NULL,'80 ft.',25,10,23,19,15,21,'{"Stealth": 6, "Perception": 14}','Necrotic, Poison; Charmed, Exhaustion, Frightened, Paralyzed, Poisoned','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 24','Common, Draconic',6,6,7,8,5,4,6,'[]','Habitat: Any','Undead','','{"value":"Spectral eyes glow with malevolent hunger as it exhales icy death upon you."}','{"value": "Dracoliches are powerful undead dragons that have achieved lichdom through a dark ritual. These creatures retain their immense strength, intelligence, and magical abilities from their former draconic selves, but now possess the added power of undeath. Dracoliches are typically created by powerful necromancers or evil dragons seeking to extend their lives and increase their power.\n\nThe process of becoming a dracolich involves the dragon sacrificing its own life force and transferring its essence into a phylactery, which is usually an ornate gem or other object. Once the transformation is complete, the dracolich''s body becomes a lifeless husk, animated by dark magic and bound to the will of its creator.\n\nDracoliches are feared and respected by all who encounter them, as they are incredibly strong and cunning adversaries. They are immune to many forms of damage, possess powerful breath weapons, and can cast a variety of potent spells. Dracoliches are often found ruling over undead armies or guarding ancient tombs and treasure hoards, using their formidable abilities to protect their lairs and further their own dark agendas.\n\nAdventurers who face a dracolich in battle must be prepared for a fierce and deadly fight, as these creatures are not easily defeated. Only the most skilled and courageous heroes have any hope of overcoming a dracolich and putting an end to its reign of terror."}',0,'Monster Manual 2024','','None',17.0,20000.0),
	 ('01990b87-0835-7ab6-b720-c36feed0a1b6'::uuid,'Drider','ChaoticEvil','6 (XP 2 300; PB +3)',2300,4,'Ambusher','Large',19,NULL,123,'13d10+52','30 ft.','30 ft.',NULL,NULL,16,19,18,13,16,12,'{"Stealth": 10, "Perception": 6}','None','Darkvision 120 ft., Passive Perception 16','Elvish, Undercommon',4,4,3,3,1,1,3,'[]','Habitat: Forest, Underdark','Monstrosity','','{"value":"Silken threads dance as it skitters along the webs, eyes gleaming with malice."}','{"value": "A Drider is a monstrous creature that results from a drow undergoing a terrible transformation. When a drow priestess or warrior fails Lolth, the Spider Queen, or defies her in some way, they may be cursed with the transformation into a Drider as punishment. This transformation involves the lower body of the drow being replaced with the abdomen and legs of a giant spider.\n\nDrider are often banished from drow society and forced to live in exile, wandering the Underdark alone or seeking out other creatures to join their twisted community. They are powerful and cunning adversaries, using their dark magic and spider-like abilities to ensnare and entrap their enemies.\n\nDrider are often encountered as guardians of drow strongholds or as leaders of groups of other monstrous creatures in the Underdark. They are feared and respected by other denizens of the dark, as their cruelty and power make them formidable foes.\n\nIn combat, Drider are skilled with both their spider-like abilities and their drow weapons, making them dangerous opponents for even experienced adventurers. They are also known for their ability to spin webs and create traps, using their natural affinity for spiders to their advantage in battle."}',0,'Monster Manual 2024 (BR)','','None',6.0,NULL),
	 ('01990b87-1c3b-77ac-ad69-00351743c641'::uuid,'Druid','TrueNeutral','2 (XP 450; PB +2)',450,1,'Controller','Medium',13,NULL,44,'8d8+8','30 ft.',NULL,NULL,NULL,10,12,13,12,16,11,'{"Nature": 3, "Medicine": 5, "Perception": 5}','None','Passive Perception 15','Common, Druidic, Sylvan',1,1,0,3,0,1,2,'["Studded Leather Armor"]','Habitat: Any','Humanoid','','{"value":"Leaves rustle as the figure raises its arms, commanding nature\u0027s wrath."}','{"value": "In Dungeons & Dragons 5th Edition, Druids are spellcasting nature priests who are deeply connected to the natural world. They revere nature and seek to maintain the balance between civilization and the wilderness. Druids have the ability to shape-shift into various animal forms and call upon the forces of nature to aid them in battle.\n\nDruids are typically found living in secluded forests or jungles, where they commune with the spirits of nature and protect the land from those who would seek to harm it. They are known for their affinity with animals and ability to communicate with them, often using them as allies in battle. Druids also have a deep understanding of herbalism and can create powerful potions and remedies from natural ingredients.\n\nIn combat, Druids can call upon the elements to cast powerful spells that can manipulate the environment, summon creatures to aid them in battle, or heal themselves and their allies. They are versatile spellcasters who can adapt to a variety of situations, making them valuable members of any adventuring party.\n\nOverall, Druids are mystical nature priests who are deeply connected to the natural world and use their powers to protect and preserve it. They are wise and powerful spellcasters who can harness the forces of nature to achieve their goals and uphold the balance of the world."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b87-4af2-7c1c-84bf-6484a78b1613'::uuid,'Dryad','TrueNeutral','1 (XP 200; PB +2)',200,1,'Ambusher','Medium',16,NULL,22,'5d8','30 ft.',NULL,NULL,NULL,10,12,11,14,15,18,'{"Stealth": 5, "Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','Elvish, Sylvan',0,1,0,2,4,2,2,'[]','Habitat: Forest','Fey','','{"value":"Leaves rustle as she steps forward, eyes glowing with ancient wisdom."}','{"value": "\n\n\nIn Dungeons and Dragons 5th Edition, a Dryad is a fey creature that is deeply connected to nature and the forests they inhabit. They are often described as beautiful creatures, with skin that resembles bark and hair that looks like leaves. Dryads are guardians of the forests, and are known to be fiercely protective of their homes.\n\nDryads are said to be bound to a single tree, known as their \"heart tree\", which serves as their home and source of power. If their heart tree is ever harmed or destroyed, the dryad will suffer greatly and may even die.\n\nDespite their beauty, dryads are not to be underestimated in combat. They are skilled archers and spellcasters, and have the ability to charm and manipulate others with their enchanting presence. They are also able to meld into trees and move through the forest with incredible speed and stealth.\n\nIn D&D lore, dryads are often depicted as mysterious and elusive creatures, rarely seen by mortals. They are said to be protectors of the natural world, and will only reveal themselves to those who prove themselves to be true friends of the forest. Those who harm the forest or its inhabitants may find themselves facing the wrath of a vengeful dryad."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b87-8e0b-7f19-ad80-21a95b744504'::uuid,'Earth Elemental','TrueNeutral','5 (XP 1 800; PB +3)',1800,-1,'Brute','Large',17,NULL,147,'14d10+70','30 ft.',NULL,NULL,NULL,20,8,20,5,10,5,'{}','Poison; Exhaustion, Paralyzed, Petrified, Poisoned, Unconscious','Darkvision 60 ft., Tremorsense 60 ft., Passive Perception 10','Primordial (Terran)',5,-1,5,0,-3,-3,3,'[]','Habitat: Mountain, Planar (Elemental Plane of Earth), Underdark','Elemental','','{"value":"Ground rumbles as a towering figure of stone and earth emerges, cracking the earth beneath."}','{"value": "Earth Elementals are powerful creatures formed from the very essence of the earth itself. These massive beings are typically summoned by powerful spellcasters to guard sacred sites, protect valuable treasures, or wreak havoc upon their enemies. \n\nEarth Elementals are known for their immense strength and resilience, as well as their ability to manipulate the earth around them to crush their foes. They are typically slow-moving but relentless in their pursuit of their targets, and their rocky bodies make them incredibly difficult to damage with conventional weapons.\n\nIn some lore, Earth Elementals are said to have a deep connection to the earth itself, making them fiercely protective of natural habitats and landscapes. They are also known to be highly territorial, often attacking intruders who venture too close to their lairs.\n\nOverall, Earth Elementals are fearsome creatures that should not be underestimated in battle. Their elemental powers and connection to the earth make them formidable foes for even the most experienced adventurers."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b87-b9cc-7d5f-b567-769c5919692e'::uuid,'Efreeti','TrueNeutral','11 (XP 7 200; PB +4)',7200,1,'Leader','Large',17,NULL,212,'17d10+119','40 ft.',NULL,NULL,'60 ft.',22,12,24,16,15,19,'{}','Fire','Darkvision 120 ft., Passive Perception 12','Primordial (Ignan)',7,1,6,6,8,3,4,'[]','Habitat: Desert, Planar (Elemental Plane of Fire)','Elemental','Genie','{"value":"Fiery Efreeti dances in the flames, eyes blazing with ancient power."}','{"value": "In the world of Dungeons and Dragons, Efreeti are powerful and cunning genies from the Elemental Plane of Fire. They are known for their fiery red skin, muscular build, and impressive stature. Efreeti are skilled in magic and are often considered to be powerful spellcasters.\n\nEfreeti are known for their love of power and wealth, and they are often encountered making deals with mortals in exchange for granting wishes. However, these wishes often come with a price, and Efreeti are known for their twisted sense of humor and tendency to grant wishes in unexpected and harmful ways.\n\nEfreeti are also known for their fierce loyalty to their rulers, the powerful Efreet sultans who rule over the City of Brass in the Elemental Plane of Fire. They are often found serving as powerful guardians and enforcers in the sultan''s court.\n\nIn combat, Efreeti are formidable opponents, using their fiery powers to burn and destroy their enemies. They are known for their ability to cast powerful fire spells, summon fire elementals, and create walls of fire to trap and damage their foes.\n\nOverall, Efreeti are dangerous and unpredictable creatures, capable of great acts of both benevolence and cruelty. They are a staple of the Dungeons and Dragons universe and are often encountered in high-level campaigns as powerful adversaries or potential allies."}',0,'Monster Manual 2024 (BR)','Genie','None',11.0,NULL),
	 ('01990b87-c81d-7590-ac33-7f246ae31afa'::uuid,'Elemental Cataclysm','ChaoticNeutral','22 (XP 41 000; PB +7)',41000,18,'Solo','Gargantuan',20,NULL,370,'20d20+160','60 ft.',NULL,'80 ft.','80 ft.',26,19,27,9,14,9,'{}','Acid, Cold, Fire, Lightning, Poison, Thunder; Blinded, Charmed, Deafened, Exhaustion, Frightened, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Stunned, Unconscious','Truesight 150 ft., Passive Perception 12','Primordial',15,11,8,9,6,-1,7,'[]','Habitat: Planar (Elemental Chaos)','Elemental','Titan','{"value":"Raging cyclones of fire and lightning crackle and churn within its form."}','{"value": "Elemental Cataclysm is a terrifying and powerful creature in the world of Dungeons and Dragons. It is said to be a being of pure elemental energy, capable of causing massive destruction and chaos wherever it goes.\n\nLegends tell of Elemental Cataclysm being created during a cataclysmic event that involved the merging of multiple elemental planes. As a result, this creature embodies the chaotic and destructive nature of all four elements - fire, water, earth, and air.\n\nElemental Cataclysm is often summoned by powerful spellcasters seeking to wreak havoc on their enemies or bring about the end of the world. Its mere presence can cause earthquakes, tsunamis, volcanic eruptions, and tornadoes, leaving destruction in its wake.\n\nThose who have encountered Elemental Cataclysm and lived to tell the tale speak of its terrifying appearance - a swirling vortex of elemental energy with crackling lightning, scorching flames, freezing ice, and crumbling earth all swirling together in a chaotic dance of destruction.\n\nMany believe that Elemental Cataclysm is a harbinger of doom, a sign that the delicate balance of the elemental planes has been disrupted and that a great catastrophe is imminent. Only the bravest and most powerful adventurers dare to face this creature, knowing that their very lives may be at stake."}',0,'Monster Manual 2024','Titan','None',22.0,NULL),
	 ('01990b87-ea92-773a-b5fc-85622295d11b'::uuid,'Elemental Cultist','ChaoticEvil','8 (XP 3 900; PB +3)',3900,4,'Leader','Medium',16,NULL,135,'18d8+54','30 ft.',NULL,NULL,NULL,18,12,16,14,18,12,'{"Arcana": 5, "Religion": 5, "Perception": 7}','None','Passive Perception 17','Common, Primordial',6,1,4,7,1,2,3,'["Chain Mail"]','Habitat: Any','Humanoid','','{"value":"Cloaked in flames, chanting in an ancient tongue with eyes ablaze."}','{"value": "Elemental Cultists are followers of powerful elemental beings such as genies, elementals, or other elemental creatures. They worship these beings as gods and seek to bring about their will on the material plane. Elemental Cultists are often spellcasters who specialize in elemental magic, using their powers to summon and control elemental creatures, manipulate the elements, and wreak havoc on their enemies.\n\nElemental Cultists are typically found in isolated locations such as remote temples, caves, or elemental planes where they can commune with their elemental patrons undisturbed. They are fiercely loyal to their elemental masters and will stop at nothing to carry out their will.\n\nIn combat, Elemental Cultists are formidable opponents, using their mastery of elemental magic to unleash devastating spells and abilities on their enemies. They can summon powerful elemental creatures to aid them in battle, manipulate the elements to create barriers and obstacles, and unleash destructive elemental attacks on their foes.\n\nOverall, Elemental Cultists are dangerous and fanatical individuals who will stop at nothing to serve their elemental masters and bring about chaos and destruction in their wake. Adventurers should approach them with caution and be prepared for a fierce and magical battle."}',0,'Monster Manual 2024','','None',8.0,NULL),
	 ('01990b87-fb2c-7d05-a534-a523438590ed'::uuid,'Elephant','Unaligned','4 (XP 1,100; PB +2)',1100,1,'Brute','Huge',12,NULL,76,'8d12+24','40 ft.',NULL,NULL,NULL,22,9,17,3,11,6,'{}','None','Passive Perception 10','None',3,1,6,0,2,4,2,'[]',NULL,'Beast','','{"value":"Tusks gleam in the sunlight as it trumpets a warning to intruders"}','{"value": "In the world of Dungeons and Dragons, elephants are majestic creatures known for their immense size, strength, and intelligence. They are often found in the wild, roaming the plains and forests in search of food and water. \n\nElephants are revered by many cultures for their wisdom and power, and are often seen as symbols of strength and endurance. In some societies, elephants are even worshipped as divine beings. \n\nIn combat, elephants are formidable opponents, using their powerful tusks and trunk to gore and crush their enemies. They are known for their fierce loyalty to their herd and will stop at nothing to protect their young. \n\nSome creatures, such as the mammoth or the mastodon, are larger and more fearsome versions of the standard elephant, often found in colder climates or more remote regions. These creatures are even more rare and revered, with some believing them to be ancient beings with connections to the gods themselves. \n\nOverall, elephants are creatures of great importance and significance in the world of Dungeons and Dragons, embodying themes of strength, wisdom, and loyalty."}',0,'Monster Manual 2024 (BR)','','None',4.0,NULL),
	 ('01990b88-3b22-7f80-9ecd-18b80e07b3dd'::uuid,'Empyrean','TrueNeutral','23 (XP 50,000; PB +7)',50000,19,'Solo','Huge',22,NULL,346,'21d12+210','50 ft.',NULL,'50 ft.','50 ft.',30,21,30,21,22,27,'{"Insight": 13, "Perception": 13}','Necrotic, Radiant','Truesight 120 ft., Passive Perception 23','All',10,5,17,13,8,5,7,'[]','Habitat: Any','Celestial or Fiend','Titan','{"value":"Radiant wings shimmer as it gazes upon you with celestial grace and power."}','{"value": "The Empyrean is a powerful celestial being in Dungeons and Dragons 5th Edition. They are often depicted as towering figures of radiant beauty, with shimmering skin and eyes that seem to hold the light of the heavens themselves. Empyreans are said to be the offspring of deities, born from the union of a god and a mortal.\n\nThese beings are known for their incredible strength and wisdom, as well as their ability to wield divine magic with ease. Empyreans are often called upon by gods to serve as their champions in times of great need, leading armies of angels into battle against the forces of darkness.\n\nDespite their divine heritage, Empyreans are not immortal and can be slain like any other creature. However, their deaths are said to be a rare and tragic event, as the loss of such a powerful being is felt across the planes.\n\nIn combat, Empyreans are formidable opponents, wielding powerful weapons and spells to smite their enemies. They are also known for their ability to inspire courage and hope in those around them, rallying allies to stand strong in the face of adversity.\n\nOverall, the Empyrean is a majestic and awe-inspiring creature, embodying the ideals of justice, righteousness, and divine power. They are rare and powerful beings, and encountering one is a sign that great events are unfolding in the world of Dungeons and Dragons."}',0,'Monster Manual 2024','Titan','Bludgeoning, Piercing, Slashing',23.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b88-8404-7707-8fe6-ed71698b280e'::uuid,'Erinyes','LawfulEvil','12 (XP 8 400; PB +4)',8400,7,'Skirmisher','Medium',18,NULL,178,'21d8+84','30 ft.',NULL,NULL,'60 ft.',18,16,18,14,14,18,'{"Perception": 6, "Persuasion": 8}','Fire, Poison; Poisoned','Truesight 120 ft., Passive Perception 16','Infernal; telepathy 120 ft.',8,7,4,2,8,2,4,'[]','Habitat: Planar (Nine Hells)','Fiend','Devil','{"value":"Seductively smirks, twirling its blade with deadly grace."}','{"value": "Erinyes, also known as Furies, are fiendish beings in Dungeons and Dragons that are often depicted as beautiful, winged women with a cruel and vengeful nature. They are typically found in the service of powerful devils or demons, acting as enforcers and punishers in the Nine Hells.\n\nAccording to lore, Erinyes were once mortal women who were wronged or betrayed in life, leading them to seek revenge and ultimately becoming fiends. They are known for their prowess in combat, using their seductive appearance and charm to lure victims before striking with their deadly weapons.\n\nErinyes are often tasked with capturing souls or hunting down enemies of their infernal masters. They are relentless in their pursuit and will stop at nothing to fulfill their duties. Despite their alluring appearance, they are ruthless and unforgiving, embodying the eternal punishment and torment of the Nine Hells.\n\nIn combat, Erinyes are skilled fighters and spellcasters, able to unleash powerful attacks and curses on their foes. They are also capable of flight, making them agile and difficult to pin down in battle.\n\nOverall, Erinyes are feared and respected within the hierarchy of fiends, as they embody both beauty and brutality in equal measure. Crossing paths with an Erinyes is often a dangerous and deadly encounter for any adventurer."}',0,'Monster Manual 2024 (BR)','Devil','Cold',12.0,NULL),
	 ('01990b88-aa7b-7878-91c3-24e32b50f8e9'::uuid,'Ettercap','NeutralEvil','2 (XP 450; PB +2)',450,2,'Ambusher','Medium',13,NULL,44,'8d8+8','30 ft.','30 ft.',NULL,NULL,14,15,13,7,12,8,'{"Stealth": 4, "Survival": 3, "Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','—',1,2,2,1,-1,-2,2,'[]','Habitat: Forest','Monstrosity','','{"value":"Skittering silently, it weaves sticky webs in the shadows, eyes gleaming with malice."}','{"value": "Ettercaps are humanoid spider-like creatures that are commonly found in forests, caves, and other remote areas. They are known for their ability to trap and capture prey using their web-spinning abilities and their sharp claws. Ettercaps are often considered to be cunning and intelligent, using their surroundings to their advantage when hunting for food.\n\nIn some lore, ettercaps are said to be the result of a curse or dark magic, transforming ordinary humans into these monstrous creatures. They are often depicted as solitary beings, preferring to live in isolation away from other creatures.\n\nEttercaps are known to be skilled hunters and are often found in the company of spiders, which they use to help them capture prey. They are also known to be territorial and will fiercely defend their lairs from any intruders.\n\nIn some D&D campaigns, ettercaps are sometimes depicted as allies or servants of more powerful creatures such as drow or driders, using their abilities to aid in their masters'' schemes. They are often seen as a threat to travelers and adventurers who venture into their territory, making them a challenging opponent to face in combat."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b88-beee-70e3-9a11-35ce058d68be'::uuid,'Ettin','ChaoticEvil','4 (XP 1 100; PB +2)',1100,-1,'Brute','Large',12,NULL,85,'10d10+30','40 ft.',NULL,NULL,NULL,21,8,17,6,10,8,'{"Perception": 4}','Blinded, Charmed, Deafened, Frightened, Stunned, Unconscious','Darkvision 60 ft., Passive Perception 14','Giant',3,-1,5,0,-1,-2,2,'["Battleaxe", "Morningstar"]','Habitat: Hill, Mountain, Underdark','Giant','','{"value":"Twin heads bicker and snarl, each eyeing the party with malice."}','{"value": "In Dungeons and Dragons 5th Edition, the Ettin is a large, two-headed giant that is known for its brutish and violent nature. Ettins are typically found in mountainous regions or other remote areas where they can live in solitude and prey on unsuspecting travelers.\n\nAccording to lore, Ettins are believed to be the result of a curse placed upon giants by a powerful deity. The curse split the giants into two separate beings, each with its own head and personality. This duality often leads to conflicting desires and actions, making Ettins unpredictable and dangerous opponents.\n\nEttins are known for their savage strength and ferocity in battle, wielding large weapons and using their brute force to overpower their enemies. They are also known for their lack of intelligence and cunning, relying on brute force and sheer aggression to get what they want.\n\nDespite their violent nature, some Ettins can be persuaded to work with or even befriend other creatures, particularly if they are offered food or treasure in exchange. However, these alliances are often short-lived, as the Ettin''s volatile nature can quickly turn against its newfound allies.\n\nOverall, Ettins are fearsome and formidable creatures that are best avoided by those who value their lives. Their unpredictable nature and savage strength make them a dangerous threat to any who cross their path."}',0,'Monster Manual 2024 (BR)','','None',4.0,NULL),
	 ('01990b88-c6ec-7810-81f1-9e125bb7324f'::uuid,'Faerie Dragon Adult','ChaoticGood','2 (XP 450; PB +2)',450,5,'Skirmisher','Tiny',15,NULL,35,'10d4+10','10 ft.',NULL,NULL,'60 ft.',3,20,13,12,12,14,'{"Arcana": 4, "Stealth": 7, "Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','Draconic, Sylvan; telepathy 60 ft. (faerie dragons only)',1,5,-4,1,2,1,2,'[]','Habitat: Forest','Dragon','','{"value":"Gleaming wings shimmer in the sunlight as it playfully flits through the trees."}','{"value": "Faerie Dragons are mischievous and playful creatures that are known for their love of pranks and tricks. They are small, winged dragons with shimmering scales that come in a variety of pastel colors. Despite their small size, Faerie Dragons are powerful spellcasters and are able to use their magic to create illusions and manipulate their surroundings.\n\nAdult Faerie Dragons are more powerful than their younger counterparts and are known for their intelligence and cunning. They are able to cast a variety of spells, including invisibility and confusion, and are skilled at using their illusions to confuse and trick their enemies. Adult Faerie Dragons are also known for their ability to communicate telepathically with other creatures, allowing them to easily manipulate and influence those around them.\n\nIn the world of D&D, Faerie Dragons are often found living in deep forests or secluded areas, where they use their magic to protect their homes from intruders. While they are generally peaceful creatures, Faerie Dragons are not afraid to use their magic to defend themselves if they feel threatened. Players who encounter an Adult Faerie Dragon should be wary of its illusions and tricks, as they are known for their ability to outsmart even the most skilled adventurers."}',0,'Monster Manual 2024','','None',2.0,NULL),
	 ('01990b88-eaff-7fce-88c0-89be6fc5901a'::uuid,'Fiend Cultist','NeutralEvil','8 (XP 3 900; PB +3)',3900,5,'Leader','Medium',16,NULL,127,'17d8+51','30 ft.',NULL,NULL,NULL,19,15,16,12,18,10,'{"Religion": 4, "Perception": 7}','None','Darkvision 90 ft. (unimpeded by magical Darkness), Passive Perception 17','Abyssal, Common, Infernal',6,2,4,7,0,1,3,'["Breastplate"]','Habitat: Any','Humanoid','','{"value":"Its eyes glow with fervor as it chants an infernal hymn, surrounded by swirling shadows."}','{"value": "Fiend Cultists are mortals who have dedicated themselves to serving powerful fiends, such as demons or devils, in exchange for dark powers and forbidden knowledge. These cultists are often drawn to the darkness and corruption of the fiends, believing that by serving them, they can gain power and influence in the world.\n\nFiend Cultists are typically found in hidden temples or secret societies, where they perform dark rituals and ceremonies to summon and commune with their fiendish masters. They may also work to spread chaos and destruction in the mortal realm, carrying out their masters'' sinister plans.\n\nIn combat, Fiend Cultists are skilled spellcasters, using dark magic and curses to weaken and harm their enemies. They may also summon lesser fiends to aid them in battle, adding an extra layer of danger to their already formidable abilities.\n\nOverall, Fiend Cultists are dangerous adversaries, as they are willing to do whatever it takes to further their dark agendas and serve their fiendish masters. It is up to brave adventurers to stop them and prevent the spread of their malevolent influence."}',0,'Monster Manual 2024','','None',8.0,NULL),
	 ('01990b89-0b5c-7bff-8495-099b3ceb1e8a'::uuid,'Fire Elemental','TrueNeutral','5 (XP 1,800; PB +3)',1800,3,'Artillery','Large',13,NULL,93,'11d10+33','50 ft.',NULL,NULL,NULL,10,17,16,6,10,7,'{}','Fire, Poison; Exhaustion, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Darkvision 60 ft., Passive Perception 10','Primordial (Ignan)',3,3,0,0,-2,-2,3,'[]','Habitat: Desert, Planar (Elemental Plane of Fire)','Elemental','','{"value":"Flames dance and crackle, heat radiating in waves from its smoldering form."}','{"value": "Fire Elementals are powerful creatures from the Elemental Plane of Fire. They are beings composed entirely of living flames, with a humanoid shape that flickers and shifts constantly. Fire Elementals are highly destructive and unpredictable, as they are driven by an insatiable hunger for destruction and chaos.\n\nThese creatures are often summoned by powerful spellcasters to do their bidding, wreaking havoc on their enemies with their fiery attacks. Fire Elementals are immune to fire damage and can set objects and creatures ablaze with a touch. They are particularly vulnerable to cold-based attacks, which can weaken and extinguish their flames.\n\nFire Elementals are not inherently evil, but their destructive nature often leads them to cause harm to those around them. They are fiercely independent and difficult to control, making them a dangerous ally or enemy in any encounter. Those who seek to harness the power of Fire Elementals must be prepared to handle their wild and fiery temperament."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',5.0,NULL),
	 ('01990b89-29a6-7954-bfdd-8dffd6d1705e'::uuid,'Flameskull','NeutralEvil','4 (XP 1 100; PB +2)',1100,3,'Artillery','Tiny',13,NULL,40,'9d4+18','5 ft.',NULL,NULL,'40 ft.',1,17,14,16,10,11,'{"Arcana": 5, "Perception": 2}','Fire, Necrotic, Poison; Charmed, Exhaustion, Frightened, Paralyzed, Poisoned, Prone','Darkvision 60 ft., Passive Perception 12','Common plus two other languages',2,3,-5,0,0,3,2,'[]','Habitat: Underdark','Undead','','{"value":"Fiery eyes burn with malevolent glee, cackling as it conjures deadly flames."}','{"value": "The Flameskull is a powerful undead creature that can be found in dungeons, ancient ruins, and other dark places. It is created when a powerful spellcaster''s spirit is bound to a skull through a dark ritual, granting it immortality and powerful magical abilities.\n\nFlameskulls are often used as guardians or protectors by those who seek to safeguard their treasures or secrets. They are known for their ability to cast powerful fire spells, such as fireball and firebolt, and can also use their fiery gaze to cause fear in their enemies.\n\nDespite their fearsome appearance and abilities, Flameskulls are intelligent creatures and can be reasoned with or bargained with if approached carefully. However, they are often driven by a desire for power and may be easily tempted by promises of greater magical knowledge or artifacts.\n\nIn combat, Flameskulls are highly dangerous opponents, using their magical abilities to weaken and defeat their enemies. They are resistant to many types of damage and can only be permanently destroyed by destroying their skull, making them a persistent threat to any adventurers who encounter them."}',0,'Monster Manual 2024','','None',4.0,NULL),
	 ('01990b89-4e73-72ac-aa87-ff8511543a7b'::uuid,'Flaming Skeleton','LawfulEvil','3 (XP 700; PB +2)',700,2,'Brute','Medium',15,NULL,65,'10d8+20','30 ft.',NULL,NULL,NULL,10,14,15,10,15,8,'{}','Fire, Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 12','Understands Common plus one other language but can''t speak',2,2,0,2,-1,0,2,'[]','Habitat: Planar (Shadowfell), Underdark, Urban','Undead','','{"value":"Bones crackle and blaze as it advances, leaving fiery footprints in its wake."}','{"value": "Flaming Skeletons are undead creatures that are created when a normal skeleton is exposed to intense heat or fire. The flames that engulf their bones give them a fiery appearance and make them much more dangerous than their non-flaming counterparts.\n\nThese creatures are often found in areas of extreme heat, such as volcanoes, deserts, or areas that have been recently ravaged by fire. They are typically created by powerful necromancers or dark sorcerers who use them as guards or servants to protect their lairs.\n\nFlaming Skeletons are immune to fire damage and can set their enemies ablaze with their fiery touch. They are relentless and will stop at nothing to destroy any living creature that crosses their path. Their burning bones also make them incredibly resistant to physical attacks, making them a formidable foe for any adventuring party.\n\nTo defeat a Flaming Skeleton, adventurers must use tactics that do not rely on fire or physical attacks. Cold-based spells or weapons are particularly effective against them, as are spells that target their undead nature. Overall, Flaming Skeletons are a dangerous and fearsome enemy that should not be underestimated."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01990b89-7002-7e74-ba06-44c5687a3ddd'::uuid,'Flesh Golem','TrueNeutral','5 (XP 1 800; PB +3)',1800,-1,'Brute','Medium',9,NULL,127,'15d8+60',NULL,NULL,NULL,NULL,19,9,18,6,10,5,'{}','Lightning, Poison; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned','Darkvision 60 ft., Passive Perception 10','Understands Common plus one other language but can''t speak',4,-1,4,0,-3,-2,3,'[]','Habitat: Any','Construct','','{"value":"It lumbers forward, groaning and dripping with oozing, necrotic flesh."}','{"value": "Flesh Golems are monstrous constructs created from various body parts and pieces of flesh stitched together to form a hulking and grotesque creature. They are typically created by powerful necromancers or mad scientists who seek to create a powerful and obedient servant.\n\nFlesh Golems are known for their immense strength and durability, as well as their mindless obedience to their creators. They are often used as guards or enforcers, and are capable of following simple commands given to them by their master.\n\nDespite their monstrous appearance, Flesh Golems are not inherently evil creatures. They lack intelligence and free will, and simply exist to serve their creator. However, if left unchecked or mistreated, a Flesh Golem can become a dangerous and uncontrollable force of destruction.\n\nIn combat, Flesh Golems rely on their sheer brute strength and resilience to overpower their foes. They are immune to many types of damage, and can shrug off even the most powerful attacks. However, they are vulnerable to certain types of magic, such as fire and lightning, which can quickly weaken and disable them.\n\nOverall, Flesh Golems are terrifying creatures that inspire fear and awe in those who encounter them. They are a testament to the twisted ingenuity of those who seek to harness the power of life and death for their own dark purposes."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b8c-df73-7037-ab0d-ec4f3bd90684'::uuid,'Gibbering Mouther','ChaoticNeutral','2 (XP 450; PB +2)',450,-1,'Controller','Medium',9,NULL,52,'7d8+21','20 ft.',NULL,'20 ft.',NULL,10,8,16,3,10,6,'{}','Prone','Darkvision 60 ft., Passive Perception 10','—',3,-1,0,0,-2,-4,2,'[]','Habitat: Underdark','Aberration','','{"value":"Whispering, gibbering mouths writhe and drool, hungering for the flesh of the living."}','{"value": "The Gibbering Mouther is a grotesque and chaotic creature that is said to have originated from the Far Realm, a place of madness and incomprehensible cosmic horrors. It is a mass of writhing, gibbering mouths and eyes that constantly mutter and babble incoherently.\n\nThe Gibbering Mouther is known to wander the dark and desolate places of the world, driven by a never-ending hunger for flesh and the desire to spread madness and confusion wherever it goes. Its mere presence can drive those who gaze upon it mad, as its babbling and gibbering voices can twist the mind and sow chaos.\n\nThe origins of the Gibbering Mouther are shrouded in mystery, but some believe it to be a creation of dark and malevolent magic, while others think it to be a manifestation of the madness and chaos of the Far Realm itself. Whatever its true origins may be, the Gibbering Mouther is a fearsome and dangerous creature that should be approached with caution and avoided at all costs."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b89-cca5-77fe-b8e6-5ae7eeab20fb'::uuid,'Galeb Duhr','TrueNeutral','6 (XP 2 300; PB +3)',2300,2,'Soldier','Medium',16,NULL,123,'13d8+65','15 ft.',NULL,NULL,NULL,20,14,20,11,12,11,'{}','Poison; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned','Darkvision 60 ft., Tremorsense 60 ft., Passive Perception 11','Primordial (Terran)',5,2,5,1,0,0,3,'[]','Habitat: Hill, Mountain','Elemental','','{"value":"Eyes gleam with ancient wisdom as it shifts and melds with the earth."}','{"value": "In Dungeons and Dragons 5th Edition, a Galeb Duhr is a large, earth elemental creature that resembles a humanoid made entirely of rock. These creatures are known for their immense strength and durability, as well as their ability to manipulate earth and stone to their advantage.\n\nGaleb Duhrs are often found in mountainous regions or deep underground, where they make their homes in caves or tunnels. They are fiercely protective of their territory and will attack any intruders that they perceive as a threat.\n\nDespite their aggressive nature, Galeb Duhrs are not inherently evil and can be reasoned with, especially if one shows respect for their domain. They are often sought out by miners and adventurers for their ability to locate valuable minerals and gems within the earth.\n\nIn combat, Galeb Duhrs are formidable opponents, using their immense strength to crush enemies with their rocky fists and hurling boulders with deadly accuracy. They can also merge with the earth itself, becoming nearly impervious to damage and surprising unsuspecting foes.\n\nOverall, Galeb Duhrs are fascinating creatures with a deep connection to the earth, making them both formidable foes and potential allies in the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','None',6.0,NULL),
	 ('01990b89-e1e8-7d85-a572-f717ecbf551e'::uuid,'Gargoyle','ChaoticEvil','2 (XP 450; PB +2)',450,2,'Skirmisher','Medium',15,NULL,67,'9d8+27','30 ft.',NULL,NULL,'60 ft.',15,11,16,6,11,7,'{"Stealth": 4}','Poison; Exhaustion, Petrified, Poisoned','Darkvision 60 ft., Passive Perception 10','Primordial (Terran)',3,0,2,0,-2,-2,2,'[]','Habitat: Underdark, Urban','Elemental','','{"value":"Wings unfurl with a menacing creak, eyes glowing in the darkness"}','{"value": "In Dungeons and Dragons 5th edition, gargoyles are stone creatures that are often used as guardians or protectors of ancient ruins or buildings. They are typically depicted as grotesque, winged creatures with sharp claws and fangs. Gargoyles are known for their ability to blend in with stone structures, making them difficult to spot until they come to life and attack.\n\nGargoyles are typically neutral evil in alignment, and they are fiercely territorial creatures that will attack anyone who intrudes on their territory. They are also known for their ability to turn to stone at will, making them even more difficult to defeat in combat. Gargoyles are often found in groups, and they are highly intelligent creatures that are capable of working together to outsmart their enemies.\n\nIn terms of combat, gargoyles are known for their powerful attacks and ability to fly. They are skilled in melee combat, using their claws and fangs to tear apart their enemies. They are also known for their ability to petrify their opponents with a touch, turning them to stone.\n\nOverall, gargoyles are formidable foes that should not be underestimated in a D&D campaign. Their ability to blend in with their surroundings and their deadly combat skills make them a challenging opponent for any group of adventurers."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b8a-0abd-725b-835e-43eefe91db05'::uuid,'Gelatinous Cube','Unaligned','2 (XP 450; PB+2)',450,-4,'Ambusher','Large',6,NULL,63,'6d10+30','15 ft.',NULL,NULL,NULL,14,3,20,1,6,1,'{}','Acid; Blinded, Charmed, Deafened, Exhaustion, Frightened, Prone','Blindsight 60 ft., Passive Perception 8','None',5,-4,2,-2,-5,-5,2,'[]','Habitat: Underdark','Ooze','','{"value":"It oozes forward, leaving a trail of dissolved debris in its wake."}','{"value": "The Gelatinous Cube is a unique and mysterious monster in the world of Dungeons and Dragons. It is a large, transparent cube-shaped creature that lurks in dark dungeons and caves, blending in with its surroundings due to its semi-translucent body. The Gelatinous Cube is known for its ability to dissolve and digest any organic matter that comes into contact with it, making it a dangerous predator for unwary adventurers.\n\nAccording to lore, Gelatinous Cubes are thought to have originated from the Elemental Plane of Water, where they were created by powerful water elementals as guardians of their domains. Over time, some of these cubes have found their way into the Material Plane, where they now roam freely in search of prey.\n\nDespite their seemingly simple appearance, Gelatinous Cubes are actually quite intelligent creatures. They are capable of setting traps and luring in unsuspecting victims before engulfing them in their acidic body. Some even say that Gelatinous Cubes possess a primitive form of telepathy, allowing them to communicate with each other and coordinate their attacks.\n\nOverall, the Gelatinous Cube is a fearsome and enigmatic monster that poses a significant threat to any adventurer who dares to venture into its domain. Its ability to dissolve flesh and bone with ease makes it a formidable adversary that should not be underestimated."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b8a-28b2-7cb4-bd51-8b6608b3196f'::uuid,'Ghast Gravecaller','ChaoticEvil','6 (XP 2 300; PB +3)',2300,3,'Ambusher','Medium',16,NULL,97,'15d8+30','30 ft.',NULL,NULL,NULL,16,17,14,18,14,8,'{}','Necrotic, Poison; Charmed, Exhaustion, Poisoned','Darkvision 120 ft., Passive Perception 12','Abyssal, Common',5,3,3,5,-1,4,3,'[]','Habitat: Swamp, Underdark, Urban','Undead','','{"value":"Spectral hands rise from the ground at its eerie command, beckoning death\u0027s embrace."}','{"value": "Ghast Gravecallers are a terrifying undead creature that haunts graveyards and other places of death. These creatures were once humanoids who died in a particularly violent or traumatic way, causing them to rise again as a ghast. However, unlike regular ghasts, Gravecallers have the ability to summon and control other undead creatures to do their bidding.\n\nGhast Gravecallers are known for their ability to communicate with the dead and can often be found performing dark rituals in graveyards to raise more undead minions. They are typically found leading groups of ghouls, zombies, and other undead creatures, using their necromantic powers to control and direct them in battle.\n\nThese creatures are particularly dangerous because of their ability to raise fallen enemies as undead minions to fight for them. They are also skilled in dark magic and can cast spells that drain the life force of their enemies, making them even more formidable opponents.\n\nOverall, Ghast Gravecallers are a terrifying and powerful foe, capable of commanding legions of undead and striking fear into the hearts of those who dare to cross their path."}',0,'Monster Manual 2024','','None',6.0,NULL),
	 ('01990b8a-5613-7d52-980e-7b704db2fa2a'::uuid,'Ghost','TrueNeutral','4 (XP 1 100; PB +2)',1100,1,'Ambusher','Medium',11,NULL,45,'10d8','5 ft.',NULL,NULL,'40 ft.',7,13,10,10,12,17,'{}','Necrotic, Poison; Charmed, Exhaustion, Frightened, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained','Darkvision 60 ft., Passive Perception 11','Common plus one other language',0,1,-2,1,3,0,2,'[]','Habitat: Underdark, Urban','Undead','','{"value":"Whispers echo through the room as a translucent figure floats silently towards you"}','{"value": "Ghosts are the spectral remnants of creatures who have died a tragic or violent death, or who have unfinished business in the mortal realm. They are typically bound to the location of their death or the object that holds significance to them, and are unable to move on to the afterlife until they have resolved whatever is keeping them tethered to the material plane.\n\nGhosts are known for their ability to phase through solid objects, making them difficult to harm with physical attacks. They can also possess the bodies of living creatures, controlling their actions and using them to further their own goals. In combat, ghosts can drain the life force from their victims, weakening and eventually killing them.\n\nSome ghosts are vengeful spirits, seeking to exact revenge on those who wronged them in life. Others are simply lost souls, searching for closure or redemption before they can move on. Regardless of their motivations, encountering a ghost is a harrowing experience, as they are powerful and malevolent beings that can cause great harm to those who cross their path."}',0,'Monster Manual 2024 (BR)','','Acid, Bludgeoning, Cold, Fire, Lightning, Piercing, Slashing, Thunder',4.0,NULL),
	 ('01990b8a-8d35-72d8-9650-d5dacb0691f5'::uuid,'Giant Ape','Unaligned','7 (XP 2 900; PB +3)',2900,5,'Brute','Huge',12,NULL,168,'16d12+64','40 ft.','40 ft.',NULL,NULL,23,14,18,5,12,7,'{"Survival": 4, "Athletics": 9, "Perception": 4}','None','Passive Perception 14','None',4,2,6,1,-2,-3,3,'[]',NULL,'Beast','','{"value":"Roaring deafens you as the enormous creature pounds its chest in challenge."}','{"value": "Giant Apes are massive creatures that resemble their smaller primate cousins but are much larger and more powerful. They are typically found in dense jungles or forests, where they live in small family groups and feed on a diet of fruits, leaves, and small animals.\n\nGiant Apes are known for their incredible strength and agility, able to easily overpower most foes with their powerful fists and sharp teeth. They are also quite intelligent, capable of problem-solving and even using tools to aid in their hunting and gathering.\n\nDespite their formidable appearance, Giant Apes are typically peaceful creatures and will only become aggressive if provoked or threatened. They are also known to be fiercely protective of their young, and will defend them at all costs.\n\nIn some cultures, Giant Apes are revered as symbols of strength and wisdom, and are sometimes even worshipped as divine beings. However, they are also hunted by some for their valuable fur and meat, leading to conflicts between humans and these powerful creatures."}',0,'Monster Manual 2024 (BR)','','None',7.0,NULL),
	 ('01990b8a-8df9-7c95-a3e9-0825353ba014'::uuid,'Giant Axe Beak','Unaligned','5 (XP 1 800; PB +3)',1800,5,'Skirmisher','Huge',15,NULL,84,'8d12+32','50 ft.',NULL,NULL,NULL,21,14,19,3,12,5,'{"Perception": 4}','None','Passive Perception 14','—',4,2,5,1,-3,-4,3,'[]','Habitat: Arctic, Grassland, Hill','Monstrosity','','{"value":"Feathers bristle as it lets out a deafening screech, eyeing you hungrily."}','{"value": "The Giant Axe Beak is a formidable creature that resembles a giant bird with razor-sharp beak and talons. These creatures are known for their aggressive nature and are often used by hunters and warriors as mounts due to their speed and ferocity in battle.\n\nIn the lore of Dungeons and Dragons, Giant Axe Beaks are native to the wild and untamed regions of the world, often found in forests, mountains, and other remote areas. They are known for their keen senses and can detect prey from great distances, making them excellent hunters.\n\nLegends say that Giant Axe Beaks were once created by ancient druids who imbued them with magical powers to serve as guardians of the natural world. Over time, however, these creatures have become more wild and unpredictable, often attacking anything that comes too close to their territory.\n\nDespite their aggressive nature, some adventurers and warriors seek to tame and train Giant Axe Beaks, using them as mounts in battle or for hunting dangerous creatures. Those who are successful in taming these creatures often find them to be loyal companions and powerful allies in combat.\n\nOverall, the Giant Axe Beak is a fearsome and majestic creature that commands respect in the world of Dungeons and Dragons, and encountering one in the wild can be both thrilling and dangerous."}',0,'Monster Manual 2024','','None',5.0,NULL),
	 ('01990b92-3118-7524-920e-92fee241c8ed'::uuid,'Lacedon Ghoul','ChaoticEvil','1 (XP 200; PB +2)',200,2,'Ambusher','Medium',12,NULL,22,'5d8','30 ft.',NULL,'30 ft.',NULL,13,15,10,7,10,6,'{}','Poison; Charmed, Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 10','Common',0,2,1,0,-2,-2,2,'[]','Habitat: Swamp, Underdark, Urban','Undead','','{"value":"Flesh drips from its gnashing teeth as it hungrily eyes its next victim."}','{"value": "Lacedon Ghouls are undead creatures that were once sailors or maritime travelers who met a watery grave. These creatures are fueled by an insatiable hunger for flesh and are known for their ability to swim swiftly through water. Lacedon Ghouls are often found lurking near shorelines, shipwrecks, or other bodies of water where they can easily ambush unsuspecting victims.\n\nIn combat, Lacedon Ghouls use their sharp claws and teeth to tear into their prey, often overwhelming them with their sheer numbers. They are known for their ability to paralyze their victims with a touch, making it easier for them to feed on their flesh.\n\nLacedon Ghouls are typically created by a powerful undead creature or necromancer, who may use them as minions to do their bidding. They are feared by sailors and coastal communities, who know to beware of their presence and take precautions to avoid falling victim to their ravenous hunger."}',0,'Monster Manual 2024','','Cold',1.0,NULL),
	 ('01990b8a-b210-78bb-bae8-1c38b3fba28e'::uuid,'Giant Boar','Unaligned','2 (XP 450; PB +2)',450,0,'Brute','Large',13,NULL,42,'5d10+15','40 ft.',NULL,NULL,NULL,17,10,16,2,7,5,'{}','None','Passive Perception 8','None',3,0,5,-2,-3,-4,2,'[]',NULL,'Beast','','{"value":"Snorting loudly, it lowers its massive tusks and charges towards you."}','{"value": "Giant Boars are massive, aggressive creatures that roam the forests and woodlands of the world. These creatures are known for their immense size, with some reaching up to 10 feet in length and weighing over 1,000 pounds. Giant Boars have powerful tusks and hooves, making them formidable opponents in battle.\n\nIn some cultures, Giant Boars are seen as symbols of strength and ferocity, often revered as sacred creatures. In other cultures, they are feared and avoided due to their aggressive nature and destructive tendencies. Giant Boars are known to be skilled hunters and will often attack anything that enters their territory, including other creatures and even humans.\n\nLegends and stories often depict Giant Boars as guardians of the forests, protecting the land from intruders and threats. Some tales tell of brave adventurers who have tamed these creatures and ridden them into battle, using their strength and ferocity to overcome their enemies.\n\nOverall, Giant Boars are creatures to be respected and approached with caution, as they are powerful and dangerous beasts that should not be underestimated."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b8a-d417-74a0-9ea5-c548485ccaa1'::uuid,'Giant Constrictor Snake','Unaligned','2 (XP 450; PB +2)',450,2,'Brute','Huge',12,NULL,60,'8d12+8','30 ft.',NULL,'30 ft.',NULL,19,14,12,1,10,3,'{"Perception": 2}','None','Blindsight 10 ft., Passive Perception 12','None',1,2,4,0,-4,-5,2,'[]',NULL,'Beast','','{"value":"Its massive coils writhe and tighten, squeezing the life out of its prey."}','{"value": "The Giant Constrictor Snake is a massive serpent known for its incredible strength and deadly coils. These creatures can grow up to 60 feet in length and are often found in dense jungles or swamps where they hunt for prey. \n\nGiant Constrictor Snakes are ambush predators, using their camouflage and stealth to surprise their victims. They rely on their powerful muscles to constrict and crush their prey before swallowing it whole. Despite their size, they are surprisingly fast and agile, able to strike with lightning speed.\n\nIn some cultures, Giant Constrictor Snakes are revered as symbols of strength and power, while in others they are feared as deadly predators. They are often used as guardians or pets by powerful individuals and are sometimes even worshiped as divine beings.\n\nAdventurers must approach Giant Constrictor Snakes with extreme caution, as their immense strength and deadly coils can easily overwhelm even the most skilled warriors. It is said that only the bravest and most skilled adventurers can hope to defeat a Giant Constrictor Snake and emerge victorious."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b8a-9b78-71e3-9665-c9bd8e175c6f'::uuid,'Giant Bat','Unaligned','1/4 (XP 50; PB +2)',50,3,'Skirmisher','Large',13,NULL,22,'4d10','10 ft.',NULL,NULL,'60 ft.',15,16,11,2,12,6,'{}','None','Blindsight 120 ft., Passive Perception 11','None',0,3,2,1,-2,-4,2,'[]',NULL,'Beast','','{"value":"Wings beat rhythmically, casting eerie shadows in the moonlight"}','{"value": "In the world of Dungeons and Dragons, giant bats are terrifying creatures that lurk in dark caves and forests. These massive bats have a wingspan of up to 15 feet and are known for their keen senses and ability to navigate through darkness with echolocation.\n\nGiant bats are nocturnal hunters, using their sharp fangs and powerful wings to swoop down on unsuspecting prey. They are highly agile and can easily outmaneuver their opponents in the air. Giant bats are often used by evil creatures such as vampires or necromancers as mounts or guardians.\n\nDespite their fearsome reputation, giant bats are not inherently evil. They are simply creatures of instinct, driven by their need to feed and survive. However, they are easily provoked and will attack anything that threatens them or their territory.\n\nAdventurers who encounter giant bats must be cautious, as these creatures can be formidable opponents. They are resistant to non-magical attacks and can quickly overwhelm their enemies with their speed and agility. Only the most skilled and prepared adventurers stand a chance against these fearsome creatures."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b8c-ed57-7759-90da-3465da45ad6a'::uuid,'Githzerai Monk','LawfulNeutral','2 (XP 450; PB +2)',450,4,'Skirmisher','Medium',14,NULL,38,'7d8+7','40 ft.',NULL,NULL,NULL,12,15,12,13,14,10,'{"Insight": 4, "Perception": 4}','None','Passive Perception 14','Common, Gith',1,4,3,4,0,3,2,'[]','Habitat: Planar (Limbo)','Aberration','Gith','{"value":"Fluidly dodges, eyes ablaze with focused determination and unyielding discipline"}','{"value": "The Githzerai are a race of humanoid creatures who were once enslaved by the mind flayers, but eventually rebelled and gained their freedom. The Githzerai are a highly disciplined and philosophical people, known for their mastery of psionics and martial arts.\n\nGithzerai monks are particularly revered among their people for their exceptional skill in combat and their deep connection to the spiritual plane. They are known for their ability to manipulate ki energy to enhance their physical abilities and perform incredible feats of agility and strength.\n\nGithzerai monks are typically solitary individuals who spend much of their time in meditation and training, seeking to perfect their martial arts and unlock the full potential of their psionic abilities. They are often found living in remote monasteries or wandering the world in search of enlightenment.\n\nIn combat, Githzerai monks are deadly opponents, using their speed and agility to outmaneuver their enemies and strike with precision and power. They are known for their ability to anticipate their opponents'' moves and react with lightning-fast reflexes, making them formidable adversaries on the battlefield.\n\nOverall, Githzerai monks are highly respected and feared throughout the world for their unparalleled skill in combat and their deep spiritual wisdom."}',0,'Monster Manual 2024','Gith','None',2.0,NULL),
	 ('01990b8c-f007-76b9-b495-0d1b63d40a97'::uuid,'Githzerai Psion','LawfulNeutral','12 (XP 8 400; PB +4)',8400,8,'Controller','Medium',18,NULL,169,'26d8+52','40 ft.',NULL,NULL,'40 ft.',12,18,15,19,18,14,'{"Arcana": 8, "Insight": 8, "Perception": 8}','None','Passive Perception 18','Common, Gith',2,8,5,8,2,8,4,'[]','Habitat: Planar (Limbo)','Aberration','Gith','{"value":"Mind crackles with psychic energy, eyes glowing with otherworldly power."}','{"value": "The Githzerai Psion is a powerful and enigmatic creature that is part of the Githzerai race, a group of highly disciplined and psychic individuals who reside in the chaotic and ever-shifting plane known as Limbo. The Githzerai Psion is a master of psionic abilities, using their mental powers to manipulate the world around them and bend reality to their will.\n\nThese creatures are highly intelligent and possess a deep understanding of the mysteries of the universe. They are able to harness their psychic energy to cast powerful spells and create potent illusions, making them formidable opponents in battle. The Githzerai Psion is also known for their stoic demeanor and unwavering determination, making them a force to be reckoned with on the battlefield.\n\nIn Githzerai society, Psions are revered and respected for their mastery of psychic powers and their ability to channel the raw energy of the universe. They often serve as advisors and mentors to younger Githzerai, passing down their knowledge and wisdom to the next generation.\n\nOverall, the Githzerai Psion is a complex and intriguing creature, embodying the fusion of psychic power and discipline that defines the Githzerai race. They are a force to be reckoned with in the world of Dungeons and Dragons, and encountering one in battle is sure to be a challenging and memorable experience."}',0,'Monster Manual 2024','Gith','None',12.0,NULL),
	 ('01990b8c-f473-7fda-91a2-43febb2b674b'::uuid,'Githzerai Zerth','LawfulNeutral','6 (XP 2 300; PB +3)',2300,7,'Skirmisher','Medium',17,NULL,84,'13d8+26','40 ft.',NULL,NULL,NULL,13,18,15,16,17,12,'{"Arcana": 6, "Insight": 6, "Perception": 6}','None','Passive Perception 16','Common, Gith',2,7,4,6,1,6,3,'[]','Habitat: Planar (Limbo)','Aberration','Gith','{"value":"Intense eyes blaze with psychic energy, projecting an aura of calm determination."}','{"value": "The Githzerai Zerth is a powerful and mysterious creature in the world of Dungeons and Dragons. They are members of the Githzerai race, a reclusive and highly disciplined people who reside in the chaotic and ever-changing plane of Limbo.\n\nZerths are elite warriors and monks among the Githzerai, known for their incredible combat skills and mastery of psionic abilities. They are highly skilled in martial arts and are able to manipulate the very fabric of reality with their psionic powers.\n\nZerths are often tasked with guarding important Githzerai strongholds and artifacts, as well as leading military campaigns against their eternal enemies, the Githyanki. They are fiercely loyal to their people and will stop at nothing to protect them from harm.\n\nIn combat, Zerths are incredibly agile and can move with blinding speed, striking their enemies with deadly precision. They are also able to unleash devastating psionic attacks, manipulating the minds of their foes and bending them to their will.\n\nOverall, the Githzerai Zerth is a formidable and enigmatic creature, feared and respected by all who know of their existence."}',0,'Monster Manual 2024','Gith','None',6.0,NULL),
	 ('01990b8d-1930-7da2-acf1-a57bd76f452c'::uuid,'Glabrezu','ChaoticEvil','9 (XP 5 000; PB +4)',5000,6,'Brute','Large',17,NULL,189,'18d10+90','40 ft.',NULL,NULL,NULL,20,15,21,19,17,16,'{"Deception": 7, "Perception": 7}','Poison; Poisoned','Truesight 120 ft., Passive Perception 17','Abyssal; telepathy 120 ft.',9,2,9,7,7,4,4,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Its eyes gleam with malevolent intelligence as it cracks its knuckles menacingly."}','{"value": "The Glabrezu is a powerful demon that appears in the Dungeons and Dragons fifth edition Monster Manual. They are known for their deceptive and manipulative nature, often using their shape-shifting abilities to trick and manipulate mortals. Glabrezus are also known for their immense strength and magical abilities, making them formidable opponents in combat.\n\nIn D&D lore, Glabrezus are often summoned by dark sorcerers or cultists to carry out their bidding. They are considered to be extremely dangerous and are usually only summoned as a last resort due to the risks involved in dealing with such a powerful and unpredictable creature.\n\nGlabrezus are said to hail from the Abyss, the chaotic and evil plane of existence in the D&D universe. They are often depicted as towering, demonic beings with crab-like pincers and a humanoid body. Despite their fearsome appearance, Glabrezus are known to be cunning and intelligent, using their powers of illusion and manipulation to get what they want.\n\nOverall, Glabrezus are a terrifying and formidable foe in the world of Dungeons and Dragons, capable of outsmarting even the most seasoned adventurers with their devious tactics and powerful abilities."}',0,'Monster Manual 2024 (BR)','Demon','Cold, Fire, Lightning',9.0,NULL),
	 ('01990b8d-3bd1-77dd-b27f-69eef1de8394'::uuid,'Gladiator','TrueNeutral','5 (XP 1 800; PB +3)',1800,5,'Brute','Medium',16,NULL,112,'15d8+45','30 ft.',NULL,NULL,NULL,18,15,16,10,12,15,'{"Athletics": 10, "Performance": 5}','None','Passive Perception 11','Common',6,5,7,4,2,0,3,'["Shield", "Spears (3)", "Studded Leather Armor"]','Habitat: Any','Humanoid','','{"value":"Roaring triumphantly, it pounds its chest before charging into battle."}','{"value": "In the world of Dungeons and Dragons, the Gladiator is a fierce and skilled warrior who is trained to fight in arenas for the entertainment of spectators. They are typically armed with a sword and shield, and are known for their impressive combat skills and ability to entertain crowds with their fighting prowess.\n\nGladiators often come from different backgrounds, ranging from former soldiers and mercenaries to slaves and criminals who have been forced into the arena. They are trained in various combat techniques and fighting styles, making them formidable opponents in battle.\n\nIn some D&D campaigns, Gladiators may also be part of a larger organization or fighting guild, where they compete in tournaments and battles for fame, glory, and riches. They are often depicted as honorable and courageous warriors who are willing to risk their lives for the thrill of combat.\n\nOverall, Gladiators are iconic figures in the world of D&D, representing the thrill of battle and the courage of those who face their enemies head-on in the arena."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b8d-4128-733e-bac3-4b5bcc5ba67f'::uuid,'Gnoll Fang of Yeenoghu','ChaoticEvil','4 (XP 1 100; PB +2)',1100,4,'Soldier','Medium',14,NULL,71,'11d8+22','30 ft.',NULL,NULL,NULL,17,15,15,10,11,13,'{}','None','Darkvision 60 ft., Passive Perception 10','Abyssal, Gnoll',4,2,3,2,3,0,2,'[]','Habitat: Desert, Forest, Grassland, Hill','Fiend','','{"value":"Jaws dripping with blood, it snarls and lunges forward, eyes ablaze with hunger."}','{"value": "The Gnoll Fang of Yeenoghu is a powerful and terrifying creature in the world of Dungeons and Dragons. Yeenoghu is the demon lord of gnolls, and the Fangs are his most elite and feared followers. These monstrous creatures are larger and more savage than regular gnolls, with razor-sharp teeth and claws that can tear through flesh and bone with ease.\n\nGnoll Fangs are known for their brutality and cruelty, often leading packs of gnolls on raids and hunts to satisfy their insatiable hunger for blood and carnage. They are also skilled in dark magic, able to summon demons and cast spells that can inflict pain and suffering on their enemies.\n\nIn battle, Gnoll Fangs are relentless and ferocious, fighting with a primal rage that makes them incredibly dangerous foes. They are also cunning and strategic, using their intelligence to outwit and outmaneuver their opponents.\n\nOverall, the Gnoll Fang of Yeenoghu is a truly terrifying monster that strikes fear into the hearts of all who encounter it. Its presence signals death and destruction, as it is a merciless killer driven by the insatiable hunger of its dark master, Yeenoghu."}',0,'Monster Manual 2024','','None',4.0,NULL),
	 ('01990b8d-42f9-7eeb-a138-99b956395b60'::uuid,'Gnoll Pack Lord','ChaoticEvil','2 (XP 450; PB +2)',450,4,'Leader','Medium',15,NULL,49,'9d8+9','30 ft.',NULL,NULL,NULL,16,14,13,8,11,9,'{}','None','Darkvision 60 ft., Passive Perception 10','Gnoll',1,2,3,0,-1,-1,2,'[]','Habitat: Desert, Forest, Grassland, Hill','Fiend','','{"value":"Roaring triumphantly, the Gnoll Pack Lord brandishes its blood-stained flail."}','{"value": "In the world of Dungeons and Dragons, Gnolls are a savage and bloodthirsty race of hyena-like humanoids who are known for their brutal and merciless nature. Gnolls are often found in packs, roaming the wilderness in search of prey to hunt and pillage. \n\nThe Gnoll Pack Lord is a powerful and cunning leader among their kind, commanding respect and fear from their fellow gnolls. They are often larger and stronger than regular gnolls, with a more developed sense of strategy and tactics. The Pack Lord is responsible for organizing raids, leading hunts, and maintaining order within the pack. \n\nGnoll Pack Lords are typically chosen through displays of strength and cunning, often through deadly combat with other aspiring leaders. Once they have established themselves as the dominant force within their pack, they will stop at nothing to maintain their power and control. \n\nIn combat, Gnoll Pack Lords are formidable opponents, using their superior strength and speed to overpower their enemies. They are often accompanied by a pack of loyal gnolls who will follow their orders without question. Their ferocity in battle, combined with their strategic mind, makes them a deadly adversary for any adventurers who cross their path."}',0,'Monster Manual 2024','','None',2.0,NULL),
	 ('01990b8d-6d2d-7ba1-b4d8-790c05291d6e'::uuid,'Goat','Unaligned','0 (XP 10; PB +2)',10,0,'Ambusher','Medium',10,NULL,4,'1d8','40 ft.','30 ft.',NULL,NULL,11,10,11,2,10,5,'{"Perception": 2}','None','Darkvision 60 ft., Passive Perception 12','None',0,0,2,0,-3,-4,2,'[]',NULL,'Beast','','{"value":"Bleats loudly, eyes glowing with a hunger that seems almost human."}','{"value": "In Dungeons and Dragons 5th Edition, the goat is a common farm animal that can also be found in the wild. They are typically docile creatures that are known for their sure-footedness and ability to climb steep terrain. In the game, goats are often used as pack animals or sources of milk and meat for adventurers traveling through rural areas.\n\nHowever, in some D&D campaigns, goats can take on a more ominous or magical role. Some cultures believe that goats are sacred animals, associated with fertility and the harvest. In these cases, goats may be protected by powerful nature spirits or deities, and harming a goat could incur their wrath.\n\nIn certain regions, goats may also be seen as symbols of trickery and mischief, due to their mischievous behavior and ability to escape from enclosures. In these cases, goats may be associated with trickster gods or fey creatures, and encountering a goat in the wild could lead to unexpected and potentially dangerous encounters.\n\nOverall, the lore of the goat in D&D is largely based on its real-world characteristics and cultural associations, but can also be influenced by the unique world-building and storytelling of individual campaigns."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b8d-92cf-78ce-9f4e-e70b7c13ac31'::uuid,'Goblin Boss','ChaoticNeutral','1 (XP 200; PB +2)',200,2,'Leader','Small',17,NULL,21,'6d6','30 ft.',NULL,NULL,NULL,10,15,10,10,8,10,'{"Stealth": 6}','None','Darkvision 60 ft., Passive Perception 9','Common, Goblin',0,2,0,-1,0,0,2,'["Chain Shirt", "Scimitar", "Shield", "Shortbow"]','Habitat: Forest, Grassland, Hill, Planar (Acheron, Feywild), Underdark','Fey','Goblinoid','{"value":"Leader snarls, brandishing a jagged blade, eyes gleaming with malice."}','{"value": "Goblin Bosses are typically larger and more powerful goblins who have managed to rise to a position of leadership within their tribe. They are often cunning and ruthless, using their strength and intelligence to maintain control over their fellow goblins. Goblin Bosses are known for their ability to rally other goblins to their cause, leading them into battle and coordinating their attacks with skill and precision.\n\nIn some cases, Goblin Bosses may have acquired their position through sheer brute force, while in others they may have used their wits and cunning to outmaneuver their rivals. Regardless of how they came to power, Goblin Bosses are generally feared and respected by their followers, who view them as powerful and charismatic leaders.\n\nIn combat, Goblin Bosses are formidable opponents, using their strength and agility to outmaneuver their enemies. They are skilled in the use of weapons and are able to coordinate attacks with their fellow goblins to overwhelm their foes. Despite their small size, Goblin Bosses are known for their ferocity and tenacity in battle, and they will stop at nothing to achieve victory and maintain their position of power within their tribe."}',0,'Monster Manual 2024 (BR)','Goblinoid','None',1.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b8d-d975-7b5c-9783-57cd638e5f74'::uuid,'Gold Dragon Wyrmling','LawfulGood','3 (XP 700; PB +2)',700,4,'Solo','Medium',17,NULL,60,'8d8+24','30 ft.',NULL,'30 ft.','60 ft.',19,14,17,14,11,16,'{"Stealth": 4, "Perception": 4}','Fire','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Draconic',3,4,4,2,3,2,2,'[]','Habitat: Forest, Grassland','Dragon','Metallic','{"value":"Wyrmling gleams brightly, playful and curious, wings fluttering with youthful exuberance."}','{"value": "Gold dragons are known for their wisdom, kindness, and sense of justice. They are one of the most powerful and noble creatures in the dragon hierarchy. Gold dragons often take on the role of protectors and guardians, using their breath weapon of fire to defend those they care about.\n\nGold dragon wyrmlings are young gold dragons, still growing and learning about the world around them. Despite their young age, they are already wise beyond their years and possess a strong sense of righteousness. They are fiercely loyal to their allies and will go to great lengths to protect them.\n\nGold dragon wyrmlings are known for their radiant golden scales, which shine like the sun. They are often seen as symbols of hope and prosperity, bringing light and warmth wherever they go. They are also skilled in combat, using their sharp claws and powerful jaws to defend themselves and their loved ones.\n\nIn D&D 5e, gold dragon wyrmlings are typically encountered as guardians of ancient treasures or important locations. They are intelligent and can communicate with other creatures, making them valuable allies in the fight against evil. Players who befriend a gold dragon wyrmling may find a powerful and loyal companion to aid them on their adventures."}',0,'Monster Manual 2024 (BR)','Metallic','None',3.0,NULL),
	 ('01990b8d-ecc4-77f9-88c3-d988fd1b66b7'::uuid,'Gorgon','Unaligned','5 (XP 1 800; PB +3)',1800,0,'Brute','Large',19,NULL,114,'12d10+48','40 ft.',NULL,NULL,NULL,20,11,18,2,12,7,'{"Perception": 7}','Exhaustion, Petrified','Darkvision 60 ft., Passive Perception 17','—',4,0,5,1,-2,-4,3,'[]','Habitat: Forest, Grassland, Hill','Construct','','{"value":"Eyes glinting, it snorts and stamps, sending up clouds of dust and stone chips."}','{"value": "In Dungeons and Dragons 5th edition, the Gorgon is a fearsome creature that resembles a massive, metallic bull with sharp horns and a petrifying gaze. According to lore, Gorgons are said to be cursed creatures, created by a powerful deity as punishment for their arrogance and vanity.\n\nGorgons are known for their ability to turn creatures to stone with a single gaze, making them incredibly dangerous adversaries. They are often found in remote, rocky areas where they can roam freely and hunt for prey. Gorgons are highly territorial and will fiercely defend their territory from intruders.\n\nDespite their fearsome reputation, Gorgons are not inherently evil creatures. Some are known to form bonds with other creatures, such as druids or rangers, who can tame and train them as loyal mounts or guardians. However, these relationships are rare and often fraught with danger, as Gorgons can be unpredictable and prone to bouts of aggression.\n\nOverall, Gorgons are powerful and formidable monsters that should not be underestimated by adventurers venturing into their territory. Their petrifying gaze and fierce attacks make them a deadly threat that requires careful planning and strategy to defeat."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b8d-f274-75ab-8d42-9a3aa12726a3'::uuid,'Goristro','ChaoticEvil','17 (XP 18 000; PB +6)',18000,6,'Brute','Huge',19,NULL,310,'23d12+161','50 ft.',NULL,NULL,NULL,25,11,25,6,13,14,'{"Survival": 7, "Perception": 7}','Poison; Poisoned','Darkvision 120 ft., Passive Perception 17','Abyssal',13,6,13,7,2,-2,6,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Roaring, it charges forward, shaking the ground with its massive hooves."}','{"value": "Goristros are massive, brutish creatures that serve as powerful enforcers and warriors in the armies of demons. They are often summoned to the material plane by powerful spellcasters to wreak havoc and destruction. Goristros are known for their incredible strength and ferocity in battle, as well as their ability to charge at opponents with incredible speed.\n\nIn terms of their origins, Goristros are believed to be the twisted result of a demon''s experimentation and manipulation of powerful magic. They are said to have been created from the souls of particularly violent and bloodthirsty individuals, twisted and transformed into hulking beasts with a burning desire to destroy and conquer.\n\nGoristros are often found in the service of demon lords and other powerful evil entities, acting as their loyal and fearsome servants. They are feared and respected by other demons for their sheer power and destructive capabilities, making them formidable opponents in battle.\n\nOverall, Goristros are creatures of chaos and destruction, embodying the brutal and savage nature of demons in the world of Dungeons and Dragons. They are a terrifying force to be reckoned with, capable of causing widespread devastation and carnage wherever they go."}',0,'Monster Manual 2024','Demon','Cold, Fire, Lightning',17.0,NULL),
	 ('01990b8e-201c-7d0c-a5e3-468259efa82a'::uuid,'Gray Slaad','ChaoticNeutral','9 (XP 5 000; PB +4)',5000,7,'Brute','Medium',18,NULL,150,'20d8+60','40 ft.',NULL,NULL,NULL,19,17,16,13,8,18,'{"Arcana": 5, "Perception": 7}','None','Blindsight 60 ft., Darkvision 60 ft., Passive Perception 17','Common, Slaad; telepathy 60 ft.',3,3,4,-1,4,1,4,'[]','Habitat: Planar (Limbo)','Aberration','','{"value":"Eyes flash with malevolent glee as it readies to unleash chaotic magic."}','{"value": "Gray Slaads are powerful extraplanar creatures that are known for their chaotic and destructive nature. They are native to the plane of Limbo, a chaotic and ever-changing realm where order and logic hold little sway.\n\nGray Slaads are large, frog-like creatures with mottled gray skin and sharp claws. They have the ability to infect other creatures with their tadpoles, which eventually transform into new Slaads. This process is often fatal to the host, as the tadpole consumes them from the inside out.\n\nGray Slaads are known for their aggressive and unpredictable behavior, often attacking anything in their path without warning. They are also highly intelligent and capable of using magic, making them even more dangerous foes.\n\nIn the world of Dungeons and Dragons, Gray Slaads are often used as powerful minions by more powerful beings, such as demon lords or powerful spellcasters. They are also sometimes summoned by cultists or other dark forces to wreak havoc and chaos upon the world.\n\nOverall, Gray Slaads are fearsome and dangerous creatures that should not be taken lightly by any adventurers brave enough to face them."}',0,'Monster Manual 2024','','Acid, Cold, Fire, Lightning, Thunder',9.0,NULL),
	 ('01990b8e-3809-787f-a678-76156f563f91'::uuid,'Green Dragon Wyrmling','LawfulEvil','2 (XP 450; PB +2)',450,3,'Ambusher','Medium',17,NULL,38,'7d8+7','30 ft.',NULL,'30 ft.','60 ft.',15,12,13,14,11,13,'{"Stealth": 3, "Perception": 4}','Poison; Poisoned','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Draconic',1,3,2,2,1,2,2,'[]','Habitat: Forest','Dragon','Chromatic','{"value":"Eyes gleaming with malice, it coils its serpentine body in preparation to strike."}','{"value": "Green dragons are known for their cunning and deceptive nature. They are master manipulators and are able to easily trick and deceive others to get what they want. Green dragon wyrmlings are the youngest of their kind and are already highly intelligent and skilled in the art of deception.\n\nGreen dragon wyrmlings are typically found in dense forests or swamps, where they can easily blend in with their surroundings. They are solitary creatures and prefer to live alone, only seeking out the company of other dragons during mating season.\n\nDespite their young age, green dragon wyrmlings are already formidable opponents in combat. They are able to breathe a powerful cone of poisonous gas that can incapacitate their enemies, and they are skilled in aerial combat, using their wings to outmaneuver their foes.\n\nGreen dragon wyrmlings are also known for their hoarding tendencies, collecting vast amounts of treasure and magical items in their lairs. They are fiercely protective of their hoards and will go to great lengths to defend them from intruders.\n\nOverall, green dragon wyrmlings are clever and dangerous adversaries, using their intelligence and deception to outwit their enemies and protect their treasures."}',0,'Monster Manual 2024 (BR)','Chromatic','None',2.0,NULL),
	 ('01990b8e-595e-7c24-b57f-98f71a97da4a'::uuid,'Green Hag','NeutralEvil','3 (XP 700; PB +2)',700,1,'Ambusher','Medium',17,NULL,82,'11d8+33','30 ft.',NULL,'30 ft.',NULL,18,12,16,13,14,14,'{"Arcana": 5, "Stealth": 3, "Deception": 4, "Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','Common, Elvish, Sylvan',3,1,4,2,2,1,2,'[]','Habitat: Forest, Hill, Swamp','Fey','','{"value":"Cackling fiercely, she dances through the swamp, eyes gleaming with mischief."}','{"value": "In Dungeons & Dragons 5th edition, a Green Hag is a powerful and malevolent fey creature known for their cunning and deceitful nature. They are often found living in secluded swamps, forests, or other remote areas, where they use their magical abilities to manipulate and terrorize unsuspecting travelers.\n\nGreen Hags are skilled in the arts of illusion and enchantment, allowing them to cast spells that can confuse and bewitch their victims. They are also known for their ability to shape-shift, taking on different forms to deceive and lure in their prey.\n\nThese creatures are often depicted as twisted and grotesque, with long, warty noses and sharp, yellow teeth. Their skin is typically a sickly shade of green, giving them their name. Despite their repulsive appearance, Green Hags are incredibly dangerous foes, capable of causing great harm to those who cross their path.\n\nIn D&D lore, Green Hags are often portrayed as members of a coven, working together with other hags to further their sinister goals. They are said to have a deep connection to the natural world and are known to hold grudges against those who despoil or disrespect the land.\n\nOverall, Green Hags are a formidable and fearsome adversary in the world of Dungeons & Dragons, with a reputation for cunning and treachery that makes them a dangerous foe for any adventurer to face."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b8e-6790-7fc4-b1a1-6c232b55350c'::uuid,'Grell','NeutralEvil','3 (XP 700; PB +2)',700,6,'Skirmisher','Medium',12,NULL,55,'10d8+10','10 ft.',NULL,NULL,'30 ft.',15,14,13,12,11,9,'{"Stealth": 6, "Perception": 4}','Lightning; Blinded, Prone','Blindsight 60 ft., Passive Perception 14','Deep Speech',1,2,2,0,-1,1,2,'[]','Habitat: Underdark','Aberration','','{"value":"Tendrils writhe eagerly, reaching out to ensnare unsuspecting prey"}','{"value": "The Grell is a bizarre and dangerous aberration that resembles a floating brain with a beak and tentacles. They are solitary creatures that lurk in underground or dark places, using their telepathic abilities to hunt for prey. Grells are highly intelligent and possess a cruel and sadistic nature.\n\nAccording to some legends, Grells were created by a powerful wizard experimenting with dark magic, while others believe they are the result of a failed summoning ritual gone wrong. Regardless of their origins, Grells are feared by many adventurers for their deadly attacks and ability to incapacitate their victims with their tentacles.\n\nGrells are known to be territorial creatures, fiercely defending their lairs from intruders. They are also known to be highly adaptable, able to survive in a variety of environments. Some reports even suggest that Grells have been encountered in the depths of the Underdark, where they have formed alliances with other denizens of the dark.\n\nIn combat, Grells use their sharp beaks and powerful tentacles to attack their enemies, often swooping down from above to surprise their prey. They are also capable of using their telekinetic abilities to manipulate objects and creatures, making them even more dangerous opponents.\n\nOverall, Grells are mysterious and enigmatic creatures that inspire fear and fascination in those who encounter them. Their origins and motivations remain a mystery, adding to their mystique as one of the most dangerous monsters in the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01990b8e-7889-73ae-b813-6bbee41db610'::uuid,'Grick','Unaligned','2 (XP 450; PB +2)',450,2,'Ambusher','Medium',14,NULL,54,'12d8','30 ft.','30 ft.',NULL,NULL,14,14,11,3,14,5,'{"Stealth": 4}','None','Darkvision 60 ft., Passive Perception 12','—',0,2,2,2,-3,-4,2,'[]','Habitat: Forest, Underdark','Aberration','','{"value":"Slithering silently, its tentacles writhe hungrily towards you."}','{"value": "The Grick is a strange and mysterious creature that lurks in dark caves and underground tunnels. It resembles a strange blend of a giant worm and a squid, with a long, serpentine body and a beaked mouth lined with sharp teeth. Its skin is tough and leathery, providing it with protection from its enemies.\n\nGricks are solitary creatures that are highly territorial and aggressive. They hunt by sensing vibrations in the ground and using their tentacles to grab and crush their prey. They are known for their stealth and ability to blend into their surroundings, making them formidable predators.\n\nIn some cultures, Gricks are believed to be servants of dark gods or powerful sorcerers, and they are often used as guardians for hidden temples or treasure troves. Others see them as simply dangerous monsters to be avoided at all costs.\n\nOverall, Gricks are feared and respected by those who know of their existence, and encountering one is often a harrowing experience for adventurers brave enough to venture into their lairs."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b8e-795c-7479-adb4-695fb7913704'::uuid,'Grick Ancient','Unaligned','7 (XP 2 900; PB +3)',2900,3,'Ambusher','Large',18,NULL,135,'18d10+36','30 ft.','30 ft.',NULL,NULL,18,16,15,4,14,9,'{"Stealth": 6}','None','Darkvision 60 ft., Passive Perception 12','—',2,3,4,2,-1,-3,3,'[]','Habitat: Forest, Underdark','Aberration','','{"value":"Slithering silently, it coils and strikes with lightning speed."}','{"value": "Grick Ancients are incredibly rare and powerful creatures that are said to be the ancient ancestors of the more common Grick. These creatures are massive in size, with long tentacles and sharp beaks that they use to hunt and kill their prey. They are known for their incredible strength and agility, able to move swiftly and silently through their underground lairs.\n\nGrick Ancients are said to be incredibly intelligent, often using cunning tactics and strategies to outsmart their enemies. They are also rumored to possess powerful magical abilities, allowing them to cast spells and manipulate the elements to their advantage.\n\nLegends say that Grick Ancients were once revered as gods by ancient civilizations, who would offer sacrifices to appease these fearsome creatures. However, over time, their numbers dwindled and they became little more than a rare and terrifying myth.\n\nEncountering a Grick Ancient is said to be a harrowing experience, as these creatures are known to be vicious and relentless in their pursuit of prey. Those who survive an encounter with a Grick Ancient are considered incredibly fortunate, as few are able to escape the clutches of these ancient and powerful monsters."}',0,'Monster Manual 2024','','None',7.0,NULL),
	 ('01990b8e-aef9-7471-9d42-724f70b0219e'::uuid,'Guard Captain','TrueNeutral','4 (XP 1,100; PB +2)',1100,4,'Soldier','Medium',18,NULL,75,'10d8+30','30 ft.',NULL,NULL,NULL,18,14,16,12,14,13,'{"Athletics": 6, "Perception": 4}','None','Passive Perception 14','Common',3,2,4,2,1,1,2,'["Breastplate", "Javelins (6)", "Longsword", "Shield"]','Habitat: Any','Humanoid','','{"value":"Its eyes narrow with authority as it barks orders to the soldiers."}','{"value": "Guard Captains are experienced and skilled warriors who have risen through the ranks of the city guard to lead their fellow guardsmen. They are often chosen for their leadership abilities, tactical skills, and ability to inspire loyalty in their troops. Guard Captains are responsible for maintaining order and protecting the citizens of their city, as well as enforcing the laws and regulations set forth by the ruling authorities.\n\nIn combat, Guard Captains are formidable opponents, wielding a combination of martial skill and strategic thinking. They are typically equipped with heavy armor, a shield, and a sturdy weapon such as a sword or spear. Guard Captains are trained to be versatile fighters, capable of adapting to a variety of situations and working effectively in a team.\n\nGuard Captains are also known for their strong sense of duty and honor, often putting the needs of their city and their comrades before their own. They are respected and admired by their fellow guardsmen, who look to them for guidance and leadership in times of crisis.\n\nOverall, Guard Captains are stalwart defenders of their city, willing to put themselves in harm''s way to protect the innocent and uphold the law. They are a crucial part of the city guard and play a vital role in maintaining peace and order in the realm."}',0,'Monster Manual 2024 (BR)','','None',4.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b8e-c90d-72f1-ba92-d76fdfcad08e'::uuid,'Guardian Naga','LawfulGood','10 (XP 5 900; PB +4)',5900,4,'Solo','Large',18,NULL,136,'16d10+48','40 ft.','40 ft.','40 ft.',NULL,19,18,16,16,19,18,'{"Arcana": 11, "History": 11, "Religion": 11}','Poison; Charmed, Paralyzed, Poisoned, Restrained','Darkvision 60 ft., Passive Perception 14','Celestial, Common',7,8,4,8,8,7,4,'[]','Habitat: Desert, Forest, Planar (Upper Planes)','Celestial','','{"value":"Scales shimmer as it gracefully coils around the ancient ruins, eyes glowing with wisdom."}','{"value": "Guardian Nagas are powerful and wise serpent-like creatures that are known for their protective nature. They are often found dwelling in ancient ruins, temples, or other sacred places, where they act as guardians and protectors of the area. \n\nGuardian Nagas are highly intelligent and possess innate magical abilities, including the ability to shape-shift into humanoid form. They are also skilled in both combat and magic, making them formidable opponents for any who would seek to desecrate the places they guard.\n\nIn addition to their role as protectors, Guardian Nagas are also known for their wisdom and knowledge. They are often sought out by adventurers and scholars for their insights and guidance, as they have a deep understanding of the history and lore of the lands they inhabit.\n\nDespite their noble nature, Guardian Nagas can be fierce and ruthless when provoked or threatened. They will not hesitate to use their formidable powers to defend the places and people under their care. Overall, Guardian Nagas are revered and respected creatures, seen as both powerful allies and formidable adversaries in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','','None',10.0,NULL),
	 ('01990b8e-d167-74e6-a122-38e3448f6f7e'::uuid,'Gulthias Blight','NeutralEvil','16 (XP 15 000; PB +5)',15000,5,'Brute','Gargantuan',20,NULL,264,'16d20+96','50 ft.',NULL,NULL,NULL,25,10,22,10,18,12,'{"Perception": 9}','Deafened','Blindsight 120 ft., Passive Perception 19','Common, Druidic',6,0,7,4,1,0,5,'[]','Habitat: Forest','Plant','','{"value":"Leaves rustle ominously as the Gulthias Blight\u0027s tendrils writhe and reach out."}','{"value": "The Gulthias Blight is a creature created by the corruption of a Gulthias tree, a malevolent plant that feeds on blood and spreads decay. The origins of the Gulthias tree are shrouded in mystery, but it is believed to have been created through dark magic or the influence of a powerful evil entity. The tree''s roots spread deep into the earth, drawing nutrients from the blood of its victims and corrupting the land around it.\n\nThe Gulthias Blight is a manifestation of the tree''s corruption, a twisted and malevolent being that seeks to spread its influence and bring death and decay to all it encounters. It is often accompanied by swarms of blighted creatures, such as blighted wolves or rats, which serve as its minions and help it in its quest to spread destruction.\n\nThose who come into contact with the Gulthias Blight risk becoming infected by its dark magic, which can turn them into mindless servants or even transform them into grotesque, plant-like creatures themselves. The Gulthias Blight is a formidable foe, capable of unleashing powerful spells and attacks that can devastate even the strongest of adventurers.\n\nThe only way to truly defeat the Gulthias Blight is to destroy the Gulthias tree from which it was spawned. This is no easy task, as the tree is usually well protected and guarded by the Blight''s minions. However, if the tree is destroyed, the Gulthias Blight will wither and die, and the land it has corrupted will slowly begin to heal."}',0,'Monster Manual 2024','','Fire, Necrotic',16.0,NULL),
	 ('01990b8f-0490-7030-9356-6df675c87d33'::uuid,'Harpy','ChaoticEvil','1 (XP 200; PB +2)',200,1,'Ambusher','Medium',11,NULL,38,'7d8+7','20 ft.',NULL,NULL,'40 ft.',12,13,12,7,10,13,'{}','None','Passive Perception 10','Common',1,1,1,0,1,-2,2,'[]','Habitat: Coastal, Forest, Hill, Mountain','Monstrosity','','{"value":"Siren\u0027s song echoes, luring prey with haunting melody and piercing cries."}','{"value": "Harpies are monstrous creatures that are often depicted as half-woman, half-bird. They are known for their beautiful faces and bodies, but their lower halves are that of a large bird, typically an eagle or vulture. Harpies are known for their seductive voices and songs, which they use to lure unsuspecting travelers to their deaths.\n\nIn D&D 5e, harpies are chaotic evil creatures that are often found in mountainous regions or near bodies of water. They are scavengers and predators, preying on any creature they can catch, including humans. Harpies are known for their ability to fly and their sharp talons, which they use to attack their prey.\n\nHarpies are often seen as a symbol of temptation and destruction in D&D lore, as they use their beauty and song to lead travelers astray and ultimately to their doom. They are typically encountered in small groups, known as flocks, and are considered a dangerous threat to adventurers exploring their territories.\n\nOverall, harpies are fearsome and dangerous creatures that are best avoided by those who wish to stay alive in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b8f-38a2-7353-b761-9b95700e93d8'::uuid,'Haunting Revenant','TrueNeutral','10 (XP 5,900; PB +4)',5900,5,'Solo','Gargantuan',20,NULL,203,'14d20+56','30 ft.',NULL,NULL,NULL,20,12,18,16,18,20,'{}','Poison; Charmed, Exhaustion, Frightened, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Truesight 60 ft., Passive Perception 14','Common plus two other languages',8,1,5,8,5,3,4,'[]','Habitat: Forest, Swamp, Urban','Undead','','{"value":"It drifts silently, its ethereal form flickering with an otherworldly glow."}','{"value": "The Haunting Revenant is a spectral undead creature that is bound to the material plane by a powerful curse or unfinished business. It is often the vengeful spirit of someone who was wronged in life and seeks retribution against those who have crossed them.\n\nThe Haunting Revenant has a ghostly appearance, with tattered robes and a pale, ethereal glow. It is capable of phasing through walls and objects, making it difficult to escape its wrath. It is also known for its ability to possess the minds of its victims, driving them to madness or compelling them to carry out its bidding.\n\nIn combat, the Haunting Revenant uses its ghostly powers to drain the life force of its enemies, weakening them and bolstering its own strength. It can also unleash chilling screams that paralyze and terrify those who hear it.\n\nThose who encounter a Haunting Revenant should approach with caution, as they are relentless in their pursuit of vengeance and will stop at nothing to achieve their goals. Only by uncovering the source of their curse and helping them find peace can the Haunting Revenant be laid to rest once and for all."}',0,'Monster Manual 2024','','Necrotic, Psychic',10.0,NULL),
	 ('01990b8f-41b8-7da7-9b87-10aa240eb011'::uuid,'Hawk','Unaligned','0 (XP 10; PB +2)',10,3,'Ambusher','Tiny',13,NULL,1,'1d4-1','10 ft.',NULL,NULL,'60 ft.',5,16,8,2,14,6,'{"Perception": 6}','None','Passive Perception 16','None',-1,3,-3,2,-2,-4,2,'[]',NULL,'Beast','','{"value":"Wings outstretched, it screeches, eyes fixed on its prey below."}','{"value": "In Dungeons and Dragons 5th edition, a Hawk is a small, bird-like creature often used as a familiar or companion for spellcasters. Hawks are known for their keen eyesight and agility, making them excellent hunters and scouts.\n\nIn D&D lore, hawks are often associated with deities of air and sky, such as the god of the hunt, or nature. They are considered a symbol of freedom, grace, and swift justice. Some cultures believe that hawks are messengers from the gods, delivering important omens or warnings to those who witness their presence.\n\nIn the world of D&D, hawks are typically found in forests, mountains, and other natural habitats where they can hunt for small prey. They are known for their piercing cries and ability to spot potential threats from great distances.\n\nAdventurers may encounter hawks in the wild, either as allies or adversaries. While hawks are not typically aggressive towards humans, they will defend themselves if threatened. Some spellcasters may choose to summon a hawk to aid them in battle or provide reconnaissance on their enemies.\n\nOverall, hawks are a majestic and iconic creature in the world of D&D, embodying traits of grace, agility, and keen perception."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b8f-71d2-7644-a2d8-35d56b36921a'::uuid,'Helmed Horror','TrueNeutral','4 (XP 1 100; PB +2)',1100,3,'Soldier','Medium',20,NULL,67,'9d8+27','30 ft.',NULL,NULL,'30 ft.',18,13,16,10,10,10,'{"Perception": 4}','Necrotic, Poison; Blinded, Charmed, Deafened, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned, Stunned','Blindsight 60 ft., Passive Perception 14','Understands Common plus one other language but can''t speak',3,1,4,0,0,0,2,'["Shield"]','Habitat: Any','Construct','','{"value":"Visor gleams ominously as it stalks forward, sword at the ready."}','{"value": "Helmed Horrors are powerful constructs created by powerful wizards or sorcerers to serve as guardians, protectors, or enforcers. They are typically crafted from the remains of fallen warriors or knights, encased in enchanted armor and imbued with a spark of magical energy to animate them.\n\nHelmed Horrors are relentless and unwavering in their loyalty to their creator, following their orders without question or hesitation. They are typically equipped with a variety of powerful weapons and are skilled in combat, making them formidable opponents in battle.\n\nDespite their fearsome appearance and formidable abilities, Helmed Horrors lack true intelligence or free will, existing only to serve their creator''s commands. They are often used to guard important locations, treasures, or individuals, and are capable of carrying out their duties with ruthless efficiency.\n\nHelmed Horrors are immune to many forms of magic and can only be destroyed through physical means, making them particularly challenging foes for spellcasters. Their unyielding dedication to their task and their formidable combat abilities make them a formidable opponent for any adventurers who cross their path."}',0,'Monster Manual 2024','','None',4.0,NULL),
	 ('01990b8f-9e92-7b17-84ea-1753824aef1a'::uuid,'Hezrou','ChaoticEvil','8 (XP 3 900; PB +3)',3900,6,'Brute','Large',18,NULL,157,'15d10+75','30 ft.',NULL,NULL,NULL,19,17,20,5,12,13,'{}','Poison; Poisoned','Darkvision 120 ft., Passive Perception 11','Abyssal; telepathy 120 ft.',8,3,7,4,1,-3,3,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Slime drips from its wretched form, exuding a foul stench of decay."}','{"value": "Hezrous are powerful demons that reside in the Abyss, the chaotic and evil plane of existence. They are large, frog-like creatures with leathery skin, sharp teeth, and powerful claws. Hezrous are known for their immense strength and ability to cast spells, particularly those related to poison and disease.\n\nThese demons are often summoned by dark sorcerers and cultists to wreak havoc and destruction upon the mortal realm. They delight in causing pain and suffering, and are known for their insatiable hunger for flesh and blood.\n\nHezrous are also skilled in manipulation and deception, often luring unsuspecting victims into their grasp with promises of power or wealth. They are considered one of the most dangerous and feared demons in the Abyss, and encountering one is a sure sign of impending doom.\n\nIn combat, Hezrous are formidable opponents, using their immense strength and magical abilities to overwhelm their enemies. They are resistant to many forms of damage and can regenerate quickly, making them difficult to defeat.\n\nOverall, Hezrous are creatures of pure evil and chaos, embodying the darkest aspects of the Abyss and posing a serious threat to any who dare to cross their path."}',0,'Monster Manual 2024 (BR)','Demon','Cold, Fire, Lightning',8.0,NULL),
	 ('01990b8f-afd8-7e44-892e-3268312e7d5a'::uuid,'Hill Giant','ChaoticEvil','5 (XP 1 800; PB +3)',1800,2,'Brute','Huge',13,NULL,105,'10d12+40','40 ft.',NULL,NULL,NULL,21,8,19,5,9,6,'{"Perception": 2}','None','Passive Perception 12','Giant',4,-1,5,-1,-2,-3,3,'[]','Habitat: Hill','Giant','','{"value":"Looming over you, it swings its massive club with thunderous force."}','{"value": "Hill giants are massive and brutish humanoid creatures that dwell in the hills and mountains of the world. They are known for their immense strength and insatiable hunger, often raiding nearby settlements for food and treasure.\n\nHill giants are typically solitary creatures, although they may form small tribes or bands with others of their kind. They are not particularly intelligent, relying more on their size and strength to overpower their enemies.\n\nIn combat, hill giants are known for their powerful attacks, which can easily crush and maim their opponents. They are also skilled in throwing rocks at their enemies from a distance.\n\nDespite their violent tendencies, hill giants are not inherently evil creatures. They simply have a primal and simplistic view of the world, driven by their basic needs for food and shelter.\n\nOverall, hill giants are a formidable and dangerous foe for adventurers to face, requiring cunning tactics and strategy to defeat."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b8f-d3ea-7cad-8439-8ffa394e7378'::uuid,'Hippopotamus','Unaligned','4 (XP 1,100; PB +2)',1100,-2,'Brute','Large',14,NULL,82,'11d10+22','30 ft.',NULL,'30 ft.',NULL,21,7,15,2,12,4,'{"Perception": 3}','None','Passive Perception 13','None',2,-2,7,1,-3,-4,2,'[]',NULL,'Beast','','{"value":"Massive jaws snap shut with a thunderous crash, sending water droplets flying."}','{"value": "In the world of Dungeons and Dragons, the Hippopotamus is a large, semi-aquatic creature known for its territorial nature and powerful bite. These creatures are often found in swamps, rivers, and lakes, where they spend their days lounging in the water and grazing on aquatic plants.\n\nHippopotamuses are known to be extremely aggressive when provoked, and will fiercely defend their territory and young. Their massive jaws are capable of crushing bones and they are known to attack boats and even crocodiles that encroach on their territory.\n\nIn some regions, hippopotamuses are revered as symbols of strength and protection, while in others they are feared and avoided at all costs. Adventurers who encounter a hippopotamus in the wild would be wise to proceed with caution, as these creatures are not to be underestimated."}',0,'Monster Manual 2024 (BR)','','None',4.0,NULL),
	 ('01990b8f-ee12-764d-bc2d-18c0bda734b3'::uuid,'Hobgoblin Captain','LawfulEvil','3 (XP 700; PB +2)',700,4,'Leader','Medium',17,NULL,58,'9d8+18','30 ft.',NULL,NULL,NULL,15,14,14,12,10,13,'{}','None','Darkvision 60 ft., Passive Perception 10','Common, Goblin',2,2,2,0,1,1,2,'["Greatsword", "Half-Plate Armor", "Longbow"]','Habitat: Desert, Forest, Grassland, Hill, Mountain, Planar (Acheron), Underdar','Fey','Goblinoid','{"value":"The Hobgoblin Captain strides forward, barking orders with authority and menace"}','{"value": "Hobgoblin Captains are powerful and cunning leaders among their kind, known for their strategic prowess and ruthless efficiency in battle. They are often found leading bands of hobgoblins into combat, using their superior intellect and combat skills to outmaneuver their enemies.\n\nHobgoblin Captains are typically larger and more imposing than regular hobgoblins, with distinctive armor and weapons that set them apart. They are highly disciplined and demand strict obedience from their subordinates, instilling fear and respect in equal measure.\n\nIn hobgoblin society, Captains often rise to power through a combination of martial prowess and political maneuvering, ruthlessly eliminating rivals and forging alliances to secure their position. They are adept at exploiting the weaknesses of their foes, using deception and subterfuge to gain the upper hand in battle.\n\nIn combat, Hobgoblin Captains are formidable opponents, using a combination of martial skill and tactical acumen to outwit and overpower their enemies. They are skilled in a variety of weapons and fighting styles, and are known for their ability to inspire and rally their troops to victory.\n\nOverall, Hobgoblin Captains are fearsome and respected figures in hobgoblin society, feared by their enemies and revered by their followers. They are a force to be reckoned with on the battlefield, and any who face them in combat would do well to tread carefully."}',0,'Monster Manual 2024 (BR)','Goblinoid','None',3.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b8f-f81c-7e0f-b4a8-89d37c601f8c'::uuid,'Hobgoblin Warlord','LawfulEvil','6 (XP 2 300; PB +3)',2300,5,'Leader','Medium',20,NULL,112,'15d8+45','30 ft.',NULL,NULL,NULL,17,14,16,14,11,15,'{}','None','Darkvision 60 ft., Passive Perception 10','Common, Goblin',3,5,3,3,5,5,3,'["nine Javelins", "Longsword", "Plate Armor", "Shield"]','Habitat: Desert, Forest, Grassland, Hill, Mountain, Planar (Acheron), Underdark','Fey','Goblinoid','{"value":"Leader surveys the battlefield, barking orders with a cruel sneer."}','{"value": "Hobgoblin Warlords are powerful leaders among hobgoblin society, known for their strategic minds, martial prowess, and ruthless ambition. These fierce warriors rise to power through a combination of cunning, strength, and charisma, often leading their tribes in conquest and expansion.\n\nHobgoblin Warlords are skilled tacticians, adept at organizing their forces and exploiting their enemies'' weaknesses. They are also formidable combatants, proficient in a variety of weapons and combat styles. Their presence on the battlefield inspires fear and loyalty in their troops, making them highly effective leaders.\n\nIn hobgoblin society, Warlords are often challenged for their position by ambitious rivals seeking to claim power for themselves. As a result, Hobgoblin Warlords are constantly on guard, ready to defend their leadership through force and guile.\n\nOverall, Hobgoblin Warlords are formidable foes to face in battle, commanding respect and fear from both their allies and enemies. Their cunning and martial prowess make them a force to be reckoned with on the battlefield, and their ambition drives them to seek ever greater power and conquest."}',0,'Monster Manual 2024','Goblinoid','None',6.0,NULL),
	 ('01990b90-2236-7a88-926e-40335136b39e'::uuid,'Hook Horror','TrueNeutral','3 (XP 700; PB +2)',700,0,'Skirmisher','Large',15,NULL,75,'10d10+20','30 ft.','30 ft.',NULL,NULL,18,10,15,6,12,7,'{"Perception": 5}','None','Blindsight 60 ft., Darkvision 120 ft., Passive Perception 15','Hook Horror',4,0,4,1,-2,-2,2,'[]','Habitat: Underdark','Monstrosity','','{"value":"Scrapes its hooked claws along the cave wall, emitting low, guttural growls"}','{"value": "The Hook Horror is a terrifying and mysterious creature that dwells deep within dark and cavernous environments. This monstrous beast resembles a large, bipedal bird with a hunched posture, sharp claws, and a long, hooked beak that it uses to impale its prey. \n\nLegends say that the Hook Horror was once a peaceful and gentle creature that lived in harmony with nature, but it was corrupted by dark forces and turned into a savage predator. It is said to be fiercely territorial and will attack anything that enters its domain, including unwary adventurers who stumble into its lair.\n\nDespite its fearsome appearance, the Hook Horror is not inherently evil. Some believe that it is simply a misunderstood creature trying to survive in a harsh and unforgiving world. However, its aggressive nature and penchant for violence make it a dangerous foe to encounter in the depths of the earth.\n\nThose who have faced a Hook Horror and lived to tell the tale often speak of its eerie screeches and haunting cries echoing through the darkness, a chilling reminder of the creature''s presence and the danger that lurks in the shadows. Adventurers beware, for the Hook Horror is a formidable opponent that should not be taken lightly."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01990b90-433f-72a7-8465-b8b8dc517a80'::uuid,'Horned Devil','LawfulEvil','11 (XP 7 200; PB +4)',7200,7,'Brute','Large',18,NULL,199,'19d10+95','30 ft.',NULL,NULL,'60 ft.',22,17,21,12,16,18,'{}','Fire, Poison; Poisoned','Darkvision 150 ft. (unimpeded by magical Darkness), Passive Perception 13','Infernal; telepathy 120 ft.',5,7,10,7,8,1,4,'[]','Habitat: Planar (Nine Hells)','Fiend','Devil','{"value":"Roars defiantly, flames licking from its nostrils and eyes ablaze with malice"}','{"value": "Horned Devils, also known as cornugons, are powerful fiends who serve as enforcers and warriors in the infernal hierarchy of the Nine Hells. They are large, muscular creatures with red skin, sharp horns, and a pair of bat-like wings. Horned Devils are known for their brutal and ruthless nature, often leading armies of lesser devils into battle and carrying out the will of their infernal masters.\n\nIn the hierarchy of the Nine Hells, Horned Devils are ranked just below the Archdevils and are considered elite warriors and commanders. They are skilled in combat and possess a range of infernal abilities, including the power to summon lesser devils to aid them in battle. Horned Devils are also known for their cunning and strategic thinking, making them dangerous adversaries on the battlefield.\n\nDespite their fearsome reputation, Horned Devils are not mindless brutes. They are intelligent creatures with a deep understanding of infernal politics and a talent for manipulation and deceit. They are often used as emissaries and envoys by the Archdevils, negotiating deals and alliances with mortals and other fiends.\n\nIn combat, Horned Devils are relentless and merciless, showing no mercy to their enemies. They are known for their ability to fly and their powerful melee attacks, which can easily cut down even the strongest of foes. In addition to their physical prowess, Horned Devils also possess a range of magical abilities, including the power to cast spells and create infernal flames.\n\nOverall, Horned Devils are fearsome adversaries in the world of Dungeons & Dragons, serving as powerful enforcers of the will of the Nine Hells and striking fear into the hearts of mortals and fiends alike."}',0,'Monster Manual 2024 (BR)','Devil','None',11.0,NULL),
	 ('01990b90-5108-7ff2-a063-d421e88d7f68'::uuid,'Hunter Shark','Unaligned','2 (XP 450; PB +2)',450,2,'Ambusher','Large',12,NULL,45,'6d10+12','5 ft.',NULL,'40 ft.',NULL,18,14,15,1,10,4,'{"Perception": 2}','None','Blindsight 60 ft., Passive Perception 12','None',2,2,4,0,-3,-5,2,'[]',NULL,'Beast','','{"value":"Sleek predator silently circles, eyes fixated on its prey."}','{"value": "In the world of Dungeons and Dragons, the Hunter Shark is a fearsome predator that lurks in the depths of the ocean. These massive creatures are known for their keen senses and relentless pursuit of prey. Hunter Sharks are known for their powerful jaws and razor-sharp teeth, which they use to tear apart their victims with brutal efficiency.\n\nLegends say that Hunter Sharks are actually the descendants of ancient sea gods, who cursed them to roam the seas in search of blood and flesh. They are feared by sailors and coastal communities alike, as they are known to attack ships and drag sailors down into the dark depths below.\n\nDespite their ferocious nature, Hunter Sharks are also revered by some seafaring cultures as symbols of strength and power. Some sailors even worship them as gods of the sea, believing that they can provide protection and guidance to those who show them respect.\n\nIn the world of D&D, encountering a Hunter Shark is a terrifying experience that can test even the bravest of adventurers. Only those with quick wits and strong weapons stand a chance against these deadly predators of the deep."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b90-7e95-74fb-b31e-8fa0039599f4'::uuid,'Hyena','Unaligned','0 (XP 10; PB +2)',10,1,'Ambusher','Medium',11,NULL,5,'1d8+1','50 ft.',NULL,NULL,NULL,11,13,12,2,12,5,'{"Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','None',1,1,0,1,-3,-4,2,'[]',NULL,'Beast','','{"value":"Grinning menacingly, it circles and snarls, saliva dripping from sharp teeth."}','{"value": "In the world of Dungeons and Dragons, the hyena is a creature known for its scavenging nature and its fierce pack mentality. Hyenas are often found in arid and grassy plains, where they hunt in groups and feast on the remains of other animals. They are known for their distinctive laughter-like vocalizations, which can be heard echoing across the savannah.\n\nHyenas are cunning and opportunistic predators, known for their ability to take down prey much larger than themselves through sheer numbers and coordinated attacks. They are also skilled at tracking and hunting down their quarry, using their keen senses of smell and hearing to pinpoint their target.\n\nIn D&D lore, hyenas are often depicted as vicious and bloodthirsty creatures, capable of tearing apart their enemies with their razor-sharp teeth and claws. They are considered a threat to travelers and settlements, as they are known to attack livestock and even unwary adventurers who wander too close to their territory.\n\nOverall, hyenas are a fearsome and dangerous creature in the world of D&D, and those who encounter them must be prepared to face their ferocious pack tactics and relentless pursuit."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b90-a159-734a-96be-817ca0c88f4a'::uuid,'Ice Devil','LawfulEvil','14 (XP 11 500; PB +5)',11500,7,'Brute','Large',18,NULL,228,'24d10+96','40 ft.',NULL,NULL,NULL,21,14,18,18,15,18,'{"Insight": 7, "Perception": 7, "Persuasion": 9}','Cold, Fire, Poison; Poisoned','Blindsight 120 ft., Passive Perception 17','Infernal; telepathy 120 ft.',9,7,5,7,9,4,5,'[]','Habitat: Planar (Nine Hells)','Fiend','Devil','{"value":"Frosty fiend sneers, frost crackling as it flexes its icy appendages"}','{"value": "Ice Devils, also known as Gelugons, are powerful fiends from the Nine Hells in the world of Dungeons and Dragons. They are known for their immense strength, cunning intelligence, and mastery over cold and ice. \n\nIce Devils are typically tall, humanoid creatures with icy blue skin, sharp horns, and a long, forked tail. They are armed with a deadly trident and are surrounded by an aura of cold that can freeze their enemies in their tracks. \n\nIn the hierarchy of Hell, Ice Devils are high-ranking fiends who serve as generals and commanders in the armies of the archdevils. They are known for their strategic minds and their ability to lead their forces to victory in battle. \n\nIce Devils are also skilled manipulators and deceivers, often using their charisma and cunning to corrupt mortals and turn them to evil. They are feared for their ability to sow chaos and destruction wherever they go. \n\nIn combat, Ice Devils are formidable opponents, using their tridents and icy powers to strike down their enemies with ruthless efficiency. They are also known for their ability to summon lesser devils to aid them in battle, making them even more dangerous foes. \n\nOverall, Ice Devils are dangerous and powerful creatures that embody the cold, cruel nature of the Nine Hells. They are a force to be reckoned with and a terrifying presence on the battlefield."}',0,'Monster Manual 2024 (BR)','Devil','None',14.0,NULL),
	 ('01990b90-d6e8-778d-99aa-2acd89ab5f33'::uuid,'Imp','LawfulEvil','1 (XP 200; PB +2)',200,3,'Ambusher','Tiny',13,NULL,21,'6d4+6','20 ft.',NULL,NULL,'40 ft.',6,17,13,11,12,14,'{"Insight": 3, "Stealth": 5, "Deception": 4}','Fire, Poison; Poisoned','Darkvision 120 ft. (unimpeded by magical Darkness), Passive Perception 11','Common, Infernal',1,3,2,1,2,0,2,'[]','Habitat: Any','Fiend','Devil','{"value":"Darting about, cackling with mischief and wielding a tiny flaming pitchfork"}','{"value": "Imps are small, fiendish creatures that serve more powerful devils in the hierarchy of the Nine Hells. They are often used as spies, messengers, or assassins by their infernal masters. Imps are known for their cunning and deceitful nature, using their shape-shifting abilities to blend in among mortals and carry out their dark tasks.\n\nIn combat, imps are not particularly strong or durable, but they make up for it with their agility and magical abilities. They can turn invisible at will, making them difficult to detect, and they are skilled spellcasters, able to cast spells such as fireball, lightning bolt, and charm person.\n\nImps are often summoned by warlocks and other spellcasters to serve as familiars, providing them with magical assistance and information in exchange for their services. However, imps are always looking for opportunities to betray their masters and further their own agendas.\n\nOverall, imps are devious and dangerous creatures that should not be underestimated, as they can cause chaos and mischief wherever they go."}',0,'Monster Manual 2024 (BR)','Devil','Cold',1.0,NULL),
	 ('01990b91-0314-793c-aaaf-fe1030f0b36b'::uuid,'Intellect Devourer','LawfulEvil','2 (XP 450; PB +2)',450,2,'Ambusher','Tiny',12,NULL,28,'8d4+8','40 ft.',NULL,NULL,NULL,6,14,13,14,11,10,'{"Stealth": 4, "Perception": 2}','None','Blindsight 60 ft., Passive Perception 12','Understands Deep Speech but can''t speak; telepathy 60 ft.',1,2,-2,0,0,2,2,'[]','Habitat: Underdark','Aberration','','{"value":"Thoughts writhe within its exposed brain, hungering for knowledge and domination."}','{"value": "Intellect Devourers are aberrations that resemble a brain with four legs and sharp claws. They are known for their ability to consume and control the minds of their victims. These creatures are often created by powerful mind flayers to serve as spies, assassins, or guards.\n\nIntellect Devourers are capable of psionically dominating the minds of creatures, allowing them to take control of their bodies and use them to further their own goals. They are also able to consume the brains of their victims, leaving behind an empty husk.\n\nIn combat, Intellect Devourers are formidable foes, using their telepathic abilities to confuse and manipulate their enemies. They are also known for their high intelligence and cunning, making them difficult to outsmart.\n\nOverall, Intellect Devourers are feared and reviled by many in the world of Dungeons and Dragons, as they represent a terrifying threat to the minds and souls of all who encounter them."}',0,'Monster Manual 2024','','Psychic',2.0,NULL),
	 ('01990b91-217f-716b-ac50-5efbfbd0a978'::uuid,'Invisible Stalker','TrueNeutral','6 (XP 2 300; PB +3)',2300,7,'Skirmisher','Large',14,NULL,97,'13d10+26','50 ft.',NULL,NULL,'50 ft.',16,19,14,10,15,11,'{"Stealth": 10, "Perception": 8}','Poison; Exhaustion, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Darkvision 60 ft., Passive Perception 18','Common, Primordial (Auran)',2,4,3,2,0,0,3,'[]','Habitat: Urban','Elemental','','{"value":"Whispers of wind reveal the Invisible Stalker\u0027s stealthy approach."}','{"value": "Invisible stalkers are elemental creatures that hail from the Plane of Air. They are known for their ability to turn invisible at will, allowing them to stalk their prey undetected. These creatures are often summoned by powerful wizards or sorcerers to carry out tasks or missions that require stealth and precision.\n\nInvisible stalkers are highly intelligent and can understand and speak multiple languages. They are typically neutral in alignment and do not have any particular loyalty to their summoner, instead focusing solely on completing their assigned task.\n\nThese creatures are relentless hunters, tracking their targets across great distances and through any terrain. They are often used as assassins or spies, as their invisibility makes them perfect for gathering information or carrying out covert operations.\n\nIn combat, invisible stalkers are incredibly agile and difficult to hit due to their ability to turn invisible. They strike quickly and efficiently, using their sharp claws to deal damage to their foes. They are not particularly strong or sturdy, however, so they rely on their speed and stealth to outmaneuver their enemies.\n\nOverall, invisible stalkers are feared and respected for their stealth and cunning, making them a formidable opponent for any adventurers who cross their path."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',6.0,NULL),
	 ('01990b91-4546-7d53-b9f9-c0071e625c63'::uuid,'Iron Golem','Unaligned','16 (XP 15 000; PB +5)',15000,9,'Brute','Large',20,NULL,252,'24d10+120','30 ft.',NULL,NULL,NULL,24,9,20,3,11,1,'{}','Fire, Poison, Psychic; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned','Darkvision 120 ft., Passive Perception 10','Understands Common plus two other languages but can''t speak',5,-1,7,0,-5,-4,5,'[]','Habitat: Any','Construct','','{"value":"Metallic joints creak as it raises its massive fists, eyes glowing with malice"}','{"value": "In Dungeons and Dragons 5th edition, the Iron Golem is a large construct made entirely of iron, created through powerful magic and alchemy. These towering guardians are created by powerful spellcasters or artificers to protect valuable treasures, important locations, or to serve as powerful defenders in battle.\n\nThe Iron Golem is known for its immense strength and durability, being nearly impervious to most physical attacks and possessing the ability to unleash devastating blows with its massive iron fists. Its body is often adorned with intricate runes and symbols that enhance its magical abilities and grant it additional powers, such as the ability to cast spells or emit a deadly poison gas.\n\nDespite their formidable nature, Iron Golems are typically mindless automatons, following the orders of their creators without question. However, in some cases, these constructs develop a semblance of sentience and may act independently, making them even more dangerous adversaries.\n\nEncountering an Iron Golem in the world of Dungeons and Dragons is often a daunting and challenging experience for adventurers, requiring careful planning and strategy to overcome its formidable defenses and overpowering strength."}',0,'Monster Manual 2024 (BR)','','None',16.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b91-4d4e-7502-a481-53355d321460'::uuid,'Jackal','Unaligned','0 (XP 10; PB +2)',10,2,'Skirmisher','Small',12,NULL,3,'1d6','40 ft.',NULL,NULL,NULL,8,15,11,3,12,6,'{"Stealth": 4, "Perception": 5}','None','Darkvision 90 ft., Passive Perception 15','None',0,2,-1,1,-2,-4,2,'[]',NULL,'Beast','','{"value":"Ravenous jackal snarls, circling with hungry eyes and bared teeth"}','{"value": "In Dungeons and Dragons 5th edition, the Jackal is a creature that is often associated with trickery and cunning. They are known for their keen senses and ability to work together in packs to take down larger prey.\n\nJackals are typically found in deserts, grasslands, and other open areas where they can easily hunt for food. They are opportunistic predators, feeding on small animals, insects, and even carrion if necessary.\n\nIn some D&D lore, Jackals are also seen as creatures of the night, often associated with dark magic and the underworld. They are sometimes portrayed as servants of evil deities or as shape-shifters capable of taking on human form.\n\nOverall, Jackals are versatile and adaptable creatures in D&D lore, often serving as a challenging and cunning opponent for adventurers to face in the wild."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b91-5c0d-726f-85bf-f125e13c2d3b'::uuid,'Juvenile Shadow Dragon','ChaoticEvil','4 (XP 1 100; PB +2)',1100,4,'Solo','Medium',15,NULL,45,'6d8+18','30 ft.','30 ft.',NULL,'60 ft.',17,14,17,12,11,15,'{"Stealth": 6, "Perception": 4}','Necrotic','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Common, Draconic',3,4,3,0,2,1,2,'[]','Habitat: Planar (Shadowfell), Underdark','Dragon','','{"value":"Sinister whispers emanate from its ebony scales as it prowls in the darkness."}','{"value": "The Juvenile Shadow Dragon is a fearsome creature that is born when a black dragon is corrupted by the power of the Shadowfell. This dark and twisted realm infuses the dragon with shadowy energy, turning its scales black as night and granting it the ability to manipulate darkness to its advantage.\n\nJuvenile Shadow Dragons are cunning and malicious beings, using their shadowy powers to hunt and terrorize those who dare to cross their path. They are known for their ability to blend into shadows, making them formidable predators in the darkness.\n\nThese dragons are also known for their ability to breathe a powerful blast of shadow energy, which can drain the life force from their enemies. They are highly intelligent and often use their powers to manipulate and control others to further their own dark agendas.\n\nJuvenile Shadow Dragons are typically found lurking in the darkest corners of the world, ruling over their own twisted domains and commanding fear and respect from those who dwell nearby. They are formidable foes for any adventurer brave enough to face them, and only the most skilled and courageous heroes stand a chance of defeating these dark and deadly creatures."}',0,'Monster Manual 2024','','See Living Shadow',4.0,NULL),
	 ('01990b91-7422-7f7b-ad0c-371cc1f81368'::uuid,'Killer Whale','Unaligned','3 (XP 700; PB +2)',700,2,'Ambusher','Huge',12,NULL,90,'12d12+12','5 ft.',NULL,'60 ft.',NULL,19,14,13,3,12,7,'{"Stealth": 4, "Perception": 3}','None','Blindsight 120 ft., Passive Perception 13','None',1,2,4,1,-2,-4,2,'[]',NULL,'Beast','','{"value":"Sleek form breaches the water, eyes fixed on prey with deadly intent."}','{"value": "In the world of Dungeons and Dragons, the Killer Whale is a powerful and fearsome creature known for its immense size, strength, and predatory nature. Also known as orcas, these creatures are apex predators of the sea and are highly intelligent and social animals.\n\nKiller Whales are often found in coastal waters and open oceans, where they hunt and feed on a variety of marine creatures, including fish, seals, and even other whales. They are known for their distinctive black and white coloring, as well as their large dorsal fin.\n\nIn D&D, Killer Whales are often depicted as aggressive and territorial creatures, capable of taking down much larger prey with their powerful jaws and razor-sharp teeth. They are typically encountered in the wilds of the ocean, where they pose a deadly threat to sailors, fishermen, and adventurers alike.\n\nSome stories tell of particularly cunning and vengeful Killer Whales that have developed a taste for humanoid flesh, making them even more dangerous adversaries. These creatures are often feared and respected by sailors and seafarers, who believe them to be harbingers of doom and destruction.\n\nOverall, Killer Whales are formidable opponents in the world of Dungeons and Dragons, and those who dare to face them in combat must be prepared for a fierce and deadly struggle."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Kraken','ChaoticEvil','23 (XP 50 000, or 62 000 in lair; PB +7)',50000,14,'Solo','Gargantuan',18,NULL,481,'26d20+208','30 ft.',NULL,'120 ft.',NULL,30,11,26,22,18,20,'{"History": 13, "Perception": 11}','Cold, Lightning; Frightened, Grappled, Paralyzed, Restrained','Truesight 120 ft., Passive Perception 21','Understands Abyssal, Celestial, Infernal, and Primordial but can''t speak; telepathy 120 ft.',15,7,17,11,5,6,7,'[]','Habitat: Underwater','Monstrosity','Titan','{"value":"Tentacles writhe menacingly, creating a deafening roar of crashing waves."}','{"value": "The Kraken is a legendary sea monster in Dungeons and Dragons, known for its immense size and power. It is said to dwell in the darkest depths of the ocean, where it preys on ships and sailors that venture too close to its lair.\n\nThe Kraken is typically depicted as a gigantic, tentacled creature with a massive, bulbous body and a beak-like mouth. Its tentacles are covered in suckers that can grip and crush even the strongest of ships. The Kraken is also said to have the ability to control the weather, creating fierce storms to further devastate its prey.\n\nLegends say that the Kraken is an ancient and powerful being, possibly even a god or deity of the sea. Its origins are shrouded in mystery, with some claiming that it is the last of its kind, while others believe that there are multiple Krakens scattered throughout the world''s oceans.\n\nEncountering a Kraken is a terrifying experience for any sailor or adventurer, as its immense size and strength make it a formidable opponent. Those who are lucky enough to survive an encounter with a Kraken often speak of the creature with a mixture of fear and awe, knowing that they have faced one of the most fearsome monsters in the world."}',0,'Monster Manual 2024 (BR)','Titan','None',23.0,62000.0),
	 ('01990b92-1ad4-7e23-860d-d244ce5f7b0a'::uuid,'Kuo-toa Archpriest','NeutralEvil','6 (XP 2 300; PB +3)',2300,2,'Leader','Medium',13,NULL,105,'14d8+42','30 ft.',NULL,'30 ft.',NULL,16,14,16,13,16,14,'{"Religion": 4, "Perception": 9}','None','Darkvision 120 ft., Truesight 30 ft., Passive Perception 19','Undercommon',3,2,3,3,2,1,3,'[]','Habitat: Coastal, Underdark','Aberration','','{"value":"Chants fervently, eyes glowing with zealous devotion to their dark deity"}','{"value": "Kuo-toa Archpriests are powerful and influential leaders within Kuo-toa society. These aquatic creatures are highly religious and devote themselves to their god, Blibdoolpoolp, the Sea Mother. The Archpriests are considered to be the chosen ones of their deity and are granted incredible powers and abilities as a result.\n\nKuo-toa Archpriests are able to manipulate water and control sea creatures with ease, using their powers to protect their people and further the goals of their god. They are also skilled in the art of spellcasting, able to call upon powerful magic to defeat their enemies and defend their underwater temples.\n\nIn addition to their magical abilities, Kuo-toa Archpriests are also skilled leaders and strategists, often leading their people into battle against other underwater races or surface dwellers. They are revered and feared by the other Kuo-toa, who see them as living embodiments of their god''s will.\n\nOverall, Kuo-toa Archpriests are formidable foes in combat, utilizing their powerful magic and leadership skills to protect their people and advance the will of their god. They are a force to be reckoned with in the underwater world of Dungeons and Dragons."}',0,'Monster Manual 2024','','None',6.0,NULL),
	 ('01990b92-2e33-729f-bc8a-7b5b0d9c9c26'::uuid,'Kuo-toa Whip','NeutralEvil','1 (XP 200; PB +2)',200,0,'Skirmisher','Medium',11,NULL,45,'7d8+14','30 ft.',NULL,'30 ft.',NULL,14,10,14,12,14,11,'{"Religion": 3, "Perception": 6}','None','Darkvision 120 ft., Truesight 30 ft., Passive Perception 16','Undercommon',2,0,2,2,0,1,2,'[]','Habitat: Coastal, Underdark','Aberration','','{"value":"Whip cracks loudly, commanding obedience from the frenzied kuo-toa horde"}','{"value": "The Kuo-toa Whip is a powerful and feared member of the Kuo-toa race, a fish-like humanoid species that dwell in the depths of the ocean. The Kuo-toa are known for their worship of dark, sea deities and their penchant for capturing and sacrificing surface-dwellers to their gods.\n\nThe Kuo-toa Whip, as its name suggests, is a skilled combatant who wields a whip with deadly precision. They are often found leading hunting parties or overseeing sacrificial rituals. The whip is not only a weapon for the Kuo-toa Whip but also a symbol of power and authority within their society.\n\nIn addition to their combat prowess, Kuo-toa Whips are also known for their ability to manipulate and control other members of their race through fear and intimidation. They are skilled at rallying their fellow Kuo-toa to follow their commands and are often seen as leaders within their communities.\n\nOverall, the Kuo-toa Whip is a formidable foe in the world of Dungeons and Dragons, combining physical strength with cunning leadership skills to strike fear into the hearts of adventurers who dare to cross their path."}',0,'Monster Manual 2024','','None',1.0,NULL),
	 ('01990b92-540f-7cb5-b91a-dccd5a002b8c'::uuid,'Lamia','ChaoticEvil','4 (XP 1 100; PB +2)',1100,1,'Ambusher','Large',13,NULL,97,'13d10+26','40 ft.',NULL,NULL,NULL,16,13,15,14,15,16,'{"Insight": 4, "Stealth": 5, "Deception": 7}','None','Darkvision 60 ft., Passive Perception 12','Abyssal, Common',2,1,3,2,3,2,2,'[]','Habitat: Desert','Fiend','','{"value":"Seductress lounges languidly, eyes gleaming with hunger and deceit"}','{"value": "In Dungeons and Dragons 5th edition, a Lamia is a monstrous creature that combines the features of a human woman with the body of a lion. They are often depicted as seductive and manipulative beings, using their beauty to lure unsuspecting victims into their grasp.\n\nLamias are typically portrayed as cunning and deceitful, using their shape-shifting abilities to disguise themselves as humans in order to blend in with society. They are known for their psychic abilities, which they use to control the minds of their prey and bend them to their will.\n\nIn D&D lore, Lamias are often associated with dark magic and evil intentions. They are considered to be dangerous and malevolent creatures, preying on the weaknesses of others for their own gain. They are often found in desolate and abandoned places, where they can easily hide and hunt without being detected.\n\nOverall, Lamias are fearsome creatures with a reputation for being both alluring and deadly. Players must beware of their charms and be cautious when encountering them in their adventures."}',0,'Monster Manual 2024 (BR)','','None',4.0,NULL),
	 ('01990b92-6735-7466-b1ca-ac2244de89ed'::uuid,'Lemure','LawfulEvil','0 (XP 10; PB +2)',10,-3,'Minion','Medium',9,NULL,9,'2d8','20 ft.',NULL,NULL,NULL,10,5,11,1,11,3,'{}','Fire, Poison; Charmed, Frightened, Poisoned','Darkvision 120 ft. (unimpeded by magical Darkness), Passive Perception 10','Understands Infernal but can''t speak',0,-3,0,0,-4,-5,2,'[]','Habitat: Planar (Nine Hells)','Fiend','Devil','{"value":"Shambling, it moans and reaches out with grasping, gelatinous hands"}','{"value": "Lemures are low-ranking devils in the hierarchy of the Nine Hells. They are the souls of evil mortals who have been damned to the Hells for their sins, and their punishment is to serve as mindless foot soldiers for their demonic overlords. Lemures are shapeless, grotesque creatures with bloated bodies, featureless faces, and no distinct features or personalities. They are often used as cannon fodder in battles or as menial laborers in the infernal realms.\n\nDespite their lowly status, lemures are still dangerous foes in combat, as they possess a number of infernal powers, such as the ability to drain the life force from their enemies with a touch, or to summon other lemures to aid them in battle. However, they are easily dispatched by more powerful creatures, and are typically seen as mere fodder by their demon masters.\n\nLemures are often used as a cautionary tale in religious teachings, warning mortals of the consequences of their sinful actions and the horrors that await them in the afterlife if they do not repent. They are also sometimes summoned by evil spellcasters to serve as minions or guardians, although their lack of intelligence and loyalty makes them unreliable servants."}',0,'Monster Manual 2024 (BR)','Devil','Cold',0.0,NULL),
	 ('01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Lich','NeutralEvil','21 (XP 33 000, or 41 000 in lair; PB +7)',33000,17,'Solo','Medium',20,NULL,315,'42d8+126','30 ft.',NULL,NULL,NULL,11,16,16,21,14,16,'{"Arcana": 19, "History": 12, "Insight": 9, "Perception": 9}','Necrotic, Poison; Charmed, Exhaustion, Frightened, Paralyzed, Poisoned','Truesight 120 ft., Passive Perception 19','All',10,10,0,9,3,12,7,'["Component Pouch"]','Habitat: Any','Undead','Wizard','{"value":"Eyes glow with malevolent power, raising skeletal hands in a dark incantation"}','{"value": "In Dungeons and Dragons, a Lich is a powerful undead spellcaster who has achieved immortality through dark magic. The process of becoming a Lich involves a ritual in which the spellcaster binds their soul to a phylactery, which serves as a vessel for their life force. As long as the phylactery remains intact, the Lich cannot truly be killed. \n\nLiches are typically former wizards or sorcerers who sought to extend their lives and gain more power through necromancy. They are often driven by a thirst for knowledge, power, or vengeance, and will stop at nothing to achieve their goals. Liches are known for their mastery of dark magic and their ability to raise the dead to do their bidding.\n\nLiches are usually depicted as skeletal figures draped in tattered robes, with glowing eyes and a malevolent aura. They are extremely intelligent and cunning, and are capable of casting powerful spells and creating powerful magical artifacts. Liches are feared and respected by other undead creatures, who often serve them as minions.\n\nIn combat, Liches are formidable opponents, using their mastery of magic to cast devastating spells and control the battlefield. They are also able to regenerate and heal themselves, making them difficult to defeat. To destroy a Lich, adventurers must locate and destroy its phylactery, which can be hidden in a secure location and protected by powerful wards and guardians.\n\nOverall, Liches are iconic villains in the world of Dungeons and Dragons, representing the ultimate combination of dark magic and undead power. They are a constant threat to adventurers and kingdoms alike, and are often the focus of epic quests and campaigns."}',0,'Monster Manual 2024 (BR)','Wizard','Cold, Lightning',21.0,41000.0),
	 ('01990b92-bfa9-75a2-a4f2-5a075ff1ac51'::uuid,'Lion','Unaligned','1 (XP 200; PB +2)',200,2,'Brute','Large',12,NULL,22,'4d10','50 ft.',NULL,NULL,NULL,17,15,11,3,12,8,'{"Stealth": 4, "Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','None',0,2,3,1,1,4,2,'[]',NULL,'Beast','','{"value":"Roaring fiercely, it prowls with golden eyes fixed on its prey."}','{"value": "In the world of Dungeons and Dragons, the lion is a powerful and majestic creature that is often found in savannas, grasslands, and other open areas. Known for their strength, agility, and ferocity, lions are fearsome predators that hunt in packs to take down large prey.\n\nIn some D&D campaigns, lions are seen as symbols of courage, nobility, and leadership, and are sometimes associated with deities or powerful beings. In other settings, lions are viewed as dangerous beasts that must be avoided or defeated in order to protect villages and travelers.\n\nLions are commonly used as mounts by powerful warriors or nobles, and some druids and rangers have been known to form bonds with these creatures, using them as companions in battle. In combat, lions are known for their powerful bite and claw attacks, as well as their ability to pounce on unsuspecting foes.\n\nOverall, lions are a versatile and iconic monster in the world of Dungeons and Dragons, and can be used in a variety of ways to challenge and engage players in their adventures."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b92-d136-73a4-8e83-5ad5de0d09ec'::uuid,'Lizard','Unaligned','0 (XP 10; PB +2)',10,0,'Ambusher','Tiny',10,NULL,2,'1d4','20 ft.','20 ft.',NULL,NULL,2,11,10,1,8,3,'{}','None','Darkvision 30 ft., Passive Perception 9','None',0,0,4,1,4,5,2,'[]',NULL,'Beast','','{"value":"Slithers silently, tongue flicking in and out, eyes fixed on prey"}','{"value": "In D&D 5e, the lizard is a small, reptilian creature that is often found in warm climates. They are known for their quick movements and sharp claws, which they use to hunt insects and small animals. Lizards are typically solitary creatures, but can sometimes be found in groups or pairs.\n\nIn some regions, lizards are considered sacred creatures and are believed to bring good luck or fortune to those who encounter them. They are also sometimes kept as pets or familiars by spellcasters.\n\nLizards are not particularly intelligent creatures, but they are cunning hunters and can be surprisingly dangerous when provoked. They are known for their ability to blend into their surroundings and move with stealth and agility.\n\nOverall, lizards are a common and relatively harmless creature in the world of D&D, but they can pose a threat to unsuspecting travelers or adventurers who underestimate their abilities."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b92-d1cb-7fe4-8ed5-8407766d2ffc'::uuid,'Lizardfolk Geomancer','TrueNeutral','2 (XP 450; PB +2)',450,0,'Support','Medium',13,NULL,33,'6d8+6','30 ft.',NULL,'30 ft.',NULL,15,10,13,10,15,8,'{"Nature": 2, "Stealth": 4, "Perception": 4}','None','Passive Perception 14','Draconic, Primordial (Terran)',1,0,2,2,-1,0,2,'[]','Habitat: Forest, Swamp','Elemental','','{"value":"Earth trembles as it molds the very ground beneath its cold, calculating gaze."}','{"value": "Lizardfolk Geomancers are a unique breed of lizardfolk known for their deep connection to the earth and their ability to manipulate the natural elements to their advantage. These creatures are typically found in swamps and marshlands, where they use their geomancy skills to control the environment and protect their territory.\n\nLizardfolk Geomancers are skilled in the use of earth-based magic, allowing them to summon earthquakes, create walls of stone, and control the flow of water. They are also adept at communicating with animals and plants, often using their abilities to command the creatures of the swamp to do their bidding.\n\nIn battle, Lizardfolk Geomancers are formidable opponents, using their earth-based magic to trap and immobilize their enemies while their allies move in for the kill. They are also known for their ability to heal themselves and their allies using the power of the earth, making them resilient and difficult to defeat.\n\nOverall, Lizardfolk Geomancers are a powerful and mysterious force in the world of D&D, using their connection to the earth to shape the world around them and protect their territory from intruders."}',0,'Monster Manual 2024','','None',2.0,NULL),
	 ('01990b92-f546-7a21-bba5-d5097eb1eacb'::uuid,'Mage','TrueNeutral','6 (XP 2,300; PB +3)',2300,2,'Artillery','Medium',15,NULL,81,'18d8','30 ft.',NULL,NULL,NULL,9,14,11,17,12,11,'{"Arcana": 6, "History": 6, "Perception": 4}','None','Passive Perception 14','Common plus three other languages',0,2,-1,4,0,6,3,'["Wand"]','Habitat: Any','Humanoid','Wizard','{"value":"Fiery energy crackles around Mage\u0027s outstretched hand, ready to unleash devastating spells."}','{"value": "Mages in D&D 5e are powerful spellcasters who have dedicated their lives to the study and mastery of magic. They are often seen as scholarly and intelligent individuals who have honed their craft through years of study and practice.\n\nMages come from a variety of backgrounds and can be found in all corners of the world. Some mages study at prestigious wizarding schools, while others learn their magic through more unconventional means. Regardless of their background, mages are able to tap into the arcane energies of the universe to cast powerful spells and wield incredible magical abilities.\n\nMages are often found in positions of power and influence, serving as advisors to kings and queens or leading powerful magical organizations. They are respected and feared for their immense power and knowledge of the arcane arts.\n\nIn combat, mages are formidable opponents, able to cast a wide variety of spells to manipulate the battlefield and defeat their enemies. They are often seen as glass cannons, with powerful offensive abilities but limited defensive capabilities.\n\nOverall, mages are complex and intriguing characters in the world of D&D, with a rich lore and history that adds depth to any campaign."}',0,'Monster Manual 2024 (BR)','Wizard','None',6.0,NULL),
	 ('01990b93-0549-7e38-a8d5-37dbe25e63bf'::uuid,'Mage Apprentice','TrueNeutral','2 (XP 450; PB +2)',450,2,'Artillery','Medium',15,NULL,49,'9d8+9','30 ft.',NULL,NULL,NULL,8,14,12,16,13,10,'{"Arcana": 5, "Perception": 3}','None','Passive Perception 13','Common plus one other language',1,2,-1,3,0,5,2,'["Component Pouch"]','Habitat: Any','Humanoid','Wizard','{"value":"Eyes wide with excitement, the Mage Apprentice fumbles with a crackling spellbook."}','{"value": "In the world of Dungeons and Dragons, Mage Apprentices are young and aspiring magic users who are just beginning to learn the intricacies of spellcasting. They are typically found studying under the guidance of a more experienced wizard or sorcerer, honing their skills and expanding their knowledge of the arcane arts.\n\nMage Apprentices are often seen as playful and curious, eager to experiment with new spells and magical abilities. However, their lack of experience and control can sometimes lead to unpredictable and dangerous results. Despite this, Mage Apprentices are valued for their potential and are often given tasks to assist their mentors in their research and magical endeavors.\n\nAs they progress in their studies, Mage Apprentices may eventually become full-fledged wizards or sorcerers in their own right, wielding powerful spells and shaping the world around them with their magic. However, the path to mastery is long and challenging, and many Mage Apprentices must overcome numerous obstacles and trials before reaching their full potential."}',0,'Monster Manual 2024','Wizard','None',2.0,NULL),
	 ('01990b93-51e4-7068-99bc-0b107add1ab3'::uuid,'Mammoth','Unaligned','6 (XP 2,300; PB +3)',2300,2,'Brute','Huge',13,NULL,126,'11d12+55','50 ft.',NULL,NULL,NULL,24,9,21,3,11,6,'{}','None','Passive Perception 10','None',8,-1,10,0,-2,-4,3,'[]',NULL,'Beast','','{"value":"Massive tusks rumble as it trumpets a deafening challenge to all who hear."}','{"value": "Mammoths are massive creatures that resemble elephants but are larger and hairier. They are typically found in cold, arctic environments and are known for their immense size and strength. In D&D lore, mammoths are often portrayed as majestic and powerful beasts that are revered by some cultures for their strength and resilience.\n\nMammoths are typically neutral in alignment and are known to be territorial creatures that will fiercely defend their herds and territory from any threats. They are herbivores and primarily feed on grasses, shrubs, and other vegetation found in their icy habitats.\n\nIn D&D, mammoths are often encountered as wild creatures that roam the frozen tundras, or they may be domesticated by certain cultures as mounts or beasts of burden. They are often used by giants and other humanoid races as war beasts due to their immense size and strength.\n\nMammoths are known for their powerful tusks, which they use for defense and in combat. They are also able to use their massive size and weight to trample enemies or knock down obstacles in their path.\n\nOverall, mammoths are iconic creatures in D&D lore that represent strength, endurance, and the harsh beauty of the frozen wilderness."}',0,'Monster Manual 2024 (BR)','','None',6.0,NULL),
	 ('01990b93-5a17-7382-b0b6-6d6147be964d'::uuid,'Manes Vaporspawn','ChaoticEvil','1 (XP 200; PB +2)',200,1,'Solo','Medium',13,NULL,19,'3d8+6','30 ft.',NULL,NULL,NULL,14,12,15,5,8,3,'{}','Poison; Charmed, Exhaustion, Frightened, Grappled, Poisoned, Restrained','Darkvision 60 ft., Passive Perception 9','Understands Abyssal but can''t speak',2,1,2,-1,-4,-3,2,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Foul vapors ooze from its writhing form, suffusing the air with noxious dread."}','{"value": "Manes Vaporspawn are grotesque and malevolent creatures that are born from the toxic miasma of the Abyss. These creatures are created when the souls of evil mortals are corrupted and twisted by the chaotic energies of the Abyss, turning them into mindless and ravenous monsters.\n\nManes Vaporspawn are often used by more powerful demons as foot soldiers and cannon fodder in the endless wars and conflicts that plague the Abyss. They are typically found in large swarms, overwhelming their enemies with sheer numbers and ferocity.\n\nThese creatures have a putrid and foul-smelling vapor that surrounds them, making them difficult to approach without becoming overwhelmed by their noxious presence. They are known for their insatiable hunger for flesh and souls, and will attack anything that crosses their path without hesitation.\n\nManes Vaporspawn are considered to be one of the lowest forms of demonic life, and are often looked down upon even by other demons. They are mindless and driven solely by their base instincts, making them both dangerous and unpredictable in combat.\n\nOverall, Manes Vaporspawn are a terrifying and repulsive threat that must be dealt with swiftly and decisively before they can spread their corruption and chaos further."}',0,'Monster Manual 2024','Demon','Cold, Fire, Lightning',1.0,NULL),
	 ('01990b93-7640-7493-ace9-872f2bf62e8c'::uuid,'Marid','ChaoticNeutral','11 (XP 7 200; PB +4)',7200,5,'Artillery','Large',17,NULL,229,'17d10+136','30 ft.',NULL,'90 ft.','60 ft.',22,12,26,18,17,18,'{}','None','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 13','Primordial (Aquan)',8,5,6,3,8,4,4,'[]','Habitat: Coastal, Planar (Elemental Plane of Water), Underwater','Elemental','Genie','{"value":"Sapphire skin shimmers, water swirling around its outstretched hand"}','{"value": "In Dungeons and Dragons, a Marid is a powerful and noble genie from the Elemental Plane of Water. They are known for their immense strength, magical abilities, and wealth. Marids are often depicted as beautiful and majestic beings with blue skin and flowing water-like hair.\n\nMarids are usually associated with bodies of water such as oceans, rivers, and lakes, and they are said to have the ability to control water and shape it to their will. They are also known for their mastery of wishes, being able to grant powerful boons or curses to those who summon them.\n\nIn D&D lore, Marids are often portrayed as proud and haughty beings, looking down on mortals as inferior creatures. They are typically encountered in adventures involving water-based quests or in campaigns set near bodies of water.\n\nOverall, Marids are formidable foes and powerful allies, depending on how they are approached by adventurers. Their presence can add a sense of mystique and danger to any campaign."}',0,'Monster Manual 2024','Genie','Acid, Cold, Lightning',11.0,NULL),
	 ('01990b97-3aae-71fe-99a0-563abef3843b'::uuid,'Piranha','Unaligned','0 (XP 10; PB +2)',10,3,'Ambusher','Tiny',13,NULL,1,'1d4-1','5 ft.',NULL,'40 ft.',NULL,2,16,9,1,7,2,'{}','None','Darkvision 60 ft., Passive Perception 8','None',-1,3,-4,-2,-4,-5,2,'[]',NULL,'Beast','','{"value":"Jaws snap aggressively in a frenzy of ravenous hunger."}','{"value": "In the world of Dungeons and Dragons, Piranhas are small, aggressive fish with razor-sharp teeth. They are typically found in freshwater rivers and lakes, where they swarm in schools to attack any creature that enters their territory.\n\nPiranhas are known for their voracious appetite and relentless hunting behavior. They are opportunistic feeders, capable of stripping the flesh from their prey in a matter of seconds. Their sharp teeth can easily tear through flesh and bone, making them a dangerous threat to adventurers who venture into their waters.\n\nIn some regions, Piranhas are even worshiped as sacred creatures by certain tribes who believe in their power and ferocity. These tribes often offer sacrifices to appease the Piranhas and ensure their own safety when traveling through piranha-infested waters.\n\nOverall, Piranhas are a fearsome and deadly predator in the world of Dungeons and Dragons, posing a significant threat to any creature that dares to enter their domain."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b93-a8ee-75a1-8e8f-a2190e84822c'::uuid,'Marilith','ChaoticEvil','16 (XP 15 000; PB +5)',15000,10,'Solo','Large',16,NULL,220,'21d10+105','40 ft.','40 ft.',NULL,NULL,18,20,20,18,16,20,'{"Perception": 8}','Poison; Poisoned','Truesight 120 ft., Passive Perception 18','Abyssal; telepathy 120 ft.',10,5,9,8,10,4,5,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Serpentine coils writhe, each blade poised to strike with deadly precision."}','{"value": "In Dungeons and Dragons 5th Edition, the Marilith is a powerful demon with the upper body of a beautiful female humanoid and the lower body of a massive serpent. They are known for their incredible skill in combat, wielding multiple swords with deadly precision.\n\nMariliths are often found leading armies of demons or serving powerful demon lords as elite warriors. They are cunning and manipulative, using their intelligence and charisma to outwit their enemies. Despite their chaotic nature, Mariliths are also known for their loyalty to their masters, as long as they are treated with respect and given opportunities for battle and conquest.\n\nIn D&D lore, Mariliths are considered to be among the most dangerous and formidable demons in the Abyss, feared for their unmatched combat prowess and cunning strategies. They are often encountered as bosses in high-level adventures, posing a significant challenge to any group of adventurers brave enough to face them."}',0,'Monster Manual 2024 (BR)','Demon','Cold, Fire, Lightning',16.0,NULL),
	 ('01990b93-f616-77af-8ec4-491dcaa71acd'::uuid,'Merfolk Wavebender','TrueNeutral','6 (XP 2 300; PB +3)',2300,4,'Support','Medium',14,NULL,97,'15d8+30','10 ft.',NULL,'40 ft.',NULL,10,18,14,13,19,15,'{"Perception": 7}','None','Passive Perception 17','Common, Primordial (Aquan)',5,7,0,7,5,1,3,'[]','Habitat: Coastal, Underwater','Elemental','','{"value":"Shimmering scales ripple as it commands the crashing waves with a graceful gesture."}','{"value": "Merfolk Wavebenders are a unique type of merfolk that have a deep connection to the elemental forces of water. They are powerful spellcasters who can manipulate water in all its forms, using it to create powerful waves and currents to defend their underwater homes. \n\nLegend has it that Merfolk Wavebenders were gifted their magical abilities by the ancient sea gods, who saw their dedication to protecting their oceanic territories. They are revered by other merfolk as wise and powerful leaders, often serving as the guardians of important underwater locations such as coral reefs and sunken cities.\n\nMerfolk Wavebenders are known for their ability to control the weather, summoning storms and tidal waves to defend their homes or attack their enemies. They are also skilled healers, using their magic to mend wounds and cure sickness among their fellow merfolk.\n\nDespite their formidable powers, Merfolk Wavebenders are generally peaceful beings who prefer to avoid conflict. However, they will not hesitate to defend themselves or their homes if threatened, using their mastery of water magic to unleash devastating attacks on their enemies.\n\nEncountering a Merfolk Wavebender can be a rare and awe-inspiring experience, as their presence is often seen as a sign of the favor of the sea gods. Those who earn the trust and respect of a Wavebender may find themselves granted powerful blessings and protection from the dangers of the deep."}',0,'Monster Manual 2024','','Cold',6.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b94-15d3-71cb-81c7-4e6e58caf071'::uuid,'Merrow','ChaoticEvil','2 (XP 450; PB +2)',450,2,'Skirmisher','Large',13,NULL,45,'6d10+12','10 ft.',NULL,'40 ft.',NULL,18,15,15,8,10,9,'{}','None','Darkvision 60 ft., Passive Perception 10','Abyssal, Primordial (Aquan)',2,2,4,0,-1,-1,2,'[]','Habitat: Coastal, Underwater','Monstrosity','','{"value":"Scales glisten as it emerges from the murky depths, eyes fixed hungrily."}','{"value": "Merrows are large, brutish aquatic creatures that are often found in coastal regions or underwater caves. They are a type of merfolk, but unlike their more graceful and elegant cousins, merrows are known for their aggressive and violent nature.\n\nMerrows are typically around 10 feet tall and have a muscular, fish-like body with webbed hands and feet. They have sharp teeth and claws, which they use to hunt for food and defend themselves from threats.\n\nMerrows are known to be skilled hunters and can be quite cunning when it comes to tracking and ambushing their prey. They are also known to be quite territorial, often attacking any intruders that come too close to their underwater lairs.\n\nIn some stories and legends, merrows are said to be the offspring of humans and sea creatures, resulting in their monstrous appearance and savage behavior. Others believe that merrows are cursed beings, doomed to live a life of violence and aggression.\n\nOverall, merrows are considered dangerous foes to encounter in the wild, and adventurers are often warned to steer clear of their territories unless they are prepared for a fierce battle."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b97-4bb7-76fc-af4f-8cda264da267'::uuid,'Pirate','Any','1 (XP 200; PB +2)',200,5,'Skirmisher','Medium',14,NULL,27,'5d8+5','30 ft.',NULL,NULL,NULL,10,16,12,8,12,14,'{}','None','Passive Perception 11','Common plus one other language',1,5,0,1,4,-1,2,'["Daggers (6)", "Leather Armor"]','Habitat: Any','Humanoid','','{"value":"Jolly Roger cackles, brandishing cutlass and pistol with swagger."}','{"value": "In Dungeons and Dragons 5th Edition, pirates are typically depicted as swashbuckling seafarers who roam the high seas in search of treasure and adventure. They are often skilled in combat, particularly with swords and pistols, and are known for their daring and reckless nature.\n\nPirates are usually part of a crew led by a captain, and they may hail from various backgrounds ranging from former sailors to disgraced nobles. They are often portrayed as morally ambiguous characters who may engage in acts of piracy and plunder, but also have a code of honor among themselves.\n\nPirates are commonly encountered as enemies in maritime settings, such as aboard a pirate ship or in a coastal town raided by a crew of pirates. They may also serve as allies or quest givers, offering the party a chance to join their crew or assist them in some daring mission.\n\nOverall, pirates in D&D 5e are colorful and charismatic characters who add an element of danger and excitement to any seafaring adventure."}',0,'Monster Manual 2024 (BR)','','None',1.0,NULL),
	 ('01990b94-295f-7c16-93d5-91a02c850c04'::uuid,'Mezzoloth','NeutralEvil','5 (XP 1 800; PB +3)',1800,3,'Soldier','Medium',18,NULL,75,'10d8+30','40 ft.',NULL,NULL,NULL,18,11,16,7,14,10,'{"Perception": 5}','Acid, Poison; Poisoned','Blindsight 60 ft., Darkvision 60 ft., Passive Perception 15','Abyssal, Infernal; telepathy 60 ft.',3,0,4,2,0,-2,3,'[]','Habitat: Planar (Gehenna)','Fiend','Yugoloth','{"value":"Slithering silently, its eyes gleam with malice as it surveys its prey."}','{"value": "Mezzoloths are fiendish creatures that serve as soldiers and enforcers in the infernal armies of the Nine Hells. They are known for their brutal and merciless nature, and are often used to intimidate and subjugate other creatures.\n\nMezzoloths are humanoid in shape, with grayish skin, sharp claws, and a pair of large horns protruding from their heads. They are proficient in combat, wielding weapons and spells with deadly precision. Mezzoloths are also capable of teleporting short distances, allowing them to quickly close the gap with their enemies.\n\nIn the hierarchy of the infernal armies, mezzoloths are considered to be low-ranking soldiers, but they are still highly respected for their ferocity and loyalty. They are often tasked with leading smaller groups of lesser fiends into battle, or carrying out missions of espionage and sabotage.\n\nMezzoloths are typically encountered in the lower planes, where they serve the archdevils and demon lords in their eternal struggle for power. They are feared by mortal creatures for their ruthless efficiency and their insatiable appetite for destruction."}',0,'Monster Manual 2024','Yugoloth','Cold, Fire, Lightning',5.0,NULL),
	 ('01990b94-45d0-7aa2-ab46-a2a3d79b665d'::uuid,'Mimic','TrueNeutral','2 (XP 450; PB +2)',450,3,'Ambusher','Medium',12,NULL,58,'9d8+18','20 ft.',NULL,NULL,NULL,17,12,15,5,13,8,'{"Stealth": 5}','Acid; Prone','Darkvision 60 ft., Passive Perception 11','None',2,1,3,1,-1,-3,2,'[]','Habitat: Underdark, Urban','Monstrosity','','{"value":"The chest creaks open, revealing rows of sharp teeth and a hungry tongue"}','{"value": "Mimics are shapeshifting monsters that are able to disguise themselves as ordinary objects, such as chests, doors, or even weapons. They are known for their ability to surprise unsuspecting adventurers by ambushing them when they least expect it.\n\nMimics are typically found in dungeons or other places where treasure is commonly stored, as they are able to lure in unsuspecting victims by disguising themselves as valuable loot. Once a mimic has its prey in close proximity, it will reveal its true form and attack with sharp teeth and adhesive tentacles.\n\nIn some lore, mimics are said to be the creations of powerful wizards or sorcerers who imbued ordinary objects with magical properties in order to guard their treasures. Other stories suggest that mimics are creatures from another plane of existence that have found their way into the material world and now roam in search of food.\n\nOverall, mimics are feared by adventurers for their ability to deceive and surprise, making them a formidable foe in any dungeon crawl."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b94-6131-7af1-92d0-c446eb6b7ea7'::uuid,'Mind Flayer','LawfulEvil','7 (XP 2 900; PB +3)',2900,4,'Controller','Medium',15,NULL,99,'18d8+18','30 ft.',NULL,NULL,'15 ft.',11,12,12,19,17,17,'{"Arcana": 7, "Insight": 6, "Stealth": 4, "Perception": 6}','None','Darkvision 120 ft., Passive Perception 16','Deep Speech, Undercommon; telepathy 120 ft.',1,4,0,6,6,7,3,'["Breastplate"]','Habitat: Underdark','Aberration','','{"value":"Inky tentacles writhe, probing the air for thoughts to feast upon"}','{"value": "Mind flayers, also known as illithids, are a terrifying and powerful race of psionic creatures in the Dungeons & Dragons universe. They are humanoid in appearance, with pale, slimy skin, tentacled mouths, and bulbous, alien-like heads. \n\nMind flayers are known for their powerful psionic abilities, including telepathy, mind control, and the ability to extract and consume the brains of their victims. They are highly intelligent and cunning, often using their psychic powers to manipulate and control others to further their own goals.\n\nOriginally hailing from the distant and mysterious realm of the Underdark, mind flayers are typically found in underground cities and strongholds, where they rule over lesser creatures and conduct twisted experiments in the pursuit of knowledge and power.\n\nIn combat, mind flayers are formidable foes, using their psionic abilities to incapacitate and control their enemies. They are also known to have a hierarchical society, with powerful elder brain creatures serving as leaders and controlling the minds of lesser mind flayers.\n\nOverall, mind flayers are one of the most feared and enigmatic creatures in the D&D universe, with a dark and sinister reputation that strikes fear into the hearts of adventurers and denizens of the Underdark alike."}',0,'Monster Manual 2024','','Psychic',7.0,NULL),
	 ('01990b94-6bac-7635-b1d6-fbcaa347d650'::uuid,'Mind Flayer Arcanist','LawfulEvil','11 (XP 7 200; PB +4)',7200,6,'Controller','Medium',16,NULL,143,'26d8+26','30 ft.',NULL,NULL,'30 ft.',11,14,13,20,17,17,'{"Arcana": 13, "Insight": 7, "Stealth": 6, "Perception": 7}','Psychic; Charmed, Frightened','Darkvision 120 ft., Passive Perception 17','Deep Speech, Undercommon; telepathy 120 ft.',1,6,0,7,7,9,4,'["Breastplate"]','Habitat: Underdark','Aberration','','{"value":"Its tentacles writhe and crackle with arcane energy, eyes glowing with sinister intellect."}','{"value": "The Mind Flayer Arcanist is a powerful and intelligent spellcaster within the Mind Flayer society. These creatures have honed their psychic abilities to a high degree, allowing them to manipulate the minds of others with ease. They are often found leading groups of Mind Flayers in their dark and sinister plans.\n\nThe Mind Flayer Arcanist is known for its mastery of illusion and enchantment spells, using its psychic powers to control and dominate its enemies. They are also skilled in telepathy, allowing them to communicate with other Mind Flayers over great distances.\n\nIn combat, the Mind Flayer Arcanist relies on its spells and psychic abilities to incapacitate and control its foes. They are highly dangerous adversaries, capable of turning the tide of battle with a single spell.\n\nOverall, the Mind Flayer Arcanist is a terrifying and formidable foe, using its intellect and psychic powers to further the goals of the Mind Flayer society. Adventurers should approach these creatures with caution and be prepared for a challenging and mind-bending encounter."}',0,'Monster Manual 2024','','None',11.0,NULL),
	 ('01990b94-7c16-7710-87c5-2d3ae837a400'::uuid,'Minotaur of Baphomet','ChaoticEvil','3 (XP 700; PB +2)',700,0,'Brute','Large',14,NULL,85,'10d10+30','40 ft.',NULL,NULL,NULL,18,11,16,6,16,9,'{"Survival": 7, "Perception": 7}','None','Darkvision 60 ft., Passive Perception 17','Abyssal',3,0,4,3,-1,-2,2,'[]','Habitat: Underdark','Monstrosity','','{"value":"Rage bellows from the Minotaur\u0027s bloodshot eyes as it charges towards you."}','{"value": "The Minotaur of Baphomet is a fearsome and powerful creature that serves as a guardian and enforcer for the demon lord Baphomet, who is the patron of minotaurs. These monstrous beings are a twisted combination of man and bull, with the head and horns of a bull atop a muscular humanoid body. They are known for their immense strength and ferocity in battle, often wielding large axes or other brutal weapons.\n\nMinotaurs of Baphomet are often found in the dark and labyrinthine lairs of their demon lord, where they serve as both protectors and executioners. They are fiercely loyal to Baphomet and will stop at nothing to defend their territory and carry out his will. It is said that they are created through dark rituals and demonic magic, imbuing them with a savage and bloodthirsty nature.\n\nIn combat, Minotaurs of Baphomet are relentless and ruthless, using their brute strength and cunning to overpower their enemies. They are known for their ability to charge at their foes with incredible speed and gore them with their horns, causing devastating injuries. Those who face a Minotaur of Baphomet in battle are often left battered and broken, if they survive at all.\n\nOverall, the Minotaur of Baphomet is a terrifying and formidable creature, embodying the brutal and savage nature of their demon lord. They are a force to be reckoned with on the battlefield, striking fear into the hearts of all who oppose them."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b94-b2f3-7eca-b9ec-d5d492803078'::uuid,'Mummy','LawfulEvil','3 (XP 700; PB +2)',700,-1,'Brute','Medium',11,NULL,58,'9d8+18','20 ft.',NULL,NULL,NULL,16,8,15,6,12,12,'{}','Necrotic, Poison; Charmed, Exhaustion, Frightened, Paralyzed, Poisoned','Darkvision 60 ft., Passive Perception 11','Common plus two other languages',2,-1,3,3,1,-2,2,'[]','Habitat: Desert, Swamp','Undead','','{"value":"Shambling forward, its bandaged limbs creak with ancient malice."}','{"value": "In Dungeons and Dragons 5e, the mummy is an undead creature that is created when a powerful being is cursed to eternal life through a ritual involving dark magic. The mummy is bound to serve its creator and carries out their commands without question. It is usually found guarding ancient tombs or temples, protecting the treasures and secrets within.\n\nThe mummy''s cursed existence causes it to slowly decay over time, giving it a desiccated appearance with rotting bandages covering its body. Despite its deteriorating state, the mummy retains its formidable strength and ability to cast powerful spells, making it a dangerous foe for adventurers to face.\n\nThe touch of a mummy carries a curse that can drain the life force from its victims, leaving them weakened and vulnerable. Those who fall victim to the mummy''s curse may find themselves slowly turning into undead creatures themselves, perpetuating the cycle of death and decay.\n\nIn combat, the mummy uses its supernatural abilities to weaken and control its enemies, using its cursed touch and spells to overpower them. Only the bravest and most skilled adventurers dare to face a mummy in battle, as the consequences of failure can be dire."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Mummy Lord','LawfulEvil','15 (XP 13 000, or 15 000 in lair; PB +5)',13000,10,'Controller','Medium',17,NULL,187,'25d8+75','30 ft.',NULL,NULL,NULL,18,10,17,11,19,16,'{"History": 5, "Religion": 5, "Perception": 9}','Necrotic, Poison; Charmed, Exhaustion, Frightened, Paralyzed, Poisoned','Truesight 60 ft., Passive Perception 19','Common plus three other languages',3,0,4,9,3,5,5,'[]','Habitat: Desert, Swamp','Undead','Cleric','{"value":"Writhes in ancient wrappings, its eyes burning with cursed knowledge"}','{"value": "In Dungeons and Dragons 5th Edition, a Mummy Lord is a powerful undead creature created through a dark ritual involving the preservation of a powerful individual''s body after death. The mummy lord retains the memories and abilities it had in life, making it a formidable foe for adventurers to face.\n\nMummy lords are often encountered in ancient tombs or ruined temples, where they serve as guardians of the treasures and secrets hidden within. They possess a variety of supernatural abilities, including the ability to paralyze their foes with a chilling touch, summoning swarms of insects to attack intruders, and casting powerful spells to manipulate the battlefield.\n\nDespite their fearsome reputation, mummy lords are not mindless monsters and are capable of complex thoughts and emotions. Some mummy lords may even seek to reclaim their former glory by amassing followers and building an undead army to conquer the living world.\n\nOverall, the lore of the mummy lord in Dungeons and Dragons 5th Edition paints them as ancient and powerful undead beings with a deep connection to the dark forces that created them, making them a formidable challenge for any group of adventurers brave enough to face them."}',0,'Monster Manual 2024 (BR)','Cleric','None',15.0,15000.0),
	 ('01990b95-13fe-7f70-a565-41604b26d0ce'::uuid,'Myconid Sovereign','LawfulNeutral','2 (XP 450; PB +2)',450,0,'Support','Large',13,NULL,45,'6d10+12','30 ft.',NULL,NULL,NULL,12,10,14,13,15,10,'{}','None','Darkvision 120 ft., Passive Perception 12','Telepathy 240 ft.',2,0,1,2,0,1,2,'[]','Habitat: Underdark','Plant','','{"value":"Mushroom king hums a calming melody, spores swirling around its regal form"}','{"value": "Myconid Sovereigns are powerful leaders of the myconid race, which are sentient fungal creatures that dwell in the Underdark. They are highly intelligent and possess powerful psionic abilities, allowing them to communicate telepathically with other creatures and manipulate their surroundings with their minds.\n\nMyconid Sovereigns are revered by other myconids, who view them as wise and benevolent rulers. They are typically found in large underground colonies, where they govern their people and ensure the harmony and well-being of their community.\n\nIn battle, Myconid Sovereigns are formidable foes, able to control the minds of their enemies and summon spores to attack and debilitate their foes. They are also skilled healers, able to use their spores to mend wounds and cure diseases.\n\nOverall, Myconid Sovereigns are mysterious and enigmatic creatures, with a deep connection to the natural world and a profound understanding of the interconnectedness of all living things. They are respected and feared by those who dwell in the Underdark, and their presence is a sign of great power and wisdom."}',0,'Monster Manual 2024','','None',2.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b95-1ab0-7d2b-96d7-8110d9a75b75'::uuid,'Myconid Sprout','LawfulNeutral','0 (XP 10; PB +2)',10,0,'Minion','Small',10,NULL,3,'1d6','10 ft.',NULL,NULL,NULL,8,10,10,8,11,5,'{}','None','Darkvision 120 ft., Passive Perception 10','Telepathy 240 ft.',0,0,-1,0,-3,-1,2,'[]','Habitat: Underdark','Plant','','{"value":"Silently swaying, emitting a sweet, earthy aroma, beckoning with outstretched cap."}','{"value": "Myconid Sprouts are the youngest and smallest members of the myconid race, which are sentient fungal creatures that inhabit underground caves and forests. They are born from spores released by myconid adults and quickly grow into small, humanoid-shaped beings with mushroom-like heads.\n\nMyconid Sprouts are typically peaceful and curious creatures, spending their time exploring their surroundings and learning from the older myconids in their community. They are often tasked with tending to the fungal gardens and assisting in the care of the myconid young.\n\nDespite their small size, Myconid Sprouts possess a connection to the mycelial network that connects all myconids, allowing them to communicate telepathically with other members of their race. They also have the ability to release spores that can induce various effects on creatures around them, such as causing confusion or hallucinations.\n\nIn combat, Myconid Sprouts are not particularly strong or skilled fighters, preferring to use their telepathic abilities and spore powers to manipulate their enemies and protect themselves. They are often accompanied by larger, more powerful myconids who will defend them if necessary.\n\nOverall, Myconid Sprouts are gentle and inquisitive creatures, but they should not be underestimated, as they are capable of defending themselves and their community when threatened."}',0,'Monster Manual 2024','','None',0.0,NULL),
	 ('01990b95-4ced-7982-a41f-3907042c6c55'::uuid,'Nalfeshnee','ChaoticEvil','13 (XP 10 000; PB +5)',10000,5,'Brute','Large',18,NULL,184,'16d10+96','20 ft.',NULL,NULL,'30 ft.',21,10,22,19,12,15,'{}','Poison; Frightened, Poisoned','Truesight 120 ft., Passive Perception 11','Abyssal; telepathy 120 ft.',11,0,5,6,7,9,5,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"It bellows, its wings casting shadows that seem to swallow the light."}','{"value": "The Nalfeshnee is a powerful demon that is often depicted as a grotesque, bloated monster with leathery wings and a horned head. They are known for their immense strength and terrifying appearance, often inspiring fear and awe in those who encounter them. \n\nIn the lore of Dungeons and Dragons, Nalfeshnees are considered to be some of the most powerful demons in the Abyss, the chaotic and evil plane of existence where demons reside. They are often seen as the generals and leaders of demonic armies, using their strength and magical abilities to command lesser demons in battle.\n\nNalfeshnees are also known for their insatiable hunger, both for physical sustenance and for power. They are often depicted as gluttonous creatures who will consume anything in their path, including other demons and even mortal beings. Their hunger drives them to seek out sources of power and influence, leading them to form alliances with other demons or powerful entities in order to further their own goals.\n\nOverall, the Nalfeshnee is a fearsome and dangerous creature in the world of Dungeons and Dragons, capable of wreaking havoc and destruction wherever they go. Players who encounter a Nalfeshnee in their adventures must be prepared for a challenging and potentially deadly encounter."}',0,'Monster Manual 2024 (BR)','Demon','Cold, Fire, Lightning',13.0,NULL),
	 ('01990b95-7fd5-7405-8962-c8e839033bb7'::uuid,'Night Hag','NeutralEvil','5 (XP 1 800; PB +3)',1800,5,'Controller','Medium',17,NULL,112,'15d8+45','30 ft.',NULL,NULL,NULL,18,15,16,16,14,16,'{"Insight": 5, "Stealth": 5, "Deception": 6, "Perception": 5}','Charmed','Darkvision 120 ft., Passive Perception 15','Abyssal, Common, Infernal, Primordial',3,2,4,2,3,3,3,'[]','Habitat: Planar (Lower Planes)','Fiend','','{"value":"Whispers haunting lullabies, her eyes gleaming with malice and cunning."}','{"value": "Night Hags are powerful and malevolent creatures that dwell in dark and desolate places such as swamps, ruins, and cemeteries. They are known for their ability to shape-shift into beautiful women to lure unsuspecting victims to their doom. Once a victim is in their clutches, the Night Hag will torture and torment them until they are driven to madness or death.\n\nNight Hags are also skilled in the dark arts of magic, particularly in curses and hexes. They are said to be able to steal the souls of their victims and sell them to other evil entities for power and wealth. They are feared by many as bringers of nightmares and harbingers of death.\n\nIn some lore, Night Hags are said to be part of a coven, working together to spread chaos and suffering. They are often depicted as cunning and manipulative, using their powers to control and manipulate those around them.\n\nOverall, Night Hags are creatures to be feared and avoided at all costs, as they are relentless in their pursuit of evil and destruction."}',0,'Monster Manual 2024 (BR)','','Cold, Fire',5.0,NULL),
	 ('01990b95-a98f-7e16-84c3-02f0ec573f7e'::uuid,'Noble Prodigy','TrueNeutral','10 (XP 5 900; PB +4)',5900,7,'Leader','Medium',16,NULL,148,'27d8+27','30 ft.',NULL,NULL,NULL,8,16,12,15,14,19,'{"Perception": 6, "Persuasion": 8}','None','Passive Perception 16','Common plus two other languages',5,7,-1,6,8,2,4,'[]','Habitat: Any','Humanoid','','{"value":"Graceful steps echo as it surveys the room with piercing, intelligent eyes"}','{"value": "The Noble Prodigy is a unique and rare monster in the world of Dungeons and Dragons. They are believed to be descendants of powerful and ancient beings, possessing innate magical abilities that far surpass those of ordinary creatures.\n\nNoble Prodigies are often born into noble families or chosen by powerful entities at a young age, and are trained in the ways of magic and combat from a very early age. They are known for their exceptional intelligence, charisma, and strength, making them formidable opponents in battle.\n\nDespite their immense power, Noble Prodigies are often solitary beings, preferring to keep to themselves and only interacting with others when necessary. They are fiercely protective of their territory and will not hesitate to defend it against any intruders.\n\nLegends say that the Noble Prodigy is destined to become a great leader or ruler, using their powers for the betterment of their people and the world. However, some believe that their incredible abilities could also be used for darker purposes, leading to fear and mistrust from those around them.\n\nEncountering a Noble Prodigy is a rare and dangerous experience, as they are not easily swayed or defeated. Those who are able to earn their trust may find a powerful ally, but those who cross them may face swift and deadly consequences."}',0,'Monster Manual 2024','','None',10.0,NULL),
	 ('01990b95-c060-7c25-96b4-5c0e8c77b13a'::uuid,'Nothic','NeutralEvil','2 (XP 450; PB +2)',450,3,'Ambusher','Medium',15,NULL,45,'6d8+18','30 ft.',NULL,NULL,NULL,14,16,16,13,10,8,'{"Arcana": 3, "Insight": 4, "Stealth": 5, "Perception": 4}','None','Truesight 120 ft., Passive Perception 14','Undercommon',3,3,2,0,-1,1,2,'[]','Habitat: Underdark','Aberration','','{"value":"It gazes hungrily, its single eye pulsating with twisted curiosity"}','{"value": "In the world of Dungeons and Dragons, a Nothic is a twisted and corrupted creature that was once a wizard seeking forbidden knowledge. Through their insatiable hunger for dark secrets, they were transformed into a grotesque being with a single, giant, unblinking eye in the center of their forehead. This eye can see into the deepest secrets and fears of those it gazes upon.\n\nNothics are often found lurking in dark and forgotten places, preying on unsuspecting travelers or adventurers who stumble into their lairs. They are known to be cunning and manipulative, using their knowledge of others'' secrets to bargain for their own survival or gain.\n\nDespite their monstrous appearance and sinister nature, some Nothics retain a sliver of their former selves, feeling regret and longing for the knowledge they lost. These Nothics may seek redemption or a way to reverse their curse, but most are consumed by their hunger for secrets and darkness.\n\nIn combat, Nothics use their psychic abilities to weaken and confuse their enemies, often driving them to madness with their mind-altering gaze. They are dangerous opponents that should not be underestimated, as they are always on the hunt for new secrets to devour."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b95-c96c-7a2f-8200-c81abe666305'::uuid,'Nycaloth','NeutralEvil','9 (XP 5 000; PB +4)',5000,4,'Soldier','Large',18,NULL,152,'16d10+64','40 ft.',NULL,NULL,'60 ft.',20,11,19,12,10,15,'{"Stealth": 4, "Perception": 4}','Acid, Poison; Poisoned','Blindsight 60 ft., Passive Perception 14','Abyssal, Infernal; telepathy 60 ft.',4,0,5,0,2,1,4,'[]','Habitat: Planar (Gehenna)','Fiend','Yugoloth','{"value":"Wings beat ominously as its eyes gleam with malevolent intelligence"}','{"value": "Nycaloths are powerful fiends native to the Abyss, known for their cunning and manipulation skills. They often serve as commanders or enforcers in demonic armies, using their intelligence and magical abilities to lead their forces to victory. Nycaloths are skilled in both melee combat and spellcasting, making them formidable opponents on the battlefield.\n\nThese fiends are known for their loyalty to their masters, often serving powerful demon lords or other evil entities in exchange for power and influence. However, nycaloths are also known for their treachery and will not hesitate to betray their allies if it serves their own interests.\n\nNycaloths have a humanoid appearance, with dark, leathery skin and sharp horns protruding from their heads. They are skilled in deception and manipulation, often using their charm and guile to manipulate others to do their bidding.\n\nIn combat, nycaloths are known for their use of powerful spells, such as fireball and lightning bolt, as well as their ability to summon other fiends to aid them in battle. They are also skilled with weapons, often wielding swords or other melee weapons with deadly precision.\n\nOverall, nycaloths are dangerous and cunning adversaries, whose loyalty can never be fully trusted. It is wise to approach these fiends with caution and to always be on guard for their deceitful schemes."}',0,'Monster Manual 2024','Yugoloth','Cold, Fire, Lightning',9.0,NULL),
	 ('01990b96-141a-7c8e-a5ac-ebc1d7950b47'::uuid,'Octopus','Unaligned','0 (XP 10; PB +2)',10,2,'Ambusher','Small',12,NULL,3,'1d6','5 ft.',NULL,'30 ft.',NULL,4,15,11,3,10,4,'{"Stealth": 6, "Perception": 2}','None','Darkvision 30 ft., Passive Perception 12','None',0,2,3,0,3,4,2,'[]',NULL,'Beast','','{"value":"Tentacles writhe and coil, leaving a slick trail in their wake"}','{"value": "In Dungeons and Dragons 5th edition, the octopus is a creature commonly found in coastal waters and deep oceans. They are known for their intelligence, adaptability, and skill in camouflage. Octopuses have eight tentacles, each lined with suction cups that allow them to grasp and manipulate objects with great dexterity.\n\nIn D&D lore, octopuses are often portrayed as cunning and elusive creatures. They are known for their ability to change color and texture to blend in with their surroundings, making them difficult to spot. They are also skilled hunters, using their tentacles to capture prey and their sharp beaks to crush and devour it.\n\nSome octopuses in D&D are also rumored to possess magical abilities, such as the ability to cast spells or control water. These creatures are often feared and respected by sailors and coastal communities, who believe them to be powerful and mysterious beings.\n\nOverall, the octopus in D&D is a fascinating and dangerous creature that adds an element of mystery and intrigue to underwater adventures."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b96-2d76-75a0-8de7-dd29eb59c7c2'::uuid,'Ogre','ChaoticEvil','2 (XP 450; PB +2)',450,-1,'Brute','Large',11,NULL,68,'8d10+24','40 ft.',NULL,NULL,NULL,19,8,16,5,7,7,'{}','None','Darkvision 60 ft., Passive Perception 8','Common, Giant',3,-1,4,-2,-2,-3,2,'["Greatclub", "Javelins (3)"]','Habitat: Arctic, Desert, Forest, Grassland, Hill, Mountain, Swamp, Underdark','Giant','','{"value":"Hulking brute bellows, swinging its massive club with reckless abandon."}','{"value": "Ogres are large, brutish humanoid creatures known for their incredible strength and formidable size. They are typically depicted as being around ten feet tall, with a hulking build and greenish skin. Ogres are known for their insatiable appetite and are often portrayed as being dim-witted and easily manipulated by more intelligent creatures.\n\nIn D&D lore, ogres are typically depicted as being evil and violent, often terrorizing villages and travelers in their quest for food and treasure. They are known for their love of raiding and pillaging, and are often hired as mercenaries by more powerful creatures.\n\nOgres are not particularly intelligent, but they make up for it with their sheer physical strength and toughness. They are formidable opponents in combat, able to wield large weapons with ease and shrug off blows that would fell lesser creatures.\n\nIn some D&D settings, ogres are depicted as being part of a larger hierarchy of giants, with more powerful giants such as hill giants and frost giants ruling over them. Ogres are often portrayed as being at the bottom of this hierarchy, serving as foot soldiers and laborers for their more powerful kin.\n\nOverall, ogres are fearsome and dangerous creatures that adventurers would do well to avoid if possible. Their sheer strength and ferocity make them formidable opponents, and their penchant for violence and destruction make them a menace to all who cross their path."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b96-40d7-77e8-800f-70598f4d229f'::uuid,'Ogre Zombie','NeutralEvil','2 (XP 450; PB +2)',450,-2,'Brute','Large',8,NULL,85,'9d10+36','30 ft.',NULL,NULL,NULL,19,6,18,3,6,5,'{}','Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 8','Understands Common and Giant but can''t speak',4,-2,4,0,-3,-4,2,'[]','Habitat: Planar (Shadowfell), Underdark, Urban','Undead','','{"value":"Stench of decay fills the air as it groans, dragging its rotting limbs."}','{"value": "Ogre zombies are terrifying undead creatures that are created when ogres are reanimated through dark necromantic magic. These creatures are even more powerful and dangerous than regular ogres, as they retain their brute strength and ferocity while also gaining the resilience and relentless nature of undead creatures.\n\nOgre zombies are often used as shock troops by necromancers and other dark magic users who seek to terrorize and dominate the living. They are typically found guarding ancient ruins, dark dungeons, and other places where evil magic holds sway.\n\nIn combat, ogre zombies are relentless and brutal, using their massive strength to smash through their enemies with powerful strikes. They are nearly impervious to pain and can shrug off most attacks, making them formidable opponents on the battlefield.\n\nDespite their terrifying appearance and relentless nature, ogre zombies are not truly sentient beings. They are mindless undead creatures driven only by a dark hunger for destruction and death. They will mindlessly attack anything that crosses their path, whether friend or foe, until they are destroyed or their master commands them to stop.\n\nOverall, ogre zombies are a terrifying and dangerous foe that should be approached with caution and dealt with swiftly before they can wreak havoc on the living."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b96-6e90-76e8-b678-74bb26715be0'::uuid,'Oni','LawfulEvil','7 (XP 2 900; PB +3)',2900,0,'Brute','Large',17,NULL,119,'14d10+42','30 ft.',NULL,NULL,'30 ft.',19,11,16,14,12,15,'{"Arcana": 5, "Deception": 8, "Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','Common, Giant',6,3,4,4,5,2,3,'[]','Habitat: Forest, Urban','Fiend','','{"value":"Steely gaze pierces the darkness, a cruel smile curling its lips"}','{"value": "In Dungeons and Dragons, Oni are large, monstrous humanoid creatures with a demonic appearance. They are often depicted as tall, muscular beings with sharp claws, tusks, and horns. Oni are known for their strength, cunning, and malevolence, and are often considered to be agents of chaos and destruction.\n\nIn D&D lore, Oni are said to be shape-shifters, able to take on different forms to deceive and manipulate their prey. They are also known for their magical abilities, particularly in the use of illusions and mind control. Oni are often depicted as being cruel and sadistic, delighting in causing pain and suffering to those they encounter.\n\nOni are typically found in remote and desolate areas, where they can prey on unsuspecting travelers and villages. They are often associated with evil deeds, such as kidnapping, murder, and other acts of violence. In D&D campaigns, Oni are often used as powerful and dangerous foes for adventurers to face, requiring skill, strategy, and courage to defeat."}',0,'Monster Manual 2024 (BR)','','Cold',7.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b96-8ea6-7451-93c7-c16bef0e1a08'::uuid,'Otyugh','TrueNeutral','5 (XP 1 800; PB +3)',1800,0,'Brute','Large',14,NULL,104,'11d10+44','30 ft.',NULL,NULL,NULL,16,11,19,6,13,6,'{}','None','Darkvision 120 ft., Passive Perception 11','Otyugh; telepathy 120 ft. (doesn''t allow the receiving creature to respond telepathically)',7,0,3,1,-2,-2,3,'[]','Habitat: Underdark','Aberration','','{"value":"Slime-drenched tendrils writhe and grasp hungrily at the air"}','{"value": "The Otyugh is a monstrous creature that resides in dank and filthy environments such as sewers, swamps, and garbage dumps. It is a large, three-eyed aberration with a bloated body covered in writhing tentacles. The Otyugh is a scavenger by nature, feeding on rotting organic matter and waste.\n\nLegends say that the Otyugh was created by a malevolent deity as a guardian of filth and decay. It is said to be incredibly intelligent and cunning, using its tentacles to grab and crush prey before consuming it whole. Despite its grotesque appearance, the Otyugh is not inherently evil and will only attack creatures that threaten its territory or food source.\n\nAdventurers who come across an Otyugh may be able to negotiate with it, offering it food or treasure in exchange for safe passage through its lair. However, those who underestimate the Otyugh''s intelligence and strength may find themselves quickly overwhelmed by its deadly tentacles and acidic secretions.\n\nIn some cultures, the Otyugh is revered as a symbol of waste and decay, with some even worshipping it as a deity of filth and destruction. These cults often make offerings to the Otyugh in exchange for its protection or favor in battle. Overall, the Otyugh is a fearsome and mysterious creature that lurks in the darkest corners of the world, ready to strike at any who dare to disturb its domain."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b96-ae8b-741f-9bf9-785e774fecbf'::uuid,'Owl','Unaligned','0 (XP 10; PB +2)',10,1,'Ambusher','Tiny',11,NULL,1,'1d4-1','5 ft.',NULL,NULL,'60 ft.',3,13,8,2,12,7,'{"Stealth": 5, "Perception": 5}','None','Darkvision 120 ft., Passive Perception 15','None',1,1,4,1,2,4,2,'[]',NULL,'Beast','','{"value":"Silent wings glide overhead, eyes glowing with predatory focus."}','{"value": "In Dungeons and Dragons 5th edition, the owl is a creature known for its wisdom, keen senses, and ability to see in the dark. Owls are often associated with magic and mystery, and are sometimes seen as companions or familiars to spellcasters.\n\nIn D&D lore, owls are often portrayed as intelligent and elusive creatures that can communicate with other animals and even some humanoids. They are known for their ability to fly silently and swiftly, making them excellent hunters and scouts.\n\nSome cultures believe that owls are harbingers of death or bad luck, while others see them as symbols of wisdom and protection. In some regions, owls are revered as guardians of the night and are believed to bring good fortune to those who show them respect.\n\nOverall, owls are a versatile and intriguing creature in D&D lore, often playing a role in quests and adventures as guides, messengers, or even magical companions. Their mysterious nature and connection to the supernatural make them a popular choice for players and Dungeon Masters alike."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b96-d276-73e6-a742-7b79624e4238'::uuid,'Pegasus','ChaoticGood','2 (XP 450; PB +2)',450,2,'Support','Large',12,NULL,59,'7d10+21','60 ft.',NULL,NULL,'90 ft.',18,15,16,10,15,13,'{"Perception": 6}','None','Passive Perception 16','Understands Celestial, Common, Elvish, and Sylvan but can''t speak',5,4,4,4,3,0,2,'[]','Habitat: Forest, Grassland, Hill, Planar (Upper Planes)','Celestial','','{"value":"Wings beat gracefully, mane shimmering in the sunlight"}','{"value": "In Dungeons and Dragons 5th edition, the Pegasus is a majestic and noble creature that combines the grace and beauty of a horse with the wings of a bird. They are known for their loyalty and bravery, often serving as mounts for good-aligned characters such as paladins or clerics.\n\nAccording to lore, Pegasi are said to be descended from the gods themselves, specifically the god of the sky and the goddess of beauty. They are commonly found in the wild, soaring through the skies and making their homes in remote and idyllic locations.\n\nPegasi are known for their ability to fly at incredible speeds and their keen intelligence. They are often sought after as companions and mounts by those who seek to do good in the world. However, they are also fiercely independent creatures and will not hesitate to defend themselves or their allies if threatened.\n\nIn D&D, Pegasi are typically depicted as white or light-colored horses with large, feathered wings. They are often revered by those who encounter them, and many cultures consider them to be symbols of purity, grace, and freedom."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b96-e481-71ab-8062-a8a4a65631bd'::uuid,'Performer Legend','TrueNeutral','10 (XP 5 900; PB +4)',5900,9,NULL,'Medium',20,NULL,162,'25d8+50','30 ft.',NULL,NULL,NULL,12,20,14,15,16,20,'{"Stealth": 9, "Athletics": 5, "Acrobatics": 13, "Perception": 7, "Performance": 13}','None','Passive Perception 17','Common plus two other languages',2,9,1,7,9,6,4,'[]','Habitat: Any','Humanoid','','{"value":"Its eyes sparkle with mischief as it twirls and leaps in a dazzling display."}','{"value": "The Performer Legend is a unique and powerful creature that hails from the Feywild, a magical realm filled with whimsical and mysterious beings. This creature is said to have been created by a powerful archfey as a form of entertainment, with the ability to charm and captivate any audience with its mesmerizing performances.\n\nThe Performer Legend is known for its stunning beauty and grace, with shimmering, iridescent wings that sparkle like precious gems in the sunlight. Its voice is said to be like music itself, able to enchant even the most stoic of listeners. It is said that those who witness the Performer Legend''s performances are left in a state of awe and wonder, unable to tear themselves away from its spellbinding presence.\n\nDespite its enchanting abilities, the Performer Legend is not to be underestimated in combat. It is a skilled fighter, able to move with lightning speed and strike with deadly precision. Its attacks are as beautiful as they are deadly, leaving opponents bewildered and disoriented.\n\nLegends say that those who are able to earn the favor of the Performer Legend may be granted great boons and blessings, while those who incur its wrath may find themselves cursed with misfortune and ill luck. Many adventurers seek out the Performer Legend in the hopes of witnessing its incredible performances or earning its favor, but few are able to survive the encounter with this enigmatic and powerful creature."}',0,'Monster Manual 2024','','None',10.0,NULL),
	 ('01990b96-f6b6-748a-827f-8d1a17f2441c'::uuid,'Performer Maestro','TrueNeutral','6 (XP 2 300; PB +3)',2300,7,'Controller','Medium',18,NULL,110,'17d8+34','30 ft.',NULL,NULL,NULL,12,18,14,13,14,19,'{"Stealth": 7, "Athletics": 4, "Acrobatics": 10, "Perception": 5, "Performance": 10}','None','Passive Perception 15','Common plus one other language',2,7,1,2,7,1,3,'["Rapier"]','Habitat: Any','Humanoid','','{"value":"With a flourish, it twirls its baton, commanding unseen forces with precision."}','{"value": "The Performer Maestro is a unique and mysterious monster in the world of Dungeons and Dragons. They are known for their incredible musical abilities and captivating performances that can mesmerize and enchant any audience. \n\nLegend has it that the Performer Maestro was once a skilled bard or musician who made a pact with a powerful entity in exchange for enhanced musical talents. This pact transformed them into a being of immense power and charisma, capable of weaving magic through their music and controlling the minds of those who listen to them.\n\nThe Performer Maestro is often encountered in elaborate theaters or grand concert halls, where they put on dazzling displays of music and magic that leave audiences in awe. However, those who cross paths with the Performer Maestro must beware, as their enchanting melodies can also be used to manipulate and control unsuspecting victims.\n\nDespite their otherworldly abilities, the Performer Maestro is a tragic figure, forever bound to their pact and unable to escape their fate. They wander the world seeking new audiences to entertain and new souls to ensnare with their haunting melodies, forever trapped in a cycle of performance and manipulation."}',0,'Monster Manual 2024','','None',6.0,NULL),
	 ('01990b97-01f6-7da7-8612-67543bde9acb'::uuid,'Peryton','ChaoticEvil','2 (XP 450; PB +2)',450,3,'Skirmisher','Medium',13,NULL,33,'6d8+6','20 ft.',NULL,NULL,'60 ft.',16,12,13,9,12,10,'{"Stealth": 3, "Perception": 5}','None','Passive Perception 15','Understands Common and Elvish but can''t speak',1,1,3,1,0,-1,2,'[]','Habitat: Hill, Mountain','Monstrosity','','{"value":"Wings beat in a haunting rhythm, casting shadows on the ground"}','{"value": "The Peryton is a creature from Greek mythology and is also featured in Dungeons and Dragons as a monster. In D&D, the Peryton is a large, bird-like creature with the head and upper body of a stag. It is known for its ability to cast a shadow that resembles that of a humanoid, and it is said that when a Peryton kills a humanoid, its shadow will transform into that of the victim.\n\nPerytons are said to be extremely territorial and aggressive, often attacking any intruders that enter their territory. They are also known for their exceptional speed and agility, making them formidable opponents in combat.\n\nIn terms of lore, Perytons are often associated with themes of vengeance and retribution. They are said to be creatures of darkness and are often seen as symbols of death and destruction. Some believe that Perytons are the result of a curse placed upon a group of humans who committed a great sin, causing them to transform into these monstrous creatures.\n\nOverall, the Peryton is a fearsome and mysterious creature in the world of Dungeons and Dragons, making for a challenging encounter for any adventuring party."}',0,'Monster Manual 2024','','None',2.0,NULL),
	 ('01990b97-5160-7cd4-95e7-ce1ec04bd346'::uuid,'Pirate Admiral','TrueNeutral','12 (XP 8 400; PB +4)',8400,10,'Leader','Medium',20,NULL,182,'28d8+56','30 ft.',NULL,NULL,NULL,14,22,14,12,14,19,'{"Athletics": 6, "Acrobatics": 10, "Perception": 6}','None','Passive Perception 16','Common plus one other language',2,10,6,6,8,1,4,'["Pistol", "Scimitar"]','Habitat: Any','Humanoid','','{"value":"With a booming voice, the Pirate Admiral raises his cutlass, demanding surrender."}','{"value": "The Pirate Admiral is a powerful and feared leader among pirate crews, known for their strategic prowess and ruthless tactics. They are often former captains who have risen to the rank of admiral through their cunning and strength in battle.\n\nThe Pirate Admiral is typically a humanoid creature, often a human or half-orc, who commands a crew of loyal sailors and cutthroats. They are skilled in both combat and leadership, able to inspire their crew to great feats of bravery and cunning.\n\nThe Pirate Admiral is also known for their love of treasure and plunder, often leading their crew on daring raids and expeditions to acquire riches and magical artifacts. They are cunning negotiators and master manipulators, able to outwit and outmaneuver their enemies in both battle and diplomacy.\n\nIn combat, the Pirate Admiral is a formidable opponent, wielding a variety of weapons and spells to take down their foes. They are often accompanied by a loyal first mate or bodyguard, who assists them in battle and helps to protect them from harm.\n\nOverall, the Pirate Admiral is a dangerous and cunning foe, not to be underestimated on the high seas or in any other setting. Their lore is filled with tales of daring escapes, epic battles, and legendary treasure hoards, making them a fearsome and respected figure in the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','None',12.0,NULL),
	 ('01990b97-7467-78e1-9bde-38e3da78c417'::uuid,'Pirate Captain','Any','6 (XP 2,300; PB +3)',2300,7,'Leader','Medium',17,NULL,84,'13d8+26','30 ft.',NULL,NULL,NULL,10,18,14,10,14,17,'{"Acrobatics": 7, "Perception": 5}','None','Passive Perception 15','Common plus one other language',2,7,3,5,6,0,3,'["Pistol", "Rapier"]','Habitat: Any','Humanoid','','{"value":"Swaggering with a cutlass in hand, the Pirate Captain\u0027s eyes gleam with greed."}','{"value": "The Pirate Captain is a formidable and cunning enemy encountered on the high seas. Known for their ruthless tactics and cunning strategies, Pirate Captains are often skilled fighters and leaders of their crew of cutthroats and pirates.\n\nFueled by a desire for power, wealth, and control, Pirate Captains are known for their willingness to do whatever it takes to achieve their goals. They are often charismatic and persuasive, able to rally their crew and inspire fear in their enemies.\n\nPirate Captains are typically equipped with a variety of weapons, including swords, pistols, and cutlasses. They are also known to have a keen sense of strategy, using their knowledge of the seas and their enemies to outsmart and outmaneuver their foes.\n\nIn battle, Pirate Captains are known for their fierce determination and their willingness to fight to the death to protect their ship and crew. They are often seen as symbols of power and authority among pirates, with many aspiring to one day become a Pirate Captain themselves.\n\nOverall, the Pirate Captain is a dangerous and cunning foe that should not be underestimated. With their skills in combat and leadership, they are a force to be reckoned with on the high seas."}',0,'Monster Manual 2024 (BR)','','None',6.0,NULL),
	 ('01990b97-aa44-7ab6-bef5-4beac1312331'::uuid,'Pit Fiend','LawfulEvil','20 (XP 25 000; PB +6)',25000,14,'Solo','Large',21,NULL,337,'27d10+189','30 ft.',NULL,NULL,'60 ft.',26,14,24,22,18,24,'{"Perception": 10, "Persuasion": 19}','Fire, Poison; Poisoned','Truesight 120 ft., Passive Perception 20','Infernal; telepathy 120 ft.',7,8,8,10,7,6,6,'[]','Habitat: Planar (Nine Hells)','Fiend','Devil','{"value":"Wings spread wide, it snarls with fiery breath, eyes ablaze with malice."}','{"value": "Pit Fiends are powerful and malevolent devils from the Nine Hells in the Dungeons and Dragons universe. They are among the highest ranking devils, second only to the Archdevils themselves. Pit Fiends are known for their immense strength, cunning intellect, and mastery of dark magic.\n\nPit Fiends are often called upon by their superiors to lead armies of lesser devils in battles against the forces of good. They are also skilled manipulators and are known for making deals with mortals in exchange for their souls. Pit Fiends are said to be able to grant incredible power to those who make pacts with them, but at a terrible cost.\n\nIn combat, Pit Fiends are fearsome opponents, wielding powerful spells and deadly physical attacks. They are immune to fire and poison, and have resistance to cold, lightning, and non-magical weapons. They can also summon other devils to aid them in battle.\n\nOverall, Pit Fiends are some of the most dangerous and feared creatures in the D&D universe, and encountering one is sure to spell trouble for any adventurers brave enough to face them."}',0,'Monster Manual 2024 (BR)','Devil','Cold',20.0,NULL),
	 ('01990b97-b994-766c-846f-2b1739d83747'::uuid,'Pixie Wonderbringer','NeutralGood','5 (XP 1 800; PB +3)',1800,5,'Support','Tiny',15,NULL,60,'24d4','10 ft.',NULL,NULL,'30 ft.',2,20,10,11,14,18,'{"Arcana": 3, "Stealth": 8, "Perception": 5}','None','Passive Perception 15','Common, Elvish, Sylvan',0,5,-4,2,4,0,3,'[]','Habitat: Forest, Planar (Feywild)','Fey','','{"value":"Light dances around her, leaving a trail of shimmering magic in her wake."}','{"value": "Pixie Wonderbringers are a special type of pixie in the world of Dungeons and Dragons, known for their exceptional magical abilities and their affinity for nature. These pixies are often seen as protectors of the natural world, using their powers to heal and restore balance to the environment.\n\nPixie Wonderbringers are skilled in both healing and offensive magic, able to cast spells such as cure wounds and fairy fire with ease. They are also known for their ability to communicate with animals and plants, often using this skill to gather information or aid in their quests.\n\nDespite their small size, Pixie Wonderbringers are fierce and courageous warriors, willing to defend their home and allies at all costs. They are revered by many as symbols of hope and inspiration, their presence often bringing peace and harmony wherever they go.\n\nOverall, Pixie Wonderbringers are beloved creatures in the world of D&D, known for their kindness, bravery, and powerful magic. They are often sought out by adventurers seeking their aid in quests or battles, knowing that their presence can turn the tide in their favor."}',0,'Monster Manual 2024','','None',5.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b97-fc76-72a6-afa9-1b7baa7356e7'::uuid,'Planetar','LawfulGood','16 (XP 15 000; PB +5)',15000,10,'Leader','Large',19,NULL,262,'21d10+147','40 ft.',NULL,NULL,'120 ft.',24,20,24,19,22,25,'{"Perception": 11}','Charmed, Exhaustion, Frightened','Truesight 120 ft., Passive Perception 21','All; telepathy 120 ft.',12,5,12,11,12,4,5,'[]','Habitat: Planar (Upper Planes)','Celestial','Angel','{"value":"Radiant wings beat, casting a warm glow as it lands gracefully before you."}','{"value": "In Dungeons and Dragons 5th edition, a Planetar is a celestial being that is a powerful servant of the gods. They are typically depicted as towering figures with shining wings and radiant auras, embodying the ideals of goodness, justice, and righteousness.\n\nPlanetars are often called upon by deities to serve as champions in battles against evil forces, acting as divine messengers and enforcers of cosmic justice. They are known for their immense strength and magical abilities, including the power to cast spells, heal the wounded, and smite their enemies with holy energy.\n\nDespite their divine origins, Planetars are not infallible and can sometimes be swayed by mortal emotions and desires. However, they are ultimately driven by a sense of duty and a commitment to upholding the values of their deity, making them formidable allies in the fight against evil.\n\nIn D&D lore, Planetars are typically associated with the upper planes of existence, such as Mount Celestia or Elysium, where they serve as guardians and protectors of the celestial realms. They are revered by mortals as symbols of hope and inspiration, and their presence is often seen as a sign of divine favor or intervention."}',0,'Monster Manual 2024 (BR)','Angel','Radiant',16.0,NULL),
	 ('01990b98-17cd-7ac5-a040-053dea768afa'::uuid,'Polar Bear','Unaligned','2 (XP 450; PB +2)',450,2,'Brute','Large',12,NULL,42,'5d10+15','40 ft.',NULL,'40 ft.',NULL,20,14,16,2,13,7,'{"Stealth": 4, "Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','None',3,2,5,1,-2,-4,2,'[]',NULL,'Beast','','{"value":"Hulking form looms, steam rising from its hot breath in the icy air"}','{"value": "In the world of Dungeons and Dragons, the Polar Bear is a large and powerful predator known for its strength and ferocity. These massive creatures are native to cold and icy regions, such as the Arctic, where they roam the frozen tundra in search of food.\n\nPolar Bears are known for their thick white fur, which helps them blend in with their snowy surroundings. They are expert swimmers and are often found hunting for seals near the edge of the ice. Despite their size and strength, Polar Bears are also surprisingly agile, able to move quickly and silently across the ice and snow.\n\nIn D&D lore, Polar Bears are often depicted as solitary creatures, fiercely territorial and protective of their hunting grounds. They are known to be highly aggressive when provoked and will not hesitate to attack anything that threatens them or their territory.\n\nAdventurers who encounter a Polar Bear in the wild must exercise caution and be prepared for a fierce battle, as these creatures are formidable opponents with razor-sharp claws and powerful jaws. However, those who are able to defeat a Polar Bear may be rewarded with valuable resources, such as its thick fur and meat, which can be used for crafting or sustenance."}',0,'Monster Manual 2024 (BR)','','Cold',2.0,NULL),
	 ('01990b98-20ab-7d35-a999-ed9935a49a1c'::uuid,'Poltergeist','ChaoticNeutral','2 (XP 450; PB +2)',450,2,'Support','Medium',12,NULL,22,'5d8','5 ft.',NULL,NULL,'50 ft.',1,14,11,10,10,14,'{}','Necrotic, Poison; Charmed, Exhaustion, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Darkvision 60 ft., Passive Perception 10','Common plus one other language',0,2,-5,0,2,0,2,'[]','Habitat: Underdark, Urban','Undead','','{"value":"Shadows dance wildly as objects hurl around the room in a chaotic frenzy"}','{"value": "Poltergeists are malevolent spirits that haunt the material plane, causing chaos and fear wherever they go. They are typically the restless souls of individuals who died in a violent or traumatic manner, unable to find peace in the afterlife. Poltergeists are known for their ability to manipulate objects in the physical world, often throwing them around or causing them to levitate. They feed off of the negative emotions of the living, growing stronger as they sow fear and discord.\n\nTo combat a poltergeist, one must first try to discover the source of its unrest and help it find peace. This may involve performing a ritual to lay the spirit to rest or confronting it directly in battle. Poltergeists are resistant to physical attacks, but can be banished with holy symbols or spells that ward off evil spirits. It is said that the only way to truly destroy a poltergeist is to find and destroy the object or person that ties it to the material plane, releasing its soul to the afterlife."}',0,'Monster Manual 2024','','Acid, Bludgeoning, Cold, Fire, Lightning, Piercing, Slashing, Thunder',2.0,NULL),
	 ('01990b98-537e-771e-9e74-036bc64ccefc'::uuid,'Priest','TrueNeutral','2 (XP 450; PB +2)',450,0,'Support','Medium',13,NULL,38,'7d8+7','30 ft.',NULL,NULL,NULL,16,10,12,13,16,13,'{"Medicine": 7, "Religion": 5, "Perception": 5}','None','Passive Perception 15','Common plus one other language',1,0,3,3,1,1,2,'["Chain Shirt", "Holy Symbol", "Mace"]','Habitat: Any','Humanoid','Cleric','{"value":"Eyes glow with a divine light as it raises its hands in prayer."}','{"value": "In Dungeons and Dragons 5th Edition, a Priest is a humanoid spellcaster who specializes in divine magic. They are typically devoted followers of a specific deity and serve as intermediaries between their god and the mortal world. Priests can be found in temples, churches, and other religious institutions, where they lead worship services, perform rituals, and provide spiritual guidance to their followers.\n\nPriests are often skilled healers, using their magic to cure wounds and illnesses, as well as to protect and buff their allies in combat. They also have access to a variety of offensive spells, such as smiting their enemies with divine power or banishing undead creatures. In addition to their spellcasting abilities, priests are usually proficient in the use of simple weapons and light armor.\n\nIn terms of lore, priests are seen as pillars of their communities, providing comfort and support to those in need. They are respected and trusted figures, often called upon to officiate weddings, funerals, and other important ceremonies. Priests are also tasked with upholding the tenets of their faith and defending their followers against supernatural threats.\n\nOverall, priests play a crucial role in the world of Dungeons and Dragons, representing the divine forces that shape the cosmos and guide the destinies of mortals."}',0,'Monster Manual 2024 (BR)','Cleric','None',2.0,NULL),
	 ('01990b98-9163-764a-8dda-423671a6312c'::uuid,'Psychic Gray Ooze','Unaligned','1 (XP 200; PB +2)',200,-1,'Ambusher','Medium',9,NULL,37,'5d8+15','10 ft.','10 ft.',NULL,NULL,12,8,16,10,6,2,'{"Stealth": 3}','Blinded, Charmed, Deafened, Exhaustion, Frightened, Grappled, Prone, Restrained','Blindsight 60 ft., Passive Perception 8','—',3,-1,1,-2,-4,0,2,'[]','Habitat: Underdark','Ooze','','{"value":"It pulses rhythmically, sending waves of disorienting thoughts through your mind"}','{"value": "The Psychic Gray Ooze is a unique and rare variant of the traditional Gray Ooze found in dungeons and dark places. This creature is known for its ability to manipulate and control the minds of those around it through psychic energy.\n\nThe Psychic Gray Ooze is believed to have been the result of a magical experiment gone wrong, where a regular Gray Ooze was exposed to powerful psychic energy, causing it to mutate and gain new abilities. This creature now has the ability to project psychic attacks and illusions, driving its enemies mad with fear and confusion.\n\nThe Psychic Gray Ooze is a dangerous foe to encounter in battle, as its psychic attacks can cause mental damage and leave its victims vulnerable to further attacks. It is also known to be highly resistant to physical attacks, making it a formidable opponent for even the most experienced adventurers.\n\nLegends say that those who have faced the Psychic Gray Ooze and survived have been haunted by its psychic influence, experiencing vivid nightmares and hallucinations long after the encounter. Some even claim that the creature has the ability to control minds and bend them to its will, turning its victims into mindless slaves.\n\nOverall, the Psychic Gray Ooze is a mysterious and enigmatic creature, shrouded in dark magic and psychic energy. Adventurers should proceed with caution when encountering this monster, as its powers are not to be underestimated."}',0,'Monster Manual 2024','','Acid, Cold, Fire, Psychic',1.0,NULL),
	 ('01990b98-c8c2-770c-a59a-a85a42827d1e'::uuid,'Purple Worm','Unaligned','15 (XP 13 000; PB +5)',13000,3,'Brute','Gargantuan',18,NULL,247,'15d20+90','50 ft.',NULL,NULL,NULL,28,7,22,1,8,4,'{}','None','Blindsight 30 ft., Tremorsense 60 ft., Passive Perception 9','—',11,-2,9,4,-3,-5,5,'[]','Habitat: Desert, Underdark','Monstrosity','','{"value":"Giant worm burrows through the earth, its maw dripping with acidic slime."}','{"value": "The Purple Worm is a massive and fearsome creature that dwells deep underground in the dark and twisting tunnels of the Underdark. These colossal beasts are known for their insatiable hunger and their ability to swallow prey whole. They are typically encountered in areas with abundant sources of food, such as underground caverns filled with other creatures.\n\nThe Purple Worm is easily recognizable by its enormous size, reaching up to 50 feet in length and weighing several tons. Its body is covered in thick, purple-colored scales that provide excellent protection against attacks. The creature has a large, gaping maw filled with rows of razor-sharp teeth, which it uses to snatch up unsuspecting victims and devour them in one swift gulp.\n\nIn combat, the Purple Worm relies on its brute strength and powerful bite to defeat its enemies. It can burrow through solid rock with ease, surprising its prey from below and launching devastating attacks. Its thick hide and natural resilience make it a formidable opponent in battle, capable of shrugging off most forms of damage.\n\nLegends say that Purple Worms are ancient creatures that have existed for centuries, feeding on whatever crosses their path. Some even believe that these creatures are the spawn of a malevolent deity, sent to terrorize the depths of the earth and instill fear in all who venture into their domain. Only the bravest and most skilled adventurers dare to face off against a Purple Worm and live to tell the tale."}',0,'Monster Manual 2024 (BR)','','None',15.0,NULL),
	 ('01990b98-dcf3-77dc-a635-5cc1cb3d4dcd'::uuid,'Quaggoth Thonot','ChaoticNeutral','3 (XP 700; PB +2)',700,1,'Brute','Medium',15,NULL,67,'9d8+27','30 ft.','30 ft.',NULL,NULL,17,12,16,6,14,7,'{"Athletics": 5}','Poison; Poisoned','Darkvision 120 ft., Passive Perception 12','Undercommon',3,1,3,2,-2,-2,2,'[]','Habitat: Underdark','Monstrosity','','{"value":"Loathsome creature snarls, dripping with foul-smelling slime."}','{"value": "Quaggoth Thonot is a creature that inhabits the Underdark in the world of Dungeons and Dragons. They are a sub-race of the quaggoth, a savage and brutish race of humanoid creatures that resemble a mix between a bear and a gorilla. Quaggoth Thonot are known for their incredible strength and ferocity in battle.\n\nThese creatures are typically found in the dark and dangerous tunnels of the Underdark, where they live in small tribes and hunt for food. They are known to be fiercely territorial and will attack any intruders that come into their territory. Quaggoth Thonot are also known to be skilled in combat, using their sharp claws and teeth to tear through their enemies.\n\nDespite their savage nature, some quaggoth thonot have been known to form alliances with other creatures in the Underdark, such as drow or duergar. These alliances are usually formed out of necessity, as the quaggoth thonot are often seen as valuable allies in battle due to their strength and combat abilities.\n\nOverall, Quaggoth Thonot are fearsome creatures that are best avoided by adventurers venturing into the dark depths of the Underdark."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01990b99-0193-7ff5-af07-4e6b690c14ab'::uuid,'Quasit','ChaoticEvil','1 (XP 200; PB +2)',200,3,'Ambusher','Tiny',13,NULL,25,'10d4','40 ft.',NULL,NULL,NULL,5,17,10,7,10,10,'{"Stealth": 5}','Poison; Poisoned','Darkvision 120 ft., Passive Perception 10','Abyssal, Common',0,3,3,0,0,2,2,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Sneers with malice, eyes glowing with wicked delight."}','{"value": "Quasits are small, impish demons that serve higher-ranking demons and devils. They are known for their mischievous and chaotic nature, often causing trouble and chaos wherever they go. Quasits are skilled shape-shifters, able to take on the form of a small, bat-winged humanoid or a tiny, black, smoky creature. They are also capable of turning invisible at will, making them excellent spies and scouts for their masters.\n\nQuasits are often summoned by warlocks or evil spellcasters to serve as familiars, providing them with magical assistance and carrying out their nefarious tasks. Despite their small size, quasits are cunning and intelligent creatures, able to manipulate and deceive others to further their own goals.\n\nIn combat, quasits are quick and agile, using their claws and teeth to attack their enemies. They are also able to cast a variety of spells, such as detect magic, detect good and evil, and invisibility, to aid them in battle. Though individually weak, quasits can be dangerous when working together in a group or alongside more powerful demons or devils.\n\nOverall, quasits are devious and malevolent creatures that embody the chaotic and destructive nature of the Abyss. They are not to be underestimated, as their cunning and magical abilities make them formidable foes for any adventurer."}',0,'Monster Manual 2024 (BR)','Demon','Cold, Fire, Lightning',1.0,NULL),
	 ('01990b99-0425-7cad-891b-d39b637c7eb5'::uuid,'Questing Knight','TrueNeutral','12 (XP 8 400; PB +4)',8400,7,'Leader','Medium',18,NULL,202,'27d8+81','30 ft.',NULL,NULL,NULL,20,16,16,11,12,18,'{"Athletics": 9, "Perception": 5, "Persuasion": 8}','Charmed, Frightened','Passive Perception 15','Common plus one other language',7,3,9,5,8,0,4,'["Greatsword", "Longbow", "Plate Armor"]','Habitat: Any','Humanoid','','{"value":"It charges forward, lance gleaming in the sunlight, eyes fixed on its target."}','{"value": "In the world of D&D 5e, the Questing Knight is a noble and valiant warrior who has dedicated their life to seeking out and completing quests in service of their deity or cause. These knights are known for their unwavering dedication to their mission, their exceptional combat skills, and their strong sense of honor and chivalry.\n\nQuesting Knights are often seen as symbols of hope and inspiration, as they are willing to go to great lengths and face great dangers in order to fulfill their quests and uphold their values. They are typically heavily armored and skilled in combat, wielding powerful weapons and often riding into battle on noble steeds.\n\nThese knights are often called upon to undertake quests that are deemed too dangerous or important for regular adventurers, and they are known for their ability to overcome seemingly insurmountable odds through sheer determination and skill. They are revered by many as heroes and champions of justice, and their deeds are often celebrated in songs and tales throughout the land.\n\nOverall, the Questing Knight is a noble and honorable figure in the world of D&D 5e, embodying the virtues of courage, loyalty, and selflessness in their quest for justice and righteousness."}',0,'Monster Manual 2024','','None',12.0,NULL),
	 ('01990b99-2af4-77f3-a870-49c221aed164'::uuid,'Rakshasa','LawfulEvil','13 (XP 10 000; PB +5)',10000,8,'Leader','Medium',17,NULL,221,'26d8+104','40 ft.',NULL,NULL,NULL,14,17,18,13,16,20,'{"Insight": 8, "Deception": 10, "Perception": 8}','Charmed, Frightened','Truesight 60 ft., Passive Perception 18','Common, Infernal',4,3,2,3,5,1,5,'[]','Habitat: Planar (Nine Hells), Urban','Fiend','','{"value":"Fiendish creature grins slyly, its eyes glowing with malevolent intent"}','{"value": "Rakshasas are fiendish, shape-shifting creatures with origins in Hindu mythology. In Dungeons & Dragons, they are powerful and cunning beings with a humanoid form, but with the head of a tiger. Rakshasas are known for their deceptive and manipulative nature, often using their shape-shifting abilities to blend in with society and gain power and influence.\n\nRakshasas are typically depicted as spellcasters, using their magical abilities to cast spells and manipulate those around them. They are also known for their ability to regenerate and their immunity to non-magical weapons. Rakshasas are often portrayed as villains in D&D campaigns, using their powers to further their own nefarious goals and cause chaos and destruction.\n\nIn terms of lore, Rakshasas are usually depicted as being part of a larger evil organization or serving a powerful demon lord. They are feared and respected within the fiendish hierarchy for their cunning and intelligence. Rakshasas are also known for their love of luxury and material wealth, often accumulating vast fortunes through their manipulations and deceptions. Overall, Rakshasas are dangerous and formidable foes in the world of Dungeons & Dragons, capable of outwitting even the most skilled adventurers."}',0,'Monster Manual 2024 (BR)','','None',13.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b99-37da-7b6a-8a53-9e5d69fef3a8'::uuid,'Rat','Unaligned','0 (XP 10; PB +2)',10,0,'Ambusher','Tiny',10,NULL,1,'1d4-1','20 ft.','20 ft.',NULL,NULL,2,11,9,2,10,4,'{"Perception": 2}','None','Darkvision 30 ft., Passive Perception 12','None',1,0,4,0,3,4,2,'[]',NULL,'Beast','','{"value":"Skittering across the filthy floor, its beady eyes fixed on your trembling form"}','{"value": "In Dungeons and Dragons 5th Edition, rats are small, common creatures that are often found scurrying around in dungeons, sewers, and other dark, damp places. They are known for their agility and cunning, as well as their ability to carry and spread diseases.\n\nRats are typically seen as low-level pests and nuisances by adventurers, but can still pose a threat in large numbers or if they are carrying a particularly virulent disease. They are often used as minions by more powerful creatures, such as wererats or necromancers, who may use them to spread chaos and disease in a city or town.\n\nRats are known for their sharp teeth and claws, which they use to tear into flesh and defend themselves when cornered. They are also known for their ability to squeeze through small spaces and move quickly, making them difficult to catch or trap.\n\nOverall, rats are seen as a minor threat in the world of Dungeons and Dragons, but they can still be dangerous in the right circumstances. Adventurers should always be cautious when encountering these creatures, as they are known for their ability to spread disease and cause chaos."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b99-44b3-76cb-a0a5-43abbb88098f'::uuid,'Raven','Unaligned','0 (XP 10; PB +2)',10,2,'Ambusher','Tiny',12,NULL,2,'1d4','10 ft.',NULL,NULL,'50 ft.',2,14,10,5,13,6,'{"Perception": 3}','None','Passive Perception 13','None',0,2,4,1,2,3,2,'[]',NULL,'Beast','','{"value":"Silent wings beat overhead, eyes gleaming with intelligence and curiosity."}','{"value": "In Dungeons and Dragons 5th edition, the Raven is a small, intelligent bird often associated with death and darkness. Ravens are known for their cunning and trickery, and are often seen as messengers or familiars of dark and mysterious beings.\n\nIn some D&D campaigns, ravens are said to be the spies and scouts of powerful necromancers or evil wizards, using their keen senses and ability to fly to gather information and report back to their masters. They are also sometimes seen as omens of death or harbingers of doom, with their cawing signaling impending danger or tragedy.\n\nRavens are known for their sharp beaks and talons, which they use to defend themselves or attack their enemies when necessary. They are highly intelligent creatures, capable of problem-solving and even learning to mimic human speech in some cases.\n\nOverall, ravens in D&D lore are often depicted as mysterious and enigmatic creatures, with a connection to the supernatural and the unknown. They are often used by DMs to add an element of foreboding or mystery to their campaigns, and can be both allies and adversaries to the player characters."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b99-5457-70dc-9bff-14b8eed31fd4'::uuid,'Red Dragon Wyrmling','ChaoticEvil','4 (XP 1,100; PB +2)',1100,2,'Solo','Medium',17,NULL,75,'10d8+30','30 ft.','30 ft.',NULL,'60 ft.',19,10,17,12,11,15,'{"Stealth": 2, "Perception": 4}','Fire','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Draconic',3,2,4,2,2,1,2,'[]','Habitat: Hill, Mountain','Dragon','Chromatic','{"value":"Flames dance in its eyes as it snarls, smoke curling from its nostrils."}','{"value": "Red Dragon Wyrmlings are the youngest and smallest members of the red dragon species, known for their fiery breath and aggressive nature. These creatures are born from eggs laid by adult red dragons and are raised by their parents until they are able to fend for themselves.\n\nRed Dragon Wyrmlings are typically around 5-10 feet long and have bright red scales that shimmer in the light. They are known for their insatiable hunger and will often attack anything that crosses their path, using their powerful jaws and claws to tear their prey apart.\n\nThese creatures have the ability to breathe fire, unleashing a scorching blast of flames that can incinerate anything in its path. They are also highly intelligent and cunning, often using their wits to outsmart their foes in battle.\n\nDespite their young age, Red Dragon Wyrmlings are incredibly dangerous and should not be underestimated. They are fiercely territorial and will defend their lairs and hoards of treasure with their lives. Adventurers who encounter a Red Dragon Wyrmling should proceed with caution, as these creatures are not to be taken lightly."}',0,'Monster Manual 2024 (BR)','Chromatic','None',4.0,NULL),
	 ('01990b99-96a5-73c1-81f5-9cc648ade295'::uuid,'Remorhaz','Unaligned','11 (XP 7 200; PB +4)',7200,5,'Brute','Huge',17,NULL,195,'17d12+85','40 ft.',NULL,NULL,NULL,24,13,21,4,10,5,'{}','Cold, Fire','Darkvision 60 ft., Tremorsense 60 ft., Passive Perception 10','—',5,1,7,0,-3,-3,4,'[]','Habitat: Arctic','Monstrosity','','{"value":"Steam billows from its fiery maw as it lunges forward, jaws snapping shut."}','{"value": "The Remorhaz is a massive, predatory creature that dwells in frigid environments such as icy caves and tundras. It resembles a gigantic centipede with a fiery red chitinous exoskeleton, and can grow up to 40 feet in length. The Remorhaz is known for its ability to generate intense heat within its body, allowing it to melt ice and snow in its path and cook its prey alive.\n\nRemorhazes are solitary hunters and fiercely territorial, attacking any creature that enters its territory with its powerful mandibles and burning body. They are incredibly resilient and can withstand extreme cold temperatures, making them formidable opponents for adventurers braving the frozen wilderness.\n\nLegends say that Remorhazes are born from the elemental plane of fire, making them creatures of pure elemental fury. Some believe that they are the spawn of the fire giant god Surtr, sent to wreak havoc on the mortal realm. Regardless of their origins, encountering a Remorhaz is a dangerous and potentially deadly experience for any adventurer."}',0,'Monster Manual 2024 (BR)','','None',11.0,NULL),
	 ('01990b99-a20e-755f-b375-625644d25079'::uuid,'Revenant','TrueNeutral','5 (XP 1 800; PB +3)',1800,2,'Brute','Medium',13,NULL,127,'15d8+60','30 ft.',NULL,NULL,NULL,18,14,18,13,16,18,'{}','Poison; Charmed, Exhaustion, Frightened, Paralyzed, Poisoned, Stunned','Darkvision 60 ft., Passive Perception 13','Common plus one other language',7,2,7,6,7,1,3,'[]','Habitat: Forest, Swamp, Urban','Undead','','{"value":"Silent specter drifts forward, eyes burning with vengeance."}','{"value": "In Dungeons and Dragons 5th Edition, the Revenant is an undead creature that has returned from the dead to seek revenge on those who wronged it in its previous life. Revenants are fueled by a powerful sense of vengeance and will stop at nothing to exact their revenge.\n\nThe lore surrounding Revenants varies depending on the campaign setting, but they are typically individuals who were wronged or killed unjustly and have been brought back to life through dark magic or a pact with a powerful entity. Revenants are often driven by a single-minded desire for revenge and will pursue their target relentlessly, even crossing into the afterlife if necessary.\n\nIn combat, Revenants are formidable adversaries, possessing supernatural strength and resilience. They are immune to many types of damage and can quickly regenerate from injuries. Their attacks are powerful and can inflict significant harm on their enemies.\n\nRevenants are a popular choice for Dungeon Masters looking to introduce a recurring villain or add an element of mystery and intrigue to their campaign. Players will need to use all of their skills and resources to defeat a Revenant and put an end to its vengeful rampage."}',0,'Monster Manual 2024','','Necrotic, Psychic',5.0,NULL),
	 ('01990b99-a99b-747a-9d7b-c3e2111acdd8'::uuid,'Rhinoceros','Unaligned','2 (XP 450; PB +2)',450,-1,'Brute','Large',13,NULL,45,'6d10+12','40 ft.',NULL,NULL,NULL,21,8,15,2,12,6,'{}','None','Passive Perception 11','None',2,-1,5,1,-2,-4,2,'[]',NULL,'Beast','','{"value":"Thunderous hooves shake the earth as it charges with primal fury."}','{"value": "In the world of Dungeons and Dragons, the Rhinoceros is a powerful and fearsome creature known for its massive size and strength. These creatures are often found in grasslands and savannas, where they roam in small herds. Rhinoceroses are herbivores, feeding on grasses and other vegetation, but they are not afraid to defend themselves if threatened.\n\nIn combat, a Rhinoceros can charge at its enemies with incredible speed and force, using its horn to gore and trample anyone in its path. Their thick hides provide them with excellent protection against attacks, making them formidable opponents in battle.\n\nDespite their aggressive nature, Rhinoceroses are generally peaceful creatures and prefer to avoid conflict whenever possible. However, they will not hesitate to defend themselves or their herd if they feel threatened.\n\nIn some cultures, Rhinoceroses are revered as symbols of strength, power, and protection. They are often depicted in art and mythology as noble and majestic creatures, embodying the primal forces of nature.\n\nOverall, the Rhinoceros is a creature to be respected and approached with caution, as provoking one can lead to disastrous consequences."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b99-ca6e-7ce5-a6ce-b0499dd693ea'::uuid,'Roc','Unaligned','11 (XP 7 200; PB +4)',7200,8,'Solo','Gargantuan',15,NULL,248,'16d20+80','20 ft.',NULL,NULL,'120 ft.',28,10,20,3,10,9,'{"Perception": 8}','None','Passive Perception 18','—',5,4,9,4,-1,-4,4,'[]','Habitat: Arctic, Coastal, Desert, Hill, Mountain','Monstrosity','','{"value":"Wings beat thunderously as it descends, talons outstretched for the kill"}','{"value": "Rocs are massive, mythical birds of prey that are said to be able to carry off elephants in their talons. In the world of Dungeons and Dragons, Rocs are colossal creatures with wingspans of up to 200 feet. They are incredibly powerful and dangerous predators that can swoop down from the sky to snatch up their prey in their massive claws.\n\nRocs are known for nesting in high mountains or cliffs, where they build massive nests out of boulders and tree branches. They are fiercely territorial creatures and will fiercely defend their nests and hunting grounds from any intruders.\n\nIn D&D lore, Rocs are often depicted as majestic and fearsome creatures that are highly sought after by hunters and adventurers for their impressive feathers and valuable eggs. However, facing off against a Roc is no easy task, as they are incredibly strong and can easily overpower even the most skilled warriors.\n\nOverall, Rocs are formidable and awe-inspiring creatures in the world of Dungeons and Dragons, and encountering one is sure to be a memorable and dangerous experience for any adventurer."}',0,'Monster Manual 2024 (BR)','','None',11.0,NULL),
	 ('01990b9a-283f-7289-9843-8c0eab8e2103'::uuid,'Saber-Toothed Tiger','Unaligned','2 (XP 450; PB +2)',450,3,'Ambusher','Large',13,NULL,52,'7d10+14','40 ft.',NULL,NULL,NULL,18,17,15,3,12,8,'{"Stealth": 7, "Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','None',2,5,6,1,-1,-4,2,'[]',NULL,'Beast','','{"value":"Roaring fiercely, it prowls with predatory grace, eyes fixed on its prey."}','{"value": "The Saber-Toothed Tiger is a fearsome predator that roams the wilds of the world. Its most distinguishing feature is its long, curved canine teeth that jut out from its jaws, giving it a menacing appearance. These teeth are used to deliver deadly bites to its prey, which typically consists of large mammals such as deer or bison.\n\nSaber-Toothed Tigers are solitary creatures, preferring to hunt and live alone rather than in packs. They are known for their agility and speed, able to quickly ambush their prey with lightning-fast strikes. Despite their solitary nature, they are fiercely territorial and will fiercely defend their hunting grounds from intruders.\n\nLegends say that Saber-Toothed Tigers were once majestic creatures that roamed the land in great numbers, but their populations have dwindled over time due to habitat loss and hunting by other predators. Now, they are rare sights in the wild, making them both a symbol of awe and fear for those who come across them.\n\nIn D&D 5th Edition, Saber-Toothed Tigers are often encountered as formidable foes for adventurers, with their powerful bites and quick reflexes making them challenging opponents to overcome. They are typically found in forested areas or mountainous regions, where they can easily blend into their surroundings and strike unexpectedly."}',0,'Monster Manual 2024 (BR)','','None',2.0,NULL),
	 ('01990b9a-3561-77cd-af86-511735cab681'::uuid,'Sahuagin Baron','LawfulEvil','5 (XP 1 800; PB +3)',1800,5,'Soldier','Large',16,NULL,76,'9d10+27','30 ft.',NULL,'50 ft.',NULL,19,15,16,14,13,17,'{"Perception": 7}','None','Darkvision 120 ft., Passive Perception 17','Sahuagin',6,5,4,4,3,2,3,'["Breastplate", "Trident"]','Habitat: Coastal, Underwater','Fiend','','{"value":"Swirling currents of water dance around the Sahuagin Baron, a regal predator of the deep."}','{"value": "Sahuagin Barons are powerful leaders among the sahuagin, a race of aquatic humanoids known for their fierce and predatory nature. These Barons are typically larger and stronger than other sahuagin, with a commanding presence that instills fear and respect in their followers.\n\nSahuagin Barons are skilled warriors and often wield powerful weapons such as tridents or magical items that enhance their combat abilities. They are also adept at using their natural aquatic abilities to their advantage, such as swimming at high speeds and breathing underwater.\n\nIn sahuagin society, Barons are usually the leaders of their respective tribes, ruling with an iron fist and demanding absolute loyalty from their subjects. They are known for their brutality and cruelty, often using their power to subjugate and exploit other underwater creatures.\n\nSahuagin Barons are also known to be highly intelligent and cunning, using their strategic minds to outwit their enemies and achieve their goals. They are often involved in complex political machinations and power struggles within their own society, as well as with other underwater races.\n\nOverall, Sahuagin Barons are fearsome adversaries that should not be underestimated, as they possess both physical prowess and cunning intellect in equal measure."}',0,'Monster Manual 2024','','Acid, Cold',5.0,NULL),
	 ('01990b9a-454b-70c6-9bc0-14752c5dc3f1'::uuid,'Sahuagin Priest','LawfulEvil','2 (XP 450; PB +2)',450,0,'Support','Medium',12,NULL,38,'7d8+7','30 ft.',NULL,'40 ft.',NULL,13,11,12,12,14,13,'{"Religion": 3, "Perception": 6}','None','Darkvision 120 ft., Passive Perception 16','Sahuagin',1,0,1,2,1,1,2,'[]','Habitat: Coastal, Underwater','Fiend','','{"value":"Anoints its trident with foul ichor, chanting in a guttural, hypnotic tone"}','{"value": "Sahuagin Priests are powerful spellcasters among the sahuagin, a race of aquatic humanoids known for their aggressive and territorial nature. These priests are revered by other sahuagin as intermediaries between their god Sekolah and the mortal realm.\n\nSahuagin Priests are typically adorned in elaborate robes and carry sacred relics and symbols of their faith. They have a deep connection to the sea and its creatures, often commanding sharks and other aquatic beasts to do their bidding.\n\nIn combat, Sahuagin Priests use their magical abilities to bolster their allies and weaken their enemies. They can cast spells such as control water, water breathing, and command sea creatures to gain the upper hand in battle.\n\nSahuagin Priests are also skilled in the art of healing, using their magic to cure wounds and ailments of their fellow sahuagin warriors. They are respected and feared by their kin, as their power and influence can sway the tide of battle in favor of their tribe.\n\nOverall, Sahuagin Priests are formidable adversaries, combining their mastery of magic with their fierce loyalty to their god and tribe. They are a force to be reckoned with in the treacherous waters they call home."}',0,'Monster Manual 2024','','Acid, Cold',2.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b9a-8da7-715e-9aa3-e9118da71461'::uuid,'Salamander Fire Snake','NeutralEvil','1 (XP 200; PB +2)',200,2,'Skirmisher','Medium',14,NULL,27,'6d8','30 ft.','30 ft.',NULL,NULL,12,14,11,7,10,8,'{}','Fire','Darkvision 60 ft., Passive Perception 10','Understands Primordial but can''t speak',0,2,1,0,-1,-2,2,'[]','Habitat: Planar (Elemental Plane of Fire), Underdark','Elemental','','{"value":"Tongue flickers as it slithers through the flames, scorching the air with heat"}','{"value": "Salamanders are fiery reptilian creatures known for their affinity for flames and their ability to manipulate fire. They are often found in volcanic regions or other areas of intense heat. Salamanders are fearsome opponents in battle, using their fiery breath and powerful claws to dispatch their enemies.\n\nIn D&D 5e, Salamanders are depicted as large, snake-like creatures with shimmering red and orange scales. They are immune to fire damage and have the ability to breathe fire in a cone, making them particularly dangerous in combat. Salamanders are often used as guardians by powerful fire-based creatures or as minions by evil fire-worshipping cults.\n\nIn some D&D campaigns, Salamanders are also known to be skilled blacksmiths, using their mastery of fire to forge powerful weapons and armor. They are sometimes depicted as cunning and intelligent creatures, capable of crafting intricate plans to achieve their goals.\n\nOverall, Salamanders are a staple of the D&D bestiary, representing the fiery and dangerous side of the natural world. Players must be cautious when encountering these creatures, as their fiery nature can quickly turn a battle in their favor."}',0,'Monster Manual 2024','','None',1.0,NULL),
	 ('01990b9a-9ea6-7000-929c-f63254b1c7de'::uuid,'Salamander Inferno Master','NeutralEvil','15 (XP 13 000; PB +5)',13000,8,'Brute','Large',18,NULL,256,'27d10+108','40 ft.','40 ft.',NULL,NULL,24,16,18,14,10,20,'{}','Fire','Darkvision 120 ft., Passive Perception 10','Primordial (Ignan)',4,8,7,5,5,2,5,'[]','Habitat: Planar (Elemental Plane of Fire), Underdark','Elemental','','{"value":"Flames dance and writhe along its scaly body, casting a searing glow."}','{"value": "The Salamander Inferno Master is a powerful and ancient creature that resides in the fiery depths of the Elemental Plane of Fire. These creatures are considered to be the masters of fire magic and are able to control and manipulate flames with incredible precision.\n\nThe Salamander Inferno Master is known for its fearsome appearance, with scales that shimmer in the light of the flames and long, sharp claws that can easily tear through armor. They are also capable of breathing fire and summoning fiery creatures to aid them in battle.\n\nThese creatures are highly intelligent and possess a deep knowledge of fire magic, which they use to create powerful spells and rituals. They are often sought out by mages and sorcerers seeking to learn from their expertise in the manipulation of fire.\n\nThe Salamander Inferno Master is a formidable opponent in combat, using their mastery of fire magic to unleash devastating attacks on their enemies. They are also known for their cunning tactics and ability to outmaneuver their foes in battle.\n\nOverall, the Salamander Inferno Master is a legendary and enigmatic creature that is both feared and respected by those who encounter them. Their mastery of fire magic and their fierce combat abilities make them a force to be reckoned with in the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','None',15.0,NULL),
	 ('01990b9a-f057-7ac2-ba2f-cf5e1d6c5a52'::uuid,'Scout Captain','TrueNeutral','3 (XP 700; PB +2)',700,5,'Skirmisher','Medium',15,NULL,66,'12d8+12','30 ft.','30 ft.',NULL,NULL,11,16,12,14,15,11,'{"Stealth": 7, "Survival": 6, "Perception": 6}','None','Passive Perception 16','Common plus one other language',1,5,0,2,0,4,2,'["Longbow", "Shortsword", "Studded Leather Armor"]','Habitat: Any','Humanoid','','{"value":"Sharp eyes narrow, as it signals its troops with precise hand gestures."}','{"value": "The Scout Captain is a powerful and experienced leader among the ranks of the scouts in the D&D world. They are known for their strategic prowess, exceptional combat skills, and ability to navigate treacherous terrain with ease. \n\nScout Captains often lead small groups of scouts on dangerous missions, gathering information, and conducting reconnaissance for their faction or army. They are highly respected by their peers and feared by their enemies for their cunning tactics and ruthless efficiency.\n\nIn battle, Scout Captains are versatile fighters, able to adapt to any situation and outmaneuver their opponents. They are skilled in both ranged and melee combat, making them a formidable adversary on the battlefield. They are also adept at tracking and hunting down enemies, using their keen senses and knowledge of the land to gain the upper hand.\n\nOverall, the Scout Captain is a seasoned veteran with a reputation for getting the job done, no matter the cost. They are a force to be reckoned with and a valuable asset to any group or army they serve."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01990b9b-3d81-7cf4-8a18-3d6f7531e6a6'::uuid,'Shadow Demon','ChaoticEvil','4 (XP 1 100; PB +2)',1100,3,'Solo','Medium',14,NULL,66,'12d8+12','30 ft.',NULL,NULL,'30 ft.',1,17,12,14,13,14,'{"Stealth": 7}','Necrotic, Poison; Exhaustion, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained','Darkvision 120 ft., Passive Perception 11','Abyssal; telepathy 120 ft.',1,5,-5,1,4,2,2,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Whispers darkly, its form flickering like a wisp of smoke."}','{"value": "In the world of Dungeons & Dragons, Shadow Demons are malevolent creatures that dwell in the Shadowfell, a dark and twisted mirror of the Material Plane. These demons are born from the souls of evil mortals who have been consumed by darkness and despair.\n\nShadow Demons are often summoned by powerful spellcasters to do their bidding, as they possess a slew of abilities that make them formidable foes in combat. They can move effortlessly through shadows, rendering them nearly invisible to their enemies. They are also able to drain the life force of their victims with their chilling touch, weakening them and bolstering their own strength in the process.\n\nThese demons are cunning and devious, often using their powers of darkness to manipulate and corrupt those around them. They take pleasure in causing fear and suffering, reveling in the chaos and destruction they sow.\n\nIn battle, Shadow Demons are relentless and merciless, striking swiftly and without warning. They are difficult to defeat, as they can phase in and out of the shadows at will, making them elusive targets.\n\nOverall, Shadow Demons are terrifying creatures that embody the darkest aspects of the Shadowfell. They are a constant threat to those who dare to tread in the realm of shadows, and only the bravest and most skilled adventurers can hope to stand against them and emerge victorious."}',0,'Monster Manual 2024','Demon','Acid, Bludgeoning, Cold, Fire, Lightning, Piercing, Slashing, Thunder',4.0,NULL),
	 ('01990b9b-4b16-700a-a615-9ee35cd340d4'::uuid,'Shadow Dragon','ChaoticEvil','13 (XP 10 000, or 11 500 in lair; PB +5)',10000,14,'Solo','Huge',16,NULL,189,'18d12+72','40 ft.','40 ft.',NULL,'80 ft.',21,19,18,14,12,18,'{"Stealth": 14, "Perception": 11}','Necrotic','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 21','Common, Draconic',4,9,5,6,4,2,5,'[]','Habitat: Planar (Shadowfell), Underdark','Dragon','','{"value":"Wings unfurl, casting a chilling darkness over the land."}','{"value": "Shadow Dragons are a type of chromatic dragon that have been corrupted by the influence of the Shadowfell, a dark and twisted parallel plane. These dragons are known for their stealth and cunning, often striking from the shadows to ambush their prey.\n\nShadow Dragons have deep black scales that seem to absorb light, allowing them to blend seamlessly into the darkness. They also have the ability to create magical darkness, further enhancing their ability to move unseen.\n\nIn addition to their physical abilities, Shadow Dragons also possess a breath weapon that unleashes a blast of shadowy energy, draining the life force from their victims. This energy can weaken and incapacitate even the strongest of foes.\n\nDespite their malevolent nature, Shadow Dragons are not mindless beasts. They are highly intelligent and often form alliances with other creatures of darkness, using their cunning and strategic thinking to further their own dark goals.\n\nOverall, Shadow Dragons are fearsome and dangerous creatures that strike fear into the hearts of those who dare to cross their path. Only the most skilled and courageous adventurers stand a chance against these deadly creatures."}',0,'Monster Manual 2024','','See Living Shadow',13.0,11500.0),
	 ('01990b9b-84af-7d50-8cd0-8e0a87af88e7'::uuid,'Shield Guardian','Unaligned','7 (XP 2 900; PB +3)',2900,-1,'Leader','Large',17,NULL,142,'15d10+60','30 ft.',NULL,NULL,NULL,18,8,18,7,10,3,'{}','Poison; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 10','Understands commands given in any language but can''t speak',4,-1,4,0,-4,-2,3,'[]','Habitat: Urban','Construct','','{"value":"Guardian stands tall, shield raised, ready to protect its master at all costs."}','{"value": "The Shield Guardian is a large construct created by powerful wizards to serve as a protector and a defender. It is usually made of metal and stone, and its body is adorned with intricate runes and symbols. The Shield Guardian is bound to a specific master, who can command it to protect them and follow their orders.\n\nThe Shield Guardian is a formidable combatant, with immense strength and durability. It is also capable of casting spells to enhance its defensive capabilities or to heal itself and its master. In addition to its combat abilities, the Shield Guardian can also serve as a guardian for valuable items or locations, using its immense strength and resilience to ward off any intruders.\n\nThe lore surrounding the Shield Guardian often involves stories of powerful wizards or noble knights who created these constructs to serve as their loyal companions and protectors. Some tales speak of Shield Guardians sacrificing themselves to protect their masters, showing unwavering loyalty and dedication to their duty.\n\nOverall, the Shield Guardian is a powerful and loyal ally, a formidable protector that will stop at nothing to defend its master and fulfill its purpose."}',0,'Monster Manual 2024 (BR)','','None',7.0,NULL),
	 ('01990b9b-8bc5-776b-9797-b3230e576d96'::uuid,'Shrieker Fungus','Unaligned','0 (PB +2)',10,-5,'Ambusher','Medium',5,NULL,13,'3d8','5 ft.',NULL,NULL,NULL,1,1,10,1,3,1,'{}','Blinded, Charmed, Deafened, Frightened','Blindsight 30 ft., Passive Perception 6','—',0,-5,-5,-4,-5,-5,2,'[]','Habitat: Underdark','Plant','','{"value":"A cacophony of shrill screams pierces the darkness, emanating from the fungal mass."}','{"value": "Shrieker Fungi are a type of fungus commonly found in dark, damp environments such as caves and underground dungeons. These fungi are known for their distinctive shrieking sound, which they emit when disturbed or threatened. The sound can be deafening, causing confusion and disorientation among nearby creatures.\n\nShrieker Fungi are not particularly dangerous on their own, but they often attract other predators with their loud noises. They are typically used by more intelligent creatures as a form of alarm system, alerting them to the presence of intruders.\n\nSome adventurers have also been known to use Shrieker Fungi to their advantage, luring enemies into traps or using the noise to cover their own movements. However, caution must be taken, as the fungi''s shrieks can also attract unwanted attention from other dangerous creatures in the area.\n\nOverall, Shrieker Fungi are considered more of a nuisance than a threat, but they should still be approached with caution by those exploring dark and dangerous environments."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Solar','LawfulGood','21 (XP 33 000; PB +7)',33000,20,'Solo','Large',21,NULL,297,'22d10+176','50 ft.',NULL,NULL,'150 ft.',26,22,26,25,25,30,'{"Perception": 14}','Poison, Radiant; Charmed, Exhaustion, Frightened, Poisoned','Truesight 120 ft., Passive Perception 24','All; telepathy 120 ft.',8,6,8,7,10,7,7,'[]','Habitat: Planar (Upper Planes)','Celestial','Angel','{"value":"Radiant angelic being bathes the area in warm, golden light."}','{"value": "The Solar is a powerful celestial being in Dungeons and Dragons 5th edition. Solars are considered to be the highest-ranking angels in the celestial hierarchy, serving the gods directly and acting as their powerful warriors and messengers. They are beings of immense power and radiance, embodying all that is good and just in the universe.\n\nSolars are often depicted as majestic and awe-inspiring beings, with golden skin, feathered wings, and glowing eyes that shine like the sun itself. They wield powerful weapons and can unleash devastating spells and abilities in combat. Despite their immense power, Solars are benevolent and compassionate beings, dedicated to upholding justice and protecting the innocent.\n\nIn D&D lore, Solars are said to be created directly by the gods themselves, and they serve as their agents in the world, carrying out their will and battling evil wherever it may be found. They are known for their unwavering commitment to righteousness and their willingness to sacrifice themselves in the defense of the greater good.\n\nEncountering a Solar in a D&D campaign is a rare and awe-inspiring event, as these beings are typically only summoned by the most dire of circumstances or by the direct intervention of the gods themselves. Players who face off against a Solar must be prepared for a challenging and epic battle, as these celestial beings are among the most powerful creatures in the D&D universe."}',0,'Monster Manual 2024 (BR)','Angel','None',21.0,NULL),
	 ('01990b9c-12de-79f6-83bc-a27b1119d392'::uuid,'Specter','ChaoticEvil','1 (XP 200; PB +2)',200,2,'Ambusher','Medium',12,NULL,22,'5d8','30 ft.',NULL,NULL,'50 ft.',1,14,11,10,10,11,'{}','Necrotic, Poison; Charmed, Exhaustion, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Darkvision 60 ft., Passive Perception 10','Understands Common plus one other language but can''t speak',0,2,-5,0,0,0,2,'[]','Habitat: Underdark, Urban','Undead','','{"value":"Whispers echo through the air as the ethereal figure glides towards you."}','{"value": "Specters are undead creatures that are formed from the souls of individuals who died with intense feelings of anger, hatred, or sorrow. These vengeful spirits are bound to the material plane, unable to move on to the afterlife due to their strong emotions and desire for revenge.\n\nSpecters are often encountered in places where great tragedies or acts of violence have occurred, such as battlefields, haunted houses, or cursed tombs. They are known for their ghostly appearance, with pale, translucent bodies and glowing red eyes that seem to pierce through the darkness.\n\nSpecters have the ability to drain the life force of living creatures with a touch, weakening them and slowly sapping away their strength. They are also resistant to many forms of damage and can move through walls and other solid objects with ease.\n\nIn combat, specters are relentless and merciless, attacking their foes with a cold and calculating demeanor. They are driven by their need for vengeance and will stop at nothing to achieve their goal.\n\nOverall, specters are fearsome and dangerous creatures that are best avoided, as they are nearly impossible to reason with and are driven by their insatiable thirst for revenge. Only the bravest and most skilled adventurers dare to face these malevolent spirits in battle."}',0,'Monster Manual 2024 (BR)','','Acid, Bludgeoning, Cold, Fire, Lightning, Piercing, Slashing, Thunder',1.0,NULL),
	 ('01990b9c-4753-7ab4-b1d4-3ca2b45e1207'::uuid,'Sphinx of Secrets','LawfulNeutral','8 (XP 3 900; PB +3)',3900,5,'Solo','Large',16,NULL,136,'16d10+48','40 ft.',NULL,NULL,'60 ft.',18,15,16,18,18,18,'{"History": 7, "Religion": 7, "Perception": 7}','Psychic; Charmed, Frightened','Truesight 60 ft., Passive Perception 17','Celestial, Common',3,2,4,4,4,4,3,'[]','Habitat: Desert, Planar (Upper Planes)','Celestial','','{"value":"Whispers secrets in a voice like silk, eyes gleaming with ancient knowledge."}','{"value": "The Sphinx of Secrets is a powerful and enigmatic creature that is said to possess vast knowledge and wisdom beyond that of any mortal being. It is believed to be a guardian of ancient secrets and mystical truths, and is often sought out by adventurers and scholars seeking answers to their most pressing questions.\n\nThe Sphinx of Secrets is said to reside in a hidden temple or labyrinth, where it tests those who seek its knowledge with riddles and puzzles of great complexity. Only those who can prove their worthiness and intelligence are granted an audience with the Sphinx, and even then, its answers are often cryptic and filled with hidden meanings.\n\nMany believe that the Sphinx of Secrets has the ability to see into the future and possess knowledge of events that have yet to come to pass. It is said to be a neutral force in the world, neither good nor evil, but rather a keeper of balance and cosmic truths.\n\nEncountering a Sphinx of Secrets is a rare and dangerous prospect, as those who fail its tests may face dire consequences. However, those who are able to unlock its mysteries may gain valuable insights and knowledge that can shape the course of their destiny."}',0,'Monster Manual 2024','','Necrotic, Radiant',8.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b9c-8dc7-70a2-825f-e4e7f1eb7123'::uuid,'Sphinx of Valor','LawfulNeutral','17 (XP 18 000, or 20 000 in lair; PB +6)',18000,12,'Solo','Large',17,NULL,199,'19d10+95','40 ft.',NULL,NULL,'60 ft.',22,10,20,16,23,18,'{"Arcana": 9, "Religion": 15, "Perception": 12}','Psychic; Charmed, Frightened','Truesight 120 ft., Passive Perception 22','Celestial, Common',11,6,6,12,4,9,6,'[]','Habitat: Desert, Planar (Upper Planes)','Celestial','','{"value":"Jaws open wide, eyes ablaze with righteous fury, ready to judge."}','{"value": "The Sphinx of Valor is a powerful and noble creature that roams the lands seeking to test the courage and worthiness of mortals. It is said to be a guardian of ancient knowledge and a protector of sacred sites.\n\nThe Sphinx of Valor is a majestic creature with the body of a lion and the head of a human, often depicted as a beautiful woman. It is known for its keen intelligence and cunning wit, often posing riddles and challenges to those who seek its wisdom.\n\nThose who pass the Sphinx''s tests are said to be granted great rewards and blessings, while those who fail are met with swift and deadly punishment. The Sphinx of Valor is a fearsome adversary in combat, using both its physical strength and magical abilities to vanquish its foes.\n\nLegends say that the Sphinx of Valor was created by a powerful deity to guard a sacred treasure or secret, and that it has existed for centuries, roaming the world in search of those worthy of its knowledge.\n\nEncountering a Sphinx of Valor is a rare and dangerous experience, but those who prove themselves brave and worthy may find themselves blessed with wisdom and fortune beyond their wildest dreams."}',0,'Monster Manual 2024 (BR)','','Necrotic, Radiant',17.0,20000.0),
	 ('01990b9c-bd39-7ff6-b85d-02672802e040'::uuid,'Spider','Unaligned','0 (XP 10; PB +2)',10,2,'Ambusher','Tiny',12,NULL,1,'1d4-1','20 ft.','20 ft.',NULL,NULL,2,14,8,1,10,2,'{"Stealth": 4}','None','Darkvision 30 ft., Passive Perception 10','None',1,2,4,0,4,5,2,'[]',NULL,'Beast','','{"value":"Legs skitter ominously, eyes gleaming in the shadows."}','{"value": "In Dungeons and Dragons 5th Edition, spiders are often depicted as creepy and dangerous creatures that inhabit dark, dank places such as caves, forests, and underground tunnels. They come in various sizes, from tiny spiders no bigger than a coin to massive, monstrous spiders the size of horses.\n\nSpiders are known for their ability to spin webs to trap their prey and their venomous bite that can paralyze or kill their victims. They are typically solitary creatures, hunting alone or with their young offspring. Some species of spiders are intelligent and can communicate with each other through vibrations in their webs.\n\nIn D&D lore, spiders are often associated with dark magic and evil creatures, such as drow or driders. They are sometimes used as guardians by dark wizards or as familiars by necromancers. In some settings, spiders are even worshipped as divine beings, with their webs representing fate or the interconnectedness of the world.\n\nOverall, spiders in D&D are fearsome creatures that inspire dread and caution in adventurers who dare to venture into their lairs. Their ability to move silently and strike quickly from the shadows makes them formidable opponents in combat."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990b9c-c625-7b7e-b7ff-07fcd206faf6'::uuid,'Spined Devil','LawfulEvil','2 (XP 450; PB +2)',450,2,'Skirmisher','Small',13,NULL,45,'10d6+10','20 ft.',NULL,NULL,'40 ft.',10,15,12,11,14,8,'{}','Fire, Poison; Poisoned','Darkvision 120 ft. (unimpeded by magical Darkness), Passive Perception 12','Infernal; telepathy 120 ft.',1,2,0,2,-1,0,2,'[]','Habitat: Planar (Nine Hells)','Fiend','Devil','{"value":"Spined Devil cackles maniacally, twirling its barbed tail in anticipation."}','{"value": "Spined Devils, also known as Spinagons, are fiendish creatures from the Nine Hells in the Dungeons and Dragons universe. They are known for their spiky, barbed bodies and their ability to manipulate fire and darkness.\n\nThese creatures are often found serving more powerful devils or infernal masters, acting as messengers, enforcers, or spies. They are cunning and devious, using their sharp minds and sharp spines to outwit and outfight their enemies.\n\nSpined Devils are skilled in combat, using their claws, teeth, and spines to attack their foes. They also have the ability to create darkness and summon flames, making them formidable opponents in battle.\n\nIn terms of lore, Spined Devils are often depicted as cowardly and treacherous, willing to betray their allies for personal gain. They are also known for their loyalty to their infernal masters, carrying out their orders without question.\n\nOverall, Spined Devils are feared and respected in the Nine Hells, known for their cunning, ferocity, and loyalty to their dark masters."}',0,'Monster Manual 2024','Devil','Cold',2.0,NULL),
	 ('01990b9c-e45d-7819-b628-3351feb49fdc'::uuid,'Spirit Naga','ChaoticEvil','8 (XP 3 900; PB +3)',3900,3,'Controller','Large',17,NULL,135,'18d10+36','40 ft.',NULL,NULL,NULL,18,17,14,16,15,16,'{}','Poison; Charmed, Poisoned','Darkvision 60 ft., Passive Perception 12','Abyssal, Common',5,6,4,5,6,3,3,'[]','Habitat: Planar (Lower Planes), Underdark','Fiend','','{"value":"Sinuous coils writhe with unnatural grace, eyes gleaming hypnotically."}','{"value": "The Spirit Naga is a powerful and cunning serpent-like creature that is found in the jungles and ruins of the world. It is said to be the reincarnated spirit of a powerful sorcerer or wizard who met a tragic end. The Spirit Naga is known for its ability to cast powerful spells, including charm and suggestion, and its venomous bite can paralyze its victims. \n\nIt is also said to possess the ability to shape-shift into the form of a beautiful woman in order to lure unsuspecting victims closer. The Spirit Naga is often found guarding ancient temples or ruins, using its powers to protect the treasures within. \n\nThose who encounter a Spirit Naga should beware, as they are highly intelligent and devious creatures who will stop at nothing to achieve their goals. Only the most skilled and brave adventurers stand a chance against the cunning Spirit Naga."}',0,'Monster Manual 2024 (BR)','','None',8.0,NULL),
	 ('01990b9d-4396-7f0b-8c80-ccd708213be2'::uuid,'Spy Master','TrueNeutral','10 (XP 5 900; PB +4)',5900,9,'Ambusher','Medium',19,NULL,137,'25d8+25','30 ft.','30 ft.',NULL,NULL,10,20,12,18,16,16,'{"Insight": 7, "Stealth": 13, "Deception": 7, "Perception": 11, "Investigation": 8, "Sleight of Hand": 9}','None','Passive Perception 21','Common plus two other languages',5,9,0,7,3,8,4,'["Hand Crossbow", "Rapier", "Thieves'' Tools"]','Habitat: Any','Humanoid','','{"value":"Cloaked in shadows, it watches with calculating eyes, fingers tapping on a hidden blade."}','{"value": "The Spy Master is a powerful and cunning creature that specializes in espionage, manipulation, and information gathering. They are often employed by powerful organizations, governments, or individuals to gather sensitive information, sabotage their enemies, or manipulate events to their advantage.\n\nSpy Masters are skilled in the art of disguise, able to blend in seamlessly with their surroundings and adopt different personas to deceive their targets. They are also highly proficient in stealth and subterfuge, able to move unseen and unheard to gather information without being detected.\n\nIn combat, Spy Masters rely on their intelligence and cunning to outmaneuver their opponents. They prefer to strike from the shadows, using their knowledge of their enemies'' weaknesses to gain the upper hand. They are also skilled in the use of poisons, traps, and other underhanded tactics to incapacitate or eliminate their foes.\n\nOverall, the Spy Master is a dangerous and elusive foe, able to outwit and outmaneuver even the most skilled adventurers. Crossing paths with a Spy Master is always a risky proposition, as their web of lies and deceit can ensnare even the most cautious of individuals."}',0,'Monster Manual 2024','','None',10.0,NULL),
	 ('01990b9d-8198-7d90-8f18-a8afea090c40'::uuid,'Stone Giant','TrueNeutral','7 (XP 2 900; PB +3)',2900,5,'Brute','Huge',17,NULL,126,'11d12+55','40 ft.',NULL,NULL,NULL,23,15,20,10,12,9,'{"Stealth": 5, "Athletics": 12, "Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','Giant',8,5,6,4,-1,0,3,'[]','Habitat: Mountain, Underdark','Giant','','{"value":"Looms above, voice like thunder, rocks clenched in massive fists"}','{"value": "Stone Giants are massive humanoid creatures that dwell in mountainous regions and rocky landscapes. They are known for their incredible strength and endurance, as well as their ability to manipulate and control stone.\n\nStone Giants are skilled craftsmen and builders, creating elaborate structures and sculptures out of stone. They are also adept at using rocks and boulders as weapons, hurling them with great accuracy and force at their enemies.\n\nDespite their impressive physical abilities, Stone Giants are generally peaceful and reclusive creatures, preferring to live in solitude and avoid conflict. However, they will defend their territory fiercely if threatened, using their immense strength to overpower and crush any intruders.\n\nIn some cultures, Stone Giants are revered as guardians of the earth and protectors of the natural world. They are often depicted as wise and ancient beings, with a deep connection to the land and the elements.\n\nOverall, Stone Giants are formidable opponents in combat, but they are not inherently malicious and can be reasoned with if approached respectfully. Their deep connection to the earth and their affinity for stone make them fascinating and enigmatic creatures in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','','None',7.0,NULL),
	 ('01990b9d-c819-752c-a16b-d7c5bed6ab33'::uuid,'Stone Golem','Unaligned','10 (XP 5,900; PB +4)',5900,3,'Brute','Large',18,NULL,220,'21d10+105','30 ft.',NULL,NULL,NULL,22,9,20,3,11,1,'{}','Poison, Psychic; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned','Darkvision 120 ft., Passive Perception 10','Understands Common plus two other languages but can''t speak',5,-1,6,0,-5,-4,4,'[]','Habitat: Any','Construct','','{"value":"Silent and unmoving, the stone golem watches with unblinking eyes."}','{"value": "In the world of Dungeons and Dragons, Stone Golems are powerful constructs created from magically animated stone. These massive and durable creatures are typically created by powerful wizards or mages to act as guardians or defenders of important locations or treasures.\n\nStone Golems are immune to most forms of magic and can only be damaged by magical or adamantine weapons. They are incredibly strong and resilient, able to smash through walls and foes with ease. Despite their slow and lumbering movements, Stone Golems are relentless in their pursuit of their targets and will not stop until they are destroyed or their task is complete.\n\nIn some lore, Stone Golems are said to have a rudimentary intelligence and can follow basic commands from their creators. However, they are generally mindless beings driven solely by their programming and cannot be reasoned with or swayed from their purpose.\n\nEncountering a Stone Golem can be a daunting and dangerous experience for adventurers, as their immense strength and durability make them formidable foes. Only the bravest and most skilled heroes stand a chance against these formidable constructs."}',0,'Monster Manual 2024 (BR)','','None',10.0,NULL),
	 ('01990b9e-1f47-7736-b2c9-33a8b0d9c7c6'::uuid,'Succubus','NeutralEvil','4 (XP 1,100; PB +2)',1100,3,'Support','Medium',15,NULL,71,'13d8+13','30 ft.',NULL,NULL,'60 ft.',8,17,13,15,12,20,'{"Insight": 5, "Stealth": 7, "Deception": 9, "Perception": 5, "Persuasion": 9}','None','Darkvision 60 ft., Passive Perception 15','Abyssal, Common, Infernal; telepathy 60 ft.',1,3,-1,1,5,2,2,'[]','Habitat: Planar (Lower Planes), Urban','Fiend','','{"value":"Succubus sashays towards you, her eyes glowing with seductive allure."}','{"value": "In Dungeons and Dragons 5th edition, the Succubus is a fiendish creature that is known for its seductive and manipulative nature. They are often depicted as devilish women with bat-like wings, horns, and a long, prehensile tail.\n\nSuccubi are skilled in the arts of seduction and deception, using their beauty and charm to lure unsuspecting victims into their grasp. Once they have ensnared someone, they feed on their life force, draining them of their vitality and leaving them weakened and vulnerable.\n\nSuccubi are often found serving powerful demons or devils, acting as spies, assassins, or temptresses to further their masters'' dark agendas. They are skilled in both combat and magic, able to use their alluring powers to manipulate minds and control others to do their bidding.\n\nDespite their evil nature, Succubi are not mindless monsters but possess intelligence and cunning. They are known for their insatiable hunger for power and pleasure, always seeking out new victims to ensnare and corrupt.\n\nOverall, Succubi are dangerous and alluring creatures that should be approached with caution by any adventurers who encounter them in their travels."}',0,'Monster Manual 2024 (BR)','','Cold, Fire, Poison, Psychic',4.0,NULL),
	 ('01990b9e-3e10-79e7-bfdc-99463f610607'::uuid,'Swarm of Crawling Claws','NeutralEvil','3 (XP 700; PB +2)',700,2,'Minion','Medium',12,NULL,49,'11d8','30 ft.','30 ft.',NULL,NULL,14,14,11,5,10,4,'{}','Necrotic, Poison; Charmed, Exhaustion, Frightened, Grappled, Incapacitated, Paralyzed, Petrified, Poisoned, Prone, Restrained, Stunned','Blindsight 30 ft., Passive Perception 10','Understands Common but can''t speak',0,2,2,0,3,3,2,'[]','Habitat: Any','Swarm of Tiny Undead','','{"value":"Fingers skitter and grasp, forming a writhing mass of disembodied hands"}','{"value": "In the world of Dungeons and Dragons, a Swarm of Crawling Claws is a terrifying and mysterious creature that consists of dozens or even hundreds of detached hands that have been animated by dark and malevolent magic. These hands scuttle and crawl across the ground, working together in eerie unison to attack and overwhelm their prey.\n\nThe origins of the Swarm of Crawling Claws are shrouded in mystery, with some believing that they are the result of a necromancer''s experimentation gone awry, while others believe that they are the cursed remains of thieves and criminals who have met a gruesome fate. Regardless of their origins, these creatures are often encountered in dark and forbidden places, where they lurk in the shadows, waiting to pounce on unsuspecting adventurers.\n\nThe Swarm of Crawling Claws attacks by swarming over their victims, overwhelming them with sheer numbers and tearing at their flesh with their sharp nails and fingers. They are relentless and difficult to kill, as they can reform and regenerate even after being seemingly destroyed. Only those with strong magic or powerful weapons stand a chance against these terrifying creatures.\n\nEncountering a Swarm of Crawling Claws is a harrowing experience, as their eerie movements and unsettling appearance can instill fear in even the bravest of adventurers. Those who survive an encounter with these creatures often carry the scars – both physical and emotional – for the rest of their lives."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',3.0,NULL),
	 ('01990b9e-45f0-7d66-8f1f-a85da0b39452'::uuid,'Swarm of Dretches','ChaoticEvil','4 (XP 1 100; PB +2)',1100,0,'Minion','Large',12,NULL,45,'6d10+12','40 ft.',NULL,NULL,NULL,14,11,14,5,8,3,'{}','Poison; Charmed, Frightened, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Stunned','Darkvision 60 ft., Passive Perception 9','Abyssal; telepathy 60 ft. (works only with creatures that understand Abyssal)',2,0,2,-1,-4,-3,2,'[]','Habitat: Planar (Abyss)','swarm of Small Fiends','Demon','{"value":"Putrid dretches writhe and swarm, emitting a noxious stench of decay."}','{"value": "In the world of Dungeons and Dragons, a Swarm of Dretches is a horrifying sight to behold. Dretches are low-ranking demons, often considered the weakest and most pitiful of their kind. They are grotesque, twisted creatures with leathery wings, sharp claws, and foul-smelling breath.\n\nWhen a group of dretches come together in a swarm, they become even more dangerous. Their numbers multiply their strength, making them a formidable force to reckon with. They move in a twisted, chaotic mass, overwhelming their enemies with sheer numbers and ferocity.\n\nSwarm of Dretches are often summoned by powerful demons or dark sorcerers to do their bidding. They are used as foot soldiers in demonic armies or as guardians of unholy places. Their presence is a sign of impending doom and suffering, as they bring chaos and destruction wherever they go.\n\nAdventurers who encounter a Swarm of Dretches must be prepared for a fierce battle. These creatures are relentless and will stop at nothing to tear their enemies apart. Only those with courage, skill, and a strong will can hope to defeat them and survive their wrath."}',0,'Monster Manual 2024','Demon','Bludgeoning, Cold, Fire, Lightning, Piercing, Slashing',4.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b9e-5df5-7343-aa54-053b37abf6fb'::uuid,'Swarm of Larvae','NeutralEvil','1 (XP 200; PB +2)',200,0,'Minion','Large',13,NULL,22,'3d10+6','30 ft.',NULL,NULL,NULL,14,11,14,6,12,2,'{}','Charmed, Frightened, Grappled, Paralyzed, Petrified, Prone, Restrained, Stunned','Darkvision 60 ft., Passive Perception 11','Understands all but can''t speak',2,0,2,1,-4,-2,2,'[]','Habitat: Planar (Lower Planes)','swarm of Medium Fiends','','{"value":"Sinister whispers emanate from the writhing mass of squirming larvae."}','{"value": "Swarm of Larvae is a horrifying creature that consists of a mass of tiny, wriggling larvae. These larvae are usually the offspring of larger, more dangerous monsters such as demons or undead creatures. The larvae are drawn to each other by a dark, malevolent energy, forming a swarm that moves and attacks as one entity.\n\nSwarm of Larvae are typically found in dark, dank places such as underground tunnels, graveyards, or abandoned buildings. They are attracted to sources of death and decay, feeding off the rotting flesh of corpses. They are mindless creatures, driven only by their insatiable hunger and the instinct to swarm and consume anything in their path.\n\nWhen encountered by adventurers, Swarm of Larvae will attack relentlessly, seeking to overwhelm their prey with sheer numbers. Their bites can cause painful wounds that fester and infect if not treated quickly. Those who are unlucky enough to be caught in a Swarm of Larvae may find themselves quickly overwhelmed and devoured by the writhing mass of tiny creatures.\n\nTo defeat a Swarm of Larvae, adventurers must rely on area-of-effect attacks that can target multiple creatures at once, such as fire spells or area-of-effect weapons. They must also be careful not to get surrounded by the swarm, as their sheer numbers can quickly overpower even the most skilled warriors.\n\nOverall, Swarm of Larvae are a terrifying and repulsive monster that serves as a reminder of the darker, more grotesque aspects of the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','Bludgeoning, Piercing, Slashing',1.0,NULL),
	 ('01990b9e-7d90-7c8c-bc33-c191c3d55828'::uuid,'Swarm of Piranhas','Unaligned','1 (XP 200; PB +2)',200,3,'Minion','Medium',13,NULL,28,'8d8-8','5 ft.',NULL,'40 ft.',NULL,13,16,9,1,7,2,'{}','Charmed, Frightened, Grappled, Paralyzed, Petrified, Prone, Restrained, Stunned','Darkvision 60 ft., Passive Perception 8','None',-1,3,1,-2,-4,-5,2,'[]',NULL,'Swarm of Tiny Beasts','','{"value":"Teeth flash in the murky water, a frenzy of hunger and death."}','{"value": "Swarm of Piranhas in D&D 5e is a monstrous swarm of small, vicious fish that attack in a frenzied pack, tearing apart anything in their path. These piranhas are often found in freshwater bodies such as rivers, lakes, and swamps, where they hunt in large groups to overwhelm their prey.\n\nThe lore behind the Swarm of Piranhas is that they are believed to be cursed creatures, created by a powerful druid or wizard who sought to punish those who disturbed the natural balance of the ecosystem. It is said that these piranhas are drawn to blood and can sense it from great distances, making them particularly dangerous to wounded or bleeding creatures.\n\nAdventurers who encounter a Swarm of Piranhas must be cautious and quick on their feet, as these creatures can quickly overwhelm and devour their prey in a matter of seconds. Those who manage to survive an encounter with a Swarm of Piranhas often have gruesome scars and tales of narrow escapes to tell."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',1.0,NULL),
	 ('01990b9e-594b-7099-a5c8-4206f1043f75'::uuid,'Swarm of Insects','Unaligned','1/2 (XP 100; PB +2)',100,1,'Minion','Medium',11,NULL,19,'3d8+6','20 ft.',NULL,NULL,'20 ft.',3,13,14,1,7,1,'{}','Charmed, Frightened, Grappled, Paralyzed, Petrified, Prone, Restrained, Stunned','Blindsight 30 ft., Passive Perception 8','None',2,1,-4,-2,-5,-5,2,'[]',NULL,'Swarm of Tiny Beasts','','{"value":"A writhing mass of chitin and wings skitters towards you, hungry for flesh."}','{"value": "Swarm of Insects is a common type of monster in Dungeons and Dragons 5th edition. These swarms are typically made up of various types of insects such as beetles, ants, or wasps, which come together to form a dangerous and menacing collective entity.\n\nThe lore behind Swarm of Insects typically describes them as being drawn together by some dark and malevolent force, such as a necromancer or a demon. These swarms are often used as guardians or minions by evil entities, sent to attack and harass intruders or enemies.\n\nSwarm of Insects are known for their ability to overwhelm opponents with sheer numbers, as well as their ability to inflict painful stings or bites that can cause poison or disease. They are often found in dark and damp places such as dungeons, forests, or swamps, where they can easily hide and ambush unsuspecting adventurers.\n\nIn D&D lore, Swarm of Insects are considered to be mindless and driven purely by instinct, making them difficult to reason with or control. They are typically treated as a natural hazard that must be dealt with swiftly and decisively, lest they overwhelm and devour their prey.\n\nOverall, Swarm of Insects are a formidable and dangerous monster in the world of Dungeons and Dragons, representing the primal and relentless power of nature in its most fearsome form."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',0.5,NULL),
	 ('01990b9e-a1a3-712c-9188-a0ff4fa0eeef'::uuid,'Swarm of Stirges','Unaligned','2 (XP 450; PB +2)',450,3,'Minion','Medium',14,NULL,36,'8d8','10 ft.',NULL,NULL,'40 ft.',4,16,11,2,8,6,'{}','Charmed, Frightened, Grappled, Paralyzed, Petrified, Prone, Restrained, Stunned','Darkvision 60 ft., Passive Perception 9','—',0,3,-3,-1,-2,-4,2,'[]','Habitat: Desert, Forest, Grassland, Hill, Mountain, Swamp, Underdark, Urban','swarm of Tiny Monstrosities','','{"value":"Wings buzz like a symphony of needles, hungering for warm blood."}','{"value": "Swarm of Stirges are a type of monstrous insect-like creature that are known for their insatiable thirst for blood. They are often found in dark, damp places such as caves, forests, and swamps where they hunt in large groups known as swarms.\n\nStirges are small, bat-like creatures with sharp proboscises that they use to puncture the skin of their victims and drain them of blood. They are highly aggressive and will attack anything that they perceive as a source of nourishment.\n\nThe swarm of stirges is a particularly dangerous foe as they can overwhelm their prey with their sheer numbers. They are known for their ability to quickly drain the blood from their victims, leaving behind only a lifeless husk.\n\nAdventurers should be wary when encountering a swarm of stirges, as they are difficult to fend off due to their small size and fast movements. It is recommended to use area of effect spells or attacks to deal with them effectively.\n\nIn some regions, stirges are considered to be a symbol of bad luck or an omen of impending danger. Encountering a swarm of stirges is often seen as a sign that the area is cursed or haunted.\n\nOverall, the swarm of stirges is a formidable opponent that should not be underestimated by even the most experienced adventurers."}',0,'Monster Manual 2024','','Bludgeoning, Piercing, Slashing',2.0,NULL),
	 ('01990b9e-b0c3-7a4d-aff3-04c5c23964c5'::uuid,'Swarm of Venomous Snakes','Unaligned','2 (XP 450; PB +2)',450,4,'Ambusher','Medium',14,NULL,36,'8d8','30 ft.',NULL,'30 ft.',NULL,8,18,11,1,10,3,'{}','Charmed, Frightened, Grappled, Paralyzed, Petrified, Prone, Restrained, Stunned','Blindsight 10 ft., Passive Perception 10','None',0,4,-1,0,-4,-5,2,'[]',NULL,'Swarm of Tiny Beasts','','{"value":"Hissing and slithering, the swarm coils and strikes with deadly precision."}','{"value": "The Swarm of Venomous Snakes is a terrifying sight on the battlefield, as hundreds of poisonous serpents slither and strike at their enemies in unison. These creatures are typically found in dark, damp environments such as swamps, caves, or underground tunnels.\n\nThe lore behind the Swarm of Venomous Snakes tells of a powerful druid or sorcerer who has the ability to control and command these deadly creatures. They are often used as guardians or sentinels to protect sacred sites or hidden treasures. Some believe that the snakes themselves are cursed spirits or manifestations of dark magic, bound to serve their master until their final breath.\n\nIn combat, the Swarm of Venomous Snakes can overwhelm their foes with sheer numbers and venomous bites. Their poison can cause paralysis, hallucinations, or even death if not treated quickly. Adventurers who dare to face these creatures must be prepared with antidotes, protective spells, and a strong will to withstand the relentless assault of the snakes.\n\nOverall, the Swarm of Venomous Snakes is a fearsome and deadly foe that should not be underestimated in the world of Dungeons and Dragons. Only the bravest and most skilled adventurers have a chance of surviving an encounter with these deadly creatures."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',2.0,NULL),
	 ('01990b9f-0f02-7d08-905c-10afb352a6b2'::uuid,'Thri-kreen Marauder','TrueNeutral','1 (XP 200; PB +2)',200,2,'Skirmisher','Medium',15,NULL,33,'6d8+6','40 ft.',NULL,NULL,NULL,12,15,13,8,12,7,'{"Stealth": 4, "Survival": 3, "Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','Thri-kreen; telepathy 60 ft.',1,2,1,1,-2,-1,2,'[]','Habitat: Desert, Grassland','Monstrosity','','{"value":"Four arms whirl in a deadly dance, eyes gleaming with predatory focus."}','{"value": "Thri-kreen are insect-like humanoid creatures native to the deserts of the D&D world. They are known for their agility, speed, and pack mentality. Thri-kreen Marauders are a particularly fierce and skilled subset of thri-kreen who excel in combat and raiding.\n\nMarauders are typically larger and more muscular than other thri-kreen, and they are known for their ruthless and aggressive nature. They are expert fighters, using their sharp claws and powerful mandibles to tear through enemies with ease. Marauders often travel in packs, coordinating their attacks and tactics to overwhelm their foes.\n\nIn addition to their physical prowess, Thri-kreen Marauders are also known for their cunning and strategic thinking. They are skilled hunters and trackers, able to navigate the harsh desert terrain with ease and anticipate their prey''s movements. Marauders are also proficient in stealth and ambush tactics, using their natural camouflage and agility to surprise their enemies.\n\nOverall, Thri-kreen Marauders are feared and respected in the desert regions where they dwell, known for their deadly combat skills and predatory instincts. Crossing paths with a pack of these formidable creatures is sure to spell trouble for any unsuspecting travelers."}',0,'Monster Manual 2024','','None',1.0,NULL),
	 ('01990b9f-0f50-7c46-a4e8-6d77502bcfc2'::uuid,'Thri-kreen Psion','TrueNeutral','8 (XP 3 900; PB +3)',3900,5,'Controller','Medium',16,NULL,149,'23d8+46','40 ft.',NULL,NULL,'20 ft.',18,15,14,19,12,11,'{"Stealth": 8, "Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','Thri-kreen; telepathy 120 ft.',5,5,7,1,0,7,3,'[]','Habitat: Desert, Grassland','Monstrosity','','{"value":"Mind hums with psychic power, eyes glowing with otherworldly intelligence."}','{"value": "Thri-kreen are insectoid humanoids with four arms and a mantis-like head. They are known for their speed, agility, and psionic abilities. Thri-kreen are native to the deserts of the world and are often found living in nomadic tribes.\n\nThri-kreen psions are individuals who have developed powerful psionic abilities through intense mental training and discipline. They are able to manipulate energy and matter with their minds, using their abilities to enhance their combat prowess or defend themselves from harm.\n\nThri-kreen psions are highly respected within their tribes, as their abilities make them formidable warriors and leaders. They often serve as spiritual guides and advisors, using their psionic powers to communicate with the spirits of the desert and gain insight into the world around them.\n\nIn combat, thri-kreen psions use their psionic abilities to confound and defeat their enemies. They can create illusions, manipulate the minds of their foes, and even teleport short distances to gain the upper hand in battle.\n\nOverall, thri-kreen psions are powerful and enigmatic creatures, feared and respected by those who encounter them in the harsh deserts of the world."}',0,'Monster Manual 2024','','Psychic',8.0,NULL),
	 ('01990b9f-4c44-74ba-92d8-529597b5b534'::uuid,'Tough Boss','Any','4 (XP 1,100; PB +2)',1100,2,'Brute','Medium',16,NULL,82,'11d8+33','30 ft.',NULL,NULL,NULL,17,14,16,11,10,11,'{}','None','Passive Perception 10','Common plus one other language',5,2,5,0,2,0,2,'["Chain Mail", "Heavy Crossbow", "Warhammer"]','Habitat: Any','Humanoid','','{"value":"Strides confidently, muscles rippling beneath its thick hide, eyes fixed with determination."}','{"value": "The Tough Boss is a legendary monster in the world of Dungeons and Dragons, feared by adventurers and rulers alike for its immense strength and cunning tactics. This towering creature is said to be a former warlord who made a pact with a powerful demon in exchange for eternal life and unmatched power.\n\nThe Tough Boss is known for its thick, impenetrable armor and deadly weaponry, which it wields with precision and skill. It is said to be nearly invincible in battle, able to withstand even the most powerful spells and attacks. Its army of loyal minions follow its every command, making it a formidable foe for any who dare to challenge it.\n\nLegends say that the Tough Boss resides in a fortress deep in the heart of a dark and treacherous forest, surrounded by traps and guardians. Those who have attempted to defeat it have never returned, their bodies left as a warning to others.\n\nDespite its fearsome reputation, some believe that the Tough Boss may have a weakness that can be exploited, a secret that could bring about its downfall. But uncovering this secret and defeating the Tough Boss will require bravery, skill, and a bit of luck. Are you up to the challenge?"}',0,'Monster Manual 2024 (BR)','','None',4.0,NULL),
	 ('01990b9f-729c-7293-b789-1eec243b8314'::uuid,'Treant','ChaoticGood','9 (XP 5 000; PB +4)',5000,3,'Brute','Huge',16,NULL,138,'12d12+60','30 ft.',NULL,NULL,NULL,23,8,21,12,16,12,'{}','None','Passive Perception 13','Common, Druidic, Elvish, Sylvan',5,-1,6,3,1,1,4,'[]','Habitat: Forest','Plant','','{"value":"Roots creak as it strides, leaves rustling with ancient whispers"}','{"value": "Treants are ancient, sentient beings that are protectors of the forests and all its creatures. They are massive, tree-like creatures that resemble walking trees, with thick bark-like skin and branches that serve as limbs. Treants are deeply connected to nature and have a strong bond with the plants and animals of the forest.\n\nTreants are peaceful creatures by nature, but they will fiercely defend their homes and the creatures within them from any threats. They are known to be powerful allies to those who show respect for nature and the balance of the forest. However, they can be wrathful and destructive to those who seek to harm the natural world or disrupt the harmony of the forest.\n\nSome treants are ancient beings that have lived for centuries, while others are younger and still growing in power and wisdom. They are often seen as wise and knowledgeable beings, with a deep understanding of the natural world and the creatures that inhabit it.\n\nTreants are often found deep in the heart of ancient forests, where they serve as guardians and protectors of the land. They are revered by druids and other nature-based creatures, who see them as embodiments of the raw power and beauty of the natural world. Treants are often seen as symbols of the cycle of life and death, as they are born from the earth and return to it when they die, only to be reborn again in a new form.\n\nOverall, treants are powerful and mysterious creatures that play a vital role in maintaining the balance of the natural world. Their presence is a reminder of the importance of respecting and protecting the forests and all the creatures that call it home."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing',9.0,NULL),
	 ('01990b9f-7514-75d6-a715-e5eb6a08277a'::uuid,'Tree Blight','NeutralEvil','7 (XP 2 900; PB +3)',2900,3,'Brute','Huge',15,NULL,115,'10d12+50','30 ft.',NULL,NULL,NULL,23,10,20,6,10,3,'{}','Deafened','Blindsight 60 ft., Passive Perception 10','Understands Common and Druidic but can''t speak',5,0,6,0,-4,-2,3,'[]','Habitat: Forest','Plant','','{"value":"Twisted branches creak and reach toward you, dripping with decay."}','{"value": "Tree Blights are twisted and corrupted versions of ordinary trees, transformed by dark magic or malevolent forces. These monstrous creatures resemble gnarled, blackened trees with sharp thorns and twisted branches. They are often found in dark, desolate forests or cursed lands, where they prey on unsuspecting travelers.\n\nTree Blights are known for their ability to manipulate plant life and use it as a weapon against their enemies. They can animate nearby plants to attack intruders, entangle them in roots and vines, or even sprout poisonous thorns to injure their foes. They are also immune to most forms of poison and have a natural resistance to magical effects.\n\nIn some lore, Tree Blights are created by evil druids or necromancers who seek to corrupt the natural world for their own twisted purposes. They are often used as guardians or minions to protect dark forests or cursed lands from intruders.\n\nOverall, Tree Blights are feared creatures that are best avoided by travelers venturing into dark and foreboding forests. Their malevolent nature and deadly abilities make them formidable foes for even the most experienced adventurers."}',0,'Monster Manual 2024','','None',7.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b9f-825a-7862-a84b-cd7bcdaaa2fb'::uuid,'Triceratops','Unaligned','5 (XP 1,800; PB +3)',1800,-1,'Brute','Huge',14,NULL,114,'12d12+36','50 ft.',NULL,NULL,NULL,22,9,17,2,11,5,'{}','None','Passive Perception 10','None',3,-1,6,0,-3,-4,3,'[]',NULL,'Beast','Dinosaur','{"value":"Massive horns lower, eyes fixated on intruders, ready to charge with thunderous force."}','{"value": "In Dungeons and Dragons 5th edition, the Triceratops is a large herbivorous dinosaur known for its distinctive three-horned frill. Triceratops are typically found in grasslands and forests, where they graze on vegetation and defend themselves from predators with their powerful horns.\n\nIn D&D lore, Triceratops are often portrayed as solitary creatures, although they may form small herds for protection. They are known for their fierce territorial nature and will aggressively defend their territory from any perceived threats.\n\nTriceratops are often used as mounts by humanoid races such as orcs or goblins, who view them as powerful and intimidating beasts of burden. In combat, Triceratops are formidable opponents, using their horns to charge at enemies and trample them underfoot.\n\nOverall, Triceratops are iconic creatures in the world of Dungeons and Dragons, known for their strength, resilience, and imposing presence on the battlefield."}',0,'Monster Manual 2024 (BR)','Dinosaur','None',5.0,NULL),
	 ('01990b9f-adbc-79b0-950a-332d7bb3236e'::uuid,'Troll','ChaoticEvil','5 (XP 1 800; PB +3)',1800,1,'Brute','Large',15,NULL,94,'9d10+45','30 ft.',NULL,NULL,NULL,18,13,20,7,9,7,'{"Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','Giant',5,1,4,-1,-2,-2,3,'[]','Habitat: Arctic, Forest, Hill, Mountain, Swamp, Underdark','Giant','','{"value":"Hulking brute roars, ready to feast on flesh with ravenous hunger."}','{"value": "Trolls are large, brutish humanoid creatures known for their regenerative abilities and insatiable hunger. They are often depicted as savage and violent, roaming the wilderness in search of food. Trolls are typically found in dark forests, caves, and mountains, where they make their lairs and hunt for prey.\n\nOne of the most well-known features of trolls is their incredible regenerative abilities. If a troll is injured in battle, it can quickly heal itself, regenerating lost limbs and recovering from wounds that would be fatal to other creatures. The only way to permanently kill a troll is to destroy its brain or use fire or acid to prevent its regeneration.\n\nTrolls are known to be voracious eaters, consuming anything they can catch, including animals, humanoids, and even other trolls. They are often considered to be a threat to nearby settlements, as they will raid farms and villages in search of food. Despite their brutish nature, trolls are not inherently evil and can be reasoned with or even befriended by skilled diplomats or adventurers.\n\nIn combat, trolls are fierce opponents, using their immense strength and sharp claws to tear through enemies. They are also known to be quite resilient, shrugging off blows that would incapacitate lesser creatures. Adventurers facing a troll must be prepared for a tough fight and employ tactics that can overcome its regenerative abilities.\n\nOverall, trolls are powerful and dangerous creatures that should not be underestimated. Their regenerative abilities and ferocious nature make them formidable foes for any adventuring party."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990b9f-dbe6-7112-90ab-5976d959b6e8'::uuid,'Tyrannosaurus Rex','Unaligned','8 (XP 3,900; PB +3)',3900,3,'Brute','Huge',13,NULL,136,'13d12+52','50 ft.',NULL,NULL,NULL,25,10,19,2,12,9,'{"Perception": 4}','None','Passive Perception 14','None',4,0,10,4,-1,-4,3,'[]',NULL,'Beast','Dinosaur','{"value":"Roaring deafens you as massive jaws snap shut in a thunderous display."}','{"value": "The Tyrannosaurus Rex is a fearsome and powerful predator that roams the primeval jungles and forests of the world. Known for its massive size, razor-sharp teeth, and incredible strength, the T-Rex is a force to be reckoned with in the world of Dungeons and Dragons.\n\nLegends say that the Tyrannosaurus Rex was created by ancient druids as a guardian of the natural world, tasked with protecting the balance of nature from those who would seek to exploit or destroy it. Some even believe that the T-Rex is a manifestation of the primal forces of nature itself, a living embodiment of the wild and untamed power of the world.\n\nIn battle, the Tyrannosaurus Rex is a formidable opponent, using its massive size and strength to crush and devour its enemies. Its jaws are capable of tearing through even the toughest armor, and its powerful legs allow it to move with surprising speed and agility for a creature of its size.\n\nDespite its ferocious reputation, the Tyrannosaurus Rex is not inherently evil. It is simply a creature of instinct, driven by its primal urges to hunt and feed. Those who approach the T-Rex with respect and caution may find that it can be a valuable ally in the wild, offering protection and aid to those who show it kindness.\n\nOverall, the Tyrannosaurus Rex is a legendary creature of the natural world, a symbol of the untamed wilderness and the power of nature itself. Those who face it in battle would do well to tread carefully, for the T-Rex is a force to be reckoned with in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','Dinosaur','None',8.0,NULL),
	 ('01990b9f-c19e-7b96-a3e5-c802b8ab3ccf'::uuid,'Troll Limb','ChaoticEvil','1/2 (XP 100; PB +2)',100,1,'Ambusher','Small',13,NULL,14,'4d6','20 ft.',NULL,NULL,NULL,18,12,10,1,9,1,'{}','None','Darkvision 60 ft., Passive Perception 9','—',0,1,4,-1,-5,-5,2,'[]','Habitat: Arctic, Forest, Hill, Mountain, Swamp, Underdark','Giant','','{"value":"Sinewy arm swings wildly, leaving a trail of destruction in its wake"}','{"value": "Troll Limbs are grotesque and powerful creatures that are created when a troll regenerates a severed limb. These limbs develop a mind of their own and become independent beings, seeking out prey to feed on.\n\nTroll Limbs have the regenerative abilities of their troll creators, making them difficult to kill. They are incredibly strong and agile, using their sharp claws and teeth to tear apart their victims. They are also known for their ability to regenerate quickly, making them a formidable opponent in battle.\n\nTroll Limbs are often found lurking in dark, damp places such as caves or swamps, where they can easily ambush unsuspecting travelers. They are solitary creatures, rarely forming alliances with other creatures.\n\nThese monstrous beings are feared by many, as they are relentless hunters that will stop at nothing to satisfy their insatiable hunger. Only the bravest and most skilled adventurers dare to face a Troll Limb in combat."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b9f-e836-7ff9-8a67-66236c7ce357'::uuid,'Ultroloth','NeutralEvil','13 (XP 10 000; PB +5)',10000,8,'Solo','Medium',19,NULL,221,'26d8+104','30 ft.',NULL,NULL,'60 ft.',19,16,18,19,15,18,'{"Stealth": 8, "Deception": 9, "Perception": 7}','Acid, Poison; Charmed, Frightened, Poisoned','Truesight 120 ft., Passive Perception 17','Abyssal, Infernal; telepathy 120 ft.',4,3,4,2,4,4,5,'[]','Habitat: Planar (Lower Planes)','Fiend','Yugoloth','{"value":"Cloaked in shadows, it whispers dark secrets with a chilling grin."}','{"value": "Ultroloths are powerful and cunning fiends that serve as emissaries and enforcers for the yugoloths, a neutral evil faction of fiends that dwell in the Grey Waste of Hades. Ultroloths are known for their manipulative and deceitful nature, often using their charm and persuasive abilities to further their own agendas.\n\nThese fiends are skilled at using their magical abilities to teleport and manipulate reality, making them formidable opponents in combat. They are also known for their ability to summon other fiends to aid them in battle, making them even more dangerous adversaries.\n\nUltroloths are often tasked with carrying out the will of their yugoloth masters, whether it be negotiating contracts with mortal beings, collecting souls for the lower planes, or enforcing the laws of the Grey Waste. They are highly intelligent and cunning creatures, always looking for ways to gain more power and influence in the fiendish hierarchy.\n\nOverall, Ultroloths are formidable foes that should not be underestimated in the world of Dungeons and Dragons. Their deceptive nature and powerful abilities make them a force to be reckoned with in any adventure."}',0,'Monster Manual 2024','Yugoloth','Cold, Fire, Lightning',13.0,NULL),
	 ('01990ba0-3ed3-7d1b-9f46-aba91aedab20'::uuid,'Unicorn','LawfulGood','5 (XP 1 800; PB +3)',1800,8,'Support','Large',12,NULL,97,'13d10+26','50 ft.',NULL,NULL,NULL,18,14,15,11,17,16,'{}','Poison; Charmed, Paralyzed, Poisoned','Darkvision 60 ft., Passive Perception 13','Celestial, Elvish, Sylvan; telepathy 120 ft.',2,2,4,3,3,0,3,'[]','Habitat: Forest, Planar (Feywild)','Celestial','','{"value":"Gracefully prancing, its silver horn gleams with ethereal light."}','{"value": "Unicorns are majestic and pure creatures that are often associated with healing and protection in the world of Dungeons and Dragons. These beautiful creatures are typically depicted as horse-like with a single spiraling horn protruding from their forehead. \n\nIn D&D lore, unicorns are often seen as symbols of good and are said to only appear to those who are pure of heart. They are known to possess powerful healing abilities, being able to cure diseases and even bring the dead back to life in some cases. \n\nUnicorns are also fierce defenders of the natural world and will often come to the aid of those in need, especially if they are protecting the forests or other areas of nature. They are known to be incredibly fast and agile, making them difficult to catch or defeat in battle. \n\nDespite their gentle and benevolent nature, unicorns are not to be underestimated as they are capable of using their horn as a deadly weapon when threatened. Overall, unicorns are revered and respected creatures in the world of D&D, embodying the ideals of purity, healing, and protection."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Vampire','LawfulEvil','13 (XP 10 000, or 11 500 in lair; PB +5)',10000,14,'Solo','Medium',16,NULL,195,'23d8+92','40 ft.','40 ft.',NULL,NULL,18,18,18,17,15,18,'{"Stealth": 9, "Perception": 7}','None','Darkvision 120 ft., Passive Perception 17','Common plus two other languages',9,9,4,7,9,3,5,'[]','Habitat: Underdark, Urban','Undead','','{"value":"Hunger gleams in its eyes as it glides silently towards you."}','{"value": "Vampires in D&D 5e are undead creatures that are known for their ability to charm and drain the life force from their victims. They are typically depicted as elegant and seductive beings, often with a taste for luxury and power.\n\nIn D&D lore, vampires are created when a humanoid creature is killed by a vampire''s bite and then rises again as a vampire themselves. They have a number of supernatural abilities, such as the ability to transform into a bat or mist, regenerate damage, and charm or dominate others.\n\nVampires are vulnerable to sunlight, which can severely weaken or even destroy them if they are exposed for too long. They also have a weakness to running water and must be invited into a home before they can enter.\n\nIn terms of society, vampires are often depicted as ruling over their own undead kingdoms or covens, where they command lesser undead creatures and mortal followers. They are often portrayed as cunning and manipulative, using their charm and powers of persuasion to get what they want.\n\nOverall, vampires in D&D 5e are dangerous and formidable foes, possessing a mix of supernatural abilities and intelligence that make them a challenging opponent for any adventuring party."}',0,'Monster Manual 2024 (BR)','','Necrotic',13.0,11500.0),
	 ('01990ba0-b815-75b3-9f30-91a807c062a9'::uuid,'Vampire Familiar','NeutralEvil','3 (XP 700; PB +2)',700,5,'Ambusher','Medium',15,NULL,65,'10d8+20','30 ft.','30 ft.',NULL,NULL,17,16,15,10,10,14,'{"Stealth": 7, "Perception": 4, "Persuasion": 4}','Charmed (except from its vampire master)','Darkvision 60 ft., Passive Perception 14','Common plus one other language',2,5,3,2,2,0,2,'["Daggers (10)"]','Habitat: Underdark, Urban','Humanoid','','{"value":"Whispers seductively, eyes glowing with hunger as it flits through the shadows."}','{"value": "Vampire Familiars are creatures that have been turned into vampires and serve as loyal companions to powerful vampires or necromancers. These creatures are typically former familiars or pets that have been transformed into undead beings through dark rituals or the bite of a vampire. \n\nVampire Familiars possess all the abilities of a vampire, including superhuman strength, speed, and the ability to drain the life force of their victims. They are also able to transform into bat or mist form, allowing them to move swiftly and stealthily through the night. \n\nDespite their undead nature, Vampire Familiars still retain some of their former personality and memories, making them particularly dangerous as they can use their knowledge of their former master''s enemies to aid in their destruction. They are fiercely loyal to their master and will stop at nothing to protect them, even at the cost of their own lives. \n\nVampire Familiars are often used as spies, assassins, or bodyguards by their vampire masters, using their powers of stealth and manipulation to further their dark agendas. They are feared and respected by those who know of their existence, as they are powerful and deadly creatures that should not be underestimated."}',0,'Monster Manual 2024 (BR)','','Necrotic',3.0,NULL),
	 ('01990ba1-056f-79ba-8588-c0862f05a8e4'::uuid,'Vampire Spawn','NeutralEvil','5 (XP 1 800; PB +3)',1800,3,'Ambusher','Medium',16,NULL,90,'12d8+36','30 ft.',NULL,NULL,NULL,16,16,16,11,10,12,'{"Stealth": 6, "Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','Common plus one other language',3,6,3,3,1,0,3,'[]','Habitat: Underdark, Urban','Undead','','{"value":"Eyes gleam with hunger as it lurches forward, baring elongated fangs."}','{"value": "Vampire spawn are creatures that have been created through the process of being bitten and drained of blood by a vampire. Unlike true vampires, vampire spawn are not able to create more of their kind through their own bites. They are essentially thralls to their vampire masters, bound by their will and forced to do their bidding.\n\nVampire spawn retain some of the powers of a true vampire, such as increased strength, speed, and regeneration, as well as the ability to charm and dominate others. However, they are not as powerful as their masters and lack some of the more potent abilities of a true vampire, such as shape-shifting and the ability to turn into mist.\n\nVampire spawn are often used by vampires as minions and guards, sent out to do their bidding and protect their lairs. They are cursed creatures, forever trapped in a state between life and death, constantly craving blood but unable to create more of their kind. They are feared and reviled by most people, as they are seen as harbingers of the true terror that is a full-fledged vampire."}',0,'Monster Manual 2024 (BR)','','Necrotic',5.0,NULL),
	 ('01990ba1-0ebc-7675-9e75-f74c5194d246'::uuid,'Vampire Umbral Lord','LawfulEvil','15 (XP 13 000, or 15 000 in lair; PB +5)',13000,14,'Solo','Medium',16,NULL,187,'22d8+88','40 ft.','40 ft.',NULL,'40 ft.',20,18,18,19,16,21,'{"Arcana": 9, "Stealth": 9, "Perception": 13}','Cold, Necrotic; Charmed, Exhaustion','Blindsight 120 ft., Passive Perception 23','Common plus three other languages',4,9,10,8,10,4,5,'[]','Habitat: Underdark, Urban','Undead','','{"value":"Shadows swirl and cling to its form, eyes glowing with hunger and malice"}','{"value": "The Vampire Umbral Lord is a powerful and ancient undead creature that has mastered the dark arts of shadow magic. It is said to have been a powerful vampire lord in life, but after delving too deeply into the realm of shadows, it was transformed into a being of pure darkness.\n\nThe Vampire Umbral Lord is able to manipulate shadows to its advantage, using them to conceal itself from enemies or to launch devastating shadow-based attacks. It is also able to drain the life force of its victims with a touch, siphoning their energy to sustain its own unholy existence.\n\nLegends say that the Vampire Umbral Lord resides in a dark and twisted castle hidden within the shadowy depths of a cursed forest, where it commands legions of undead minions and plots dark schemes to extend its influence over the land. Those who dare to face this terrifying creature must be prepared for a battle of both strength and wit, as the Vampire Umbral Lord is a cunning and ruthless foe."}',0,'Monster Manual 2024','','None',15.0,15000.0);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990ba1-1781-72c7-a196-7efa46118fb4'::uuid,'Vine Blight','NeutralEvil','1/2 (XP 100; PB +2)',100,-1,'Ambusher','Medium',12,NULL,19,'3d8+6','20 ft.',NULL,NULL,NULL,15,8,14,5,10,3,'{"Stealth": 1}','Deafened','Blindsight 60 ft., Passive Perception 10','Common',2,-1,2,0,-4,-3,2,'[]','Habitat: Forest','Plant','','{"value":"Twisting vines writhe, constricting and suffocating all in their path"}','{"value": "Vine Blights are plant creatures that resemble twisted vines and branches that move and attack on their own. They are created by dark magic or the corruption of nature, and are often found in forests or other areas where plant life is abundant. Vine Blights are known for their ability to entangle and restrain their enemies with their long, thorny vines. They are also capable of draining the life force from creatures they come into contact with, making them a dangerous foe to encounter in the wild. In some cases, Vine Blights may serve as guardians or minions to a more powerful nature-based being, such as a druid or a powerful fey creature. Overall, Vine Blights are considered to be a threat to those who venture into their territory, and adventurers should tread carefully when encountering them."}',0,'Monster Manual 2024','','None',0.5,NULL),
	 ('01990ba1-65b6-7a75-a157-ead1d511ef35'::uuid,'Vrock','ChaoticEvil','6 (XP 2 300; PB +3)',2300,2,'Brute','Large',15,NULL,152,'16d10+64','40 ft.',NULL,NULL,'60 ft.',17,15,18,8,13,8,'{}','Poison; Poisoned','Darkvision 120 ft., Passive Perception 11','Abyssal; telepathy 120 ft.',4,5,3,4,2,-1,3,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Wings beat furiously as it screeches, talons poised to strike."}','{"value": "Vrocks are large, grotesque, avian demons that are often summoned by powerful spellcasters to serve as guardians or soldiers. They are known for their fierce and aggressive nature, as well as their ability to unleash powerful attacks in combat.\n\nIn the lore of Dungeons and Dragons, vrocks are said to originate from the Abyss, the chaotic and evil plane of existence. They are often found in the service of powerful demon lords, acting as their minions and enforcers. Vrocks are known for their love of violence and chaos, and they take great pleasure in causing destruction and mayhem wherever they go.\n\nIn terms of abilities, vrocks possess sharp claws and beaks that they use to tear apart their enemies in combat. They also have the ability to unleash a deafening screech that can stun and disorient their foes. Additionally, vrocks are capable of casting spells and using their demonic powers to manipulate and control their surroundings.\n\nOverall, vrocks are fearsome and dangerous creatures that should not be underestimated in combat. Their demonic nature and penchant for violence make them formidable opponents for any adventurer brave enough to face them."}',0,'Monster Manual 2024 (BR)','Demon','Cold, Fire, Lightning',6.0,NULL),
	 ('01990ba1-747c-7190-af9c-d8e426c92d24'::uuid,'Vulture','Unaligned','0 (XP 10; PB +2)',10,0,'Support','Medium',10,NULL,5,'1d8+1','10 ft.',NULL,NULL,'50 ft.',7,10,13,2,12,4,'{"Perception": 3}','None','Passive Perception 13','None',1,0,-2,1,-3,-4,2,'[]',NULL,'Beast','','{"value":"Feathers ruffle as it eyes the party, waiting for weakness to show."}','{"value": "In the world of Dungeons and Dragons, the Vulture is a large scavenging bird often found in desolate and remote areas. Vultures are known for their keen eyesight and sense of smell, which allows them to locate carrion from great distances. They are often associated with death and decay, as they feed primarily on the remains of dead animals.\n\nVultures are typically solitary creatures, although they may gather in large groups when food is plentiful. They are not known for being aggressive towards living creatures, but they will defend their food source fiercely if necessary. Some vultures are even known to follow hunting parties or armies in search of easy meals.\n\nIn some cultures, vultures are seen as symbols of death and the afterlife, while in others they are considered omens of bad luck. Despite their somewhat sinister reputation, vultures play an important role in maintaining the balance of ecosystems by cleaning up decaying matter and preventing the spread of disease.\n\nIn Dungeons and Dragons, vultures are often encountered in wilderness areas or near battlefields, where they can provide an added element of danger to adventurers. They are typically depicted as large, menacing birds with sharp talons and beaks, and are often used by dungeon masters to add atmosphere to their campaigns."}',0,'Monster Manual 2024 (BR)','','None',0.0,NULL),
	 ('01990ba1-c083-784c-b3c0-e5467b244e32'::uuid,'Warrior Commander','TrueNeutral','10 (XP 5 900; PB +4)',5900,9,'Leader','Medium',18,NULL,161,'19d8+76','30 ft.',NULL,NULL,NULL,21,20,18,14,16,14,'{"Insight": 7, "Athletics": 9, "Perception": 7}','None','Passive Perception 17','Common plus one other language',8,9,9,7,2,2,4,'["Greatsword", "Longbow", "Plate Armor"]','Habitat: Any','Humanoid','','{"value":"Commander stands tall, barking orders with a voice that shakes the ground."}','{"value": "The Warrior Commander is a fearsome and powerful monster in the world of D&D 5e. These creatures are known for their exceptional combat skills and their ability to lead armies into battle. Warrior Commanders are often found at the head of a group of soldiers, directing their every move with precision and skill.\n\nThese creatures are typically highly intelligent and strategic thinkers, able to anticipate their opponent''s moves and plan their own attacks accordingly. They are also known for their incredible physical strength and agility, making them formidable opponents in combat.\n\nWarrior Commanders are often seen as symbols of power and authority in the world of D&D, with many aspiring warriors seeking to emulate their skills and rise through the ranks to become leaders themselves. They are revered by their followers and feared by their enemies, making them a force to be reckoned with on the battlefield.\n\nOverall, the Warrior Commander is a formidable and respected monster in D&D 5e, known for their exceptional combat skills, strategic thinking, and leadership abilities."}',0,'Monster Manual 2024','','None',10.0,NULL),
	 ('01990ba1-f9a3-7a38-b354-a999f5fa4e47'::uuid,'Warrior Veteran','TrueNeutral','3 (XP 700; PB +2)',700,3,'Soldier','Medium',17,NULL,65,'10d8+20','30 ft.',NULL,NULL,NULL,16,13,14,10,11,10,'{"Athletics": 5, "Perception": 2}','None','Passive Perception 12','Common plus one other language',2,1,3,0,0,0,2,'["Greatsword", "Heavy Crossbow", "Splint Armor"]','Habitat: Any','Humanoid','','{"value":"Proudly stands tall, scars telling tales of battles won and lost"}','{"value": "The Warrior Veteran is a seasoned and battle-hardened warrior who has seen many conflicts and emerged victorious from numerous battles. They are skilled in a variety of combat techniques and are often sought after as mercenaries or hired muscle for those in need of protection.\n\nThese warriors have honed their skills through years of training and experience, making them formidable opponents on the battlefield. They are typically outfitted in heavy armor and armed with a variety of weapons, such as swords, axes, or spears.\n\nWarrior Veterans are known for their loyalty and sense of duty, often fighting for a cause they believe in or for a leader they respect. They are disciplined and fearless in the face of danger, willing to lay down their lives for their comrades or their cause.\n\nDespite their grizzled appearance and tough exterior, Warrior Veterans can also be compassionate and honorable individuals, showing mercy to their enemies or aiding those in need. They are respected by their peers and feared by their enemies, making them a force to be reckoned with on the battlefield."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990ba2-01e5-7e62-a23b-bc4f7f433f37'::uuid,'Water Elemental','TrueNeutral','5 (XP 1 800; PB +3)',1800,2,'Brute','Large',14,NULL,114,'12d10+48','30 ft.',NULL,'90 ft.',NULL,18,14,18,5,10,8,'{}','Poison; Exhaustion, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Darkvision 60 ft., Passive Perception 10','Primordial (Aquan)',4,2,4,0,-1,-3,3,'[]','Habitat: Coastal, Planar (Elemental Plane of Water), Swamp, Underwater','Elemental','','{"value":"Ripples in its form dance with a serene fluidity, beckoning with watery grace."}','{"value": "Water Elementals are powerful beings that are formed from the very essence of water itself. They are typically summoned or created by powerful spellcasters or elemental beings to serve as guardians, protectors, or minions. \n\nWater Elementals are usually found in bodies of water such as oceans, rivers, lakes, or even magical fountains. They are able to manipulate water in various ways, such as creating tidal waves, whirlpools, or even summoning water creatures to aid them in battle. \n\nWater Elementals are neutral in alignment and are typically not hostile unless provoked. They are known to be unpredictable and can be easily swayed by emotions or the will of their summoner. \n\nIn combat, Water Elementals are formidable opponents, using their watery form to absorb physical attacks and their ability to control water to drown or freeze their enemies. They are resistant to most types of damage and can move through water with incredible speed and agility. \n\nOverall, Water Elementals are mysterious and enigmatic creatures that are often feared and respected by those who encounter them. Their connection to the element of water gives them a sense of power and fluidity that makes them a force to be reckoned with in the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','Acid, Fire',5.0,NULL),
	 ('01990ba2-04ab-796d-b138-5a3d719d2c6a'::uuid,'Water Weird','TrueNeutral','3 (XP 700; PB +2)',700,3,'Ambusher','Large',13,NULL,65,'10d10+10','5 ft.',NULL,'60 ft.',NULL,17,16,13,11,10,10,'{}','Poison; Exhaustion, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Blindsight 30 ft., Passive Perception 10','Understands Primordial but can''t speak',1,3,3,0,0,0,2,'[]','Habitat: Underdark, Urban','Elemental','','{"value":"Ripples silently, its form twisting and contorting beneath the surface."}','{"value": "A Water Weird is a strange elemental creature that resides in bodies of water such as lakes, rivers, or even wells. It is a magical being made of water that is bound to a specific area and will attack any intruders that come near its territory.\n\nThe Water Weird is a mysterious and elusive creature, often only seen as a disturbance in the water or a faint shimmering presence. It is said to be created by powerful water elementals or wizards to guard their treasures or secrets.\n\nThe Water Weird has the ability to manipulate water and can create whirlpools, waves, or jets of water to attack its enemies. It is a formidable opponent, able to drown unsuspecting adventurers or drag them down into the depths of the water.\n\nSome believe that the Water Weird is a sentient being with its own thoughts and motivations, while others think it is merely a mindless guardian bound to its duty. Regardless, encountering a Water Weird is always a dangerous and unpredictable experience for any adventurer brave enough to venture into its domain."}',0,'Monster Manual 2024','','Fire',3.0,NULL),
	 ('01990ba2-397a-7509-a669-39a4d196f52a'::uuid,'Werebear','NeutralGood','5 (XP 1 800; PB +3)',1800,3,'Brute','Medium',15,NULL,135,'18d8+54','30 ft.','30 ft.',NULL,NULL,19,10,17,11,12,12,'{"Perception": 7}','None','Darkvision 60 ft., Passive Perception 17','Common (can''t speak in bear form)',3,0,4,1,1,0,3,'["four Handaxes"]','Habitat: Arctic, Forest, Hill','Monstrosity','Lycanthrope','{"value":"Massive werebear stands on hind legs, roaring with primal fury."}','{"value": "In the world of Dungeons and Dragons, the Werebear is a type of lycanthrope that is able to transform between the form of a humanoid and that of a bear. They are often depicted as noble creatures with a strong sense of justice and a deep connection to nature.\n\nIn their humanoid form, Werebears are typically large and muscular individuals with thick, shaggy hair and sharp claws. They are known for their incredible strength and resilience, as well as their ability to heal quickly from injuries.\n\nDuring a full moon, a Werebear may transform into their bear form, which is a massive, fearsome creature with powerful jaws and razor-sharp claws. In this form, they are even more formidable in combat and possess heightened senses of smell and hearing.\n\nDespite their fearsome appearance, Werebears are not inherently evil and often use their powers to protect the natural world and those in need. They are known to live in secluded forests or mountains, where they form close-knit communities with other Werebears and creatures of the wild.\n\nHowever, like all lycanthropes, Werebears must be careful to control their urges and avoid harming innocent creatures while in their bear form. If they lose control or give in to their more savage instincts, they may be hunted down by adventurers or other lycanthropes seeking to eliminate a potential threat.\n\nOverall, Werebears are complex and fascinating creatures in the world of Dungeons and Dragons, embodying both the ferocity of the bear and the nobility of the humanoid form."}',0,'Monster Manual 2024 (BR)','Lycanthrope','None',5.0,NULL),
	 ('01990ba2-6114-7177-8fb4-2818a044b6e2'::uuid,'Wereboar','NeutralEvil','4 (XP 1 100; PB +2)',1100,2,'Brute','Medium',15,NULL,97,'15d8+30','30 ft.',NULL,NULL,NULL,17,10,15,10,11,8,'{"Perception": 2}','None','Passive Perception 12','Common (can''t speak in boar form)',2,0,3,0,-1,0,2,'["six Javelins"]','Habitat: Forest, Grassland, Hill','Monstrosity','Lycanthrope','{"value":"Snorting loudly, it charges with tusks bared, eyes gleaming in the moonlight."}','{"value": "In Dungeons and Dragons 5th Edition, wereboars are creatures that are cursed with lycanthropy, transforming them into half-man, half-boar creatures under the light of the full moon. These creatures are known for their ferocity and strength, often hunting in packs and terrorizing villages and travelers.\n\nAccording to lore, wereboars are typically chaotic evil in alignment, driven by their primal instincts and desires. They are known to be skilled fighters and hunters, using their razor-sharp tusks and brute strength to overpower their enemies. In addition to their physical prowess, wereboars are also known for their cunning and ability to outsmart their opponents.\n\nIn terms of their origins, wereboars are said to be created when a humanoid is bitten by a wereboar and contracts lycanthropy. The curse then takes hold during the next full moon, transforming the individual into a wereboar. Some believe that wereboars are the result of a curse placed upon those who have committed heinous acts or angered powerful beings.\n\nOverall, wereboars are fearsome creatures in the world of Dungeons and Dragons, posing a significant threat to those who cross their path. Players must exercise caution when encountering these creatures, as they are known to be relentless in their pursuit of prey."}',0,'Monster Manual 2024 (BR)','Lycanthrope','None',4.0,NULL),
	 ('01990ba2-adea-76b2-95a6-c217f23fb54c'::uuid,'Weretiger','TrueNeutral','4 (XP 1 100; PB +2)',1100,2,'Skirmisher','Medium',12,NULL,120,'16d8+48','30 ft.',NULL,NULL,NULL,17,15,16,10,13,11,'{"Stealth": 4, "Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','Common (can''t speak in tiger form)',3,2,3,1,0,0,2,'["Longbow"]','Habitat: Desert, Forest, Grassland','Monstrosity','Lycanthrope','{"value":"Lurking in the shadows, it prowls with deadly grace and predatory intent."}','{"value": "In the world of Dungeons and Dragons, weretigers are powerful shape-shifting creatures that combine the strength and ferocity of a tiger with the cunning and intelligence of a human. They are often portrayed as solitary hunters, using their shapeshifting abilities to blend in with their surroundings and stalk their prey without being detected.\n\nWeretigers are said to be fiercely territorial and will fiercely defend their territory from any intruders. They are known for their speed and agility, making them formidable opponents in combat. Despite their predatory nature, weretigers are not always portrayed as evil creatures and may sometimes be depicted as guardians of the wilderness or protectors of the natural world.\n\nLike other lycanthropes, weretigers are vulnerable to silver weapons and can only be killed by a silvered weapon while in their beast form. They are also said to have a weakness to magical spells and effects that target shapechangers.\n\nOverall, weretigers are a fearsome and mysterious creature in the world of D&D, with a rich lore and history that adds depth to any campaign."}',0,'Monster Manual 2024 (BR)','Lycanthrope','None',4.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990ba2-e045-7df6-864d-b0a83c748250'::uuid,'Werewolf','ChaoticEvil','3 (XP 700; PB +2)',700,4,'Skirmisher','Medium',15,NULL,71,'11d8+22','40 ft.',NULL,NULL,NULL,16,14,14,10,11,10,'{"Stealth": 4, "Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','Common (can''t speak in wolf form)',2,2,3,0,0,0,2,'["Longbow"]','Habitat: Forest, Hill','Monstrosity','Lycanthrope','{"value":"Fur bristles, fangs bared, the werewolf snarls with hunger under the full moon."}','{"value": "In Dungeons and Dragons 5th edition, the werewolf is a fearsome creature that is cursed to transform into a wolf-like monster under the light of the full moon. Werewolves are typically depicted as being incredibly strong and agile, with razor-sharp claws and teeth. They are known for their ferocity in battle and their insatiable hunger for human flesh.\n\nWerewolves are often portrayed as tragic figures, cursed to live a dual existence as both man and beast. In their human form, they may struggle to control their violent urges and resist the call of the full moon. Some werewolves may even try to find a cure for their curse, seeking out powerful magic or alchemical remedies to free themselves from their monstrous alter ego.\n\nIn D&D lore, werewolves are often depicted as pack creatures, living in secluded forests or mountains and preying on unsuspecting travelers. They are considered to be a serious threat to those who venture into their territory, as their speed and strength make them formidable opponents in combat. However, some werewolves may be more cunning and intelligent, able to outsmart their enemies and manipulate them to serve their own dark purposes.\n\nOverall, werewolves are a classic monster in D&D lore, representing the primal fear of the unknown and the struggle between man and beast. They are a popular choice for DMs looking to add a touch of horror and mystery to their campaigns, as players never know when the next full moon will rise and bring out the savage nature of the werewolf."}',0,'Monster Manual 2024 (BR)','Lycanthrope','None',3.0,NULL),
	 ('01990ba3-3ff6-7d5c-8664-486a196fb755'::uuid,'White Dragon Wyrmling','ChaoticEvil','2 (XP 450; PB +2)',450,2,'Solo','Medium',16,NULL,32,'5d8+10','30 ft.',NULL,'30 ft.','60 ft.',14,10,14,5,10,11,'{"Stealth": 2, "Perception": 4}','Cold','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14','Draconic',2,2,2,2,0,-3,2,'[]','Habitat: Arctic','Dragon','Chromatic','{"value":"Frosty breath billows out as it coils its serpentine body, eyes glinting with malice."}','{"value": "White Dragons are one of the most classic and iconic creatures in Dungeons & Dragons lore. They are known for their fierce and predatory nature, as well as their ability to breathe blasts of icy cold air. \n\nWhite Dragon Wyrmlings are young white dragons, typically around 5 to 15 years old. Despite their youth, they are still formidable predators and can be quite dangerous to unsuspecting adventurers. They are smaller and less powerful than adult white dragons, but they still possess many of the same abilities, such as their breath weapon and their keen senses.\n\nWhite Dragon Wyrmlings are typically found in cold, snowy environments such as mountains or icy caves. They are solitary creatures, preferring to hunt and live on their own rather than in groups. They are known for their cunning and intelligence, using their environment to their advantage when hunting prey.\n\nIn terms of combat, White Dragon Wyrmlings rely heavily on their breath weapon, which can freeze their enemies in place or cause them to suffer cold damage. They are also skilled in physical combat, using their sharp claws and teeth to tear through their foes.\n\nOverall, White Dragon Wyrmlings are fearsome opponents that should not be underestimated, even in their younger years. Adventurers would do well to approach them with caution and respect their power and cunning."}',0,'Monster Manual 2024 (BR)','Chromatic','None',2.0,NULL),
	 ('01990ba3-7008-7efe-b3a4-73087f811671'::uuid,'Winter Wolf','NeutralEvil','3 (XP 700; PB +2)',700,1,'Ambusher','Large',13,NULL,75,'10d10+20','50 ft.',NULL,NULL,NULL,18,13,14,7,12,8,'{"Stealth": 5, "Perception": 5}','Cold','Passive Perception 15','Common, Giant',2,1,4,1,-1,-2,2,'[]','Habitat: Arctic','Monstrosity','','{"value":"Frosty breath billows as it prowls, eyes gleaming with predatory hunger."}','{"value": "In Dungeons and Dragons 5th edition, the Winter Wolf is a large, wolf-like creature that dwells in cold, snowy regions. These creatures are known for their icy breath and ability to summon blizzards to aid them in battle.\n\nWinter Wolves are said to be intelligent and cunning, often working together in packs to take down larger prey. They are known to be fiercely territorial and will defend their hunting grounds fiercely against any intruders.\n\nLegends say that Winter Wolves are actually the offspring of a white dragon and a normal wolf, giving them their icy breath and resistance to cold. Some believe that these creatures are cursed or blessed by powerful winter spirits, giving them their otherworldly abilities.\n\nEncountering a Winter Wolf in the wild is a dangerous proposition, as they are known to be deadly hunters and relentless predators. Adventurers who come across these creatures must be cautious and prepared for a fierce battle if they wish to survive the encounter."}',0,'Monster Manual 2024 (BR)','','None',3.0,NULL),
	 ('01990ba3-b839-7a29-a74b-7d028cc297cb'::uuid,'Wyvern','Unaligned','6 (XP 2 300; PB +3)',2300,0,'Skirmisher','Large',14,NULL,127,'15d10+45','30 ft.',NULL,NULL,'80 ft.',19,10,16,5,12,6,'{"Perception": 4}','None','Darkvision 120 ft., Passive Perception 14','—',3,0,4,1,-2,-3,3,'[]','Habitat: Hill, Mountain','Dragon','','{"value":"Wings beat ominously as it circles, eyeing its prey with hunger."}','{"value": "In Dungeons and Dragons 5th edition, the wyvern is a fearsome and powerful creature that resembles a dragon, but with only two legs instead of four. Wyverns are known for their poisonous stingers, which they use to paralyze and kill their prey. They are often found in mountainous regions or other remote areas, where they hunt for large animals to feed on.\n\nWyverns are known to be aggressive and territorial, often attacking anything that comes too close to their lair. They are intelligent creatures, capable of understanding and communicating in Draconic, and are often used as mounts by evil beings such as dragons or giants.\n\nIn D&D lore, wyverns are considered to be a lower form of dragon, lacking the intelligence and magical abilities of their larger cousins. They are often used as guardians or pets by more powerful creatures, or as mounts by orc tribes or other evil factions.\n\nOverall, the wyvern is a dangerous and formidable creature in the world of Dungeons and Dragons, capable of posing a serious threat to adventurers who cross its path."}',0,'Monster Manual 2024 (BR)','','None',6.0,NULL),
	 ('01990ba3-5f04-78b0-9430-6fbafe10933f'::uuid,'Winged Kobold','TrueNeutral','1/4 (XP 50; PB +2)',50,3,'Skirmisher','Small',15,NULL,10,'4d6-4','30 ft.',NULL,NULL,'30 ft.',7,16,9,8,7,8,'{}','None','Darkvision 60 ft., Passive Perception 8','Common, Draconic',-1,3,-2,-2,-1,-1,2,'[]','Habitat: Arctic, Coastal, Desert, Forest, Hill, Mountain, Swamp, Underdark, Urban','Dragon','','{"value":"Leaping from the shadows, it screeches and dives with razor-sharp talons outstretched."}','{"value": "In the world of Dungeons and Dragons, Winged Kobolds are a unique variant of the standard Kobold creature. These creatures are typically more cunning and agile than their grounded counterparts, using their wings to swoop down on unsuspecting foes and attack from the air.\n\nWinged Kobolds are often found in mountainous regions or caves, where their ability to fly gives them a significant advantage in hunting and defending their territory. They are known for their loyalty to powerful dragon masters, often serving as scouts or messengers for these larger, more powerful creatures.\n\nDespite their small size and relatively weak physical strength, Winged Kobolds are formidable opponents when working together in groups, using their aerial mobility to outmaneuver enemies and strike from unexpected angles. They are also known for their skill in trap-making and ambush tactics, making them dangerous foes for even experienced adventurers to face.\n\nIn terms of appearance, Winged Kobolds are similar to regular Kobolds but with the addition of leathery wings that allow them to fly. They are typically around 2-3 feet tall, with scaly skin, sharp teeth, and a cunning glint in their eyes. Overall, Winged Kobolds are a fascinating and challenging monster to encounter in the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','None',0.25,NULL),
	 ('01990ba3-de82-7b6d-aa69-e8c531983283'::uuid,'Xorn','TrueNeutral','5 (XP 1 800; PB +3)',1800,0,'Solo','Medium',19,NULL,84,'8d8+48','20 ft.',NULL,NULL,NULL,17,10,22,11,10,11,'{"Stealth": 6, "Perception": 6}','Poison; Paralyzed, Petrified, Poisoned','Darkvision 60 ft., Tremorsense 60 ft., Passive Perception 16','Primordial (Terran)',6,0,3,0,0,0,3,'[]','Habitat: Planar (Elemental Plane of Earth), Underdark','Elemental','','{"value":"Jaws grind greedily, eyes darting between shimmering gems."}','{"value": "Xorns are strange, earth-elemental creatures that dwell deep underground in the dark places of the world. They have a bizarre appearance, with three powerful arms emerging from a rocky, segmented body. Their large, gaping mouths are filled with sharp teeth, and they use their powerful jaws to crush and consume rocks and minerals.\n\nXorns are known for their insatiable hunger for minerals and gemstones, which they consume as their primary source of sustenance. They can sense the presence of precious metals and stones from great distances, and will burrow through solid rock to reach them. They are highly valued by miners and treasure hunters for their ability to locate valuable ores and gems.\n\nDespite their fearsome appearance and destructive capabilities, xorns are not inherently evil creatures. They are neutral in alignment and are generally unconcerned with the affairs of surface-dwellers. However, they can become aggressive if they feel threatened or if their food source is threatened.\n\nIn combat, xorns are formidable opponents, using their immense strength and powerful jaws to crush their enemies. They are also capable of burrowing through solid rock at incredible speeds, allowing them to surprise and overwhelm their foes. Adventurers who encounter a xorn deep underground would be wise to tread carefully and approach with caution."}',0,'Monster Manual 2024 (BR)','','None',5.0,NULL),
	 ('01990ba4-0775-7c93-a9c9-7f5a06bb764b'::uuid,'Yeti','ChaoticEvil','3 (XP 700; PB +2)',700,1,'Brute','Large',12,NULL,51,'6d10+18','40 ft.','40 ft.',NULL,NULL,18,13,16,8,12,7,'{"Stealth": 5, "Perception": 5}','Cold','Darkvision 60 ft., Passive Perception 15','Yeti',3,1,4,1,-2,-1,2,'[]','Habitat: Arctic','Monstrosity','','{"value":"Snow crunches beneath its massive feet as it bellows into the frosty air."}','{"value": "In Dungeons and Dragons 5th edition, the Yeti is a large, ape-like creature that inhabits cold and snowy regions. Known for their white fur and fierce demeanor, Yetis are solitary hunters that prowl the icy wilderness in search of prey.\n\nAccording to lore, Yetis are believed to be distant relatives of the more civilized and intelligent creatures known as the abominable snowmen. Some stories suggest that Yetis possess a primitive form of intelligence and can communicate with each other through a series of grunts and gestures.\n\nLegends also tell of Yetis possessing supernatural abilities, such as the power to turn invisible or create blizzard-like conditions to confuse and disorient their prey. Despite their brutish appearance, Yetis are often depicted as cunning and resourceful hunters, capable of outsmarting even the most skilled adventurers.\n\nIn D&D campaigns, Yetis are typically encountered in snowy mountain ranges, caves, and other cold environments. They are often portrayed as dangerous and territorial creatures that will attack anything that enters their territory, making them a formidable foe for adventurers brave enough to face them."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01990ba4-1890-76bb-b10f-6df9bdd65981'::uuid,'Yochlol','ChaoticEvil','10 (XP 5 900; PB +4)',5900,8,'Controller','Medium',15,NULL,153,'18d8+72','30 ft.','30 ft.',NULL,NULL,15,19,18,13,15,17,'{"Insight": 6, "Deception": 11}','Poison; Poisoned','Darkvision 120 ft., Passive Perception 12','Abyssal, Elvish, Undercommon',4,8,2,6,7,5,4,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Whispers seductively, tendrils writhing with dark enchantment"}','{"value": "Yochlols are powerful demons that serve the demon queen Lolth, the primary deity of the drow. These shapeshifting demons are often sent by Lolth to do her bidding on the Material Plane, carrying out tasks such as assassinations, espionage, and corrupting mortals.\n\nYochlols have the ability to change their form at will, often taking on the appearance of a beautiful female drow to deceive their enemies. They are skilled in dark magic and possess an array of powerful spells and abilities, making them formidable adversaries in combat.\n\nIn addition to their combat prowess, yochlols are also known for their ability to manipulate and control others, using their seductive nature to bend mortals to their will. They are cunning and manipulative creatures, always seeking to further the goals of Lolth and advance their own power within the ranks of the demon queen''s followers.\n\nOverall, yochlols are dangerous and unpredictable creatures that should be approached with caution by any adventurer brave enough to face them in battle."}',0,'Monster Manual 2024','Demon','Cold, Fire, Lightning',10.0,NULL),
	 ('01990ba4-378c-7e18-9d1c-5dd1b073934f'::uuid,'Young Black Dragon','ChaoticEvil','7 (XP 2 900; PB +3)',2900,5,'Brute','Large',18,NULL,127,'15d10+45','40 ft.',NULL,'40 ft.','80 ft.',19,14,17,12,11,15,'{"Stealth": 5, "Perception": 6}','Acid','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 16','Common, Draconic',3,5,4,3,2,1,3,'[]','Habitat: Swamp','Dragon','Chromatic','{"value":"Scales shimmer as it slinks out of the shadows, eyes fixed on prey."}','{"value": "Young Black Dragons are cunning and cruel creatures that dwell in swamps, marshes, and other dark, watery environments. They are known for their stealth and ambush tactics, using their natural camouflage to surprise their prey.\n\nThese dragons are fiercely territorial, claiming large swaths of land as their own and fiercely defending it from intruders. They are known to attack unsuspecting travelers, raiding villages, and even striking bargains with other creatures in exchange for protection or services.\n\nYoung Black Dragons are proficient swimmers and can hold their breath for extended periods of time, allowing them to move stealthily through water and surprise their enemies from below. They are also skilled in combat, using their sharp claws, teeth, and powerful tail to subdue and defeat their foes.\n\nOverall, Young Black Dragons are feared and respected by those who know of their existence, as they are powerful and dangerous predators that should not be underestimated."}',0,'Monster Manual 2024 (BR)','Chromatic','None',7.0,NULL),
	 ('01990b98-9e5a-72db-b8ca-65afee882069'::uuid,'Pteranodon','Unaligned','1/4 (XP 50; PB +2)',50,2,'Skirmisher','Medium',13,NULL,13,'3d8','10 ft.',NULL,NULL,'60 ft.',12,15,10,2,9,5,'{"Perception": 1}','None','Passive Perception 11','None',0,2,1,-1,-3,-4,2,'[]',NULL,'Beast','Dinosaur','{"value":"Silhouetted against the sun, it swoops down with a piercing screech."}','{"value": "Pteranodons are large flying reptiles that are commonly found in tropical and subtropical regions. They have a wingspan of up to 30 feet and are known for their distinctive long crest on their heads. Pteranodons are carnivorous and primarily feed on fish and small animals, using their sharp beaks to catch and eat their prey.\n\nIn the world of Dungeons and Dragons, pteranodons are often depicted as aggressive creatures that will attack anything that they perceive as a threat. They are known for their speed and agility in the air, making them formidable opponents for adventurers who encounter them in the wild.\n\nPteranodons are typically encountered in mountainous regions or near bodies of water where they can easily hunt for food. They are often used by evil creatures such as goblins or orcs as mounts, adding an extra layer of danger for adventurers who may come across them.\n\nOverall, pteranodons are fearsome creatures that are best avoided unless one is prepared for a challenging and potentially deadly encounter."}',0,'Monster Manual 2024 (BR)','Dinosaur','None',0.25,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990ba4-6585-7ae6-a512-a299d2b4901e'::uuid,'Young Brass Dragon','ChaoticGood','6 (XP 2 300; PB +3)',2300,3,'Artillery','Large',17,NULL,110,'13d10+39','40 ft.',NULL,NULL,'80 ft.',19,10,17,12,11,15,'{"Stealth": 3, "Perception": 6, "Persuasion": 5}','Fire','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 16','Common, Draconic',3,3,4,3,2,1,3,'[]','Habitat: Desert','Dragon','Metallic','{"value":"Wings unfurl as it lets out a scorching blast of fiery breath."}','{"value": "Young Brass Dragons are known for their playful and mischievous nature. They are typically found in deserts or other arid regions, where they use their camouflage abilities to blend in with their surroundings. They are skilled burrowers and often create elaborate underground lairs to hide their hoards of treasure.\n\nDespite their love of pranks and jokes, Young Brass Dragons are also fiercely territorial and will defend their territory with fiery breath and sharp claws if necessary. They are highly intelligent creatures and enjoy engaging in conversation with other beings, often testing their wit and intelligence.\n\nIn combat, Young Brass Dragons rely on their breath weapon - a cone of scorching hot fire - as well as their physical strength and agility. They are known for their quick reflexes and cunning tactics, using their surroundings to their advantage in battle.\n\nOverall, Young Brass Dragons are complex creatures that embody both the playful and fierce aspects of dragonkind. They are a formidable opponent in combat, but can also be a valuable ally if approached with respect and intelligence."}',0,'Monster Manual 2024 (BR)','Metallic','None',6.0,NULL),
	 ('01990ba4-869c-7210-8f30-7961ff114b30'::uuid,'Young Bronze Dragon','LawfulGood','8 (XP 3 900; PB +3)',3900,3,'Artillery','Large',17,NULL,142,'15d10+60','40 ft.',NULL,'40 ft.','80 ft.',21,10,19,14,13,17,'{"Insight": 4, "Stealth": 3, "Perception": 7}','Lightning','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 17','Common, Draconic',4,3,5,4,3,2,3,'[]','Habitat: Coastal','Dragon','Metallic','{"value":"Wings spread wide, it breathes a crackling bolt of lightning into the air."}','{"value": "Young Bronze Dragons are proud and noble creatures that often take on the role of protectors of the land. They are known for their benevolent nature and willingness to help those in need. These dragons are typically found in coastal regions or near bodies of water, where they can swim and fly with ease.\n\nYoung Bronze Dragons have shimmering scales that range in color from a deep copper to a bright bronze. They are skilled in combat and possess a breath weapon that allows them to exhale a powerful bolt of lightning, which can be devastating to their enemies.\n\nThese dragons are highly intelligent and often form alliances with other good-aligned creatures, such as elves or other dragons. They are known to be wise and knowledgeable, often offering advice and guidance to those who seek their help.\n\nOverall, Young Bronze Dragons are revered for their strength, wisdom, and compassion, making them valuable allies and formidable foes in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','Metallic','None',8.0,NULL),
	 ('01990ba4-c421-75bc-a07e-40fec710eb31'::uuid,'Young Gold Dragon','LawfulGood','10 (XP 5 900; PB +4)',5900,6,'Solo','Large',18,NULL,178,'17d10+85','40 ft.',NULL,'40 ft.','80 ft.',23,14,21,16,13,20,'{"Insight": 5, "Stealth": 6, "Perception": 9, "Persuasion": 9}','Fire','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 19','Common, Draconic',5,6,6,5,5,3,4,'[]','Habitat: Forest, Grassland','Dragon','Metallic','{"value":"Glowing with noble grace, it eyes you with curiosity and wisdom."}','{"value": "In the world of Dungeons and Dragons, Gold Dragons are one of the most noble and powerful creatures. They are known for their wisdom, compassion, and sense of justice. Young Gold Dragons are the offspring of adult Gold Dragons, and while they may not have the same level of experience or power as their parents, they still possess many of the same qualities.\n\nYoung Gold Dragons are typically good-aligned and strive to protect the innocent and uphold justice. They are highly intelligent and often serve as protectors of villages or guardians of sacred sites. They have a strong sense of honor and will go to great lengths to uphold their principles.\n\nIn combat, Young Gold Dragons are formidable opponents. They have powerful breath weapons in the form of a cone of fire, as well as sharp claws and teeth. They are also skilled in magic, able to cast spells that can both heal allies and harm enemies.\n\nOverall, Young Gold Dragons are noble and powerful creatures that embody the ideals of justice and compassion. They are revered by many as symbols of hope and protection in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','Metallic','None',10.0,NULL),
	 ('01990ba4-e2c5-7577-9e5b-0a2aa37753fa'::uuid,'Young Green Dragon','LawfulEvil','8 (XP 3 900; PB +3)',3900,4,'Solo','Large',18,NULL,136,'16d10+48','40 ft.',NULL,'40 ft.','80 ft.',19,12,17,16,13,15,'{"Stealth": 4, "Deception": 5, "Perception": 7}','Poison; Poisoned','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 17','Common, Draconic',3,4,4,4,2,3,3,'[]','Habitat: Forest','Dragon','Chromatic','{"value":"Wings unfurl with a thunderous snap, revealing gleaming scales and glowing eyes"}','{"value": "The Young Green Dragon is a fearsome and cunning creature that is known for its deceptive nature and its toxic breath. These dragons are typically found in dense forests and swamps, where they use their natural camouflage to blend in with their surroundings. They are known for their intelligence and their ability to outwit their foes in combat.\n\nYoung Green Dragons are known to be particularly fond of treasure and will go to great lengths to hoard as much wealth as possible. They are also known to be very territorial, often attacking anyone who intrudes on their territory without hesitation. Despite their young age, these dragons are still incredibly powerful and should not be underestimated.\n\nIn combat, Young Green Dragons rely on their sharp claws, powerful bite, and deadly breath weapon to take down their enemies. Their breath weapon is a noxious cloud of poisonous gas that can quickly incapacitate even the most skilled adventurers. They are also known to be adept at using their surroundings to their advantage, such as using trees and foliage to ambush their enemies.\n\nOverall, the Young Green Dragon is a formidable foe that should be approached with caution and respect. Their cunning nature and toxic breath make them a dangerous adversary for any adventurer brave enough to face them."}',0,'Monster Manual 2024 (BR)','Chromatic','None',8.0,NULL),
	 ('01990ba4-f743-7608-9cf7-fac7ec5870b8'::uuid,'Young Red Dragon','ChaoticEvil','10 (XP 5 900; PB +4)',5900,4,'Brute','Large',18,NULL,178,'17d10+85','40 ft.','40 ft.',NULL,'80 ft.',23,10,21,14,11,19,'{"Stealth": 4, "Perception": 8}','Fire','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 18','Common, Draconic',5,4,6,4,4,2,4,'[]','Habitat: Hill, Mountain','Dragon','Chromatic','{"value":"Roaring, it flexes its wings and exhales scorching flames."}','{"value": "In the world of Dungeons and Dragons, Young Red Dragons are powerful and fearsome creatures known for their fiery breath and insatiable greed. These dragons are typically found dwelling in volcanic regions or deep underground in caves and dungeons.\n\nYoung Red Dragons are cunning and intelligent beings, often using their superior intellect to outsmart their foes. They are also highly territorial and will fiercely defend their lairs from any intruders. These dragons are known for their fiery breath weapon, which can unleash a stream of scorching flames that can incinerate anything in its path.\n\nDespite their fierce nature, Young Red Dragons are also known to be cunning negotiators and may be willing to make deals or alliances with adventurers if it benefits them in some way. However, their ultimate goal is always to amass wealth and power, and they will stop at nothing to achieve their desires.\n\nEncountering a Young Red Dragon in the world of Dungeons and Dragons is a dangerous and thrilling experience, as these creatures are formidable opponents that should not be underestimated. Only the bravest and most skilled adventurers have a chance of defeating a Young Red Dragon and claiming the treasure that lies within its lair."}',0,'Monster Manual 2024 (BR)','Chromatic','None',10.0,NULL),
	 ('01990ba5-07d4-7327-a197-220f29438c1f'::uuid,'Young Remorhaz','Unaligned','5 (XP 1 800; PB +3)',1800,1,'Brute','Large',14,NULL,93,'11d10+33','30 ft.',NULL,NULL,NULL,18,13,17,3,10,4,'{}','Cold, Fire','Darkvision 60 ft., Tremorsense 60 ft., Passive Perception 10','—',3,1,4,0,-3,-4,3,'[]','Habitat: Arctic','Monstrosity','','{"value":"Steam billows from its glowing maw as it burrows towards you with hungry anticipation."}','{"value": "The Young Remorhaz is a fearsome creature that resembles a giant centipede with a fiery exoskeleton. These creatures are known for their immense size, strength, and ferocity. They are often found in cold, mountainous regions where they burrow through the ice and snow in search of prey.\n\nYoung Remorhazes are solitary creatures and fiercely territorial, attacking anything that comes too close to their lairs. They are highly resistant to cold damage and can emit a scorching heat from their bodies that can burn their enemies. They are also known for their powerful bite and ability to swallow their prey whole.\n\nIn some cultures, Young Remorhazes are feared and even worshipped as gods of the frozen wilderness. They are considered symbols of strength and resilience, and many adventurers seek to challenge these powerful creatures in order to prove their own bravery and skill. Overall, the Young Remorhaz is a formidable opponent that should not be underestimated in the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','None',5.0,NULL),
	 ('01990ba5-3179-7370-806a-46800b48c495'::uuid,'Young White Dragon','ChaoticEvil','6 (XP 2 300; PB +3)',2300,3,'Soldier','Large',17,NULL,123,'13d10+52','40 ft.',NULL,'40 ft.','80 ft.',18,10,18,6,11,12,'{"Stealth": 3, "Perception": 6}','Cold','Blindsight 30 ft., Darkvision 120 ft., Passive Perception 16','Common, Draconic',4,3,4,3,1,-2,3,'[]','Habitat: Arctic','Dragon','Chromatic','{"value":"Frost swirls around as it snarls, icy breath chilling the air around it."}','{"value": "Young White Dragons are fearsome creatures known for their icy breath and formidable physical strength. They are typically found in cold, snowy regions, such as mountains or frozen wastelands. \n\nThese dragons are known for their aggressive and territorial nature, often hunting and attacking anything that enters their domain. They are also known to be cunning and intelligent creatures, capable of setting traps and using tactics to outsmart their enemies.\n\nYoung White Dragons are born with a natural ability to manipulate ice and cold, allowing them to freeze their foes with their breath or create icy terrain to impede their enemies'' movement. They are also skilled in physical combat, using their sharp claws and teeth to tear through armor and flesh.\n\nDespite their formidable abilities, Young White Dragons are still considered relatively weaker compared to older and more powerful dragons. They are often used as guards or servants by older dragons, or as threats to be vanquished by brave adventurers seeking glory and treasure."}',0,'Monster Manual 2024 (BR)','Chromatic','None',6.0,NULL),
	 ('01990ba5-40a7-754d-abee-531bf4e05ef7'::uuid,'Yuan-ti Abomination','NeutralEvil','7 (XP 2 900; PB +3)',2900,6,'Brute','Large',15,NULL,127,'15d10+45','40 ft.','30 ft.',NULL,NULL,19,16,17,17,18,15,'{"Stealth": 6, "Perception": 7}','Poison; Poisoned','Darkvision 60 ft., Passive Perception 17','Abyssal, Common, Draconic',3,3,4,4,2,3,3,'[]','Habitat: Desert, Forest, Swamp, Urban','Monstrosity','','{"value":"Serpentine coils writhe menacingly, eyes gleaming with malice"}','{"value": "Yuan-ti Abominations are powerful, snake-like creatures that are the result of a ritualistic transformation undergone by yuan-ti purebloods or malisons. Through a series of dark rituals and sacrifices, a yuan-ti abomination is created, imbuing them with immense strength, magical abilities, and a terrifying appearance.\n\nThese creatures are often seen as leaders or high-ranking members within yuan-ti society, commanding respect and fear from their lesser kin. They possess a mix of snake and humanoid features, with serpentine scales, fangs, and eyes, along with human-like limbs and torsos. Their magical abilities include shape-shifting, spellcasting, and the ability to command snakes and other creatures.\n\nYuan-ti Abominations are often found leading yuan-ti cults or serving as powerful allies to other evil beings such as demons or devils. They are cunning and manipulative, using their powers of persuasion and deception to achieve their goals. Their ultimate ambition is to further the goals of their dark deity, Merrshaulk, and bring about the domination of all other races."}',0,'Monster Manual 2024','','None',7.0,NULL),
	 ('01990b8b-be83-7e61-84be-ac62ebdc70c4'::uuid,'Giant Rat','Unaligned','1/8 (XP 25; PB +2)',25,3,'Minion','Small',13,NULL,7,'2d6','30 ft.','30 ft.',NULL,NULL,7,16,11,2,10,4,'{"Perception": 2}','None','Darkvision 60 ft., Passive Perception 12','None',0,5,-2,0,-3,-4,2,'[]',NULL,'Beast','','{"value":"Skittering frantically, its red eyes gleaming with hunger and disease."}','{"value": "In the world of Dungeons and Dragons, Giant Rats are typically seen as a common and mundane creature, often found infesting sewers, dungeons, and other dark and damp places. However, these oversized rodents can still pose a threat to adventurers with their sharp teeth and disease-ridden bites.\n\nGiant Rats are known for their scavenging nature, feeding on scraps of food and any other small creatures they can catch. They are typically seen as pests and are often hunted or exterminated by city guards or adventurers looking to clear out infestations.\n\nIn some cases, Giant Rats may be controlled or bred by more powerful creatures, such as wererats or evil wizards, to serve as minions or guards. They can also be found in swarms, overwhelming their prey with sheer numbers.\n\nDespite their low intelligence and relatively weak combat abilities, Giant Rats can still be a threat to unwary travelers or inexperienced adventurers. Their ability to spread disease through their bites can also make them a dangerous foe if not dealt with swiftly."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990ba5-488e-721d-82b5-0a8f25d90b0a'::uuid,'Yuan-ti Infiltrator','NeutralEvil','1 (XP 200; PB +2)',200,1,'Skirmisher','Medium',11,NULL,40,'9d8','30 ft.',NULL,NULL,NULL,11,12,11,13,14,12,'{"Stealth": 3, "Deception": 5, "Perception": 4}','Poison; Poisoned','Darkvision 60 ft., Passive Perception 14','Abyssal, Common, Draconic',0,1,0,2,1,1,2,'["Scimitar"]','Habitat: Desert, Forest, Swamp, Urban','Monstrosity','','{"value":"Serpentine figure slithers silently, eyes calculating and tongue flicking in the shadows"}','{"value": "Yuan-ti Infiltrators are snake-like humanoid creatures that are known for their ability to blend in with human society and manipulate others to achieve their own goals. These cunning and deceptive creatures are often found plotting in the shadows, using their shape-shifting abilities and charm to manipulate those around them.\n\nYuan-ti Infiltrators are typically members of the Yuan-ti race, a group of snake-like creatures who worship and serve evil serpent gods. They are often found working as spies, assassins, or cult leaders, using their natural charisma and cunning to gain the trust of others before betraying them at the opportune moment.\n\nIn combat, Yuan-ti Infiltrators are skilled manipulators, using their shape-shifting abilities to confuse and disorient their enemies. They are also known for their deadly poison attacks, which can incapacitate or kill their foes with just a single strike.\n\nOverall, Yuan-ti Infiltrators are dangerous and deceptive foes, who excel at using their intelligence and charm to achieve their sinister goals. Players should be wary of trusting anyone who seems too good to be true, as they may just be a disguised Yuan-ti Infiltrator in disguise."}',0,'Monster Manual 2024','','None',1.0,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990bad-ef51-7b44-bdca-f7a4fcf1190e'::uuid,'Will-o''-Wisp','ChaoticEvil','2 (XP 450; PB +2)',450,9,'Ambusher','Tiny',19,NULL,27,'11d4','5 ft.',NULL,NULL,'50 ft.',1,28,10,13,14,11,'{}','Lightning, Poison; Exhaustion, Grappled, Paralyzed, Petrified, Poisoned, Prone, Restrained, Unconscious','Darkvision 120 ft., Passive Perception 12','Common plus one other language',0,9,-5,2,0,1,2,'[]','Habitat: Forest, Swamp, Urban','Undead','','{"value":"Light flickers and dances, drawing you closer with an enchanting allure"}','{"value": "Will-o''-wisps are mysterious and malevolent creatures that appear as floating orbs of bright light. They are said to be the spirits of souls who died tragically or were otherwise lost in the darkness, seeking to lead travelers astray in the night.\n\nThese creatures are known for their ability to create illusions and manipulate light, often luring unsuspecting victims into dangerous situations. They are also known to feed on the life force of living creatures, draining them of their energy until they are left weakened and vulnerable.\n\nWill-o''-wisps are often found in dark and desolate places such as swamps, marshes, and graveyards. They are elusive and difficult to catch, as they can easily disappear into the darkness or change their form to evade capture.\n\nThose who encounter a will-o''-wisp are advised to proceed with caution, as these creatures are not to be underestimated. Their deceptive nature and powerful abilities make them a formidable foe for even the most experienced adventurers."}',0,'Monster Manual 2024 (BR)','','Acid, Bludgeoning, Cold, Fire, Necrotic, Piercing, Slashing',2.0,NULL),
	 ('01990bbd-65b1-7982-a900-580d5c5dee1f'::uuid,'Yuan-ti Malison (Type 1)','NeutralEvil','3 (XP 700; PB +2)',700,2,'Ambusher','Medium',12,NULL,66,'12d8+12','30 ft.','30 ft.',NULL,NULL,16,14,13,14,16,12,'{"Stealth": {"bonus": 4, "condition": "while in snake form", "conditionalBonus": 6}}','Poison; Poisoned','Darkvision 60 ft., Passive Perception 13','Abyssal, Common, Draconic',1,2,3,3,1,2,2,'[]','Habitat: Desert, Forest, Swamp, Urban','Monstrosity','','{"value":"Scales ripple as it slithers, eyes fixed on prey with hunger."}','{"value": "The Yuan-ti Malison (Type 1) is a snake-like humanoid creature that is part of the Yuan-ti race, a group of serpentfolk creatures known for their cunning and deceitful nature. The Type 1 Malison is one of the lower-ranking members of the Yuan-ti hierarchy, serving as scouts, spies, and assassins for their more powerful leaders.\n\nThese creatures are often found lurking in the shadows, using their natural stealth and shape-shifting abilities to blend in with their surroundings. They are highly intelligent and are skilled in both melee and ranged combat, using poison-tipped weapons and deadly spells to take down their enemies.\n\nThe Yuan-ti Malison (Type 1) is known for their worship of the serpent god, Merrshaulk, and they often seek to further the goals of their deity by infiltrating human societies and sowing chaos and discord. They are feared and reviled by many, as their manipulative and treacherous nature makes them dangerous foes to encounter.\n\nOverall, the Yuan-ti Malison (Type 1) is a cunning and deadly creature that poses a significant threat to any who cross their path. Their presence in the world of Dungeons and Dragons adds an element of mystery and danger, as players must always be on guard for the serpentfolk''s deceptive schemes."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01990bc3-f466-7e3b-ab27-409bedb12abe'::uuid,'Yuan-ti Malison (Type 3)','NeutralEvil','3 (XP 700; PB +2)',700,2,'Brute','Medium',12,NULL,66,'12d8+12','30 ft.','30 ft.',NULL,NULL,16,14,13,14,16,12,'{"Stealth": {"bonus": 4, "condition": "while in snake form", "conditionalBonus": 6}}','Poison; Poisoned','Darkvision 60 ft., Passive Perception 13','Abyssal, Common, Draconic',1,2,3,3,1,2,2,'[]','Habitat: Desert, Forest, Swamp, Urban','Monstrosity','','{"value":"Serpentine figure coils tightly, eyes flickering with malice."}','{"value": "The Yuan-ti Malison, also known as the Type 3 Yuan-ti, are a powerful and cunning race of snake-like humanoids in the Dungeons and Dragons universe. They are considered to be the most powerful and elite members of the Yuan-ti society, often serving as leaders and commanders of their lesser kin.\n\nYuan-ti Malisons are known for their mastery of dark magic and their ability to shape-shift into a more human-like form, allowing them to blend in with other humanoid races and manipulate them to further their own goals. They are also skilled in combat, using both their natural snake-like abilities and weapons to take down their enemies.\n\nIn terms of lore, Yuan-ti Malisons are often depicted as cruel and ruthless beings who seek power and domination over others. They are known to worship dark deities and practice dark rituals in order to gain more power and influence. They are often found leading armies of lesser Yuan-ti in their quest for conquest and control.\n\nOverall, Yuan-ti Malisons are a formidable and dangerous foe in the world of Dungeons and Dragons, capable of outsmarting and outmaneuvering their enemies with their cunning and deceitful nature. Players who encounter them should be prepared for a tough and challenging battle."}',0,'Monster Manual 2024','','None',3.0,NULL),
	 ('01991605-4bd8-70c9-9520-3c710e71d074'::uuid,'Serpentshade Stalker','NeutralEvil','3 (XP 700; PB +2)',700,2,'Ambusher','Medium',12,NULL,66,'12d8+12','30 ft.','30 ft.',NULL,NULL,16,14,13,14,16,12,'{"Stealth": {"bonus": 4, "condition": "while in snake form", "conditionalBonus": 6}}','Poison; Poisoned','Darkvision 60 ft., Passive Perception 13','Abyssal, Common, Draconic',1,2,3,3,1,2,2,'[]','Habitat: Desert, Forest, Swamp, Urban','Monstrosity','','Stealthy serpent assassins strike from shadows, vanishing before retaliation can be taken.','{"originalLore": "The Yuan-ti Malison (Type 1) Ambusher is a cunning and elusive serpent-like creature that excels in the art of ambush and stealth. Unlike other Yuan-ti Malisons, this particular variation has evolved to have a heightened sense of awareness and agility, allowing it to move swiftly and silently through its environment.\n\nOne unique ability of the Yuan-ti Malison (Type 1) Ambusher is its ability to blend seamlessly into its surroundings, almost becoming one with the shadows. This allows it to lie in wait for its prey, patiently biding its time until the perfect moment to strike. Once it has chosen its target, the Ambusher will launch a surprise attack, using its razor-sharp fangs and venomous bite to incapacitate its victim.\n\nAfter delivering its initial strike, the Yuan-ti Malison (Type 1) Ambusher will quickly retreat into the shadows, disappearing from sight before its prey even has a chance to react. It will then circle back around, using its superior speed and agility to outmaneuver its target and strike again from a different angle. This hit-and-run tactic makes it extremely difficult for its prey to defend against, as they are constantly on edge and unable to predict where the Ambusher will strike next.\n\nIn addition to its exceptional stealth and ambush abilities, the Yuan-ti Malison (Type 1) Ambusher also possesses a heightened sense of smell, allowing it to track its prey with uncanny accuracy. This, combined with its natural agility and speed, makes it a formidable opponent in any environment.\n\nOverall, the Yuan-ti Malison (Type 1) Ambusher is a deadly predator that relies on its superior stealth and ambush tactics to take down its prey. Its ability to strike quickly and disappear just as fast sets it apart from other creatures of its kind, making it a feared and respected hunter in the wild."}',0,'AI Generated','','None',3.0,NULL),
	 ('01992a30-6e17-7f7b-bc06-9cc11cb17518'::uuid,'Shadow Stalker','Unaligned','3 (XP 700; PB +2)',700,3,'Ambusher','Large',14,NULL,45,'7d10+7','30 ft.','30 ft.',NULL,NULL,15,16,12,6,10,6,'{"Stealth": 7}','None','Darkvision 60 ft., Passive Perception 10','—',1,3,2,0,-2,-2,2,'[]','Habitat: Desert, Forest, Grassland, Hill, Planar (Ethereal Plane), Underdark, Urban','Monstrosity','','Stealthy Phase Spiders strike from shadows, vanishing after a deadly ambush.','{"originalLore": "The Ambusher Phase Spider is a cunning and elusive predator that lurks in the shadows, waiting for the perfect moment to strike. Unlike traditional Phase Spiders, these creatures have evolved to be even more adept at ambushing their prey.\n\nOne unique ability of the Ambusher Phase Spider is its ability to create illusory duplicates of itself, confusing and disorienting its target. These duplicates can move independently, allowing the Ambusher to attack from multiple angles simultaneously.\n\nIn addition to their teleportation abilities, Ambusher Phase Spiders have developed a venomous bite that paralyzes their victims, making it easier for them to drag their prey back to their lair. Once their target is incapacitated, the Ambusher will cocoon them in webbing, slowly draining their life force until they are ready to feast.\n\nThese creatures are highly intelligent and strategic hunters, often working together in small packs to take down larger prey. They are patient and methodical, carefully planning their attacks to ensure the greatest chance of success.\n\nThose who encounter an Ambusher Phase Spider should beware, as these creatures are masters of deception and stealth. Only the most vigilant and resourceful adventurers stand a chance against these deadly predators."}',0,'AI Generated','','None',3.0,NULL),
	 ('01990ba3-9645-73c0-9c3a-7435da06e06c'::uuid,'Worg','NeutralEvil','1/2 (XP 100; PB +2)',100,1,'Skirmisher','Large',13,NULL,26,'4d10+4','50 ft.',NULL,NULL,NULL,16,13,13,7,11,8,'{"Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','Goblin, Worg',1,1,3,0,-1,-2,2,'[]','Habitat: Forest, Grassland, Hill, Planar (Feywild)','Fey','','{"value":"Baring its teeth, the worg snarls and circles, eyes fixed on its prey."}','{"value": "In the world of Dungeons & Dragons, a Worg is a large and vicious wolf-like creature that is often found in the company of goblins, orcs, and other evil humanoids. Worgs are known for their keen senses, ferocious bite, and pack mentality.\n\nWorgs are highly intelligent creatures and are capable of understanding and communicating in various languages, making them valuable allies to their humanoid companions. They are often used as mounts by goblin and orc riders, as their speed and strength make them formidable in battle.\n\nWorgs are known for their predatory nature and are often found hunting in packs. They are relentless hunters and will pursue their prey for miles if necessary. They are also known to be cunning and will use tactics and strategy to outsmart their enemies.\n\nIn some D&D campaigns, it is said that Worgs were created by dark and malevolent forces to serve as guardians and enforcers for evil creatures. They are often feared and respected by those who dwell in the wild and are known to be formidable adversaries in combat.\n\nOverall, Worgs are dangerous and deadly creatures that should not be underestimated by adventurers who encounter them in their travels."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b8b-51c4-7e64-a091-e018d08d0b1e'::uuid,'Giant Frog','Unaligned','1/4 (XP 50; PB +2)',50,1,'Skirmisher','Medium',11,NULL,18,'4d8','30 ft.',NULL,'30 ft.',NULL,12,13,11,2,10,3,'{"Stealth": 4, "Perception": 2}','None','Darkvision 30 ft., Passive Perception 12','None',0,1,1,0,-4,-4,2,'[]',NULL,'Beast','','{"value":"It croaks loudly, its sticky tongue lashing out towards you."}','{"value": "In the world of Dungeons and Dragons, the Giant Frog is a large amphibious creature that dwells in swamps, marshes, and other wetlands. These creatures are known for their voracious appetite and powerful jumping ability, which they use to ambush their prey.\n\nGiant Frogs are typically solitary creatures, but some may form small groups or colonies in areas with abundant food sources. They are opportunistic hunters and will eat almost anything that they can catch, including insects, small animals, and even unwary adventurers.\n\nThese creatures are highly territorial and will aggressively defend their hunting grounds from intruders. They are known for their loud croaking calls, which they use to communicate with other frogs and warn off potential threats.\n\nIn some D&D campaigns, Giant Frogs may be used as mounts by certain humanoid races or as guardians of hidden swamps or treasure troves. They are also sometimes used as familiars by spellcasters, who value their hunting skills and ability to navigate through water with ease.\n\nOverall, Giant Frogs are fearsome predators that are best avoided by those who wish to stay on their good side. Their powerful jaws and sharp teeth make them formidable opponents in combat, and their ability to leap great distances makes them difficult to escape from once they have caught their prey."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b8b-7739-7ab9-81c0-8544d5f95137'::uuid,'Giant Lizard','Unaligned','1/4 (XP 50; PB +2)',50,1,'Skirmisher','Large',12,NULL,19,'3d10+3','40 ft.','40 ft.',NULL,NULL,15,12,13,2,10,5,'{}','None','Darkvision 60 ft., Passive Perception 10','None',1,3,2,0,-3,-4,2,'[]',NULL,'Beast','','{"value":"Jaws snap shut with a thunderous crunch, sending scales scattering in all directions"}','{"value": "In the world of Dungeons and Dragons, the Giant Lizard is a fearsome creature that roams the wilds and jungles of the realm. These massive reptiles are known for their sharp teeth, powerful jaws, and swift movements, making them formidable predators.\n\nLegends say that Giant Lizards were created by ancient druids as guardians of the natural world, imbued with primal magic that allows them to blend seamlessly into their surroundings and strike with deadly precision. Some believe that these creatures are the descendants of dragons, claiming their ferocity and strength from their draconic ancestors.\n\nDespite their intimidating appearance, Giant Lizards are not inherently evil and will typically only attack if provoked or hungry. They are solitary creatures, preferring to hunt alone and avoid confrontation with other predators. However, they are fiercely territorial and will defend their territory fiercely against any intruders.\n\nAdventurers who encounter a Giant Lizard in the wild must exercise caution and approach with care, as these creatures are known to be quick and aggressive when threatened. Those who manage to defeat a Giant Lizard can often find valuable resources in its hide and teeth, making them a sought-after target for hunters and collectors."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b9b-b26a-7327-8441-d4f66f09bca3'::uuid,'Skeleton','LawfulEvil','1/4 (XP 50; PB +2)',50,3,'Soldier','Medium',14,NULL,13,'2d8+4','30 ft.',NULL,NULL,NULL,10,16,15,6,8,5,'{}','Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 9','Understands Common plus one other language but can''t speak',2,3,0,-1,-3,-2,2,'["Shortbow", "Shortsword"]','Habitat: Planar (Shadowfell), Underdark, Urban','Undead','','{"value":"Bones rattle as it tilts its skull to fix its hollow gaze upon you"}','{"value": "In Dungeons and Dragons, a skeleton is an undead creature created from the remains of a deceased humanoid. These creatures are often animated through dark magic or necromancy, typically by a powerful necromancer or dark sorcerer. \n\nSkeletons are mindless servants, following the commands of their creator without question. They are often used as guards, soldiers, or laborers by those who seek to wield the power of the undead. \n\nIn combat, skeletons are relentless and relentless, using their bony claws and weapons to attack their enemies. They are immune to many forms of damage, such as poison and exhaustion, and are resistant to necrotic damage. However, they are vulnerable to bludgeoning damage, as their fragile bones can be easily shattered.\n\nSkeletons are often found in ancient crypts, graveyards, or other places where death and decay are prevalent. They are considered a common threat for adventurers exploring dark and dangerous dungeons."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b9b-be81-714c-8a96-1504fc180739'::uuid,'Slaad Tadpole','ChaoticNeutral','1/8 (XP 25; PB +2)',25,2,'Ambusher','Tiny',12,NULL,7,'3d4','30 ft.',NULL,NULL,NULL,7,15,10,3,5,3,'{"Stealth": 4}','None','Darkvision 60 ft., Passive Perception 7','Understands Slaad but can''t speak',0,2,-2,-3,-4,-4,2,'[]','Habitat: Planar (Limbo)','Aberration','','{"value":"Glistening tadpole writhes, emitting a foul stench as it hungrily eyes its prey."}','{"value": "In the world of Dungeons & Dragons, Slaad tadpoles are small, amphibious creatures that are the larvae of the chaotic and destructive Slaad. Slaad are extraplanar beings that come from the plane of Limbo, where chaos reigns supreme.\n\nSlaad tadpoles are typically found in pools of water or other damp environments, where they feed on organic matter and grow rapidly. As they mature, they undergo a metamorphosis into one of the various forms of adult Slaad, such as the red, blue, or green Slaad.\n\nSlaad tadpoles are dangerous creatures in their own right, as they can infect other creatures with a disease known as Chaos Phage. This disease can transform a creature into a Slaad if left untreated, or kill them if their body cannot handle the chaotic energies.\n\nOverall, Slaad tadpoles are a symbol of chaos and destruction in the world of Dungeons & Dragons, and encountering one can be a dangerous and unpredictable experience for adventurers."}',0,'Monster Manual 2024 (BR)','','Acid, Cold, Fire, Lightning, Thunder',0.125,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b8b-aaa9-7731-bbdf-5536ecc06363'::uuid,'Giant Owl','TrueNeutral','1/4 (XP 50; PB +2)',50,2,'Ambusher','Large',12,NULL,19,'3d10+3','5 ft.',NULL,NULL,'60 ft.',13,15,12,10,14,10,'{"Stealth": 6, "Perception": 6}','None','Darkvision 120 ft., Passive Perception 16','Celestial; understands Common, Elvish, and Sylvan but can''t speak them',1,2,1,4,0,0,2,'[]',NULL,'Celestial','','{"value":"Wings beat softly as it surveys the forest with keen, golden eyes"}','{"value": "In the world of Dungeons and Dragons, the Giant Owl is a majestic and formidable creature that roams the skies with grace and power. These creatures are known for their keen eyesight, sharp talons, and silent flight, making them deadly predators in the wild.\n\nGiant Owls are often revered by druids and nature-based societies for their connection to the natural world and their role as guardians of the forest. They are known to be wise and mysterious creatures, often serving as guides or messengers for those who earn their trust.\n\nDespite their gentle nature, Giant Owls are fierce defenders of their territory and will not hesitate to attack anything they perceive as a threat. They are skilled hunters, preying on small animals and creatures that roam the forests and mountains where they make their homes.\n\nEncountering a Giant Owl in the wild can be a breathtaking and awe-inspiring experience, as they are truly magnificent creatures to behold. However, adventurers should approach with caution, as these creatures are not to be underestimated in battle."}',0,'Monster Manual 2024 (BR)','','Necrotic, Radiant',0.25,NULL),
	 ('01990b83-1f9a-7427-808a-c5984549892c'::uuid,'Bullywug Warrior','TrueNeutral','1/4 (XP 50; PB +2)',50,2,'Skirmisher','Medium',15,NULL,11,'2d8+2','30 ft.',NULL,'30 ft.',NULL,12,14,13,7,10,7,'{"Stealth": 4}','None','Passive Perception 10','Bullywug, Common',1,2,1,0,-2,-2,2,'[]','Habitat: Swamp','Fey','','{"value":"Croaks loudly, leaping forward with spear raised high."}','{"value": "In the world of Dungeons and Dragons, Bullywugs are frog-like humanoid creatures that inhabit swamps and marshlands. Bullywug Warriors are the elite members of their society, known for their strength, combat prowess, and fierce loyalty to their leaders.\n\nThese creatures typically stand around 5 to 6 feet tall and have powerful limbs that allow them to leap great distances. Bullywug Warriors are often equipped with primitive weapons such as spears, clubs, and shields, which they use to defend their territory and hunt for food.\n\nBullywugs are known for their aggressive nature and territorial behavior, often attacking intruders on sight. They are ruled by a hierarchy of chieftains and shamans, with the Bullywug Warriors serving as the enforcers of their will.\n\nIn battle, Bullywug Warriors are formidable opponents, using their agility and strength to overwhelm their enemies. They are known for their ability to work together as a cohesive unit, using tactics and strategy to outmaneuver their foes.\n\nOverall, Bullywug Warriors are fearsome creatures that should not be underestimated in combat, especially when encountered in their natural habitat of swamps and marshes."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b88-0695-7c32-8632-b3e6866e0e39'::uuid,'Elk','Unaligned','1/4 (XP 50; PB +2)',50,0,'Skirmisher','Large',10,NULL,11,'2d10','50 ft.',NULL,NULL,NULL,16,10,11,2,10,6,'{"Perception": 2}','None','Darkvision 60 ft., Passive Perception 12','None',0,0,3,0,2,4,2,'[]',NULL,'Beast','','{"value":"Gentle elk graze peacefully, their antlers catching the fading sunlight."}','{"value": "In Dungeons and Dragons 5th edition, Elk are large, majestic creatures that roam the forests and grasslands of the world. They are known for their impressive antlers and swift speed, making them a popular choice for hunters and trackers.\n\nIn D&D lore, Elk are often seen as symbols of strength, grace, and nobility. They are respected by many druids and rangers for their connection to nature and the wilderness. Some believe that Elk possess a certain wisdom and mystical energy, and that encountering one in the wild can bring good fortune.\n\nIn the game, Elk are typically depicted as neutral creatures that will only attack if provoked or threatened. They are herbivores, feeding on grasses, leaves, and shrubs, and are known to be quite skittish around humans and other predators.\n\nOverall, Elk are seen as peaceful and noble creatures in D&D lore, embodying the beauty and power of the natural world."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b8c-839a-776e-8575-09d205af9286'::uuid,'Giant Venomous Snake','Unaligned','1/4 (XP 50; PB +2)',50,4,'Ambusher','Medium',14,NULL,11,'2d8+2','40 ft.',NULL,'40 ft.',NULL,10,18,13,2,10,3,'{"Perception": 2}','None','Blindsight 10 ft., Passive Perception 12','None',1,4,0,0,-4,-4,2,'[]',NULL,'Beast','','{"value":"Slithers silently, flicking its forked tongue with predatory precision."}','{"value": "In the world of Dungeons and Dragons, the Giant Venomous Snake is a fearsome creature known for its deadly bite and potent venom. These serpents can grow up to 20 feet in length and are often found lurking in dark, damp places such as caves, swamps, and dense forests.\n\nLegends say that Giant Venomous Snakes were created by a powerful sorcerer who sought to create the ultimate guardian for his hidden lair. Through dark rituals and twisted magic, he imbued ordinary snakes with immense size, strength, and a venom so potent that even a single bite could kill a fully grown man.\n\nMany adventurers have fallen victim to the Giant Venomous Snake''s deadly bite, making it a creature to be feared and respected in the world of D&D. Those who are brave enough to face these serpents must exercise caution and quick reflexes, as one wrong move could be their last.\n\nSome believe that the Giant Venomous Snake is a symbol of the dangers that lurk in the shadows of the natural world, a reminder that even the most seemingly harmless creatures can be deadly if provoked. Others see them as a test of strength and courage, a challenge to be overcome in order to prove one''s worth as an adventurer.\n\nRegardless of their origins or motivations, Giant Venomous Snakes are a staple of D&D lore, appearing in many campaigns and adventures as a formidable foe that must be defeated in order to claim victory and glory."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b8a-95e8-74f1-9696-fdacb3c1bef3'::uuid,'Giant Badger','Unaligned','1/4 (XP 50; PB +2)',50,0,'Skirmisher','Medium',13,NULL,15,'2d8+6','30 ft.',NULL,NULL,NULL,13,10,17,2,12,5,'{"Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','None',3,0,1,1,-3,-4,2,'[]',NULL,'Beast','','{"value":"The badger snarls, digging furiously with its massive claws, eyes gleaming with ferocity."}','{"value": "In Dungeons and Dragons 5th edition, Giant Badgers are large, aggressive creatures that inhabit underground burrows and tunnels. They are typically solitary creatures, known for their ferocity and powerful digging abilities.\n\nGiant Badgers are known for their sharp claws and powerful bite, making them formidable opponents in combat. They are also skilled diggers, able to quickly burrow through soil and create complex tunnel systems.\n\nIn D&D lore, Giant Badgers are often depicted as territorial creatures that fiercely defend their burrows from intruders. They are typically neutral in alignment, but will attack anything that threatens their territory or young.\n\nAdventurers may encounter Giant Badgers in the wild or in dungeons, where they may be guarding treasure or serving as minions to more powerful creatures. Their tough hide and aggressive nature make them formidable foes, especially in confined spaces where their digging abilities give them an advantage.\n\nOverall, Giant Badgers are a unique and interesting monster in the world of Dungeons and Dragons, adding a touch of realism and danger to underground environments."}',0,'Monster Manual 2024 (BR)','','Poison',0.25,NULL),
	 ('01990b91-6501-79c4-914c-96a4d5127d8b'::uuid,'Kenku','TrueNeutral','1/4 (XP 50; PB +2)',50,3,'Skirmisher','Medium',13,NULL,13,'3d8','30 ft.',NULL,NULL,NULL,10,16,10,11,10,10,'{"Stealth": 5, "Deception": 4, "Perception": 2}','None','Darkvision 60 ft., Passive Perception 12','Common, Primordial (Auran)',0,3,0,0,0,0,2,'[]','Habitat: Forest, Planar (Shadowfell), Urban','Monstrosity','','{"value":"Wings flutter anxiously as it mimics the sounds of the forest."}','{"value": "In the world of Dungeons and Dragons, Kenku are a humanoid race known for their mastery of mimicry and deception. Originally, Kenku were created by the god of trickery and deceit, and as a result, they are inherently skilled at using their voices to imitate sounds and voices they have heard before.\n\nKenku are often seen as sneaky and untrustworthy by other races, due to their history of using their mimicry abilities for thievery and deception. However, Kenku society also values creativity and artistic expression, and many Kenku use their mimicry abilities to create beautiful music and art.\n\nOne unique aspect of Kenku culture is their lack of a true language of their own. Instead, they communicate using a combination of mimicry, gestures, and a simplified form of Common. This can make it difficult for other races to understand Kenku, leading to further misunderstandings and mistrust.\n\nOverall, Kenku are a complex and intriguing race in the world of Dungeons and Dragons, known for their cunning and creativity, as well as their reputation for deception and trickery."}',0,'Monster Manual 2024','','None',0.25,NULL),
	 ('01990b8e-8ff9-7d57-804a-c0e37950f607'::uuid,'Grimlock','NeutralEvil','1/4 (XP 50; PB +2)',50,1,'Brute','Medium',11,NULL,11,'2d8+2','30 ft.','30 ft.',NULL,NULL,16,12,12,9,8,6,'{"Stealth": 5, "Athletics": 5, "Perception": 3}','None','Blindsight 30 ft., Passive Perception 13','—',1,1,3,-1,-2,-1,2,'[]','Habitat: Underdark','Aberration','','{"value":"Lurking in darkness, it sniffs the air with blind eyes, hungering for prey."}','{"value": "Grimlocks are humanoid creatures that live deep underground in dark caves and tunnels. They are blind, but possess a keen sense of smell and hearing that allows them to navigate their surroundings without difficulty. Grimlocks are known for their savage and violent nature, often attacking any intruders that wander into their territory.\n\nAccording to some legends, Grimlocks were once a civilized race of humans who were cursed by a powerful deity for their arrogance and greed. As a result, they were transformed into the monstrous creatures they are today, doomed to live in darkness and solitude.\n\nGrimlocks are often found in small tribes led by a powerful chieftain. They are skilled hunters and trackers, using their heightened senses to locate prey in the darkness. They are also known to be proficient in melee combat, using crude weapons like clubs and spears to take down their enemies.\n\nDespite their violent tendencies, Grimlocks are not inherently evil. Some tribes are known to form alliances with other creatures, such as drow or duergar, in order to protect their territory or achieve a common goal. However, their unpredictable nature and ferocious attacks make them a dangerous foe for any adventurer who dares to venture into their domain."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b93-eb07-73c9-8530-4ce0ab69f055'::uuid,'Merfolk Skirmisher','TrueNeutral','1/8 (XP 25; PB +2)',25,1,'Skirmisher','Medium',11,NULL,11,'2d8+2','10 ft.',NULL,'40 ft.',NULL,10,13,12,11,14,12,'{}','None','Passive Perception 12','Common, Primordial (Aquan)',1,1,0,2,1,0,2,'[]','Habitat: Coastal, Underwater','Elemental','','{"value":"Darting effortlessly through the waves, the merfolk skirmisher wields its trident with deadly precision."}','{"value": "Merfolk Skirmishers are agile and cunning predators that dwell in the oceans, rivers, and lakes of the world. They are known for their exceptional swimming abilities and their skill in combat, making them formidable opponents in battle. \n\nMerfolk Skirmishers are typically encountered in small groups, patrolling the waters and hunting for prey. They are known to be territorial creatures, fiercely defending their territory from intruders. They often use hit-and-run tactics in battle, darting in and out of the water to attack their enemies before retreating to safety.\n\nThese creatures are highly intelligent and possess a deep understanding of their aquatic environment. They are skilled hunters, using their keen senses and natural weapons to track and capture their prey. Merfolk Skirmishers are also known for their proficiency with weapons such as tridents and nets, which they use to great effect in combat.\n\nOverall, Merfolk Skirmishers are dangerous and resourceful adversaries, capable of outmaneuvering and outwitting even the most skilled of opponents. Adventurers who dare to challenge these creatures should be prepared for a fierce and deadly fight."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b9d-6859-7c01-ad19-4c968eca4e64'::uuid,'Stirge','Unaligned','1/8 (XP 25; PB +2)',25,3,'Ambusher','Tiny',13,NULL,5,'2d4','10 ft.',NULL,NULL,'40 ft.',4,16,11,2,8,6,'{}','None','Darkvision 60 ft., Passive Perception 9','None',0,3,-3,-1,-2,-4,2,'[]','Habitat: Desert, Forest, Grassland, Hill, Mountain, Swamp, Underdark, Urban','Monstrosity','','{"value":"Wings buzzing, the stirge swoops down with a piercing hunger."}','{"value": "Stirges are small, bat-like creatures that are known for their insatiable bloodlust. These creatures are often found in dark, damp places such as caves and dungeons, where they lie in wait for unsuspecting prey to pass by. \n\nStirges have a sharp proboscis that they use to suck blood from their victims, draining them of their life force. They are relentless hunters and will attack anything that crosses their path, swarming in large numbers to overwhelm their prey. \n\nIt is said that stirges are created by dark magic, and some believe that they are the result of cursed souls trapped in the bodies of these monstrous creatures. Others believe that they are simply the result of natural evolution in the dark, twisted places where they dwell. \n\nRegardless of their origins, stirges are feared by many adventurers and travelers, as their attacks can be deadly if not dealt with swiftly. They are often hunted for their valuable blood, which is said to have powerful magical properties."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b9f-cb0d-7fa9-b929-06e4dfa130bb'::uuid,'Twig Blight','NeutralEvil','1/8 (XP 25; PB +2)',25,2,'Ambusher','Small',14,NULL,7,'2d6','20 ft.',NULL,NULL,NULL,6,14,11,4,8,3,'{"Stealth": 4}','Deafened','Blindsight 60 ft., Passive Perception 9','Understands Common but can''t speak',0,2,-2,-1,-4,-3,2,'[]','Habitat: Forest','Plant','','{"value":"Twigs writhe and twist, their tiny branches reaching out with hungry malice."}','{"value": "Twig blights are small, twisted creatures that resemble animated plants. They are created through dark rituals and necromantic magic, usually by evil druids or necromancers. These creatures are often used as minions or guards by their creators, as they are mindless and obedient.\n\nTwig blights are known for their ability to blend in with their surroundings, making them difficult to spot until it is too late. They are also able to move quickly and quietly, making them ideal for ambushes and surprise attacks. Despite their small size, twig blights are surprisingly strong and can overwhelm unsuspecting adventurers with their sheer numbers.\n\nIn combat, twig blights use their sharp thorns to slash at their opponents, causing painful wounds that can quickly add up. They are also able to entangle their enemies with their vines, immobilizing them and leaving them vulnerable to further attacks.\n\nOverall, twig blights are considered to be a minor threat by experienced adventurers, but they should not be underestimated, especially when encountered in large numbers or in conjunction with more powerful creatures."}',0,'Monster Manual 2024','','None',0.125,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b94-9338-76fb-9ca0-e265241cda55'::uuid,'Mud Mephit','NeutralEvil','1/4 (XP 50; PB +2)',50,1,'Ambusher','Small',11,NULL,13,'3d6+3','20 ft.',NULL,'20 ft.','20 ft.',8,12,12,9,11,7,'{"Stealth": 3}','Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 10','Primordial (Aquan, Terran)',1,1,-1,0,-2,-1,2,'[]','Habitat: Planar (Elemental Planes)','Elemental','','{"value":"Mud Mephit squelches forward, leaving a trail of muck in its wake"}','{"value": "Mud Mephits are small, elemental creatures that inhabit swamps, marshes, and other wetlands. They are typically summoned by powerful spellcasters to serve as guardians or messengers. \n\nThese creatures are formed from the very essence of mud and earth, giving them the ability to manipulate and control muddy terrain. They are known for their mischievous and playful nature, often creating illusions or causing minor chaos just for their own amusement.\n\nIn combat, Mud Mephits can spew globs of mud at their enemies, causing them to become slowed and bogged down. They can also create small whirlpools of mud to trap and immobilize their foes.\n\nMud Mephits are not inherently evil, but they can be unpredictable and difficult to control. They are often considered a nuisance by those who encounter them, but can also be valuable allies to those who know how to communicate with them effectively."}',0,'Monster Manual 2024','','None',0.25,NULL),
	 ('01990b95-4dc5-7688-89f8-bbda421b72b3'::uuid,'Needle Blight','NeutralEvil','1/4 (XP 50; PB +2)',50,1,'Ambusher','Medium',12,NULL,16,'3d8+3','30 ft.',NULL,NULL,NULL,12,12,13,4,8,3,'{}','Deafened','Blindsight 60 ft., Passive Perception 9','Understands Common but can''t speak',1,1,1,-1,-4,-3,2,'[]','Habitat: Forest','Plant','','{"value":"Rustling with a rhythmic whisper, it extends sharp, thorn-covered limbs towards you."}','{"value": "Needle blights are twisted, malevolent creatures that resemble walking, humanoid-shaped bundles of thorns and needles. They are created through dark rituals, often by evil druids or fey creatures, and are typically found in forests or other natural environments where they can easily blend in with their surroundings.\n\nNeedle blights are known for their ability to magically shoot sharp, needle-like projectiles at their enemies from a distance, making them dangerous adversaries in combat. They are also resistant to piercing damage, thanks to their thick covering of sharp needles.\n\nThese creatures are often used by evil forces as guardians or sentinels, tasked with protecting sacred groves or other locations of importance. They are fiercely loyal to their creators and will stop at nothing to defend their territory.\n\nDespite their menacing appearance and aggressive nature, some needle blights are capable of forming a symbiotic relationship with certain plant creatures, such as treants or dryads. In these cases, the needle blights act as protectors and defenders of their plant allies, using their sharp projectiles to ward off intruders and keep their charges safe.\n\nOverall, needle blights are considered to be dangerous and unpredictable creatures, best avoided by those who value their safety and wellbeing."}',0,'Monster Manual 2024','','None',0.25,NULL),
	 ('01990b85-28ee-746c-ae0c-eff53bb2b3c5'::uuid,'Cultist','Any','1/8 (XP 25; PB +2)',25,1,'Support','Medium',12,NULL,9,'2d8','30 ft.',NULL,NULL,NULL,11,12,10,10,11,10,'{"Religion": 2, "Deception": 2}','None','Passive Perception 10','Common',0,1,0,2,0,0,2,'["Leather Armor", "Sickle"]','Habitat: Any','Humanoid','','{"value":"Chants fervently, eyes ablaze with fanatic devotion"}','{"value": "Cultists are fanatical followers of dark and sinister powers, often found in hidden temples or secret societies. They are devoted to their deity or cause, willing to do anything to further their goals. Cultists are typically humans or other humanoid races who have been indoctrinated into their cult''s beliefs through manipulation, brainwashing, or promises of power.\n\nIn combat, cultists are usually spellcasters or skilled in dark rituals, using their magic to summon demons, cast curses, or control the minds of their enemies. They are often accompanied by monstrous creatures or undead servants that they have summoned or raised through their dark arts.\n\nCultists are a dangerous threat to society, as they seek to spread their influence and corrupt others to their cause. They can be found in all corners of the world, in hidden enclaves or operating in plain sight, working to bring about the destruction of all that is good and pure. Adventurers must be wary when encountering cultists, as they are cunning and manipulative, and will stop at nothing to achieve their dark ambitions."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b80-36d6-7672-97ef-b05408248832'::uuid,'Bandit','TrueNeutral','1/8 (XP 25; PB +2)',25,1,'Skirmisher','Medium',12,NULL,11,'2d8+2','30 ft.',NULL,NULL,NULL,11,12,12,10,10,10,'{}','None','Passive Perception 10','Common, Thieves'' Cant',1,1,0,0,0,0,2,'["Leather Armor", "Light Crossbow", "Scimitar"]','Habitat: Any','Humanoid','','{"value":"Grins menacingly, twirling a dagger between calloused fingers"}','{"value": "Bandits are typically humanoid creatures that have turned to a life of crime, often robbing travelers on the road or looting villages and towns. They are known for their cunning and agility, as well as their proficiency with weapons such as swords, bows, and daggers.\n\nBandits often form small groups or gangs, working together to ambush their targets and divide the spoils of their ill-gotten gains. They are usually motivated by greed and a desire for power, and will stop at nothing to get what they want.\n\nSome bandits may have a more complex backstory, such as being former soldiers or mercenaries who turned to a life of crime after being disillusioned with their former employers. Others may have been driven to banditry by poverty or desperation, feeling that they have no other options to survive.\n\nIn combat, bandits are skilled fighters who can pose a significant threat to unprepared adventurers. They are adept at using stealth and surprise tactics to gain the upper hand, and will not hesitate to resort to violence if necessary. However, they are not usually very well organized or disciplined, making them vulnerable to more coordinated attacks.\n\nOverall, bandits are a common threat in the world of Dungeons & Dragons, and adventurers must always be on their guard when traveling through dangerous territories."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b81-a0e0-7eaa-be54-be5c1227c639'::uuid,'Blink Dog','LawfulGood','1/4 (XP 50; PB +2)',50,3,'Skirmisher','Medium',13,NULL,16,'3d8+3','40 ft.',NULL,NULL,NULL,12,17,12,10,13,11,'{"Stealth": 5, "Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','Blink Dog; understands Elvish and Sylvan but can''t speak them',1,3,1,1,0,0,2,'[]','Habitat: Forest, Planar (Feywild)','Fey','','{"value":"Eagerly wagging its tail, the Blink Dog fixes its gaze on you."}','{"value": "Blink Dogs are magical beasts known for their ability to teleport short distances in a blink of an eye. They are typically intelligent and noble creatures, often serving as loyal companions to fey creatures or good-aligned adventurers. Blink Dogs are known for their keen senses and swift agility, making them formidable hunters and guardians.\n\nIn the lore of Dungeons & Dragons, Blink Dogs are said to have originated from the feywild, a mystical realm closely connected to the material plane. They are considered to be highly intelligent and social creatures, often living in packs and communicating with each other through a complex system of barks and body language.\n\nBlink Dogs are known to be fiercely loyal and protective of their companions, often forming strong bonds with those they choose to travel with. They are also known for their hatred of evil creatures, particularly fiends and undead, whom they see as abominations that must be eradicated.\n\nIn combat, Blink Dogs are swift and agile, using their teleportation ability to surprise their enemies and strike from unexpected angles. They are known to work together in packs, using coordinated tactics to outmaneuver and overpower their foes.\n\nOverall, Blink Dogs are seen as noble and trustworthy creatures in the world of Dungeons & Dragons, valued for their loyalty, intelligence, and formidable combat abilities."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b81-fa5c-76ef-ab6d-78c02d7160d5'::uuid,'Boar','Unaligned','1/4 (XP 50; PB +2)',50,0,'Brute','Medium',11,NULL,13,'2d8+4','40 ft.',NULL,NULL,NULL,13,11,14,2,9,5,'{}','None','Passive Perception 9','None',2,0,1,1,-3,4,2,'[]',NULL,'Beast','','{"value":"Razorback charges, snorting and digging up the earth with powerful tusks."}','{"value": "In the world of Dungeons and Dragons, boars are large, aggressive wild pigs that are often found in forests, grasslands, and other natural environments. They are known for their tough hides, sharp tusks, and fierce temperaments, making them formidable opponents for adventurers who cross their paths.\n\nBoars are typically solitary creatures, but can sometimes be found in small groups or herds. They are omnivorous and will eat almost anything, including plants, insects, and even small animals. They are known for their powerful charging attacks, which can cause significant damage to anyone caught in their path.\n\nIn some cultures, boars are revered as symbols of strength, courage, and ferocity. They are often featured in myths and legends as powerful and noble creatures, capable of defeating even the most fearsome foes. In other cultures, boars are seen as dangerous pests that must be hunted and destroyed to protect crops and livestock.\n\nIn D&D, boars are often encountered as random encounters in the wilderness, or as guardians of hidden treasures or sacred sites. They are typically depicted as aggressive and territorial creatures that will attack anything that threatens them or their territory. Adventurers who manage to defeat a boar in combat may be able to harvest valuable materials from its body, such as tusks or hide, which can be sold for a profit or used to craft powerful items.\n\nOverall, boars are a classic and iconic monster in the world of D&D, known for their ferocity, strength, and resilience. They are a formidable opponent for any adventurer brave enough to face them in battle."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b84-b0ff-7381-9f99-f52e92ce162e'::uuid,'Constrictor Snake','Unaligned','1/4 (XP 50; PB +2)',50,2,'Ambusher','Large',13,NULL,13,'2d10+2','30 ft.',NULL,'30 ft.',NULL,15,14,12,1,10,3,'{"Stealth": 4, "Perception": 2}','None','Blindsight 10 ft., Passive Perception 12','None',1,2,2,0,4,5,2,'[]',NULL,'Beast','','{"value":"Coils tightly, scales whispering against the ground, eyes fixed on its prey"}','{"value": "In the world of Dungeons and Dragons, the Constrictor Snake is a large, powerful serpent known for its ability to crush its prey to death with its powerful coils. These snakes are often found in jungles, forests, and swamps, where they lie in wait for unsuspecting prey to come within striking distance.\n\nConstrictor Snakes are solitary creatures, only coming together to mate or compete for territory. They are highly territorial and will aggressively defend their hunting grounds from any intruders. These snakes are known for their incredible strength, able to take down creatures much larger than themselves with ease.\n\nIn D&D lore, Constrictor Snakes are often depicted as cunning and patient predators, using their keen senses to track down prey and ambush them when they least expect it. They are also known for their ability to camouflage themselves among the foliage, making them difficult to spot until it''s too late.\n\nAdventurers traveling through snake-infested areas must always be on their guard, as a Constrictor Snake could be lurking around any corner, ready to strike. Those who underestimate these powerful creatures may find themselves in a deadly embrace, squeezed to death by the coils of the Constrictor Snake."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b86-baec-751a-b388-3457ac1a2f3c'::uuid,'Draft Horse','Unaligned','1/4 (XP 50; PB +2)',50,0,'Brute','Large',10,NULL,15,'2d10+4','40 ft.',NULL,NULL,NULL,18,10,15,2,11,7,'{}','None','Passive Perception 10','None',2,0,4,0,2,4,2,'[]',NULL,'Beast','','{"value":"Hooves pound the ground as it snorts and tosses its powerful head."}','{"value": "Draft horses are large, powerful creatures known for their strength and endurance. They are often used for heavy labor, such as pulling carts and plows. In the world of Dungeons and Dragons, draft horses are commonly found in rural areas, working on farms and in villages.\n\nThese horses are highly valued for their ability to carry heavy loads and their calm temperament. They are known for their loyalty to their owners and their willingness to work hard. Draft horses are often seen as symbols of strength and reliability, and many people believe that owning a draft horse brings good luck.\n\nIn combat, draft horses can be formidable opponents. Their size and strength make them difficult to take down, and they can trample enemies with ease. Some adventurers even choose to ride draft horses into battle, using their strength and speed to their advantage.\n\nOverall, draft horses are respected and admired creatures in the world of Dungeons and Dragons, valued for their hard work and loyalty."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b86-e2c8-7aca-9f42-29d2e13b16e4'::uuid,'Dretch','ChaoticEvil','1/4 (XP 50; PB +2)',50,0,'Minion','Small',11,NULL,18,'4d6+4','20 ft.',NULL,NULL,NULL,12,11,12,5,8,3,'{}','Poison; Poisoned','Darkvision 60 ft., Passive Perception 9','Abyssal; telepathy 60 ft. (works only with creatures that understand Abyssal)',1,0,1,-1,-4,-3,2,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"It shambles forward, its bloated form emitting a putrid stench."}','{"value": "Dretches are low-ranking demons in the hierarchy of the Abyss, the chaotic evil plane of existence. They are considered the weakest of demonkind, often used as foot soldiers or menial laborers by more powerful demons.\n\nDretches are grotesque, hunched creatures with leathery skin, sharp teeth, and a foul odor. They are known for their insatiable hunger and will eat almost anything, including rotting corpses and excrement. Despite their limited intelligence, they are cunning and resourceful in their own way, often using their natural camouflage abilities to hide in shadows and surprise their enemies.\n\nDretches are summoned by powerful spellcasters to do their bidding, usually as cannon fodder in battles or to carry out menial tasks. They are not particularly strong or skilled in combat, but their sheer numbers and relentless attacks can overwhelm even the most skilled warriors. In the Abyss, dretches serve as slaves to more powerful demons, often enduring cruel treatment and abuse.\n\nOverall, dretches are considered the bottom feeders of demon society, but their sheer numbers and tenacity make them a formidable force to be reckoned with in the eternal conflict between the forces of good and evil."}',0,'Monster Manual 2024 (BR)','Demon','Cold, Fire, Lightning',0.25,NULL),
	 ('01990b94-9fd5-7d7e-b792-6249f7f5b476'::uuid,'Mule','Unaligned','1/8 (XP 25; PB +2)',25,0,'Brute','Medium',10,NULL,11,'2d8+2','40 ft.',NULL,NULL,NULL,14,10,13,2,10,5,'{}','None','Passive Perception 10','None',1,0,4,0,3,4,2,'[]',NULL,'Beast','','{"value":"Hooves stomp and ears flatten as it kicks up a cloud of dust."}','{"value": "In Dungeons and Dragons 5th edition, the mule is a creature that is a hybrid of a horse and a donkey. They are typically used as pack animals due to their strength and endurance, able to carry heavy loads over long distances.\n\nMules are known for their stubbornness and can be difficult to train, requiring a patient and skilled handler. They are also known for their sure-footedness, making them ideal for traversing rough terrain.\n\nIn D&D lore, mules can be found in various environments, from farms and villages to wilderness areas and dungeons. They are often used by adventurers to carry supplies and equipment on their journeys.\n\nOverall, mules are seen as reliable and hardworking creatures in the world of Dungeons and Dragons, valued for their strength and endurance in helping characters on their quests and adventures."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b89-905c-7d0e-bf9b-a16b8172a90b'::uuid,'Flumph','LawfulGood','1/8 (XP 25; PB +2)',25,2,'Support','Small',12,NULL,7,'2d6','5 ft.',NULL,NULL,'30 ft.',6,15,10,14,14,11,'{"Arcana": 4, "History": 4, "Religion": 4}','None','Darkvision 60 ft., Passive Perception 12','Understands Undercommon but can''t speak; telepathy 60 ft.',0,2,-2,2,0,2,2,'[]','Habitat: Underdark','Aberration','','{"value":"Floating silently, tendrils twitching in anticipation, the flumph watches with gentle curiosity."}','{"value": "Flumphs are peaceful and benevolent creatures that float through the Underdark on long tendrils, resembling jellyfish with tentacles. They are known for their ability to detect and feed off of psychic energy, which they use to communicate with each other and other creatures. Despite their strange appearance, flumphs are highly intelligent and are often sought out by adventurers for their wisdom and guidance.\n\nFlumphs are social creatures that live in colonies and work together to protect their homes from threats. They are fiercely loyal to their own kind and will defend each other at all costs. However, they are also known for their pacifist nature and will rarely engage in combat unless absolutely necessary.\n\nIn D&D lore, flumphs are often seen as quirky and eccentric creatures that are more likely to befriend adventurers than attack them. They are often considered to be quirky and eccentric creatures that are more likely to befriend adventurers than attack them. Despite their peaceful nature, flumphs are still formidable opponents when provoked, as they can use their psychic abilities to incapacitate enemies and protect themselves and their allies."}',0,'Monster Manual 2024','','None',0.125,NULL),
	 ('01990b89-9e14-7a98-9021-d30e64a024d3'::uuid,'Flying Snake','Unaligned','1/8 (XP 25; PB +2)',25,2,'Skirmisher','Tiny',14,NULL,5,'2d4','30 ft.',NULL,'30 ft.','60 ft.',4,15,11,2,12,5,'{}','None','Blindsight 10 ft., Passive Perception 11','None',0,2,-3,1,-3,-4,2,'[]',NULL,'Monstrosity','','{"value":"Serpentine body twists and darts through the air, tongue flicking in anticipation."}','{"value": "In the world of Dungeons and Dragons, the Flying Snake is a small, colorful serpent with the ability to glide through the air using its wings. These creatures are often found in tropical and subtropical climates, where they hunt for small prey such as insects and small mammals.\n\nFlying Snakes are known for their agility and speed, making them formidable predators despite their small size. They are also highly territorial creatures, fiercely defending their nests and young from any potential threats.\n\nLegends say that Flying Snakes were created by ancient sorcerers as messengers and spies, using their aerial abilities to gather information and deliver messages across great distances. Some believe that these creatures still serve as the eyes and ears of powerful wizards and sorcerers, carrying out secretive missions on their behalf.\n\nIn battle, Flying Snakes are known for their venomous bite, which can quickly incapacitate their prey. They are also capable of using their wings to swoop down on unsuspecting foes, striking quickly and then retreating to a safe distance.\n\nOverall, the Flying Snake is a fascinating and mysterious creature in the world of D&D, with a rich lore that adds depth and intrigue to any campaign."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b8c-af71-7a94-b072-cdec4df977e9'::uuid,'Giant Weasel','Unaligned','1/8 (XP 25; PB +2)',25,3,'Skirmisher','Medium',13,NULL,9,'2d8','40 ft.','30 ft.',NULL,NULL,11,17,10,4,12,5,'{"Stealth": 5, "Acrobatics": 5, "Perception": 3}','None','Darkvision 60 ft., Passive Perception 13','None',0,3,0,1,-3,-3,2,'[]',NULL,'Beast','','{"value":"It snarls and darts through the shadows, eyes gleaming with predatory hunger."}','{"value": "In the world of Dungeons and Dragons, the Giant Weasel is a creature known for its speed, agility, and ferocity. These creatures are larger and more aggressive versions of their smaller weasel counterparts. Giant Weasels are often found in forests and other wilderness areas, where they hunt small prey such as rodents and birds.\n\nGiant Weasels are solitary creatures and are known for their cunning and stealth. They use their keen sense of smell and sharp claws and teeth to track down and kill their prey. Despite their small size, Giant Weasels are formidable opponents in combat, using their speed and agility to outmaneuver their enemies.\n\nIn some D&D campaigns, Giant Weasels are sometimes used as familiars or animal companions by druids and rangers. These characters value the weasel''s keen senses and hunting abilities, using them to aid in tracking and hunting game.\n\nOverall, Giant Weasels are creatures to be feared and respected in the world of Dungeons and Dragons, known for their ferocity and cunning in the wild."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b8c-bf84-712f-8454-f0680352d835'::uuid,'Giant Wolf Spider','Unaligned','1/4 (XP 50; PB +2)',50,3,'Ambusher','Medium',13,NULL,11,'2d8+2','40 ft.','40 ft.',NULL,NULL,12,16,13,3,12,4,'{"Stealth": 7, "Perception": 3}','None','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 13','None',1,3,1,1,-3,-4,2,'[]',NULL,'Beast','','{"value":"Legs skitter across the ground, fangs dripping with venomous anticipation."}','{"value": "The Giant Wolf Spider is a monstrous creature found in dark and dank places such as caves and underground tunnels. It is known for its large size, predatory nature, and ability to spin webs to capture its prey. Giant Wolf Spiders are highly venomous, using their toxic bite to paralyze their victims before feeding on them.\n\nThese creatures are often solitary hunters, stalking their prey with stealth and agility. They are capable of climbing walls and ceilings with ease, making them formidable opponents in combat. Giant Wolf Spiders are typically neutral in alignment, but can be aggressive if provoked or hungry.\n\nSome believe that Giant Wolf Spiders were created by dark magic or experimentation, while others think they are simply a natural evolution of their smaller counterparts. Regardless of their origins, these creatures are a dangerous threat to adventurers and travelers who venture into their territory."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b8a-bd20-7b80-91f9-0ccc60c1e54d'::uuid,'Giant Centipede','Unaligned','1/4 (XP 50; PB +2)',50,2,'Ambusher','Small',14,NULL,9,'2d6+2','30 ft.','30 ft.',NULL,NULL,5,14,12,1,7,3,'{}','None','Blindsight 30 ft., Passive Perception 8','None',1,2,-3,-2,-4,-5,2,'[]',NULL,'Beast','','{"value":"Serrated legs skitter menacingly as it coils up, ready to strike."}','{"value": "In the world of Dungeons and Dragons, the Giant Centipede is a fearsome creature known for its size, speed, and deadly venom. These monstrous insects can grow up to 10 feet long and have a voracious appetite for flesh.\n\nGiant Centipedes are often found in dark, damp places such as caves, sewers, and underground tunnels. They are skilled hunters, using their lightning-fast reflexes to catch their prey and inject them with paralyzing venom.\n\nLegends say that Giant Centipedes were created by dark magic, either as guardians for ancient tombs or as servants of evil sorcerers. Some believe that they are actually the result of a curse placed on a tribe of humans, transforming them into monstrous insects as punishment for their wicked ways.\n\nAdventurers who encounter Giant Centipedes must be cautious and prepared for a fierce battle. Their sharp mandibles and potent venom can quickly incapacitate even the most skilled warriors. Only those with quick reflexes and a keen eye for weakness can hope to defeat these deadly creatures."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b8a-e16f-7168-b140-c7efc3359d3b'::uuid,'Giant Crab','Unaligned','1/8 (25 XP; PB +2)',25,1,'Skirmisher','Medium',15,NULL,13,'3d8','30 ft.',NULL,'30 ft.',NULL,13,13,11,1,9,3,'{"Stealth": 3}','None','Blindsight 30 ft., Passive Perception 9','None',0,1,1,-1,-4,-5,2,'[]',NULL,'Beast','','{"value":"Claws click ominously as it scuttles forward, eyes fixed on prey."}','{"value": "In the world of Dungeons and Dragons, giant crabs are massive, aggressive crustaceans that can be found in coastal regions and underwater caves. These creatures are known for their powerful claws, which they use to crush their prey and defend themselves against threats.\n\nGiant crabs are often solitary creatures, preferring to live in isolated areas where they can easily hunt for food. They are carnivorous creatures, feeding on fish, mollusks, and even other giant crabs. Some giant crabs have been known to attack sailors and adventurers who venture too close to their territory.\n\nDespite their fearsome reputation, giant crabs are not particularly intelligent creatures. They rely on their natural instincts and brute strength to survive in their harsh environments. However, some cunning individuals have been known to train giant crabs as mounts or guardians.\n\nIn some regions, giant crabs are considered sacred creatures and are worshipped by local tribes as symbols of strength and survival. These tribes often offer sacrifices to the giant crabs in exchange for protection and blessings.\n\nOverall, giant crabs are formidable opponents for adventurers and sailors alike, with their massive size and powerful claws making them a force to be reckoned with in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b8d-a6ce-7c4e-a62b-4bb28f62972a'::uuid,'Goblin Minion','ChaoticNeutral','1/8 (XP 25; PB +2)',25,2,'Minion','Small',12,NULL,7,'2d6','30 ft.',NULL,NULL,NULL,8,15,10,10,8,8,'{"Stealth": 6}','None','Darkvision 60 ft., Passive Perception 9','Common, Goblin',0,2,-1,-1,-1,0,2,'["Daggers (3)"]','Habitat: Forest, Grassland, Hill, Planar (Acheron, Feywild), Underdark','Fey','Goblinoid','{"value":"Grinning, it bounces eagerly on its toes, dagger at the ready."}','{"value": "Goblin minions are small, mischievous creatures that are often found serving more powerful beings such as goblin bosses, hobgoblin warlords, or even dragons. They are known for their cowardice and tendency to flee from danger, but can be dangerous in large numbers or when under the command of a stronger leader.\n\nGoblin minions are typically armed with crude weapons such as rusty swords, spears, or bows, and often wear ragged clothing or scraps of armor. They are quick and nimble, able to dart in and out of combat to harass their enemies and create chaos on the battlefield.\n\nDespite their small size and seemingly low intelligence, goblin minions are cunning and resourceful, using traps, ambushes, and other dirty tactics to gain the upper hand in a fight. They are also known for their love of looting and stealing, often scavenging for valuables after a battle or raid.\n\nOverall, goblin minions are a common threat in the world of Dungeons and Dragons, often serving as the foot soldiers in larger goblinoid armies or as the loyal henchmen of more powerful creatures. They may be weak individually, but their numbers and tenacity make them a force to be reckoned with in any encounter."}',0,'Monster Manual 2024 (BR)','Goblinoid','None',0.125,NULL),
	 ('01990b8d-bb40-7c71-b60e-cc398afeaa4f'::uuid,'Goblin Warrior','ChaoticNeutral','1/4 (XP 50; PB +2)',50,2,'Soldier','Small',15,NULL,10,'3d6','30 ft.',NULL,NULL,NULL,8,15,10,10,8,8,'{"Stealth": 6}','None','Darkvision 60 ft., Passive Perception 9','Common, Goblin',0,2,-1,-1,-1,0,2,'["Leather Armor", "Scimitar", "Shield", "Shortbow"]','Habitat: Forest, Grassland, Hill, Planar (Acheron, Feywild), Underdark','Fey','Goblinoid','{"value":"Grinning wickedly, it brandishes its rusted sword, eyes glinting with malice."}','{"value": "Goblin Warriors are fierce and cunning creatures that are infamous for their brutality and ruthlessness in battle. They are often found in tribes led by powerful chieftains, who command them to raid and pillage nearby settlements.\n\nGoblin Warriors are known for their agility and skill with a variety of weapons, including swords, bows, and spears. They are also proficient in tactics and strategy, often using their small size and stealth to their advantage on the battlefield.\n\nDespite their small stature, Goblin Warriors are fearless and will stop at nothing to achieve victory in battle. They are fiercely loyal to their tribe and will fight to the death to protect their homeland and their chieftain.\n\nIn D&D lore, Goblin Warriors are often depicted as chaotic evil creatures who delight in causing chaos and destruction wherever they go. They are considered a common threat to adventurers and travelers alike, and are usually encountered in large numbers, making them a formidable foe to overcome."}',0,'Monster Manual 2024 (BR)','Goblinoid','None',0.25,NULL),
	 ('01990b8e-9644-74c3-8518-ede5532405a9'::uuid,'Guard','TrueNeutral','1/8 (XP 25; PB +2)',25,1,'Soldier','Medium',16,NULL,11,'2d8+2','30 ft.',NULL,NULL,NULL,13,12,12,10,11,10,'{"Perception": 2}','None','Passive Perception 12','Common',1,1,1,0,0,0,2,'["Chain Shirt", "Shield", "Spear"]','Habitat: Any','Humanoid','','{"value":"Armor gleams in the torchlight as it stands sentinel, eyes unblinking."}','{"value": "In D&D 5e, guards are typically depicted as skilled warriors or soldiers who are tasked with protecting a specific location or person. They are often found patrolling the streets of a city, standing watch at a castle gate, or protecting a noble''s estate. Guards are trained in combat and are usually equipped with weapons such as swords, spears, or bows.\n\nGuards are usually organized into groups or squads, each led by a captain or commander. They are known for their loyalty and dedication to their duties, and will not hesitate to defend their charges with their lives if necessary.\n\nIn combat, guards are proficient in both melee and ranged attacks, making them versatile opponents. They are also trained in tactics and can work together effectively as a team to overcome their enemies. Guards are typically of medium size and have average stats, making them a challenging but not insurmountable threat for adventurers.\n\nOverall, guards are a common sight in D&D campaigns and can add an element of realism and challenge to encounters. Whether they are friend or foe, guards play an important role in the world of D&D as protectors of the peace and order."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b91-a38f-7599-8a56-0270d2412fe2'::uuid,'Kobold Warrior','TrueNeutral','1/8 (XP 25; PB +2)',25,2,'Minion','Small',14,NULL,7,'3d6-3','30 ft.',NULL,NULL,NULL,7,15,9,8,7,8,'{}','None','Darkvision 60 ft., Passive Perception 8','Common, Draconic',-1,2,-2,-2,-1,-1,2,'["Daggers (3)"]','Habitat: Arctic, Coastal, Desert, Forest, Hill, Mountain, Swamp, Underdark, Urban','Dragon','','{"value":"Sneers menacingly, brandishing a rusted sword in the dim torchlight"}','{"value": "Kobolds are small, reptilian humanoids known for their cunning and cowardly nature. They are often found in underground caves and tunnels, where they live in tribes led by powerful sorcerers or chieftains. Kobolds are known for their skill in traps and ambushes, using their small size and agility to their advantage in combat.\n\nKobold Warriors are the backbone of a kobold tribe''s military forces. They are typically armed with small weapons such as daggers, slings, and spears, and are trained in basic combat tactics. While individually weak, Kobold Warriors can be dangerous in large numbers, overwhelming enemies with sheer force of numbers.\n\nIn battle, Kobold Warriors will often work together to flank and outmaneuver their enemies, using their pack tactics to gain advantage in combat. They are fiercely loyal to their tribe and will fight to the death to protect their home and their leaders.\n\nKobold Warriors are often used as scouts and skirmishers by more powerful creatures such as dragons or drow, who see them as expendable pawns in their schemes. Despite their lowly status, Kobold Warriors should not be underestimated, as their cunning and teamwork make them a formidable foe in battle."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b92-0f8a-71ae-a5ff-450bfb8cce38'::uuid,'Kuo-Toa','NeutralEvil','1/4 (XP 50; PB +2)',50,0,'Skirmisher','Medium',13,NULL,18,'4d8','30 ft.',NULL,'30 ft.',NULL,13,10,11,11,10,8,'{"Perception": 4}','None','Darkvision 120 ft., Truesight 30 ft., Passive Perception 14','Undercommon',0,0,1,0,-1,0,2,'["Spear"]','Habitat: Coastal, Underdark','Aberration','','{"value":"Whispers in a guttural tongue, eyes glinting with mad devotion."}','{"value": "The Kuo-Toa are a race of fish-like humanoid creatures that dwell in the depths of the ocean. They are known for their worship of strange and malevolent deities, particularly the demon lord known as Blibdoolpoolp. The Kuo-Toa are often driven to madness by their devotion to these dark powers, leading them to perform bizarre and horrifying rituals in their honor.\n\nDespite their chaotic and unpredictable nature, the Kuo-Toa are skilled hunters and warriors, using their agility and underwater abilities to outmaneuver their enemies. They are also known for their ability to craft powerful weapons and armor from the bones of sea creatures, making them formidable opponents in battle.\n\nIn addition to their martial prowess, the Kuo-Toa also possess a unique ability to shape reality through their collective belief. This ability, known as \"The Power of the Deep\", allows them to create powerful illusions and even summon creatures from the depths of the ocean to aid them in battle.\n\nOverall, the Kuo-Toa are a mysterious and dangerous race of creatures that are best avoided by travelers venturing into the depths of the ocean. Their devotion to dark powers and their ability to manipulate reality make them a formidable threat to any who dare to cross their path."}',0,'Monster Manual 2024','','None',0.25,NULL),
	 ('01990b93-52bd-72d6-b78d-2f5cd788941f'::uuid,'Manes','ChaoticEvil','1/8 (XP 25; PB +2)',25,-1,'Minion','Small',9,NULL,9,'2d6+2','20 ft.',NULL,NULL,NULL,10,9,13,3,8,4,'{}','Poison; Charmed, Frightened, Poisoned','Darkvision 60 ft., Passive Perception 9','Understands Abyssal but can''t speak',1,-1,0,-1,-3,-4,2,'[]','Habitat: Planar (Abyss)','Fiend','Demon','{"value":"Shadows writhe and moan, their eyes glowing with malice and hunger"}','{"value": "Manes are low-ranking demons in the hierarchy of the Abyss, the chaotic and evil plane of existence. They are the lowest form of demon and are typically created from the souls of evil mortals who have been transformed through torment and corruption in the Abyss. Manes are mindless and savage, driven only by their insatiable hunger for destruction and chaos.\n\nDespite their lack of intelligence, manes are still dangerous creatures due to their sheer numbers and their ability to overwhelm opponents through sheer force of numbers. They are typically used as cannon fodder by more powerful demons, sent into battle to weaken enemy forces before the real assault begins.\n\nManes are grotesque in appearance, resembling emaciated, corpse-like humanoids with twisted features and sharp claws. They emit a foul stench that can sicken those who come too close to them. In combat, manes attack relentlessly, slashing and biting at their enemies with a frenzied desperation.\n\nOverall, manes are considered to be little more than pests by more powerful demons, but they can still pose a threat to unwary adventurers who underestimate their numbers and ferocity. Only the bravest and most skilled warriors dare to face these vile creatures in battle."}',0,'Monster Manual 2024','Demon','Cold, Fire, Lightning',0.125,NULL),
	 ('01990b93-b352-75fb-8e36-de30d954a3d4'::uuid,'Mastiff','Unaligned','1/8 (XP 25; PB +2)',25,2,'Support','Medium',12,NULL,5,'1d8+1','40 ft.',NULL,NULL,NULL,13,14,12,3,12,7,'{"Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','None',1,2,1,3,2,4,2,'[]',NULL,'Beast','','{"value":"Growls low, hackles raised, eyes fixed on prey with unwavering intensity"}','{"value": "In the world of Dungeons and Dragons, the Mastiff is a large, loyal dog breed known for its strength, courage, and keen senses. They are often used as guard dogs, hunters, and loyal companions to their masters. Mastiffs are known for their strong bond with their owners and will fiercely protect them from any danger.\n\nIn the game, Mastiffs are typically depicted as large, muscular dogs with a powerful bite and sharp teeth. They are often used by guards, hunters, and adventurers as loyal companions and protectors. Mastiffs are known for their intelligence and ability to learn commands quickly, making them valuable allies in combat situations.\n\nIn terms of gameplay, Mastiffs are often used as animal companions for characters with the Ranger class or those with the ability to summon and control animals. They can be trained to track enemies, protect their owners, and even aid in combat by attacking enemies with their powerful bite.\n\nOverall, Mastiffs are portrayed as loyal and powerful creatures in the world of Dungeons and Dragons, making them valuable allies to any adventurer in need of a faithful companion."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990b96-cbb2-7edf-9190-2ef0b2f3e003'::uuid,'Panther','Unaligned','1/4 (XP 50; PB +2)',50,3,'Skirmisher','Medium',13,NULL,13,'3d8','50 ft.','40 ft.',NULL,NULL,14,16,10,3,14,7,'{"Stealth": 7, "Perception": 4}','None','Darkvision 60 ft., Passive Perception 14','None',0,3,2,2,2,4,2,'[]',NULL,'Beast','','{"value":"Silent shadow stalks, amber eyes gleaming with primal hunger."}','{"value": "In the world of Dungeons and Dragons, the panther is a sleek and stealthy predator known for its speed and agility. These powerful creatures are often found lurking in dense forests and jungles, where they hunt their prey with deadly precision.\n\nPanthers are solitary creatures, preferring to roam their territory alone and fiercely defending it from any intruders. They are highly territorial and will not hesitate to attack anything that threatens them or their hunting grounds.\n\nDespite their solitary nature, panthers are known to form bonds with other creatures, such as druids or rangers who share a deep connection with nature. These individuals may be able to communicate with panthers and even form alliances with them, using their skills to aid each other in hunting and survival.\n\nIn combat, panthers are formidable opponents, using their incredible speed and agility to outmaneuver their foes. They are known to strike swiftly and silently, often catching their prey off guard before delivering a deadly bite with their powerful jaws.\n\nOverall, the panther is a fearsome and respected creature in the world of Dungeons and Dragons, embodying the primal power and grace of the natural world."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b97-b1b4-708c-b748-3e5654731264'::uuid,'Pixie','NeutralGood','1/4 (XP 50; PB +2)',50,5,'Support','Tiny',15,NULL,9,'6d4-6','10 ft.',NULL,NULL,'30 ft.',2,20,8,10,14,15,'{"Stealth": 7, "Perception": 4}','None','Passive Perception 14','Sylvan',-1,5,-4,2,2,0,2,'[]','Habitat: Forest, Planar (Feywild)','Fey','','{"value":"Giggling mischievously, it flits about, leaving a trail of sparkling dust in its wake."}','{"value": "Pixies are small, mischievous fey creatures that are known for their playful and whimsical nature. They are often found in enchanted forests or other magical places, where they enjoy playing tricks on unsuspecting travelers. Despite their small size, pixies are powerful spellcasters and are able to use their magic to create illusions, cast spells, and even turn invisible at will.\n\nPixies are also known for their beautiful wings, which allow them to fly swiftly and gracefully through the air. They are skilled archers and often use their bows and arrows to defend themselves against larger creatures. However, pixies are more likely to use their magic to confuse or trick their enemies rather than engage in direct combat.\n\nIn some stories, pixies are said to be guardians of the natural world, protecting the forests and creatures that inhabit them. They are often depicted as benevolent beings who help those in need, especially if they show respect for nature and the fey. However, pixies can also be capricious and unpredictable, so it is wise to approach them with caution.\n\nOverall, pixies are fascinating and complex creatures that add a touch of magic and whimsy to the world of Dungeons and Dragons. Players who encounter pixies in their adventures may find themselves charmed by their playful antics, or challenged by their cunning tricks."}',0,'Monster Manual 2024','','None',0.25,NULL),
	 ('01990b98-66d1-7646-a214-1590f4d6401b'::uuid,'Priest Acolyte','TrueNeutral','1/4 (XP 50; PB +2)',50,0,'Support','Medium',13,NULL,11,'2d8+2','30 ft.',NULL,NULL,NULL,14,10,12,10,14,11,'{"Medicine": 4, "Religion": 2}','None','Passive Perception 12','Common',1,0,2,2,0,0,2,'["Chain Shirt", "Holy Symbol", "Mace"]','Habitat: Any','Humanoid','Cleric','{"value":"Whispers prayers under its breath, eyes glowing with zealous devotion."}','{"value": "The Priest Acolyte is a devout follower of a particular deity or religion in the world of Dungeons and Dragons. They are typically found in temples, churches, or other religious institutions, where they serve as assistants to higher-ranking priests or clerics.\n\nPriest Acolytes are responsible for performing various religious rituals and ceremonies, as well as providing guidance and support to the members of their faith community. They may also be tasked with studying religious texts, leading prayers, and helping to maintain the temple or church.\n\nIn addition to their religious duties, Priest Acolytes are often trained in combat and have some proficiency in healing magic. They may accompany adventuring parties on quests or missions that align with the goals of their deity or religion, using their skills to aid their allies in battle and provide healing when needed.\n\nOverall, Priest Acolytes are dedicated and loyal servants of their faith, willing to do whatever is necessary to uphold the tenets of their religion and spread the word of their deity to the world."}',0,'Monster Manual 2024 (BR)','Cleric','None',0.25,NULL),
	 ('01990b98-8592-7920-935d-97867b9345cb'::uuid,'Pseudodragon','NeutralGood','1/4 (XP 50; PB +2)',50,2,'Ambusher','Tiny',14,NULL,10,'3d4+3','15 ft.',NULL,NULL,'60 ft.',6,15,13,10,12,10,'{"Stealth": 4, "Perception": 5}','None','Blindsight 10 ft., Darkvision 60 ft., Passive Perception 15','Understands Common and Draconic but can''t speak',1,2,2,1,0,0,2,'[]','Habitat: Coastal, Desert, Forest, Hill, Mountain, Urban','Dragon','','{"value":"Wings flutter softly as it eyes you with curious intelligence"}','{"value": "Pseudodragons are small, intelligent, and curious dragon-like creatures that are commonly found in forests and other natural habitats. They are known for their playful and mischievous nature, as well as their ability to bond with a single individual and serve as a loyal companion.\n\nPseudodragons have a telepathic ability that allows them to communicate with their bonded companion, making them excellent familiars for spellcasters. They are also capable of delivering a poisonous sting with their tail, although they rarely use this ability unless threatened.\n\nIn terms of appearance, pseudodragons resemble miniature dragons with colorful scales, bat-like wings, and a long, thin tail. They are generally friendly towards creatures they view as allies, but can be fiercely protective of their bonded companion.\n\nOverall, pseudodragons are beloved creatures in the world of Dungeons and Dragons, known for their intelligence, loyalty, and playful nature."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b99-b3b1-76b2-a0d0-e154e8b8d0cf'::uuid,'Riding Horse','Unaligned','1/4 (XP 50; PB +2)',50,1,'Soldier','Large',11,NULL,13,'2d10+2','60 ft.',NULL,NULL,NULL,16,13,12,2,11,7,'{}','None','Passive Perception 10','None',1,1,3,0,2,4,2,'[]',NULL,'Beast','','{"value":"Majestic steed snorts and stamps, eager for its rider\u0027s command."}','{"value": "Riding horses are domesticated animals commonly used by travelers, adventurers, and merchants in the world of Dungeons and Dragons. They are strong and sure-footed creatures, capable of carrying a rider and their gear long distances over various terrains. \n\nRiding horses are typically bred and trained for their speed, endurance, and obedience. They are often well-cared for by their owners and are prized for their loyalty and utility. Many adventurers rely on riding horses to help them navigate the wilderness, making them essential companions in their journeys.\n\nIn the world of D&D, riding horses are known for their intelligence and ability to form strong bonds with their riders. They are often trained in combat techniques, making them useful in battle situations. Some riding horses are even magically enhanced, possessing abilities such as increased speed or strength.\n\nOverall, riding horses are highly valued creatures in the world of D&D, playing a crucial role in transportation, exploration, and combat. Their loyalty and strength make them invaluable assets to any adventurer seeking to traverse the vast and dangerous landscapes of the fantasy realm."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b9b-c709-72f9-ae96-1c28873c30e7'::uuid,'Smoke Mephit','NeutralEvil','1/4 (XP 50; PB +2)',50,2,'Ambusher','Small',12,NULL,13,'3d6+3','30 ft.',NULL,NULL,'30 ft.',6,14,12,10,10,11,'{"Stealth": 4, "Perception": 2}','Fire, Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 12','Primordial (Auran, Ignan)',1,2,-2,0,0,0,2,'[]','Habitat: Planar (Elemental Planes)','Elemental','','{"value":"Billowing smoke, the mephit cackles as it dances through the flames."}','{"value": "Smoke Mephits are small, impish elemental creatures that are native to the Plane of Air. They are mischievous and love causing chaos and confusion wherever they go. Smoke Mephits are known for their ability to create smoke clouds and use them to blind and disorient their enemies.\n\nIn combat, Smoke Mephits will use their smoke cloud ability to create cover for themselves and their allies, making it difficult for enemies to target them accurately. They are also capable of casting spells like darkness and invisibility to further confuse their opponents.\n\nSmoke Mephits are often summoned by more powerful spellcasters to serve as minions or distractions in battle. They are not particularly strong on their own, but their ability to manipulate smoke and create illusions makes them valuable allies in certain situations.\n\nOverall, Smoke Mephits are playful and chaotic creatures that add an element of unpredictability to any encounter. Their ability to manipulate smoke and create illusions makes them both formidable opponents and useful allies in the world of Dungeons and Dragons."}',0,'Monster Manual 2024','','None',0.25,NULL),
	 ('01990b9c-f5cd-7d93-88b1-727940aba349'::uuid,'Sprite','NeutralGood','1/4 (XP 50; PB +2)',50,4,'Skirmisher','Tiny',15,NULL,10,'4d4','10 ft.',NULL,NULL,'40 ft.',3,18,10,14,13,11,'{"Stealth": 8, "Perception": 3}','None','Passive Perception 13','Common, Elvish, Sylvan',0,4,4,1,0,2,2,'[]','Habitat: Forest, Planar (Feywild)','Fey','','{"value":"Fluttering about, the sprite leaves a trail of sparkling pixie dust in its wake."}','{"value": "Sprites are tiny fey creatures that are known for their mischievous and playful nature. They are often found in forests and other natural settings, where they use their magical abilities to create illusions and trick unsuspecting creatures. Despite their small size, sprites are skilled fighters and are capable of using their magical powers to defend themselves and their homes.\n\nSprites are typically portrayed as having delicate features and colorful wings, similar to those of butterflies. They are known for their love of music and dancing, and are often seen playing instruments or frolicking in the forest. However, sprites can also be fiercely protective of their homes and will not hesitate to use their magic to defend themselves against any threat.\n\nIn some lore, sprites are said to be the guardians of the natural world, protecting the balance of nature and punishing those who harm the environment. They are also known to form close bonds with other creatures, particularly animals and other fey beings.\n\nOverall, sprites are whimsical and enchanting creatures that add a sense of magic and wonder to any D&D campaign."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b9d-5f81-7d10-ba9f-0e4240a48ed5'::uuid,'Steam Mephit','NeutralEvil','1/4 (XP 50; PB +2)',50,0,'Ambusher','Small',10,NULL,17,'5d6','30 ft.',NULL,NULL,'30 ft.',5,11,10,11,10,12,'{"Stealth": 2}','Fire, Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 10','Primordial (Aquan, Ignan)',0,0,3,0,1,0,2,'[]','Habitat: Planar (Elemental Planes)','Elemental','','{"value":"Sizzling with heat, it dances on the edge of a boiling puddle."}','{"value": "Steam Mephits are small, mischievous elemental creatures that are native to the Elemental Plane of Fire. They are often summoned by powerful spellcasters to serve as guardians or messengers.\n\nSteam Mephits are known for their ability to exhale scalding steam, which they use to attack their enemies. They are also capable of creating illusions to confuse and disorient their foes.\n\nIn some lore, Steam Mephits are said to be created when a drop of water from the Elemental Plane of Water comes into contact with the intense heat of the Elemental Plane of Fire. This fusion of opposing elements gives Steam Mephits their unique abilities and appearance.\n\nDespite their small size, Steam Mephits can be quite dangerous when provoked, as they are cunning and quick to retaliate against those who would seek to harm them. They are also known for their playful nature, often engaging in pranks and tricks on unsuspecting travelers.\n\nOverall, Steam Mephits are interesting and versatile creatures that add a touch of chaos and unpredictability to any encounter in the world of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b9e-2eb1-7e96-9c4d-dca36a8a937c'::uuid,'Swarm of Bats','Unaligned','1/4 (XP 50; PB +2)',50,2,'Ambusher','Large',12,NULL,11,'2d10','5 ft.',NULL,NULL,'30 ft.',5,15,10,2,12,4,'{}','Charmed, Frightened, Grappled, Paralyzed, Petrified, Prone, Restrained, Stunned','Blindsight 60 ft., Passive Perception 11','None',0,2,-3,1,-3,-4,2,'[]',NULL,'Swarm of Tiny Beasts','','{"value":"Wings flap wildly as a cloud of bats descends, screeching and swirling in the darkness."}','{"value": "Swarm of Bats are a common sight in dark and cavernous places, where they gather in large numbers to hunt for prey. These creatures are typically found in abandoned buildings, caves, and forests, where they can easily blend in and surprise their victims. \n\nSwarm of Bats are known for their ability to move quickly and silently, making them difficult to detect until it''s too late. They attack by swarming their prey in a chaotic flurry of bat wings and sharp teeth, overwhelming them with sheer numbers. \n\nThese creatures are attracted to blood and can sense it from great distances, making them particularly dangerous to wounded or weakened creatures. They are also known to carry diseases and parasites, adding an extra layer of danger to their attacks. \n\nSwarm of Bats are typically not very intelligent, operating on instinct rather than strategy. They are driven by their insatiable hunger and will continue to attack until their prey is either dead or has managed to escape. \n\nOverall, Swarm of Bats are a common and dangerous threat in the world of D&D, often serving as a minor nuisance or a deadly obstacle for adventurers to overcome."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',0.25,NULL),
	 ('01990b9e-89ef-7d2f-8b2b-fb832e11eab9'::uuid,'Swarm of Rats','Unaligned','1/4 (XP 50; PB +2)',50,0,'Minion','Medium',10,NULL,14,'4d8-4','30 ft.','30 ft.',NULL,NULL,9,11,9,2,10,3,'{}','Charmed, Frightened, Grappled, Paralyzed, Petrified, Prone, Restrained, Stunned','Darkvision 30 ft., Passive Perception 10','None',-1,2,-1,0,-4,-4,2,'[]',NULL,'Swarm of Tiny Beasts','','{"value":"Skittering horde of rats scurry, their beady eyes fixed on your flesh."}','{"value": "Swarm of Rats are a common sight in dungeons, sewers, and other dark and damp places. These creatures are typically attracted to places with abundant sources of food and water, making them a common nuisance for adventurers exploring these locations.\n\nSwarm of Rats are typically made up of hundreds of individual rats, working together as a single entity to overwhelm their prey. They move as a collective, using their sheer numbers to their advantage when attacking.\n\nThese creatures are known for their disease-carrying abilities, as their bites can transmit various illnesses and infections to their victims. They are also known for their speed and agility, making them difficult to hit with attacks.\n\nSwarm of Rats are usually drawn to the scent of blood and fresh meat, making them particularly dangerous to wounded adventurers. They are also known to be attracted to sources of warmth, which can lead them to seek out shelter in the bodies of unconscious or sleeping creatures.\n\nOverall, Swarm of Rats are a low-level threat individually, but their sheer numbers and disease-carrying abilities make them a dangerous foe when encountered in large groups. It is important for adventurers to be cautious when facing these creatures and to be prepared for the possibility of contracting a disease from their bites."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',0.25,NULL),
	 ('01990b9e-9b5e-7a25-9ba7-e257b3e5d813'::uuid,'Swarm of Ravens','Unaligned','1/4 (XP 50; PB +2)',50,2,'Minion','Medium',12,NULL,11,'2d8+2','10 ft.',NULL,NULL,'50 ft.',6,14,12,5,12,6,'{"Perception": 5}','Charmed, Frightened, Grappled, Paralyzed, Petrified, Prone, Restrained, Stunned','Passive Perception 15','None',1,2,-2,1,-2,-3,2,'[]',NULL,'Swarm of Tiny Beasts','','{"value":"Feathers rustle as the swarm descends, cawing and pecking with relentless hunger."}','{"value": "Swarm of Ravens are a type of creature found in the world of Dungeons and Dragons. These swarms are made up of a large number of individual ravens that have come together to form a cohesive and deadly force. They are often found in dark and mysterious places, such as haunted forests or abandoned ruins.\n\nThe lore surrounding Swarm of Ravens is shrouded in mystery and fear. It is said that these creatures are drawn to places of death and despair, feeding off the negative energy that lingers in such places. They are often associated with omens of death or impending doom, and are believed to be harbingers of ill fortune.\n\nSwarm of Ravens are known for their relentless and coordinated attacks, swooping down on their victims in a whirlwind of black feathers and sharp beaks. They are capable of causing significant damage to their enemies, overwhelming them with their sheer numbers and ferocity.\n\nDespite their fearsome reputation, some believe that Swarm of Ravens can be appeased or even controlled by those with the right knowledge and skills. Druids and other nature-based spellcasters are said to have the ability to communicate with and influence these creatures, harnessing their power for their own purposes.\n\nOverall, Swarm of Ravens are a formidable and enigmatic foe in the world of Dungeons and Dragons, embodying the dark and mysterious aspects of the natural world. Those who encounter them would do well to tread carefully and approach with caution."}',0,'Monster Manual 2024 (BR)','','Bludgeoning, Piercing, Slashing',0.25,NULL),
	 ('01990b9f-8941-783a-8d6c-88a22040402f'::uuid,'Troglodyte','ChaoticEvil','1/4 (XP 50; PB +2)',50,0,'Ambusher','Medium',11,NULL,13,'2d8+4','30 ft.','30 ft.',NULL,NULL,14,10,14,6,10,6,'{"Stealth": 4}','None','Darkvision 60 ft., Passive Perception 10','Troglodyte',2,0,2,0,-2,-2,2,'[]','Habitat: Underdark','Monstrosity','','{"value":"Savage troglodyte snarls, brandishing a crude bone club."}','{"value": "Troglodytes are reptilian humanoids that dwell in dark, damp caves and underground tunnels. They are known for their foul odor and savage nature, often attacking travelers and adventurers on sight. Troglodytes are typically about 5 to 6 feet tall, with scaly skin that ranges in color from dark grey to green. They have sharp claws and teeth, which they use to tear apart their prey.\n\nTroglodytes are organized into tribes, with each tribe led by a powerful chief. They worship dark deities and perform twisted rituals to appease their gods. Troglodytes are known to be cunning hunters and skilled in ambush tactics, using their natural camouflage and ability to see in the dark to surprise their enemies.\n\nIn combat, troglodytes fight with a primal ferocity, using their claws and teeth to rip apart their foes. They are known to wield crude weapons such as clubs and spears, but their preferred method of attack is to overwhelm their enemies with sheer numbers and brute strength.\n\nDespite their savage nature, troglodytes are not mindless beasts. They are capable of forming alliances with other creatures, such as goblins or kobolds, in order to achieve their goals. However, their alliances are often short-lived, as troglodytes are notoriously treacherous and quick to turn on their allies if it suits their purposes.\n\nOverall, troglodytes are a dangerous and unpredictable threat to those who venture into their territory. Adventurers would be wise to approach with caution and be prepared for a vicious and deadly encounter."}',0,'Monster Manual 2024','','None',0.25,NULL),
	 ('01990ba1-172c-73f6-890c-ab578abcad67'::uuid,'Venomous Snake','Unaligned','1/8 (XP 25; PB +2)',25,2,'Ambusher','Tiny',12,NULL,5,'2d4','30 ft.',NULL,'30 ft.',NULL,2,15,11,1,10,3,'{}','None','Blindsight 10 ft., Passive Perception 10','None',0,2,4,0,4,5,2,'[]',NULL,'Beast','','{"value":"Forked tongue flickers, eyes fixed on prey, ready to strike."}','{"value": "Venomous snakes are creatures found in various environments such as forests, deserts, and swamps in the world of Dungeons and Dragons. These creatures are known for their deadly venomous bite, which can cause paralysis or even death to their victims.\n\nVenomous snakes are typically solitary creatures, hunting for small animals such as rodents and birds to feed on. They are ambush predators, using their stealth and camouflage to surprise their prey before delivering a quick and lethal strike with their venomous fangs.\n\nIn some regions, venomous snakes are revered as symbols of cunning and power, while in other cultures they are feared and avoided at all costs. Some druids and rangers may have a special connection to these creatures, using them as companions or allies in their quests.\n\nIn combat, venomous snakes rely on their speed and agility to outmaneuver their opponents, striking quickly and retreating before they can be countered. Their venom is a potent weapon, capable of incapacitating even the toughest of foes.\n\nOverall, venomous snakes are formidable creatures that should not be underestimated in the world of Dungeons and Dragons. They serve as a reminder of the dangers that lurk in the wilderness, and adventurers would do well to tread carefully when encountering these deadly serpents."}',0,'Monster Manual 2024 (BR)','','None',0.125,NULL),
	 ('01990ba1-22fe-7fe4-9f2b-90b2a58a9466'::uuid,'Violet Fungus','Unaligned','1/4 (XP 50; PB +2)',50,-5,'Ambusher','Medium',5,NULL,18,'4d8','5 ft.',NULL,NULL,NULL,3,1,10,1,3,1,'{}','Blinded, Charmed, Deafened, Frightened','Blindsight 30 ft., Passive Perception 6','None',0,-5,-4,-4,-5,-5,2,'[]','Habitat: Underdark','Plant','','{"value":"It pulses rhythmically, tendrils reaching out hungrily for any passing prey"}','{"value": "The Violet Fungus is a monstrous creature found in dark and damp environments such as underground caves, forests, and swamps. It resembles a large purple-hued mushroom with long tendrils that it uses to lash out at unsuspecting prey. \n\nThe Violet Fungus is a carnivorous creature that feeds on living creatures by luring them in with a sweet smell and then attacking with its tendrils. It is a slow-moving creature but can be quite deadly in large numbers or if caught off guard. \n\nLegends say that the Violet Fungus was created by a powerful wizard as a guardian for their underground lair, but over time it has spread to other areas and become a menace to travelers and adventurers alike. Some scholars believe that the fungus may have a connection to the Shadowfell, as its dark and twisted nature seems to mirror that of the plane of shadows. \n\nAdventurers who encounter a Violet Fungus must be cautious and prepared to deal with its deadly attacks. Fire and other forms of radiant damage are particularly effective against the creature, as it is weak to light and heat. Those who manage to defeat a Violet Fungus may be able to harvest its spores for use in alchemical or magical concoctions."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990ba3-8ef5-7f92-9108-2a6e7eb361a0'::uuid,'Wolf','Unaligned','1/4 (XP 50; PB +2)',50,2,'Skirmisher','Medium',12,NULL,11,'2d8+2','40 ft.',NULL,NULL,NULL,14,15,12,3,12,6,'{"Stealth": 4, "Perception": 5}','None','Darkvision 60 ft., Passive Perception 15','None',1,2,2,1,2,4,2,'[]',NULL,'Beast','','{"value":"Eyes gleam with hunger as it circles, growling low in its throat."}','{"value": "In Dungeons and Dragons, the wolf is a common creature found in the wilds of various fantasy worlds. Wolves are typically depicted as cunning and vicious predators, often traveling in packs to take down larger prey. They are known for their keen senses, swift movements, and sharp teeth.\n\nIn some D&D settings, wolves are associated with certain deities or supernatural forces, such as the moon or nature itself. They are sometimes seen as symbols of loyalty, teamwork, and primal instincts.\n\nWolves are often encountered by adventurers as they travel through forests, mountains, or other untamed landscapes. They can be a challenging opponent for low-level characters, especially when encountered in groups. However, they can also be tamed and trained as loyal animal companions or mounts.\n\nOverall, wolves in D&D represent the untamed wilderness and the dangers that lurk within it, adding an element of realism and excitement to the game world."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990ba5-5883-7540-9b42-f073451d929e'::uuid,'Zombie','NeutralEvil','1/4 (XP 50; PB +2)',50,-2,'Brute','Medium',8,NULL,15,'2d8+6','20 ft.',NULL,NULL,NULL,13,6,16,3,6,5,'{}','Poison; Exhaustion, Poisoned','darkvision 60 ft., Passive Perception 8','Understands Common plus one other language but can''t speak',3,-2,1,0,-3,-4,2,'[]','Habitat: Planar (Shadowfell), Underdark, Urban','Undead','','{"value":"Shambling towards you, its vacant eyes fixed on your flesh."}','{"value": "Zombies are undead creatures that are reanimated through dark magic or necromantic rituals. They are typically created from the corpses of deceased humans or other creatures, and they retain only a fraction of their former intelligence and abilities.\n\nZombies are mindless and driven by a singular hunger for flesh. They are slow-moving but relentless in their pursuit of living creatures to devour. They are often depicted as decaying and grotesque, with rotting flesh and vacant, lifeless eyes.\n\nIn Dungeons & Dragons 5th Edition, zombies are classified as medium undead creatures with low intelligence and little to no ability to communicate. They are often controlled by a necromancer or other dark magic user, who can command them to do their bidding.\n\nZombies are typically weak to fire and radiant damage, as well as being vulnerable to slashing weapons. They are immune to poison and diseases, as they are already dead. Overall, zombies are a common and relatively low-level threat in D&D campaigns, but they can still pose a danger in large numbers or when controlled by a powerful necromancer."}',0,'Monster Manual 2024 (BR)','','None',0.25,NULL),
	 ('01990b9a-af9d-7b43-9798-39e69b39e965'::uuid,'Satyr','ChaoticNeutral','1/2 (XP 100; PB +2)',100,3,'Skirmisher','Medium',13,NULL,31,'7d8','40 ft.',NULL,NULL,NULL,12,16,11,12,10,14,'{"Stealth": 5, "Perception": 2, "Performance": 6}','None','Passive Perception 12','Common, Elvish, Sylvan',0,3,1,0,2,1,2,'[]','Habitat: Forest, Planar (Feywild)','Fey','','{"value":"Whirling, it capers in the moonlight, playing a haunting melody on its pipes"}','{"value": "Satyrs are fey creatures known for their mischievous and playful nature. They are half-man, half-goat beings with the upper body of a human and the lower body of a goat. Satyrs are often depicted as carefree and hedonistic, enjoying music, revelry, and wine.\n\nIn D&D 5e, satyrs are chaotic neutral creatures that inhabit forests and woodlands. They are skilled musicians and dancers, often playing their pan flutes and engaging in lively festivities. Satyrs are also known for their ability to charm and seduce others with their enchanting music and charisma.\n\nDespite their playful nature, satyrs are formidable in combat, using their hooves and horns to attack enemies when provoked. They are also adept at stealth and can use their natural agility to evade danger.\n\nIn D&D lore, satyrs are often associated with the god of wine and revelry, Dionysus. They are seen as carefree companions of the god, spreading joy and merriment wherever they go. However, some satyrs can be more malicious and trickster-like, leading travelers astray or luring them into dangerous situations for their own amusement.\n\nOverall, satyrs are colorful and vibrant creatures in the world of D&D, embodying the dual nature of wildness and revelry. Players may encounter them as allies, foes, or simply as mischievous tricksters along their adventures in the fantastical realms of Dungeons and Dragons."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b8c-0720-7c91-a79a-0ee072be9cab'::uuid,'Giant Seahorse','Unaligned','1/2 (XP 100; PB +2)',100,1,'Skirmisher','Large',14,NULL,16,'3d10','5 ft.',NULL,'40 ft.',NULL,15,12,11,2,12,5,'{}','None','Passive Perception 11','None',0,1,2,1,-3,-4,2,'[]',NULL,'Beast','','{"value":"Gracefully glides through the water, its rainbow scales shimmering in the sunlight."}','{"value": "Giant seahorses are majestic and rare creatures that dwell in the deepest oceans of the world. They are known for their stunning beauty and graceful movements as they glide through the water with ease. These creatures are much larger than their smaller cousins, with some reaching lengths of up to 15 feet.\n\nGiant seahorses are often sought after by sailors and adventurers for their magical properties. It is said that their scales and fins contain potent magical ingredients that can be used in potions and spells. Some believe that consuming the flesh of a giant seahorse can grant the consumer incredible powers, while others believe that simply being in the presence of one can bring good luck and fortune.\n\nDespite their magical properties, giant seahorses are peaceful creatures that prefer to live in solitude. They are gentle and passive by nature, but will defend themselves fiercely if threatened. Their mesmerizing beauty and mysterious aura make them a coveted prize for those who seek to capture or study them, but few are able to successfully tame or control these elusive creatures.\n\nLegends say that giant seahorses are guardians of the ocean depths, watching over shipwrecks and lost treasures with their keen eyesight and supernatural senses. Some even believe that they are the messengers of the sea gods, delivering messages and warnings to sailors and fishermen in times of need.\n\nEncountering a giant seahorse in the wild is a rare and awe-inspiring experience, one that is sure to leave a lasting impression on those fortunate enough to witness it. But those who seek to harm or exploit these majestic creatures may find themselves facing the wrath of the ocean itself, as giant seahorses are fiercely protected by the forces of nature."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b97-2be6-7cc9-b556-b14da970f7b9'::uuid,'Piercer','Unaligned','1/2 (XP 100; PB +2)',100,3,'Skirmisher','Medium',15,NULL,22,'3d8+9','5 ft.','15 ft.',NULL,NULL,13,13,16,1,7,3,'{"Stealth": 5}','None','Blindsight 30 ft., Darkvision 60 ft., Passive Perception 8','None',3,1,1,-2,-4,-5,2,'[]','Habitat: Underdark','Aberration','','{"value":"From the shadows above, it drops silently, hunger in its sharp gaze."}','{"value": "Piercers are large, predatory creatures that dwell in dark caves and tunnels. They have a long, slender body with a sharp, pointed end that resembles a stalactite, allowing them to blend in with their surroundings and ambush unsuspecting prey from above. \n\nPiercers are known for their ability to drop from the ceiling and impale their victims with their sharp, stony bodies. They are highly adapted to life in the darkness, with keen senses that allow them to detect vibrations and movements in their environment. \n\nPiercers are solitary creatures and are rarely encountered in groups. They are opportunistic hunters, feeding on any creature that comes within their reach. They are particularly drawn to the scent of blood, which can attract them from great distances. \n\nWhile piercers are not particularly intelligent, they are cunning hunters and possess a strong survival instinct. They will retreat and wait for another opportunity to strike if their initial attack fails. \n\nAdventurers should exercise caution when exploring caves and tunnels, as piercers are known to be a deadly threat to those who venture into their territory."}',0,'Monster Manual 2024','','None',0.5,NULL),
	 ('01990b99-7329-775d-9640-522d26f93c52'::uuid,'Reef Shark','Unaligned','1/2 (XP 100; PB +2)',100,2,'Ambusher','Medium',12,NULL,22,'4d8+4','5 ft.',NULL,'30 ft.',NULL,14,15,13,1,10,4,'{"Perception": 2}','None','Blindsight 30 ft., Passive Perception 12','None',1,2,2,0,3,5,2,'[]',NULL,'Beast','','{"value":"Jaws snap shut with a menacing crunch, eyes fixed on prey."}','{"value": "Reef Sharks are medium-sized, aggressive predators that can be found in tropical and subtropical waters. They are typically solitary creatures, but they have been known to form small groups or schools when hunting for food.\n\nThese creatures are known for their sharp teeth and powerful jaws, which they use to catch and devour their prey. Reef Sharks primarily feed on fish, crustaceans, and other small marine creatures.\n\nIn some regions, Reef Sharks are considered sacred or revered by local communities, who believe that they possess spiritual or mystical powers. In other areas, they are seen as a nuisance or a threat to swimmers and fishermen.\n\nIn D&D 5e, Reef Sharks are often encountered in coastal regions or shallow waters, where they lurk near coral reefs or rocky outcrops. They are typically neutral in alignment, but they will attack if they feel threatened or if they are hungry. Adventurers should be cautious when swimming or sailing in areas where Reef Sharks are known to inhabit, as they are swift and aggressive predators."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b8c-a74e-70c0-926d-1099ff063e14'::uuid,'Giant Wasp','Unaligned','1/2 (XP 100; PB +2)',100,2,'Skirmisher','Medium',13,NULL,22,'5d8','10 ft.',NULL,NULL,'50 ft.',10,14,10,1,10,3,'{}','None','Passive Perception 10','None',0,2,0,0,-4,-5,2,'[]',NULL,'Beast','','{"value":"Wings buzz angrily as it hovers, venom dripping from its stinger."}','{"value": "Giant Wasps are a terrifying variant of the common wasp, growing to enormous sizes due to exposure to magical or alchemical substances. These monstrous insects are known for their aggressive and territorial behavior, often attacking anything that comes too close to their nests.\n\nGiant Wasps are typically found in forests, caves, and other secluded areas where they can build their nests without interference. They are known for their potent venom, which can paralyze or even kill their prey in a matter of seconds. Many adventurers have fallen victim to these creatures, underestimating their speed and deadly stingers.\n\nIn some regions, Giant Wasps are revered as symbols of strength and ferocity, with tribes of humanoids even worshipping them as divine beings. However, most people view them as nothing more than dangerous pests, to be avoided at all costs.\n\nTo defeat a Giant Wasp in combat, adventurers must be quick and precise, as their stingers can pierce through even the toughest armor. Fire-based attacks are particularly effective against these creatures, as they are highly susceptible to heat. However, caution must be exercised, as Giant Wasps are known to attack in swarms, overwhelming their enemies with sheer numbers.\n\nOverall, Giant Wasps are a formidable foe in the world of Dungeons and Dragons, requiring skill and strategy to overcome. Only the bravest and most skilled adventurers dare to face these monstrous insects in battle."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b84-8463-7f43-bef1-1f8e74a0543c'::uuid,'Cockatrice','Unaligned','1/2 (XP 100; PB +2)',100,1,'Ambusher','Small',11,NULL,22,'5d6+5','20 ft.',NULL,NULL,'40 ft.',6,12,12,2,13,5,'{}','Petrified','Darkvision 60 ft., Passive Perception 11','None',1,1,-2,1,-3,-4,2,'[]','Habitat: Grassland','Monstrosity','','{"value":"Feathers bristle as it fixes its deadly gaze upon you"}','{"value": "In Dungeons and Dragons 5th edition, the Cockatrice is a small, magical creature with the body of a chicken and the head and wings of a dragon. They are known for their ability to turn creatures to stone with a single glance, making them a dangerous foe to encounter in the wild.\n\nCockatrices are believed to have originated from experiments conducted by powerful wizards, who combined the traits of chickens and dragons to create these deadly creatures. They are often found in caves, forests, and other remote locations, where they hunt for prey and turn them to stone to feed on later.\n\nDespite their fearsome reputation, Cockatrices are not inherently evil and can be befriended or tamed by skilled adventurers. Some wizards even seek out Cockatrices for their magical abilities, using them as guardians or pets.\n\nOverall, the Cockatrice is a unique and intriguing monster in the world of Dungeons and Dragons, with a rich lore that adds depth to any campaign or adventure."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b85-1c56-7205-85c3-47035b70aed4'::uuid,'Crocodile','Unaligned','1/2 (XP 100; PB +2)',100,0,'Ambusher','Large',12,NULL,13,'2d10+2','20 ft.',NULL,'30 ft.',NULL,15,10,13,2,10,5,'{"Stealth": 2}','None','Passive Perception 10','None',3,0,2,0,3,4,2,'[]',NULL,'Beast','','{"value":"Jaws snap shut with a deafening crunch, eyes fixed hungrily on prey"}','{"value": "In Dungeons and Dragons 5e, the crocodile is a large reptilian creature that dwells in swamps, rivers, and other bodies of water. Known for their powerful jaws and stealthy hunting abilities, crocodiles are fearsome predators that can strike with surprising speed and ferocity.\n\nIn D&D lore, crocodiles are often depicted as solitary creatures that lurk beneath the surface of the water, waiting for unsuspecting prey to come within striking distance. They are known for their ambush tactics, using their camouflage to blend in with their surroundings before launching a sudden and deadly attack.\n\nCrocodiles are typically portrayed as neutral creatures, neither inherently good nor evil. However, they are fiercely territorial and will defend their hunting grounds against any intruders, including adventurers who stumble into their territory.\n\nIn some D&D campaigns, crocodiles may be associated with deities or other powerful beings, serving as guardians or symbols of strength and cunning. They are often used by evil creatures or villains as guardians or enforcers, using their natural abilities to protect their masters'' lairs or carry out their bidding.\n\nOverall, crocodiles are a staple monster in D&D, providing a dangerous and exciting challenge for adventurers exploring watery environments. Their lore emphasizes their predatory nature and stealthy hunting tactics, making them a formidable opponent for even the most experienced adventurers."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b85-63f2-708b-a711-cef326d626f8'::uuid,'Darkmantle','Unaligned','1/2 (XP 100; PB +2)',100,3,'Ambusher','Small',11,NULL,22,'5d6+5','10 ft.',NULL,NULL,'30 ft.',16,12,13,2,10,5,'{"Stealth": 3}','None','Blindsight 60 ft., Passive Perception 10','None',1,1,3,0,-3,-4,2,'[]','Habitat: Underdark','Aberration','','{"value":"Shadows swirl as it drops from above, enveloping its prey in darkness."}','{"value": "Darkmantles are small, predatory creatures that resemble floating cloaks with a single large eye in the center. They are known for their ability to camouflage themselves against cave walls and ceilings, waiting for unsuspecting prey to pass by before swooping down and enveloping them in their dark, leathery folds.\n\nThese creatures are often found in underground caverns and dungeons, where they use their natural camouflage to ambush adventurers and travelers. They are fiercely territorial and will attack anyone who enters their territory, using their darkmantle ability to create darkness around them to disorient their prey.\n\nIn some regions, darkmantles are believed to be the result of a curse placed on ancient wizards or sorcerers, transforming them into these malevolent creatures as punishment for their hubris. Others believe that darkmantles are actually extraplanar beings that have been summoned to the material plane by powerful magic users.\n\nRegardless of their origins, darkmantles are feared for their stealthy ambush tactics and ability to quickly overwhelm their prey. It is said that the only way to defeat a darkmantle is to strike at its vulnerable underbelly, as its thick, leathery folds offer protection from most attacks. Those who are able to defeat a darkmantle are often rewarded with valuable treasures that the creature has hoarded in its lair."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b87-6767-794b-a18d-241931c6b713'::uuid,'Dust Mephit','NeutralEvil','1/2 (XP 100; PB +2)',100,2,'Ambusher','Small',12,NULL,17,'5d6','30 ft.',NULL,NULL,'30 ft.',5,14,10,9,11,10,'{"Stealth": 4, "Perception": 2}','Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 12','Primordial (Auran, Terran)',0,2,-3,0,0,-1,2,'[]','Habitat: Planar (Elemental Planes)','Elemental','','{"value":"It whirls in a frenzied dance, kicking up choking clouds of swirling dust"}','{"value": "Dust Mephits are small, imp-like creatures that inhabit desolate and arid environments. They are known for their mischievous and devious nature, often causing trouble for travelers and adventurers in the desert. Dust Mephits have the ability to create clouds of choking dust and sand, which they use to blind and disorient their enemies.\n\nIn D&D lore, Dust Mephits are considered to be part of a larger group of elemental creatures known as Mephits. They are typically summoned by powerful spellcasters to serve as minions or guards. Dust Mephits are known to be cunning and quick-witted, using their abilities to evade capture and outsmart their foes.\n\nDust Mephits are often found in ruins, tombs, and other abandoned places, where they scavenge for food and treasure. They are attracted to shiny objects and valuable items, which they hoard in their lairs. Despite their small size, Dust Mephits can be quite dangerous in large numbers, overwhelming their enemies with their swift and coordinated attacks.\n\nOverall, Dust Mephits are considered to be a nuisance to those who encounter them, but they can also be valuable sources of information and assistance if approached with caution and respect."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b89-f05c-701a-beaf-f22b1bb73f3f'::uuid,'Gas Spore Fungus','Unaligned','1/2 (XP 100; PB +2)',100,-5,'Ambusher','Large',8,NULL,13,'9d10-36','5 ft.',NULL,NULL,'10 ft.',5,1,3,1,1,1,'{}','Poison; Blinded, Charmed, Deafened, Frightened, Paralyzed, Poisoned, Prone','Blindsight 30 ft., Passive Perception 5','—',-4,-5,-3,-5,-5,-5,2,'[]','Habitat: Underdark','Plant','','{"value":"Pulsating sac sways ominously, releasing noxious fumes and spores into the air"}','{"value": "Gas Spores are a type of fungus that mimic the appearance of Beholders, a powerful and feared aberration in the Dungeons and Dragons universe. Despite their seemingly intimidating appearance, Gas Spores are actually harmless to most creatures.\n\nGas Spores float through the air, propelled by small gas sacs within their bodies. They are often found in dark, damp areas such as caves or underground tunnels. Gas Spores are attracted to sources of light and warmth, and will float towards any light source they detect.\n\nWhen a creature gets too close to a Gas Spore, it will burst open, releasing a cloud of toxic gas. This gas is highly flammable and can cause severe damage to any creature caught in its radius. However, Gas Spores are not intelligent and do not actively seek out creatures to attack. Instead, they rely on their mimicry of Beholders to deter potential threats.\n\nDespite their harmless nature, Gas Spores are often mistaken for dangerous monsters and are sometimes used as traps by more cunning creatures. Adventurers must be cautious when encountering Gas Spores, as their explosive nature can catch even the most experienced adventurers off guard."}',0,'Monster Manual 2024','','None',0.5,NULL),
	 ('01990b8d-6573-779e-ad4a-a382cc30b508'::uuid,'Gnoll Warrior','ChaoticEvil','1/2 (XP 100; PB +2)',100,1,'Soldier','Medium',15,NULL,27,'6d8','30 ft.',NULL,NULL,NULL,14,12,11,6,10,7,'{}','None','Darkvision 60 ft., Passive Perception 10','Gnoll',0,1,2,0,-2,-2,2,'[]','Habitat: Desert, Forest, Grassland, Hill','Fiend','','{"value":"Snarling, it brandishes its blood-stained axe, eyes filled with primal fury."}','{"value": "Gnolls are a humanoid race that resembles a mix between a hyena and a human. They are known for their fierce and savage nature, often living in tribes that roam the wilderness in search of prey. Gnoll warriors are the strongest and most skilled fighters within these tribes, known for their brutal combat tactics and relentless pursuit of their enemies.\n\nGnoll warriors are typically led by a powerful chieftain or pack lord, who commands them in battle and dictates their movements. They are often seen wearing crude armor made from scavenged materials, such as bones and hides, and wield weapons like spears, axes, and bows. In combat, gnoll warriors fight with a ferocity that borders on madness, using their sharp teeth and claws to tear into their foes.\n\nGnoll warriors are often encountered in raiding parties or hunting groups, where they work together to take down larger prey or overwhelm their enemies. They are driven by a primal instinct to hunt and kill, making them dangerous adversaries for any adventurer unlucky enough to cross their path.\n\nOverall, gnoll warriors are a fearsome and relentless force on the battlefield, embodying the savage and brutal nature of their hyena-like race."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990b8e-1b92-75b0-8919-3ae08628359b'::uuid,'Gray Ooze','Unaligned','1/2 (XP 100; PB +2)',100,-2,'Solo','Medium',9,NULL,22,'3d8+9','10 ft.','10 ft.',NULL,NULL,12,6,16,1,6,2,'{"Stealth": 2}','Blinded, Charmed, Deafened, Exhaustion, Frightened, Grappled, Prone, Restrained','Blindsight 60 ft., Passive Perception 8','None',3,-2,1,-2,-4,-5,2,'[]','Habitat: Underdark','Ooze','','{"value":"Pulsating silently, its amorphous form stretches and oozes toward you."}','{"value": "The Gray Ooze is a mindless, amorphous creature that dwells in dark, damp places such as caves, sewers, and underground tunnels. It is a slow-moving, gelatinous blob that feeds on organic matter, such as plants, animals, and even adventurers unlucky enough to stumble upon it.\n\nThe Gray Ooze is a dangerous predator that uses its ability to blend in with its surroundings to ambush unsuspecting prey. It is also able to secrete a corrosive acid that dissolves flesh and metal, making it a formidable opponent in combat.\n\nLegends say that the Gray Ooze was created by a powerful wizard experimenting with alchemical concoctions, but the creature''s true origins remain a mystery. Some believe that it is a product of the natural world, a primordial force of destruction and decay.\n\nAdventurers who encounter a Gray Ooze must use caution and strategy to defeat it, as its acidic attacks can quickly overwhelm even the strongest of warriors. Some brave souls have managed to capture and tame Gray Oozes, using them as guardians or weapons in their own quests for power and glory."}',0,'Monster Manual 2024 (BR)','','Acid, Cold, Fire',0.5,NULL),
	 ('01990b90-0f52-780e-ad21-d5dfaee219b4'::uuid,'Hobgoblin Warrior','LawfulEvil','1/2 (XP 100; PB +2)',100,3,'Soldier','Medium',18,NULL,11,'2d8+2','30 ft.',NULL,NULL,NULL,13,12,12,10,10,9,'{}','None','Darkvision 60 ft., Passive Perception 10','Common, Goblin',1,1,1,0,-1,0,2,'["Half-Plate Armor", "Longbow", "Longsword", "Shield"]','Habitat: Desert, Forest, Grassland, Hill, Mountain, Planar (Acheron), Underdar','Fey','Goblinoid','{"value":"Warrior sneers, brandishing its bloodied sword with a menacing glare"}','{"value": "In the world of Dungeons and Dragons, hobgoblins are a militaristic and disciplined race of goblinoids that are known for their skill in combat and strategy. Hobgoblin warriors are the backbone of hobgoblin society, serving as soldiers, guards, and enforcers for their tribes and clans.\n\nHobgoblin warriors are trained from a young age in the arts of war, honing their skills with weapons and tactics to become formidable fighters on the battlefield. They are known for their discipline and organization, often working together in highly coordinated units to overpower their enemies.\n\nHobgoblin warriors are fiercely loyal to their leaders and will follow orders without question, making them valuable allies in battle. They are also known for their ruthless efficiency, showing no mercy to their enemies and often resorting to brutal tactics to achieve victory.\n\nIn combat, hobgoblin warriors are known for their proficiency with a variety of weapons, including swords, spears, and bows. They are skilled fighters both at range and up close, making them versatile opponents on the battlefield.\n\nOverall, hobgoblin warriors are a formidable force to be reckoned with in the world of Dungeons and Dragons, representing the disciplined and militaristic side of goblinoid society."}',0,'Monster Manual 2024 (BR)','Goblinoid','None',0.5,NULL),
	 ('01990b90-bbd2-7941-9fe5-ba2969848b88'::uuid,'Ice Mephit','NeutralEvil','1/2 (XP 100; PB +2)',100,1,'Ambusher','Small',11,NULL,21,'6d6','30 ft.',NULL,NULL,'30 ft.',7,13,10,9,11,12,'{"Stealth": 3, "Perception": 2}','Cold, Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 12','Primordial (Aquan, Auran)',0,1,-2,0,1,-1,2,'[]','Habitat: Planar (Elemental Planes)','Elemental','','{"value":"Frosty breath billows as it dances on icy winds, eyes glittering with mischief."}','{"value": "Ice Mephits are small, mischievous creatures that originate from the Elemental Plane of Ice. They are typically summoned by powerful spellcasters to serve as minions or guards. Ice Mephits resemble humanoid figures made entirely of ice, with sharp, jagged features and icy blue skin.\n\nIce Mephits are known for their ability to control and manipulate cold, creating blasts of freezing air and ice shards to attack their enemies. They are also able to freeze objects and surfaces with a touch, making them formidable foes in combat.\n\nDespite their icy nature, Ice Mephits are not inherently evil and can be bargained with or persuaded to aid adventurers in exchange for something valuable, such as gems or magical items. However, they are easily angered and can be quick to turn on those who do not show them proper respect.\n\nIn the wild, Ice Mephits are often found living in frigid, inhospitable environments such as glaciers or icy caves. They are known to form small groups or tribes, working together to survive and protect their territory from intruders.\n\nOverall, Ice Mephits are cunning and resourceful creatures that should not be underestimated, especially when encountered in their natural habitat."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b93-1c54-7090-bb80-392aa9995fa4'::uuid,'Magma Mephit','NeutralEvil','1/2 (XP 100; PB +2)',100,1,'Ambusher','Small',11,NULL,18,'4d6+4','30 ft.',NULL,NULL,'30 ft.',8,12,12,7,10,10,'{"Stealth": 3}','Fire, Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 10','Primordial (Ignan, Terran)',1,1,-1,0,0,-2,2,'[]','Habitat: Planar (Elemental Planes)','Elemental','','{"value":"It dances on the lava\u0027s edge, cackling as fiery sparks fly."}','{"value": "Magma Mephits are small, imp-like creatures that are native to the Elemental Plane of Fire. They are formed from the raw elemental energy of the plane and are often summoned by powerful spellcasters to serve as guardians or messengers. Magma Mephits have a fiery appearance, with glowing eyes and a body that radiates heat.\n\nThese creatures are known for their mischievous and chaotic nature, delighting in causing destruction and chaos wherever they go. They are capable of breathing out jets of superheated magma, which can burn their enemies to a crisp. Magma Mephits are also immune to fire damage and can move through lava and molten rock without being harmed.\n\nDespite their destructive tendencies, Magma Mephits can also be cunning and resourceful when it comes to achieving their goals. They are often willing to serve as minions to more powerful beings in exchange for promises of power or rewards. However, they are not particularly loyal and will betray their masters if they see an opportunity for personal gain.\n\nIn combat, Magma Mephits are agile and unpredictable, using their fiery abilities to keep their enemies off balance. They are also capable of summoning other Mephits to aid them in battle, creating a chaotic and dangerous situation for their foes. Overall, Magma Mephits are dangerous foes to underestimate, as their fiery nature and cunning tactics make them formidable opponents."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b95-04c0-7809-a5de-686aa748adb9'::uuid,'Myconid Adult','LawfulNeutral','1/2 (XP 100; PB +2)',100,0,'Brute','Medium',12,NULL,16,'3d8+3','20 ft.',NULL,NULL,NULL,10,10,12,10,13,7,'{}','None','Darkvision 120 ft., Passive Perception 11','Telepathy 240 ft.',1,0,0,1,-2,0,2,'[]','Habitat: Underdark','Plant','','{"value":"Spores burst forth as it sways, emitting a calming aura of earthy tranquility."}','{"value": "Myconid Adults are humanoid fungi creatures that dwell in underground caverns and forests. They are peaceful by nature and are known for their ability to communicate with other creatures through telepathy. \n\nMyconid Adults are part of a larger fungal society known as the Myconids, which includes various other creatures such as Spore Servants and Myconid Sovereigns. The Myconids have a symbiotic relationship with the fungi that grow in their territories, using them for food and shelter.\n\nMyconid Adults are typically around 5 feet tall and have a humanoid shape with a fungal appearance. They have the ability to release spores that can induce various effects on creatures that inhale them, such as causing confusion or paralysis.\n\nIn combat, Myconid Adults are not particularly aggressive and will only fight to defend themselves or their territory. They are more likely to try to communicate with potential threats rather than resorting to violence. \n\nOverall, Myconid Adults are peaceful creatures that prefer to live in harmony with their environment and other creatures. They are often sought out by adventurers for their knowledge of the underground and their ability to communicate telepathically."}',0,'Monster Manual 2024','','None',0.5,NULL),
	 ('01990b96-e1e7-762c-a995-d93eab93bf30'::uuid,'Performer','TrueNeutral','1/2 (XP 100; PB +2)',100,3,'Skirmisher','Medium',13,NULL,27,'5d8+5','30 ft.',NULL,NULL,NULL,12,16,12,13,14,16,'{"Athletics": 3, "Acrobatics": 5, "Performance": 7}','None','Passive Perception 12','Common plus one other language',1,5,1,2,5,1,2,'["Shortsword"]','Habitat: Any','Humanoid','','{"value":"Graceful creature twirls, casting colorful illusions that dance before your eyes"}','{"value": "The Performer is a unique and mysterious creature that is said to dwell in the depths of the Feywild. This creature is known for its mesmerizing performances, captivating those who witness it with its graceful movements and otherworldly beauty. \n\nLegends say that the Performer was once a mortal being who was blessed by the Fey with extraordinary talent and grace. As a result, the Performer was able to entrance audiences with its performances, drawing in crowds from all corners of the Feywild. \n\nHowever, as time passed, the Performer became consumed by its desire for perfection and recognition. It made a pact with a powerful Fey entity, trading its mortal soul for eternal beauty and talent. In exchange, the Performer was bound to the Fey entity, forced to perform for all eternity in the depths of the Feywild.\n\nNow, the Performer is a haunting and tragic figure, forever trapped in a cycle of endless performances. It is said that those who witness the Performer''s shows are forever changed, their minds filled with visions of beauty and sorrow. Some even say that the Performer''s performances have the power to drive people mad, leaving them entranced and lost in a world of illusion.\n\nThose who seek out the Performer do so at their own peril, for the creature''s allure is as dangerous as it is enchanting. Only the bravest and most skilled adventurers dare to face the Performer, hoping to uncover the secrets of its tragic past and perhaps free it from its eternal torment."}',0,'Monster Manual 2024','','None',0.5,NULL),
	 ('01990b9a-68a7-7a84-a4e0-ea7d9ad79cdc'::uuid,'Sahuagin Warrior','LawfulEvil','1/2 (XP 100; PB +2)',100,0,'Soldier','Medium',12,NULL,22,'4d8+4','30 ft.',NULL,'40 ft.',NULL,13,11,12,12,13,9,'{"Perception": 5}','None','Darkvision 120 ft., Passive Perception 15','Sahuagin',1,0,1,1,-1,1,2,'[]','Habitat: Coastal, Underwater','Fiend','','{"value":"Swirling currents around it, the Sahuagin Warrior bares its sharp teeth in aggression."}','{"value": "Sahuagin are a race of fish-like humanoids that dwell in the oceans and coastal regions of the world. They are known for their fierce warrior culture and their worship of the shark god Sekolah. Sahuagin warriors are highly skilled in combat, using their razor-sharp teeth and claws to tear apart their enemies.\n\nSahuagin warriors are typically clad in armor made from the shells of giant sea creatures, and they wield tridents and nets in battle. They are known for their ruthless tactics and their ability to coordinate attacks with their fellow sahuagin.\n\nSahuagin warriors are often encountered leading raiding parties against coastal settlements, capturing slaves and plundering resources. They are feared by sailors and coastal dwellers alike for their ferocity and their relentless pursuit of their enemies.\n\nIn battle, sahuagin warriors are relentless fighters, using their superior swimming abilities to outmaneuver their foes and strike from unexpected angles. They are cunning tacticians, able to adapt to changing circumstances and exploit their enemies'' weaknesses.\n\nOverall, sahuagin warriors are formidable adversaries that should not be underestimated by any who venture into their watery domain."}',0,'Monster Manual 2024 (BR)','','Acid, Cold',0.5,NULL),
	 ('01990b9a-0d53-779a-9bee-d3b2886d72d1'::uuid,'Rust Monster','Unaligned','1/2 (XP 100; PB +2)',100,1,'Ambusher','Medium',14,NULL,33,'6d8+6','40 ft.',NULL,NULL,NULL,13,12,13,2,13,6,'{}','None','Darkvision 60 ft., Passive Perception 11','—',1,1,1,1,-2,-4,2,'[]','Habitat: Underdark','Monstrosity','','{"value":"Metallic chitin scrapes against the ground, its antennae twitching with hunger."}','{"value": "The Rust Monster is a creature that roams the underground tunnels and caverns of the world, known for its insatiable appetite for metal. It resembles a large insect with a rust-colored carapace and sharp mandibles. \n\nLegends say that the Rust Monster was created by a powerful wizard as a guardian of his treasure hoard, using dark magic to give it the ability to consume metal. Over time, the creature multiplied and spread throughout the underground, becoming a feared presence for adventurers and miners alike.\n\nRust Monsters are drawn to the scent of metal, particularly iron and steel, and will actively seek out and devour any metal objects they come across. Their touch causes metal to rapidly corrode and disintegrate, leaving behind nothing but rusted remnants. This ability makes them a deadly threat to adventurers who rely on metal weapons and armor.\n\nDespite their destructive nature, Rust Monsters are not inherently evil creatures. They are simply driven by their insatiable hunger for metal and will not attack living creatures unless provoked. Some have even been known to form symbiotic relationships with other creatures, such as Dwarves who use them to dispose of unwanted metal scraps.\n\nOverall, Rust Monsters are a unique and dangerous addition to the world of Dungeons and Dragons, serving as a reminder of the dangers that lurk beneath the surface."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990b9a-d1d6-7283-83d9-68dca445683a'::uuid,'Scout','TrueNeutral','1/2 (XP 100; PB +2)',100,2,'Skirmisher','Medium',13,NULL,16,'3d8+3','30 ft.',NULL,NULL,NULL,11,14,12,11,13,11,'{"Nature": 4, "Stealth": 6, "Survival": 5, "Perception": 5}','None','Passive Perception 15','Common plus one other language',1,2,0,1,0,0,2,'["Leather Armor", "Longbow", "Shortsword"]','Habitat: Any','Humanoid','','{"value":"Eyes darting, it moves silently through the shadows, alert for any movement."}','{"value": "In Dungeons and Dragons 5th edition, a Scout is a skilled and versatile warrior who excels at stealth, reconnaissance, and tracking. They are often employed by military organizations, adventuring parties, or other groups in need of skilled individuals to gather information, scout out enemy positions, or navigate dangerous terrain.\n\nScouts are typically lightly armored and armed, preferring to rely on their agility, speed, and keen senses to outmaneuver and outwit their foes. They are highly trained in survival skills, able to navigate through forests, mountains, and other challenging environments with ease.\n\nIn combat, Scouts are adept at striking quickly and decisively, using hit-and-run tactics to keep their enemies off balance. They are skilled archers, able to pick off targets from a distance with deadly accuracy, or they may choose to engage in melee combat with finesse and precision.\n\nOverall, Scouts are valuable assets in any adventuring party, able to provide crucial information, reconnaissance, and support in a variety of situations. They are often seen as the eyes and ears of the group, able to anticipate danger and react swiftly to changing circumstances."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL),
	 ('01990ba1-7b48-7294-8e7f-7728b1132bd5'::uuid,'Warhorse','Unaligned','1/2 (XP 100; PB +2)',100,1,'Brute','Large',11,NULL,19,'3d10+3','60 ft.',NULL,NULL,NULL,18,12,13,2,12,7,'{}','None','Passive Perception 11','None',1,1,4,3,2,4,2,'[]',NULL,'Beast','','{"value":"Hooves thunder as the majestic warhorse charges, mane flowing like a battle standard"}','{"value": "Warhorses are powerful, loyal, and highly trained steeds that are often used by knights and other warriors in battle. These majestic creatures are bred for war and are known for their strength, speed, and courage on the battlefield.\n\nIn the world of Dungeons and Dragons, warhorses are often seen as symbols of strength and nobility. They are often used by knights and other noble warriors to ride into battle, charging fearlessly into the fray and trampling enemy soldiers beneath their hooves.\n\nWarhorses are highly intelligent creatures and are capable of forming strong bonds with their riders. They are fiercely loyal and will fight to the death to protect their owners. In battle, warhorses are known for their powerful kicks and their ability to charge through enemy lines with incredible speed and force.\n\nOverall, warhorses are respected and admired by many in the world of D&D for their bravery, strength, and unwavering loyalty to their masters. They are truly a force to be reckoned with on the battlefield."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL);
INSERT INTO public.monsters (id,"name",alignment,challenge_rating,xp,initiative_bonus,"role",creature_size,armor_class,minion_armor_class,hit_points,hit_dice,speed,climb,swim,fly,strength,dexterity,constitution,intelligence,wisdom,charisma,skills,damage_immunities,senses,languages,con_saving_throw,dex_saving_throw,str_saving_throw,wis_saving_throw,cha_saving_throw,int_saving_throw,proficiency_bonus,equipments,habitats,creature_type,monster_group,manner,lore,page_source,"source",creature_sub_type,damage_resistances,cr,cr_in_lair) VALUES
	 ('01990ba1-86e4-7bd4-8d38-75830e163557'::uuid,'Warhorse Skeleton','LawfulEvil','1/2 (XP 100; PB +2)',100,1,'Brute','Large',13,NULL,22,'3d10+6','60 ft.',NULL,NULL,NULL,18,12,15,2,8,5,'{}','Poison; Exhaustion, Poisoned','Darkvision 60 ft., Passive Perception 9','None',2,1,4,-1,-3,-4,2,'[]','Habitat: Planar (Shadowfell), Underdark, Urban','Undead','','{"value":"Bones clatter menacingly as it charges, eyes glowing with an otherworldly fire."}','{"value": "Warhorse Skeletons are undead creatures that are created through dark magic and necromancy. These creatures are the animated remains of once noble and majestic warhorses that have been raised from the dead to serve their necromancer masters in battle.\n\nThese creatures are typically found in the service of powerful necromancers, dark knights, or evil warlords who use them as mounts or guardians. Warhorse Skeletons are fiercely loyal to their masters and will attack anyone who threatens them.\n\nIn combat, Warhorse Skeletons use their powerful hooves and teeth to trample and bite their enemies. They are relentless and fearless in battle, showing no signs of pain or fear as they charge into the fray.\n\nDespite their intimidating appearance and deadly combat abilities, Warhorse Skeletons are vulnerable to radiant damage and can be turned or destroyed by a cleric or paladin who channels divine energy. However, they are resilient and difficult to defeat, making them a formidable foe for any adventurer brave enough to face them in battle."}',0,'Monster Manual 2024 (BR)','','None',0.5,NULL);
